  import mutable.{ArrayBuffer, ListBuffer}
  import scala.reflect.ClassTag

  val MOD = 1000000007
  val out = new PrintWriter(System.out)

  def solve(): Unit = {
    val N = ni()
    val A = na(N)

    /**
      * (左から詰めたブロックに右から入って出てこない, 右から入って右から出た)
      */
    def calc(A: Array[Int]): (Array[Long], Array[Long]) = {
      val cum = cumSum(A)
      val L_i, L_io = Array.ofDim[Long](N + 1)
      L_i(0) = 0
      L_io(0) = 0

      def cost(i: Int, roundtrip: Boolean, joint: Boolean) = {
        if (joint) {
          if (roundtrip) {
            if (A(i) == 0) 2 else A(i)&1 // 0なら+2、それ以外は奇数なら+1
          } else {
            if (A(i) == 0) 1 else A(i)&1^1// 0なら+1、それ以外は偶数なら+1
          }
        } else {
          if (roundtrip) {
            if (A(i) == 0) 0 else A(i)&1 // 0なら+0、それ以外は奇数なら+1
          } else {
            if (A(i) == 0) 0 else A(i)&1^1// 0なら+0、それ以外は偶数なら+1
          }
        }
      }

      REP(N) { i =>
        {
          val all0 = cum(i + 1) // iも含めて左を全部0にする
          val all0butMe = cum(i) + cost(i, roundtrip = false, joint = false) // 一つ手前までを0にする

          // 入って出てこないケースは、L_i, L_ioどっちと繋ぐこともできる
          val v = min(L_i(i), L_io(i)) + cost(i, roundtrip = false, joint = true)
          L_i(i + 1) = min(min(all0, all0butMe), v)
        }
        {
          val all0 = cum(i + 1) // iも含めて左を全部0にする
          val all0butMe = cum(i) + cost(i, roundtrip = true, joint = false) // 一つ手前までを0にする

          // 入って出てくるケースは、はいったままのケースと繋ぐことはできない
          val v = L_io(i) + cost(i, roundtrip = true, joint = true)
          L_io(i + 1) = min(min(all0, all0butMe), v)
        }
      }

      (L_i, L_io)
    }

    val (l_i, l_io) = calc(A)
    val (r_i_rev, r_io_rev) = calc(A.reverse)
    val r_i = r_i_rev.reverse
    val r_io = r_io_rev.reverse

//    debug("L_i")
//    debug(l_i)
//    debug("L_io")
//    debug(l_io)
//    debug("R_i")
//    debug(r_i)
//    debug("R_io")
//    debug(r_io)

    // 0-Nで、ここからはじめたらってのを全羅列する
    val ans = map(N + 1) { i =>
      min(l_io(i) + r_i(i), r_io(i) + l_i(i))
    }.min

    out.println(ans)
  }


