object Main extends App {
  import scala.io.StdIn._

  val l = readInt
  val ears = Array.tabulate(l){_ ⇒ readLong}
  println(solve(ears))
  def solve(ears: Array[Long]): Long = {
    val memo = Array.tabulate(3){_ ⇒ Array.tabulate(ears.length + 1){_ ⇒ Long.MaxValue}}//0, 0>E, 0>E>O
    memo(0)(0) = 0
    memo(1)(0) = 0
    memo(2)(0) = 0
    def M(i: Int): Long = {
      if (memo(2)(i) == Long.MaxValue){
          memo(2)(i) = List(M(i - 1) + (ears(i - 1) + 1) % 2, E(i - 1) + (if (ears(i - 1) == 0) 1 else 0), Z(i - 1)).min
      }
      memo(2)(i)
    }
    def E(i: Int): Long = {
      if (memo(1)(i) == Long.MaxValue) {
          memo(1)(i) = List(E(i - 1) + (if (ears(i - 1) == 0) 2 else ears(i - 1) % 2), Z(i - 1) + ears(i - 1) % 2).min
      }
      memo(1)(i)
    }
    def Z(i: Int): Long = {
      if (memo(0)(i) == Long.MaxValue) {
        memo(0)(i) = Z(i - 1) + ears(i - 1)
      }
      memo(0)(i)
    }
    val reversed = Array.tabulate(3){_ ⇒ Array.tabulate(ears.length + 1){_ ⇒ Long.MaxValue}}
    reversed(0)(0) = 0
    reversed(1)(0) = 0
    reversed(2)(0) = 0
    def MR(i: Int): Long = {
      if (reversed(2)(i) == Long.MaxValue) {
        reversed(2)(i) = List(MR(i - 1) + (ears(ears.length - i) + 1) % 2, ER(i - 1) + (if (ears(ears.length - i) == 0) 1 else 0), ZR(i - 1)).min
      }
      reversed(2)(i)
    }
    def ER(i: Int): Long = {
      if (reversed(1)(i) == Long.MaxValue) {
        reversed(1)(i) = List(ER(i - 1) + (if (ears(ears.length - i) == 0) 2 else ears(ears.length - i) % 2), ZR(i - 1) + ears(ears.length - i) % 2).min
      }
      reversed(1)(i)
    }
    def ZR(i: Int): Long = {
      if (reversed(0)(i) == Long.MaxValue) {
        reversed(0)(i) = ZR(i - 1) + ears(ears.length - i)
      }
      reversed(0)(i)
    }
    for (i ← 0 to ears.length by 3000) {
      M(i)
      MR(i)
    }
    M(ears.length); MR(ears.length)
    (0 to ears.length).map(i ⇒ M(i) + MR(ears.length - i)).min
  }
  implicit class Scope[T](val value: T) extends AnyVal {
    @inline def also(@inline func: T ⇒ Unit): T = {
      func(value)
      value
    }
    @inline def let[A](@inline func: T ⇒ A): A = func(value)
  }
}

