    val N = ni()
    val A = na(N)
    val dp = Array.fill[Long](5, N + 1)(1e18.toLong)
    dp(0)(0) = 0

    // 01234
    // 02120 これの部分文字列がありえる状態って感じ
    REP(N) { i =>
      dp(0)(i + 1) = dp(0)(i) + A(i) //0 -> 0 全部取り除く必要がある

      // 1, 3の遷移のとき、0の場合は最低2必要ってのに注意。2のときは最低1必要
      dp(1)(i + 1) = reduceDimFlip(dp, i, 2)(min) + (if (A(i) == 0) 2 else A(i)%2) // 0, 1 -> 1 奇数の場合は１こ取り除く
      dp(2)(i + 1) = reduceDimFlip(dp, i, 3)(min) + (if (A(i) == 0) 1 else A(i)%2^1) // 0, 1, 2 -> 2 偶数の場合は１こ取り除く
      dp(3)(i + 1) = reduceDimFlip(dp, i, 4)(min) + (if (A(i) == 0) 2 else A(i)%2) // 0, 1, 2, 3 -> 3 奇数の場合は１こ取り除く
      dp(4)(i + 1) = reduceDimFlip(dp, i, 5)(min) + A(i)  //0, 1, 2, 3, 4 -> 4 全部取り除く必要がある
    }

    debugDimFlip(dp)

    val ans = dp.map(_(N)).min
