//    debug("L_io")
//    debug(l_io)
//    debug("R_i")
//    debug(r_i)
//    debug("R_io")
//    debug(r_io)

    // 0-Nで、ここからはじめたらってのを全羅列する
    val ans = map(N + 1) { i =>
      min(l_io(i) + r_i(i), r_io(i) + l_i(i))
    }.min

    out.println(ans)
  }


