// idx, (未処理, 偶数左, 奇数, 偶数右)
const int VARI = 5;
int dp[200010][VARI];

signed main() {
  int N;
  cin >> N;
  vec<int> v(N);
  rep (i, N) {
    cin >> v[i];
  }

  const int one = 0; // 左のゼロ区間
  const int two = 1; // 右のゼロ区間
  const int three = 2; // 左の偶数区間
  const int four = 3; // 右の偶数区間
  const int five = 4; // 奇数区間

  // 初期化
  fill(dp[0], dp[N+1], INF);
  dp[0][one] = 0;
  dp[0][two] = 0;
  dp[0][three] = 0;
  dp[0][four] = 0;
  dp[0][five] = 0;

  // DP
  rep (i, N) {
    // 左のゼロ区間
    chmin(dp[i+1][one], dp[i][one] + v[i]);

    // 左の偶数区間
    int cost1 = (v[i] == 0 ? 2 : (v[i] % 2));
    chmin(dp[i+1][two], min(dp[i][two], dp[i][one]) + cost1);

    // 奇数
    int cost3 = 1 - (v[i] % 2);
    int mi = min({dp[i][two], dp[i][three], dp[i][one]});
    chmin(dp[i+1][three], mi + cost3);

    // 右の偶数区間
    int cost2 = (v[i] == 0 ? 2 : (v[i] % 2));
    chmin(dp[i+1][four], min({dp[i][three], dp[i][four], dp[i][one], dp[i][two]}) + cost2);


    // 未処理右
    int mi2 = min({dp[i][two], dp[i][four], dp[i][three], dp[i][five], dp[i][one]});
    chmin(dp[i+1][five], mi2 + v[i]);
  }

  int ans = INF;
  rep (i, VARI) {
    chmin(ans, dp[N][i]);
  }

  cout << ans << endl;

  return 0;
}

