        int tmp2 = cnt2 + A[pt2 - 1];
        if (tmp1 <= tmp2) {
            cnt1 += (A[pt1 + 1] % 2 == 0);
            pt1++;
        } else {
            cnt2 += A[pt2 - 1];
            pt2--;
        }
    }

    int ret = LLONG_MAX;
    int cnt3 = 0;
    rep(now, L) {
        int val = cnt1 + cnt2 + cnt3;
        ret = min(ret, val);

        //cerr << "now:" << now << " pt1:" << pt1 << " pt2:" << pt2 << " cnt1:" << cnt1 << " cnt2:" << cnt2 << " cnt3:" << cnt3 << " val:" << val << endl;

        if (now == L - 1) break;
        cnt1 -= (A[now + 1] % 2 == 0);
        cnt3 += A[now];
        while (pt1 < L - 1 && pt2 < L - 1 && cnt1 + (A[pt1 + 1] % 2 == 0) <= cnt2 - A[pt2]) {
            cnt1 += (A[pt1 + 1] % 2 == 0);
            cnt2 -= A[pt2];
            pt1++;
            pt2++;
        }
        if (cnt1 < 0) break;
    }

    return ret;
}

int solve2(int L, vector<int> &A) {
    vector<int> sum1_1(L + 1), sum1_2(L + 1), sum2_1(L + 1), sum2_2(L + 1);

    bool flag = false;
    bool firstEven = false;
    rep(i, L) {
        if (!flag && A[i]) {
            flag = true;
            firstEven = A[i] % 2 == 0;
        }
        sum1_1[i + 1] = sum1_1[i] + A[i];
        sum1_2[i + 1] = sum1_2[i] + (flag && (A[i] % 2 == 0 || A[i] == 0));
    }
    flag = false;
    for (int i = L - 1; i >= 0; i--) {
        if (A[i]) flag = true;
        sum2_1[i] = sum2_1[i + 1] + A[i];
        sum2_2[i] = sum2_2[i + 1] + (flag && (A[i] % 2 == 1 || A[i] == 0));
    }
    if (firstEven) {
        rep(i, L) {
            sum1_2[i + 1] = max(0LL, sum1_2[i + 1] - 1);
        }
    }

    //cerr << "sum1_1: ";
    //rep(i, L + 1) cerr << sum1_1[i] << " ";
    //cerr << endl;
    //cerr << "sum1_2: ";
    //rep(i, L + 1) cerr << sum1_2[i] << " ";
    //cerr << endl;
    //cerr << "sum2_1: ";
    //rep(i, L + 1) cerr << sum2_1[i] << " ";
    //cerr << endl;
    //cerr << "sum2_2: ";
    //rep(i, L + 1) cerr << sum2_2[i] << " ";
    //cerr << endl;

    int ret = LLONG_MAX;
    rep(i, L + 1) {
        ret = min(ret, min(sum1_1[i], sum1_2[i]) + min(sum2_1[i], sum2_2[i]));
        //cerr << "i:" << i << " val:" << min(sum1_1[i], sum1_2[i]) + min(sum2_1[i], sum2_2[i]) << endl;
    }

    //cerr << " return " << ret << endl;
    //cerr << "---" << endl;

    return ret;
}

