struct segmentTree{

    int N;
    vector<int> node;
    vector< pair<long long, int> > mini, maxi;
    vector<long long> sum;
    const long long INF = 2e18;

    void init(int siz){
        N = 1;
        while(N < siz){
            N <<= 1;
        }
        mini.resize(N * 2 - 1, {INF, -1});
        maxi.resize(N * 2 - 1, {-INF, -1});
        sum.resize(N * 2 - 1);
        return;
    }

    void build(vector<long long> &dat){
        for(int i = 0, len = dat.size() ; i < len ; ++i){
            mini[i + N - 1] = {dat[i], i};
            maxi[i + N - 1] = {dat[i], i};
            sum[i + N - 1] = dat[i];
        }
        for(int i = N - 2 ; i >= 0 ; --i){
            mini[i] = min(mini[i * 2 + 1], mini[i * 2 + 2]);
            maxi[i] = max(maxi[i * 2 + 1], maxi[i * 2 + 2]);
            sum[i] = sum[i * 2 + 1] + sum[i * 2 + 2];
        }
    }

    void update(int k, long long x){
        k += N - 1;
        mini[k].first = x;
        maxi[k].first = x;
        sum[k] = x;
        while(k > 0){
            k = (k - 1) / 2;
            mini[k] = min(mini[k * 2 + 1], mini[k * 2 + 2]);
            maxi[k] = max(maxi[k * 2 + 1], maxi[k * 2 + 2]);
            sum[k] = sum[k * 2 + 1] + sum[k * 2 + 2];
        }
    }

    pair<long long, int> getMin(int a, int b, int k, int l, int r){
        if(r <= a || b <= l){
            return {INF, -1};
        }
        if(a <= l && r <= b){
            return mini[k];
        }
        pair<long long, int> vl = getMin(a, b, k * 2 + 1, l, (l + r) / 2);
        pair<long long, int> vr = getMin(a, b, k * 2 + 2, (l + r) / 2, r);
        return min(vl, vr);
    }

    pair<long long, int> getMin(int a, int b){
        return getMin(a, b, 0, 0, N);
    }

    pair<long long, int> getMax(int a, int b, int k, int l, int r){
        if(r <= a || b <= l){
            return {-INF, -1};
        }
        if(a <= l && r <= b){
            return maxi[k];
        }
        pair<long long, int> vl = getMax(a, b, k * 2 + 1, l, (l + r) / 2);
        pair<long long, int> vr = getMax(a, b, k * 2 + 2, (l + r) / 2, r);
        return max(vl, vr);
    }

    pair<long long, int> getMax(int a, int b){
        return getMax(a, b, 0, 0, N);
    }

    long long getSum(int a, int b, int k, int l, int r){
        if(r <= a || b <= l){
            return 0LL;
        }
        if(a <= l && r <= b){
            return sum[k];
        }
        long long vl = getSum(a, b, k * 2 + 1, l, (l + r) / 2);
        long long vr = getSum(a, b, k * 2 + 2, (l + r) / 2, r);
        return vl + vr;
    }

    long long getSum(int a, int b){
        return getSum(a, b, 0, 0, N);
    }

};

int main(){
    cin.tie(0);
    ios::sync_with_stdio(false);

    cin >> l;

    a.resize(l + 1);
    REP(i, 1, l + 1){
        cin >> a[i];
    }
    sum.resize(l + 1);
    REP(i, 1, l + 1){
        sum[i] = sum[i - 1] + a[i];
    }
    o.resize(l + 1);
    e.resize(l + 1);
    z.resize(l + 1);
    REP(i, 1, l + 1){
        if(a[i] == 0){
            z[i] = 1;
        }else if(a[i] % 2 == 0){
            e[i] = 1;
        }else{
            o[i] = 1;
        }
        o[i] += o[i - 1];
        e[i] += e[i - 1];
        z[i] += z[i - 1];
    }

    int left = l, right = 0;
    lint dif = LLINF;
    rep(i, l + 1){
        if(chmin(dif, sum[l] - sum[i] - z[l] + z[i])){
            right = i;
        }
    }
    dif = LLINF;
    repr(i, l + 1){
        if(chmin(dif, sum[i] - z[i])){
            left = i;
        }
    }

    vector<lint> v(l + 1);
    rep(i, l + 1){
        v[i] = e[i] - o[i] - z[i];
    }

    segmentTree seg;
    seg.init(l + 1);
    seg.build(v);

    lint ans = LLINF;
    REP(i, left, right + 1){
        lint le, mi, ri;
        le = o[i] - o[left] + (z[i] - z[left]) * 2LL;
        int k = seg.getMin(i - 1, right).second;
        mi = e[k] - e[i] + z[k] - z[i];
        ri = o[right] - o[k] + (z[right] - z[k]) * 2LL;
        chmin(ans, le + mi + ri);
    }
    ans += sum[left] + sum[l] - sum[right];

    cout << ans << endl;

    return 0;
}

