// i 番目を見ていて、現在の状態が state のときの最小値
// 0: 何もしない
// 1: 2 以上の偶数は 0
// 2: 奇数は 0
// 3: 2 以上の偶数は 0
// 4: 何もしない
ll dfs(ll i, ll state) {
    if(i >= L) { return 0; }

    ll& ret = dp[i][state];
    if(~ret) { return ret; }
    ret = LLINF;

    ll cost = 0;
    if(state == 0 || state == 4) {
        cost = A[i];
    }
    else if(state == 1 || state == 3) {
        if(A[i] == 0) { cost = 2; }
        else if(A[i] % 2 != 0) { cost = 1; }
    }
    else {
        if(A[i] % 2 == 0) { cost = 1; }
    }
    for(int j = 0; j + state < 5; ++j) {
        ret = min(ret, dfs(i + 1, state + j) + cost);
    }
    return ret;

}

ll solve() {
    MINUS(dp);
    return min({dfs(0, 0), dfs(0, 1), dfs(0, 2), dfs(0, 3), dfs(0, 4)});
