void solve(long long L, vector<long long> A){
  vector< vector<long long> > dp(L, vector<long long>(5, 0));
  vector<long long> a = {0, 2, 1, 2, 0};
  for (int i = 0; i < 5; i++) {
    switch (i) {
      case 0:
        dp[0][i] = - A[0];
        break;
      case 1:
        dp[0][i] = - (abs(A[0]-2)%2);
        break;
      case 2:
        dp[0][i] = - (abs(A[0]-1)%2);
        break;
      case 3:
        dp[0][i] = - (abs(A[0]-2)%2);
        break;
      case 4:
        dp[0][i] = - A[0];
        break;
    }
  }
  for (int i = 1; i < L; i++) {
    for (int j = 0; j < 5; j++) {
      if (j == 0 || j == 4) {
        dp[i][j] = *max_element(dp[i-1].begin(), dp[i-1].begin()+1+j) - A[i];
      } else {
        if (A[i] == 0) {
          dp[i][j] = *max_element(dp[i-1].begin(), dp[i-1].begin()+1+j) - abs(A[i]-a[j]);
        } else {
          dp[i][j] = *max_element(dp[i-1].begin(), dp[i-1].begin()+1+j) - (abs(A[i]-a[j])%2);
        }
      }
    }
  }
  std::cout << - *max_element(dp[L-1].begin(), dp[L-1].end()) << std::endl;
}

int main(){
  long long L;
  scanf("%lld",&L);
  vector<long long> A(L);
  for(int i = 0 ; i < L ; i++){
    scanf("%lld",&A[i]);
  }
  solve(L, A);
  return 0;
}

