constexpr ll TEN(int n) { return (n == 0) ? 1 : 10 * TEN(n - 1); }
template <class T> using V = vector<T>;
template <class T> using VV = V<V<T>>;


using A = array<ll, 3>;

V<A> solve(V<ll> a) {
    int n = int(a.size());
    V<A> dp(n + 1, A{});
    for (int i = 0; i < n; i++) {
        dp[i+1][0] = dp[i][0] + a[i];
        dp[i+1][2] = min(dp[i][0], dp[i][2]) + (a[i] == 0 ? 2 : a[i] % 2);
        dp[i+1][1] = min({dp[i][0], dp[i][2], dp[i][1]}) + 1 - a[i] % 2;
    }
    return dp;
}

int main() {
