    reverse(a.begin(), a.end());
    auto s2 = solve(a);
    reverse(s2.begin(), s2.end());
    ll mi = TEN(18);

    for (int i = 0; i < n; i++) {
        for (int x = 0; x < 9; x++) {
            mi = min(mi, s1[i][x/3] + s2[i][x%3]);
        }
    }
    cout << mi << endl;
    return 0;
}

