    // init
    for (int i = 0; i < 5; i++) {
        ll temp = A[0];
        if (i != 0 && i != 4 && A[0] == 0) continue;
        if (i == 1 || i == 3) temp = (A[0] % 2 == 1);
        if (i == 2) temp = (A[0] % 2 == 0);
        dp[0][i] = temp;
    }
    auto transition = [&](int now) {
        for (int i = 0; i < 5; i++) {
            ll before = INFLL;
            for (int j = 0; j <= i; j++) {
                before = min(before, dp[now - 1][j]);
            }
            ll temp = A[now];
            if (i != 0 && i != 4 && A[now] == 0) continue;
            if (i == 1 || i == 3) temp = (A[now] % 2 == 1);
            if (i == 2) temp = (A[now] % 2 == 0);
            dp[now][i] = min(dp[now][i], before + temp);
        }
    };
    for (int i = 1; i < L; i++) transition(i);
    ll ans = INFLL;
    for (int i = 0; i < 5; i++) ans = min(ans, dp[L - 1][i]);
    cout << ans << endl;
}

