const int MAXN = 2e5+10;
const i64 INF = 0x7fffffffffffffff;
i64 n, ar[MAXN], ps[MAXN];
i64 t1[MAXN], t2[MAXN], dp[MAXN]; // [..i] (i..]
void input() {
	cin >> n;
	FOR(i, 0, n) cin >> ar[i], ps[i] = (i == 0 ? 0 : ps[i-1]) + ar[i];
	ps[n] = ps[n-1];
}

i64 rs(int s, int e) {
	if(e < 0) return 0;
	return ps[e] - (s == 0 ? 0 : ps[s-1]);
}

i64 gettour1(i64 x) {
	if(x == 0) return 2;
	if(x % 2) return 1;
	return 0;
}

i64 getstr(i64 x) {
	if(x == 0) return 1;
	if(x % 2) return 0;
	return 1;
}

int solve() {
	FOR(i, 0, n) {
		t1[i] = min((i == 0 ? 0 : t1[i-1]) + gettour1(ar[i]), rs(0, i-1) + ar[i]%2); // 이전꺼까지 투어하던가, 여기서 끊던가
	}
	RFOR(i, n-2, 0) {
		t2[i] = min(t2[i+1] + gettour1(ar[i+1]), rs(i+2, n) + ar[i+1]%2);
	}
	i64 ans = INF;
	FOR(i, 0, n) {
		// 이전에서 오는 경우 (직선)
		dp[i] = (i == 0 ? 0 : dp[i-1]) + getstr(ar[i]);
		// 새로 만들어지는 경우 (투어)
		dp[i] = min(dp[i], t1[i]);
		ans = min(ans, dp[i] + t2[i]);
	}
	cout << ans << ENDL;
	return 0;
}

