void solve(const vector<ll> &a, vector<int> &dp0, vector<int> &dp1){
  const int n = a.size();
  ll sum = 0;
  REP(i,n){
    dp0[i + 1] = dp0[i] + (a[i] == 0 ? 2 : a[i] % 2);
    dp1[i + 1] = dp1[i] + ((a[i] + 1) % 2);

    dp0[i + 1] = min<ll>(dp0[i + 1], sum + a[i] % 2);
    sum += a[i];
  }
}

