template <class T> struct PSA : public std::vector<T> {
	PSA(const std::vector<T>& v) : std::vector<T>(v.size() + 1) {
		std::partial_sum(begin(v), end(v), begin(*this) + 1);
	}

	T operator()(size_t l, size_t r) const { // [l, r)
		return (*this)[r] - (*this)[l];
	}
};

template <class T> std::vector<T> read(int n) {
	std::vector<T> res(n);
	for (auto& r : res) {
		std::cin >> r;
	}

	return res;
}

int L;
std::vector<i64> A, dpf, dpg;
PSA<i64> sum(A);

// min score to clear [0, i] and come back to i - 1
i64 g(int i) {
	if (i == 0) return 0;
	if (dpg[i] != -1) return dpg[i];

	i64 ans = sum(0, i);

	if (A[i - 1] == 0) {
		ans = std::min(ans, 2 + g(i - 1));
	} else if (A[i - 1] == 1) {
		ans = std::min(ans, 1 + g(i - 1));
	} else if (A[i - 1] % 2 == 0) {
		ans = std::min(ans, g(i - 1));
	} else if (A[i - 1] % 2 == 1) {
		ans = std::min(ans, 1 + g(i - 1));
	} else {
		assert(0);
	}

	return dpg[i] = ans;
}

// min score to clear [0, i]
i64 f(int i) {
	if (i == 0) return 0;
	if (dpf[i] != -1) return dpf[i];

	i64 ans = sum(0, i);
	if (A[i - 1] % 2 == 1) {
		ans = std::min(ans, f(i - 1));
	} else if (A[i - 1] == 0) {
		ans = std::min(ans, 1 + f(i - 1));
	} else if (A[i - 1] % 2 == 0) {
		ans = std::min(ans, std::min(1 + f(i - 1), g(i - 1)));
	} else {
		assert(0);
	}

	return dpf[i] = ans;
}

