namespace SEG
{
	ll Min[N << 2];
	void init() { memset(Min, 0x3f, sizeof Min); }
	void update(int id, int l, int r, int pos, ll val)
	{
		if (l == r)
		{
			Min[id] = val;
			return;
		}
		int mid = (l + r) >> 1;
		if (pos <= mid) update(id << 1, l, mid, pos, val);
		else update(id << 1 | 1, mid + 1, r, pos, val);
		Min[id] = min(Min[id << 1], Min[id << 1 | 1]);
	}
	ll query(int id, int l, int r, int ql, int qr)
	{
		if (ql < 1 || qr > n) return 0;
		if (l >= ql && r <= qr) return Min[id];
		int mid = (l + r) >> 1;
		ll res = (ll)0;
		if (ql <= mid) res = min(res, query(id << 1, l, mid, ql, qr));
		if (qr > mid) res = min(res, query(id << 1 | 1, mid + 1, r, ql, qr));
		return res;
	}
}

