		for (int i = n; i >= 1; --i)   
		{
			base += 2 - b[i];
			SEG::update(1, 1, n, i, a[i] - (2 - b[i]) + SEG::query(1, 1, n, i + 1, i + 1));
		}
		res = min(res, base + SEG::query(1, 1, n, 1, n));
		for (int i = 1; i <= n; ++i)
