			base += 1 - b[i] % 2;
			SEG::update(1, 1, n, i, a[i] - (1 - b[i] % 2) + SEG::query(1, 1, n, i - 1, i - 1));
			res = min(res, base + SEG::query(1, 1, n, i + 1, n) + SEG::query(1, 1, n, 1, i)); 	
