	FOR(i,0,blk[id].size()){
		if(blk[id][i]&1) --cnt;
		else ++cnt;
		l[id]=max(l[id],cnt);
	}
	cnt=0;
	for(int i=blk[id].size()-1;i>=0;--i){
		if(blk[id][i]&1) --cnt;
		else ++cnt;
		r[id]=max(r[id],cnt);
	}
	cnt=0;
	int dp[maxn]={};
	FOR(i,0,blk[id].size()){
		if(blk[id][i]&1) dp[i]=-1,--cnt;
		else dp[i]=1,++cnt;
		if(i) dp[i]=min(dp[i],dp[i-1]+dp[i]);
	}
	FOR(i,0,blk[id].size()) b[id]=max(b[id],cnt-dp[i]);
//	printf("%d\n",b[id]);
	return;
}

