}

int t[200100];
int lowbit(int x){
	return x&(-x);
}
int add(int x,int y){
	while(x<=200000){
		t[x]=min(y,t[x]);
		x+=lowbit(x);
	}
}

int query(int x){
	int ans=4000000;
	if(x==0) return 0;
	while(x){
		ans=min(ans,t[x]);
		x-=lowbit(x);
	}
	return ans;
}
