ll cal(vector<ll>v){
    ll n=v.size();
    ll a[n+1];rep(i,0,n-1)a[i+1]=v[i]%2;
    ll dp[n+1][3];//rep(i,0,n)rep(j,0,2)dp[i][j]=inf;
