#define dmin(a,b) (a = min(a, b))

ll zero_count(const vl& a) {
    return a[0] == 0 ? a.size() : 0LL;
}

ll sum_value(const vl& a) {
    return accumulate(all(a), 0LL);
}

ll waste_count(vl a, bool start=false, bool end=false) {
    ll n = a.size(), odd_cnt = 0;
    rep(i,n) odd_cnt += a[i] % 2;
    ll even_cnt = n - odd_cnt;

    if (start and end) {
        ll mx = 1e9, cnt = 0;
        rep(i,n) {
            if (a[i] % 2 == 0) dmin(mx, odd_cnt-cnt), cnt = 0;
            else cnt++;
        }
        if (cnt) dmin(mx, odd_cnt-cnt);
        return mx;
    }
    ll res = even_cnt;
    if (start or end) {
        if (end) reverse(all(a));
        ll cnt = 0;
        rep(i,n) {
            if (a[i] % 2) cnt++, odd_cnt--;
            else even_cnt--;
            dmin(res, even_cnt + cnt);
        }
    }
    return res;
}

int main() {
    ll L; cin >> L;
    vl a(L); rep(i,L) scanf("%lld", &a[i]);

    ll pre = 0, N = 0;
    vvl as;
    rep(i,L) {
        if ((pre == 0) xor (a[i] == 0)) {
            as.push_back(vl());
            pre = a[i];
            N++;
        }
        if (N > 0) as[N-1].push_back(a[i]);
    }
    if (N == 0) { cout << 0 << endl; return 0; }

    ll sum = 0, used = 0, rest;
    rep(i,L) sum += a[i];
    ll ans = rest = sum, pre_waste = waste_count(as[0],1,0);
    for (int i = 0; i < N; i += 2) {
        ll now = sum_value(as[i]);
        rest -= now;
        dmin(ans, used + waste_count(as[i],1,1) + rest);
        if (i > 1) {
            dmin(ans, pre_waste + zero_count(as[i-1]) + waste_count(as[i],0,1) + rest);
            ll a = pre_waste + zero_count(as[i-1]) + waste_count(as[i],0,0);
            ll b = used + waste_count(as[i],1,0);
            pre_waste = min(a, b);
        }
        used += now;
    }
    cout << ans << endl;
    return 0;
}

