int cost(int i, int s, const vector<int> &A){
    if(s == 0 || s == 4) return A[i];
    else if(s == 1 || s == 3){
        if(A[i] % 2 == 0) return (A[i] == 0 ? 2 : 0);
        else return 1;
    }else{
        if(A[i] % 2 == 0) return 1;
        else return 0;
    }
