constexpr ll inf = 1e18;

ll solve(vector<ll> a) {
    const int n = a.size();
    vector<vector<ll>> dp(n + 1, vector<ll>(5, inf));
    dp[0][0] = 0;
    for(int i = 0; i < n; ++i) {
        dp[i + 1][0] = dp[i][0] + a[i];
        dp[i + 1][1] = min(dp[i][0], dp[i][1]) + (a[i] == 0 ? 2 : (a[i] & 1));
        dp[i + 1][2] = min({dp[i][0], dp[i][1], dp[i][2]}) + (a[i] % 2 == 0);
        dp[i + 1][3] = min({dp[i][0], dp[i][1], dp[i][2], dp[i][3]}) + a[i];
    }

    return *min_element(begin(dp[n]), end(dp[n]));
}

