ll mx1[300500], mx2[300500], mx3[300500];
ll solve(){
    repp(i,N) Z[i] = S[i] = E[i] = O[i] = 0;
    rep(i,N+2) mx1[i] = mx2[i] = mx3[i] = -1e15;
    repp(i,N){
        S[i] = S[i-1] + p[i];
        O[i] = O[i-1] + ((p[i]%2==1)?1:0);
        E[i] = E[i-1] + ((p[i]%2==0&&p[i]!=0)?1:0);
        Z[i] = Z[i-1] + ((p[i]==0)?1:0);
    }
    rep(i,N+1){
        if( i == 0 ) mx1[i] = 2*Z[i] + O[i] - S[i];
        else mx1[i] = max(mx1[i-1],  2*Z[i] + O[i] - S[i]);
        if( i == 0 ) mx3[i] = (Z[i]+E[i]) - (2*Z[i]+O[i]-mx1[i]);
        else mx3[i] = max(mx3[i-1], (Z[i]+E[i]) - (2*Z[i]+O[i]-mx1[i]));
    }
    for(int i=N;i>=1;i--){
        if( i == N ) mx2[i] = S[i]-O[i]-2*Z[i];
        else mx2[i] = max(mx2[i+1], S[i]-O[i]-2*Z[i]);
    }
    //repp(i,N) Debug(i, mx1[i], mx2[i], mx3[i]);
    ll ans = 1e18;
