            dp[i + 1][j] = min(dp[i + 1][j], min_num(dp[i], j) + add_cost);
        }
    }

    int ans = INF;
    REP(i, 5) {
        ans = min(ans, dp[n][i]);
    }

#if DEBUG
    cout << "** RESULT **" << endl; // debug
#endif
    cout << ans << endl;
    return 0;
}

