const int INF = INT_MAX / 2;

long long solve(const vector<int>& a)
{
    int n = a.size();
    vector<long long> dp(5, 0);
    for(int i=0; i<n; ++i){
        vector<long long> nextDp(5, INF);
        long long tmp = dp[0];
        nextDp[0] = tmp + a[i];

        tmp = min(tmp, dp[1]);
        nextDp[1] = tmp + (a[i] == 0 ? 2 : a[i] % 2);

        tmp = min(tmp, dp[2]);
        nextDp[2] = tmp + ((a[i] + 1) % 2);

        tmp = min(tmp, dp[3]);
        nextDp[3] = tmp + (a[i] == 0 ? 2 : a[i] % 2);

        tmp = min(tmp, dp[4]);
        nextDp[4] = tmp + a[i];

        dp = move(nextDp);
    }
    return *min_element(dp.begin(), dp.end());
}

