int solve(int N, int k)
{
    if(N == 0)
        return 0;

    if(dp[N][k] != -1)
        return dp[N][k];

    int ans = inf;

    if(k == 4)
    {
        if(A[N] == 0)
            ans = solve(N-1, k);
        else if(A[N] % 2 == 1)
            ans = min(solve(N-1, 4) + A[N], min(solve(N-1, 2), solve(N-1, 3) + 1));
        else
            ans = min(solve(N-1, 4) + A[N], min(solve(N-1, 3), solve(N-1, 2) + 1));
    }
    else if(k == 3)
    {
        if(A[N] == 0)
            ans = min(solve(N-1, 0) + A[N], min(solve(N-1, 2) + 1, solve(N-1, 3) + 2));
        else if(A[N] % 2 == 1)
            ans = min(solve(N-1, 0) + A[N], min(solve(N-1, 2), solve(N-1, 3) + 1));
        else
            ans = min(solve(N-1, 0) + A[N], min(solve(N-1, 2) + 1, solve(N-1, 3)));
    }
    else if(k == 2)
    {
        if(A[N] == 0)
            ans = min(solve(N-1, 0) + A[N], min(solve(N-1, 1) + 2, solve(N-1, 2) + 1));
        else if(A[N] % 2 == 1)
            ans = min(solve(N-1, 0) + A[N], min(solve(N-1, 1) + 1, solve(N-1, 2)));
        else
            ans = min(solve(N-1, 0) + A[N], min(solve(N-1, 1), solve(N-1, 2) + 1));
    }
    else if(k == 1)
    {
        if(A[N] == 0)
            ans = min(solve(N-1, 0) + A[N], solve(N-1, 1) + 2);
        else if(A[N] % 2 == 1)
            ans = min(solve(N-1, 0) + A[N], solve(N-1, 1) + 1);
        else
            ans = min(solve(N-1, 0) + A[N], solve(N-1, 1));
    }
    else
        ans = solve(N-1, 0) + A[N];

    return dp[N][k] = min(ans, inf);
}

