const long long INF = 1e18;

struct SegmentTree {
private:
  int n;
  vector< long long > node;//min,max
public:
  SegmentTree(vector<long long> v, vector<long long> u){
    int sz = v.size();
    n = 1;
    while(n < sz) n *= 2;
    node.resize(2*n-1,INF);
    for(int i = 0; i < sz; ++i){
      node[i+n-1] = v[i];
      if(i > 0) node[i+n-1] += u[i-1];
    }
    for(int i = n-2; i >= 0; --i)
      node[i] = min(node[2*i+1],node[2*i+2]);
  }
  void update(int idx, int val){
    idx += n-1;
    node[idx] = val;
    while(idx > 0){
      idx = (idx-1)/2;
      node[idx] = min(node[2*idx+1],node[2*idx+2]);
    }
  }
  long long get_min(int a, int b, int k=0, int l=0, int r=-1){
    if(r < 0) r = n;
    if(r <= a or b <= l) return INF;
    if(a <= l and r <= b) return node[k];
    long long vl = get_min(a,b,2*k+1,l,(l+r)/2);
    long long vr = get_min(a,b,2*k+2,(l+r)/2,r);
    return min(vl,vr);
  }
};

