  for(int i = 0; i < L; ++i){
    long long t = A[i]%2;
    if(A[i] < 2) t = 2-A[i];
    F[i+1] = min(F[i]+t,C[i+1]);
  }
  for(int i = L-1; i >= 0; --i){
    long long t = A[i]%2;
