        //cerr << "now:" << now << " pt1:" << pt1 << " pt2:" << pt2 << " cnt1:" << cnt1 << " cnt2:" << cnt2 << " cnt3:" << cnt3 << " val:" << val << endl;

        if (now == L - 1) break;
        cnt1 -= (A[now + 1] % 2 == 0);
        cnt3 += A[now];
        while (pt1 < L - 1 && pt2 < L - 1 && cnt1 + (A[pt1 + 1] % 2 == 0) <= cnt2 - A[pt2]) {
            cnt1 += (A[pt1 + 1] % 2 == 0);
            cnt2 -= A[pt2];
            pt1++;
            pt2++;
        }
        if (cnt1 < 0) break;
    }

    return ret;
}

