	ll ans = 0, res = 0;
	scanf("%d", &n);
	for(int i = 1; i <= n; i++)
	{
		scanf("%d", &a[i]);
		ans += a[i];
		res += a[i];
		sum1[i] = sum1[i-1]+(a[i]&1);
		sum2[i] = i-sum1[i];
	}
	for(int i = 1; i <= n; i++)
	{
		ll det = 0;
		int j = i, cnt;
		while(j<=n&&a[j]>0)
		{
			det += a[j++];
		}
		if(i==j)
		{
			continue;
		}
		j--;
		cnt = min(query1(i, j), query2(i, j));
		for(int k = i; k < j; k++)
		{
			cnt = min(cnt, query1(i, k)+query2(k+1, j));
			cnt = min(cnt, query2(i, k)+query1(k+1, j));
		}
		cnt = min(cnt, dp(i, j));
		i = j;
		res = min(res, ans-det+cnt);
	}
	printf("%lld\n", res);
