	if (mem[pos][xx] != -1) return mem[pos][xx];

	long long tmp = sum;

	if (xx == 0) {
		tmp = min(tmp,pre[pos+1]);
		tmp = min(tmp,DP1(pos,1));

		int nyan;
		if (a[pos] % 2 == 1) nyan = 0; else nyan = 1;
		tmp = min(tmp,DP1(pos+1,xx) + nyan);

		return mem[pos][xx] = tmp;
	} else {
		int nyan;
		if (a[pos] % 2 == 1) nyan = 1; else
		if (a[pos] == 0) nyan = 2; else nyan = 0;

		tmp = min(tmp,pre[pos+1] + a[pos]%2);
		tmp = min(tmp,DP1(pos+1,xx) + nyan);

		return mem[pos][xx] = tmp;

	}
}

long long DP2(int pos, int xx) {
	if (pos == 0) return 0;
	if (mem[pos][xx] != -1) return mem[pos][xx];

	long long tmp = sum;

	if (xx == 0) {
		tmp = min(tmp,pre[pos-1]);
		tmp = min(tmp,DP2(pos,1));

		int nyan;
		if (a[pos] % 2 == 1) nyan = 0; else nyan = 1;
		tmp = min(tmp,DP2(pos-1,xx) + nyan);

		return mem[pos][xx] = tmp;
	} else {
		int nyan;
		if (a[pos] % 2 == 1) nyan = 1; else
		if (a[pos] == 0) nyan = 2; else nyan = 0;

		tmp = min(tmp,pre[pos-1] + a[pos]%2);
		tmp = min(tmp,DP2(pos-1,xx) + nyan);

		return mem[pos][xx] = tmp;

	}

}

int main() {
	scanf("%lld",&n);
	for (i=1 ; i<=n ; i++) {
		scanf("%lld",&a[i]);
		sum += a[i];
	}

	ans = sum;
	for (i=n ; i>=1 ; i--) {
		mem[i][0] = -1;
		mem[i][1] = -1;
		pre[i] = pre[i+1] + a[i];
	}

	ctr = 0;
	for (i=1 ; i<=n ; i++) {
		ans = min(ans,ctr+DP1(i,0));
		ans = min(ans,ctr+DP1(i,1));
		ctr += a[i];
	}

	for (i=1 ; i<=n ; i++) {
		mem[i][0] = -1;
		mem[i][1] = -1;
		pre[i] = pre[i-1] + a[i];
	}

	ctr = 0;
	for (i=n ; i>=1 ; i--) {
		ans = min(ans,ctr+DP2(i,0));	
		ans = min(ans,ctr+DP1(i,1));
		ctr += a[i];
	}

	printf("%lld\n",ans);
}

