      if (a[i]%2==0) chmin(dp[0][i], s[i-1]);  // return

      chmin(dp[1][i], dp[1][i-1] + (a[i]%2==0?0:1));
      chmin(dp[1][i], dp[0][i-1] + (a[i]%2==0?0:1));
      if (a[i]%2==0) chmin(dp[1][i], s[i-1]);  // return
    }

    // uadte res
    chmin(res, dp[1][i]+(s[L-1]-s[i]));
    chmin(res, dp[0][i]+(s[L-1]-s[i]));
  }

  dump_2d(dp, 2, L);
  cout << res << endl;

  return 0;
}

