using namespace std;
typedef long long lint;

const int MOD = 1000000007, INF = 1111111111;
const double EPS = 1e-9;

int main() {

	cin.tie(0);

	lint L;
	cin >> L;

	vector<lint> A(L);
	for (int i = 0; i < L; i++) cin >> A[i];

	// 座標をノードと考え、Aiをパスの数として1筆書きで消せるパスが最大になるときを求めればよい
	// 閉路ごとの合計のパスの数-(奇点ノードの数-2)が消せる最大数

	lint sum = 0, closed_sum = 0, prev_A = 0, odd_num = 0, max_elim = 0;

	for (int i = 0; i < L; i++){

		if (i > 0) prev_A = A[i - 1];
		sum += A[i];
		odd_num += (prev_A + A[i]) % 2;

		if (A[i] > 0) {

			closed_sum += A[i];
		}
		else {

			max_elim = max<lint>(max_elim, closed_sum - max<lint>(odd_num / 2 - 1, 0));

			closed_sum = 0;
			odd_num = 0;
		}
	}

	odd_num += A[L - 1] % 2;
	max_elim = max<lint>(max_elim, closed_sum - max<lint>(odd_num / 2 - 1, 0));

	cout << sum - max_elim;
	return 0;
}

