#define MOD 1000000007LL
#define INF (1LL<<60)
/*
L,S,E,H in [0, N]
[1, L] 0
(L, S] even, >0
(S, E] odd, >0
(E, H] even, >0
(H, N] 0
*/
int main() {
	cin.tie(0);
	ios::sync_with_stdio(false);
	ll N;
	while(cin>>N) {
		VI A(N);
		REP(i, N) cin>>A[i];
		VVI dp(N+1, VI(5, INF));
		REP(i, 5) dp[0][i] = 0;
		RANGE(i, 1, N+1) {
			// 0->0
			dp[i][0] = dp[i-1][0] + A[i-1];
			// 0,1->1
			dp[i][1] = *min_element(&dp[i-1][0], &dp[i-1][2]) + (A[i-1]==0 || (A[i-1]&1)==1);
			// 0,1,2->2
			dp[i][2] = *min_element(&dp[i-1][0], &dp[i-1][3]) + (A[i-1]==0 || (A[i-1]&1)==0);
			// 0,1,2,3->3
			dp[i][3] = *min_element(&dp[i-1][0], &dp[i-1][4]) + (A[i-1]==0 || (A[i-1]&1)==1);
			// 0,1,2,3,4->4
			dp[i][4] = *min_element(&dp[i-1][0], &dp[i-1][5]) + A[i-1];
		}
		ll ans = *min_element(ALL(dp[N]));
		cout<<ans<<endl;
	}

	return 0;
}

