using namespace std;

typedef long long ll;

ll EvenGain(ll x) {
  if (x < 2) return x - 2;
  return x - x % 2;
}

ll OddGain(ll x) {
  if (x == 0) return -1;
  x--;
  return 1 + x - x % 2;
}

void Debug(vector<ll> a, string name) {
  return;
  cerr << name << endl;
  for (int x : a) cerr << x << "\t";
  cerr << endl << endl;
}

int main()
{
  int n;
  cin >> n;
  vector<ll> a(n + 2);
  ll sum = 0;
  for (int i = 0; i < n; ++i) {
    cin >> a[i + 1];
    if (a[i + 1] > 4) a[i + 1] = a[i + 1] % 2 + 2;
    sum += a[i + 1];
  }

  //cerr << "sum = " << sum << endl;

  Debug(a, "a");

  vector<ll> sOdd(a.size());
  for (int i = 1; i <= n; ++i) sOdd[i] = sOdd[i - 1] + OddGain(a[i]);

  Debug(sOdd, "sOdd");

  vector<ll> sEvenLeft(a.size());
  for (int i = 1; i <= n; ++i) sEvenLeft[i] = sEvenLeft[i - 1] + EvenGain(a[i]);

  Debug(sEvenLeft, "sEvenLeft");

  vector<ll> sEvenRight(a.size());
  for (int i = n; i >= 1; --i) sEvenRight[i] = sEvenRight[i + 1] + EvenGain(a[i]);

  Debug(sEvenRight, "sEvenRight");

  vector<ll> L(a.size());
  for (int i = 1; i <= n; ++i) L[i] = min(L[i - 1], sEvenLeft[i]);

  Debug(L, "L");

  vector<ll> R(a.size());
  for (int i = n; i >= 1; --i) R[i] = min(R[i + 1], sEvenRight[i]);

  Debug(R, "R");

  vector<ll> Q(a.size());
  for (int i = 1; i <= n; ++i) Q[i] = max(Q[i - 1] , sEvenLeft[i] - L[i] - sOdd[i]);

  Debug(Q, "Q");

  ll result = 0;
  for (int i = 1; i <= n; ++i) {
    ll cur = sOdd[i] + Q[i] + sEvenRight[i + 1] - R[i + 1];
    //cerr << i << " " << cur << endl;
    result = max(result, cur);
  }

  cout << sum - result << endl;

  return 0;
}

