constexpr ll INF = 1e+16;

void solve(istream &cin) {
    ll L ;
    if (!(cin >> L)) { return; }
    vector<ll> A;
    ll sum = 0;
    for (int i = 0; i < L; ++i) {
        ll tmp;
        cin >> tmp;
        A.push_back(tmp);
        sum += tmp;
    } // end i
    vector<array<ll, 5>> dp(L+1);
    dp[0] = {0, 0, 0, 0, 0};
    for (int i = 0; i < L; ++i) {
        ll odd = A[i] % 2ll;
        ll even = A[i] % 2ll == 0;
        bool zero = A[i] == 0;
        dp[i+1][0] = dp[i][0] + A[i];
        dp[i+1][1] = min(dp[i][1], dp[i][0]) + (zero ? 2 : odd);
        dp[i+1][2] = min({dp[i][0], dp[i][1], dp[i][2]}) + even;
        dp[i+1][3] = min({dp[i][0], dp[i][1], dp[i][2], dp[i][3]}) +
                (zero? 2 : odd);
        dp[i+1][4] = min({dp[i][0], dp[i][1], dp[i][2], dp[i][3], dp[i][4]})
                          + A[i];
    } // end i
    cout << *min_element(dp.back().begin(), dp.back().end()) << endl;

}

int main(int argc, char *argv[]) {
    string FileName("D"), Modifier("MEPH_");
    string ExecutionName = Modifier + FileName;
    string sub(argv[0]);
    // /home/USER/.../MEPH_X -> MEPH_X
    if (sub.size() > ExecutionName.size())
        sub = sub.substr(sub.size() - ExecutionName.size(), ExecutionName.size());

    cout << setprecision(16) << scientific;
    if (sub != ExecutionName) {
        cin.tie(nullptr);
        ios::sync_with_stdio(false);
        while (cin) { solve(cin); }
    } else {
        cerr << sub << " test" << endl;
        string inFile = FileName + ".txt";
        auto fs = fstream(inFile, fstream::in);
        while (fs) { solve(fs); }
    }
}

