int main() {
	int L; cin >> L;
	vector<ll> a, lodd(L + 2), rodd(L + 2), leven(L + 2), reven(L + 2), sum(L + 2);
	for (int i = 0; i < L; i++) {
		ll b; cin >> b;
		if (a.empty() && b == 0) continue;
		a.push_back(b);
	}
	while (a.back() == 0) a.pop_back();
	L = a.size();
	for (int i = 0; i < L; i++) sum[i + 1] = sum[i] + a[i];
	for (int i = 0; i < L; i++) {
		lodd[i + 1] = lodd[i] + (a[i] % 2 == 1) + 2 * (a[i] == 0);
		leven[i + 1] = leven[i] + (a[i] % 2 == 0);
		if (lodd[i + 1] >= sum[i + 1]) lodd[i + 1] = sum[i + 1];
		if (leven[i + 1] >= sum[i + 1]) leven[i + 1] = sum[i + 1];
	}
	for (int i = L - 1; i >= 0; i--) {
		rodd[i + 1] = rodd[i + 2] + (a[i] % 2 == 1) + 2 * (a[i] == 0);
		reven[i + 1] = reven[i + 2] + (a[i] % 2 == 0);
		if (rodd[i + 1] >= sum[L] - sum[i]) rodd[i + 1] = sum[L] - sum[i];
		if (reven[i + 1] >= sum[L] - sum[i]) reven[i + 1] = sum[L] - sum[i];
	}

	ll ans = 1e18;
	for (int i = 0; i <= L; i++) {
		ll left = lodd[i], right = reven[i + 1];
		ans = min(ans, left + right);
		left = leven[i], right = rodd[i + 1];
		ans = min(ans, left + right);
	}
	cout << ans << endl;
	return 0;
}

