    for(int i=1;i<=n;++i)
    {
        if(a[i]%2==0)
        {
            if(a[i]==0)
                rr[i]=min(su,2+rr[i-1]);
            else
                rr[i]=min(su,rr[i-1]);
        }
        else
        {
            rr[i]=min(su+1,1+rr[i-1]);
        }
        su+=a[i];
    }
    int ans=inf;
    for(int i=0;i<=n;++i)
    {
        ans=min(ans,lr[i+1]+r[i]);
        ans=min(ans,rr[i]+l[i+1]);
    }
    cout<<ans;
}

#include <cstdio>
#include <cstdint>
#include <vector>
#include <algorithm>

int main() {
  size_t L;
  scanf("%zu", &L);
  std::vector<intmax_t> A(L);
  for (auto& ai: A) {
    scanf("%jd", &ai);
  }

  intmax_t INF = 1e15;
  std::vector<std::vector<intmax_t>> dp(L+1, std::vector<intmax_t>(6, INF));

  dp[0][0] = 0;
  for (size_t i = 1; i <= L; ++i) {
    {
      // unstarted
      dp[i][0] = std::min(dp[i][0], dp[i-1][0] + (A[i-1]));
    }
    {
      // starts from left
      dp[i][1] = std::min(dp[i][1], dp[i-1][0] + (1 - A[i-1] % 2));
      dp[i][1] = std::min(dp[i][1], dp[i-1][1] + (1 - A[i-1] % 2));
      dp[i][1] = std::min(dp[i][1], dp[i-1][2] + (1 - A[i-1] % 2));
    }
    {
      // starts from right
      int a = (A[i-1]? A[i-1]%2 : 2);
      dp[i][2] = std::min(dp[i][2], dp[i-1][0] + (a));
      dp[i][2] = std::min(dp[i][2], dp[i-1][2] + (a));
    }
    {
      // ends to right
      int a = (1 - A[i-1] % 2);
      dp[i][3] = std::min(dp[i][3], dp[i-1][1] + (a));
      dp[i][3] = std::min(dp[i][3], dp[i-1][2] + (a));
      // dp[i][3] = std::min(dp[i][3], dp[i-1][3] + (A[i-1]));
    }
    {
      // ends to left
      int a = (A[i-1]? A[i-1]%2 : 2);
      dp[i][4] = std::min(dp[i][4], dp[i-1][1] + (a));
      dp[i][4] = std::min(dp[i][4], dp[i-1][2] + (a));
      dp[i][4] = std::min(dp[i][4], dp[i-1][3] + (a));
      dp[i][4] = std::min(dp[i][4], dp[i-1][4] + (a));
      // dp[i][4] = std::min(dp[i][4], dp[i-1][4] + (A[i-1]));
    }
    {
      // ended
      dp[i][5] = std::min(dp[i][5], dp[i-1][0]);
      dp[i][5] = std::min(dp[i][5], dp[i-1][3] + A[i-1]);
      dp[i][5] = std::min(dp[i][5], dp[i-1][4] + A[i-1]);
      dp[i][5] = std::min(dp[i][5], dp[i-1][5] + A[i-1]);
    }
  }

  for (size_t j = 0; j < dp[0].size(); ++j)
    for (size_t i = 0; i <= L; ++i)
      fprintf(stderr, "%jd%c", dp[i][j], i<L? ' ':'\n');

  printf("%jd\n", *std::min_element(dp[L].begin(), dp[L].end()));
}

