const ll INF = LLONG_MAX/3;

struct SegTree{
    int n; vector<ll> dat;
    //初期化
    SegTree(int _n){
        n=1;
        while(n<_n) n*=2;
        dat=vector<ll>(2*n-1,INF);
    }
    //k番目(0-indexed)の値をaに変更
    void update(int k, ll a){
        k+=n-1;
        dat[k]=a;
        //更新
        while(k>0){
            k=(k-1)/2;
            dat[k]=min(dat[2*k+1],dat[2*k+2]);
        }
    }
    //内部的に投げられるクエリ
    ll _query(int a, int b, int k, int l, int r){
        if(r<=a || b<=l) return INF;

        if(a<=l && r<=b) return dat[k];

        ll vl=_query(a,b,2*k+1,l,(l+r)/2);
        ll vr=_query(a,b,2*k+2,(l+r)/2,r);
        return min(vl,vr);
    }
    //[a,b)の最大値を求める
    ll query(int a, int b){
        return _query(a,b,0,0,n);
    }
};


ll calc(const vector<ll> &a){
    int n = a.size();

    vector<ll> suf(n+1);
    for(int i=n-1; i>=0; --i) suf[i] = suf[i+1] + a[i];

    SegTree st(n+4);

    int ev = 0;
    rep(i,n){
        st.update(i,suf[i+1]+ev);
        if(a[i]%2==0) ++ev;
    }

    dbg(a);

    ll ret = INF;

    ll pre = 0;
    ll sub = 0;
    rep(i,n){
        ll mv = st.query(i,n+1);

        printf("%d: %lld + %lld - %lld\n",i,mv,pre,sub);
        ret = min(ret, mv+pre-sub);

        pre += a[i];
        if(a[i]%2==0) ++sub;
    }

    return ret;
}

int main(){
    int n;
    cin >>n;
    vector<ll> a(n);
    rep(i,n) cin >>a[i];

    vector<ll> e(n+1);
    rep(i,n){
        if(a[i]==0) e[i] = 2;
        else if(a[i]%2==1) e[i] = 1;
    }
    rep(i,n) e[i+1] += e[i];

    auto EV = [&](int r){
        if(r==0) return 0LL;
        return e[r-1];
    };

    vector<ll> o(n+1);
    rep(i,n){
        if(a[i]%2==0) o[i]++;
    }
    rep(i,n) o[i+1] += o[i];

    auto OD = [&](int r){
        if(r==0) return 0LL;
        return o[r-1];
    };

    vector<ll> dp(n+1,0);
    ll s = 0;
    rep(i,n){
        s += a[i];
        dp[i+1] = s;
    }
    // dbg(dp);

    // ev | od
    vector<ll> nx(n+1,INF);
    ll val = INF;
    rep(i,n+1){
        val = min(val, dp[i]-EV(i));
        nx[i] = min(nx[i], val+EV(i));
    }
    dp = nx;
    // dbg(dp);

    // od | ev
    nx = vector<ll>(n+1,INF);
    val = INF;
    rep(i,n+1){
        val = min(val, dp[i]-OD(i));
        nx[i] = min(nx[i], val+OD(i));
    }
    dp = nx;

    // ev | od
    nx = vector<ll>(n+1,INF);
    val = INF;
    rep(i,n+1){
        val = min(val, dp[i]-EV(i));
        nx[i] = min(nx[i], val+EV(i));
    }
    dp = nx;

    ll ans = INF;
    s = 0;
    for(int i=n; i>=0; --i){
        ans = min(ans, dp[i]+s);
        if(i>0) s += a[i-1];
    }
    cout << ans << endl;
    return 0;
}

