    For(i, 1, L + 1) {
        if (zero[i - 1]) pre += 2;
        pre2 += A[i - 1];
        if (A[i - 1] % 2 == 0) ST.update(0, i - 1, 1);
        else pre++;
        pre = min(pre, pre2);
        dp[i] = ST.query(0, i - 1);
        ST.update(i, i, pre);
    }
