			sum -= A[i];
			if (guki > 0) guki--;
		} else if (A[i] == 0) {
			sum++;
			if (guki > 0) guki--;
		} else {
			sum -= A[i]-1;
			guki++;
		}
		res = min(res, sum-guki);
	}

	printf("%lld\n", res);

	return 0;
}

