ll cost(ll state, ll target){
        if(state==0||state==4) return target;
        else if(state==2) return (target&1)?0:1;
        else return (target)?target%2:2;
}

int main() {
    int L; cin>>L;
    vector<ll> A(L+1);
    for (int i = 0; i < L; i++) cin>>A[i]; A[L]=0;
    vector<vector<ll>>dp(L+2, vector<ll>(5, INF));
    fill(dp[0].begin(), dp[0].end(), 0);

    for(int i = 1; i <= L+1; i++)
    {
        for(int j = 0; j < 5; j++)
        {
