// 2 : そもそも行かない
li dp[200200][3];

inline li solve(const vector<li>& a) {
    sum[0] = 0;
    rin{
        sum[i + 1] = sum[i] + a[i];
    }

    if (a[n - 1] == 0) {
        dp[n - 1][0] = 1;
        dp[n - 1][1] = 2;
        dp[n - 1][2] = 0;
    } else if (a[n - 1] % 2 > 0) {
        // odd
        dp[n - 1][0] = 0;
        dp[n - 1][1] = 1;
        dp[n - 1][2] = a[n - 1];
    } else {
        // even
        dp[n - 1][0] = 1;
        dp[n - 1][1] = 0;
        dp[n - 1][2] = a[n - 1];
    }

    for (li i = n - 2; i >= 0; i--) {
        if (a[i] == 0) {
            dp[i][0] = 1 + min(dp[i + 1][0], min(dp[i + 1][1], dp[i + 1][2]));
            dp[i][1] = 2 + min(dp[i + 1][1], dp[i + 1][2]);
            dp[i][2] = dp[i + 1][2] + a[i];
        } else if (a[i] % 2 > 0) {
            // odd
            dp[i][0] = min(dp[i + 1][0], min(dp[i + 1][1], dp[i + 1][2]));
            dp[i][1] = 1 + min(dp[i + 1][1], dp[i + 1][2]);
            dp[i][2] = dp[i + 1][2] + a[i];
        } else {
            // even
            dp[i][0] = 1 + min(dp[i + 1][0], min(dp[i + 1][1], dp[i + 1][2]));
            dp[i][1] = min(dp[i + 1][1], dp[i + 1][2]);
            dp[i][2] = dp[i + 1][2] + a[i];
        }
    }

    li res = INF;
    rin{
        res = min(res, sum[i] + min(dp[i][0], min(dp[i][1], dp[i][2])));
    }
    return res;
}

int main() {
