		if(dp[i][3]<0) dp[i][3]=INF;
		if(dp[i][4]<0) dp[i][4]=INF;
	}
	long long ans=min(min(min(dp[l][0],dp[l][1]),min(dp[l][2],dp[l][3])),dp[l][4]);
