constexpr int MAX = 200200;
constexpr int INF = (1 << 30);

template<class T>
inline void chmin (T &a, T b) {
    if (a > b) a = b;
}

int main() {
    int n;
    cin >> n;
    vector<int> a(n);
    for (int &e : a) cin >> e;

    vector<vector<int>> dp(n + 1, vector<int>(5, INF));
    for (int j = 0; j < 5; j++) dp[0][j] = 0;

    auto cost = [&] (int i, int j) -> int {
        if (j == 0 or j == 4) return a[i];
        if (j == 2) return ((a[i] + 1) % 2);
        return (a[i] == 0 ? 2 : (a[i] & 1));
    };

    for (int i = 0; i < n; i++) {
        for (int j = 0; j < 5; j++) {
            int pre = INF;
            for (int k = 0; k <= j; k++) chmin(pre, dp[i][k]);
            dp[i + 1][j] = pre + cost(i, j);
        }
    }

    int ans = INF;
    for (int j = 0; j < 5; j++) chmin(ans, dp[n][j]);

    cout << ans << '\n';

    return 0;
}

