using namespace std;
using ll = long long;

ll L;
vector<ll> A;

void input() {
    cin >> L;
    A.resize(L);
    for (auto& a : A)
        cin >> a;
}

void solve() {
    array<array<ll, 4>, 2> dp;
    {
        auto f = A[0];
        bool odd = f % 2;
        bool nonzero = f > 0;
        dp[0] = {
            odd ? 1 : (nonzero ? 0 : 2),
            odd ? 0 : 1,
            odd ? 1 : (nonzero ? 0 : 2),
            f
        };
    }
    ll sum = A[0];
    for (ll i = 1; i < L; i++) {
        bool odd = A[i] % 2 == 1;
        bool nonzero = A[i] > 0;
        auto& cdp = dp[i%2];
        auto& pdp = dp[(i-1)%2];
        ll tmp;
        cdp[0] = (tmp = min(sum, pdp[0])) + (odd ? 1 : (nonzero ? 0 : 2));
        cdp[1] = (tmp = min(tmp, pdp[1])) + (odd ? 0 : 1);
        cdp[2] = (tmp = min(tmp, pdp[2])) + (odd ? 1 : (nonzero ? 0 : 2));
        cdp[3] = (tmp = min(tmp, pdp[3])) + A[i];
        sum += A[i];
    }
    auto& bdp = dp[(L-1)%2];
    ll ans = *min_element(bdp.begin(), bdp.end());
    cout << ans << endl;
}

int main() {
    input();
    solve();

    return 0;
}

