        cin >> aa;
        sum += aa;
    }

    int64_t unreached = 0;
    int64_t ended = 0;
    int64_t turned = 0;
    int64_t ans = sum;
    int64_t rsum = sum;
    for (auto i : irange(0L, l)) {
        auto is_even = (a[i] % 2 == 0);
        auto next_unreached = min({unreached, ended, turned}) + a[i];
        auto next_ended = min(ended, sum - rsum) + (is_even ? 1: 0);
