        rsum -= a[i];
        auto next_min = min({next_unreached, next_ended, next_turned}) + rsum;
        ans = min(ans, next_min);

        unreached = next_unreached;
        ended = next_ended;
        turned = next_turned;
    }

    cout << ans << endl;
