ll findTedad(ll l,ll r,ll v){
	if(r<l)return 0;
	if(l==0)return cnt[r][v];
	return cnt[r][v]-cnt[l-1][v];
}
ll findLeft(ll n,ll r){
	if(r<0)return 0;
	ll ans=inf;
	for(ll i=r+1;i>=0;i--){
		ll res=findTedad(0,i-1,0)*0+findTedad(0,i-1,1)*1+findTedad(0,i-1,2)*2+findTedad(i,r,0)*1+findTedad(i,r,1)*0+findTedad(i,r,2)*1;
		ans=min(ans,res);
	}
	return ans;
}
ll findRight(ll n,ll l){
	if(l>=n)return 0;
	ll ans=inf;
	for(ll i=l-1;i<n;i++){
		ll res=findTedad(l,i,0)*2+findTedad(l,i,1)*1+findTedad(l,i,2)*0+findTedad(i+1,n-1,0)*0+findTedad(i+1,n-1,1)*1+findTedad(i+1,n-1,2)*2;
		ans=min(ans,res);
	}
	return ans;
}
ll findAns(ll n){
	memset(cnt,0,sizeof cnt);
	cnt[0][a[0]]=1;
	for(ll i=1;i<n;i++){
		cnt[i][0]=cnt[i-1][0];
		cnt[i][1]=cnt[i-1][1];
		cnt[i][2]=cnt[i-1][2];
		cnt[i][a[i]]++;
	}
	ll ans=inf;
	for(ll i=0;i<n;i++){
		ans=min(ans,findRight(n,i)+findLeft(n,i-1));
	}
	return ans;
}
