		if(a[i]>=2 && a[i]%2==0){
			a[i]=2;
		}
		if(a[i]%2==1)a[i]=1;
	}	
	ll ans=findAns(n);
	reverse(a,a+n);
	ans=min(ans,findAns(n));
	cout<<ans;
}

