const int N=2e5+5;
const int M=1e5+5;

ll a[N];
int n;
ll psum[N],odd[N],extra[N];

ll func(int mid,int start)
{
    ll ret=0;
    ret=psum[n]-psum[mid];
    ret+=max(0,odd[mid-1]-odd[start+1]);
    ret+=max(0,extra[mid-1]-extra[start+1]);
   // ret+=max(0,a[start]%2);
    return ret;
}

ll ternary(int start)
{
    int l=start,r=n;
    ll ret=inf;
    while(r-l>1)
    {
        int mid=(l+r)/2;
        if(func(mid,start)>func(mid+1,start))
        {
            l=mid;
            ret=min(ret,func(l, start));
            ret=min(ret,func(l+1,start));
        } else
        {
            r=mid;
        }
    }
    return min(ret,min(func(l,start),func(l+1,start)));
}

