        even_before[i] = min(even_before[i - 1] + here_left_here_cost, sum[i]);
        odd_before[i] = min(odd_before[i - 1] + left_here_cost, even_before[i]);
    }
    for (int i = L - 1; i >= 0; i--) {
        even_after[i] = min(even_after[i + 1] + (even[i + 1] - even[i]), sum[L] - sum[i]);
        odd_after[i] = min(odd_after[i + 1] + (odd[i + 1] - odd[i]), even_after[i]);
    }
    ll ans = 1e16;
    for(int i = 0; i <= L; i++) {
        ans = min(ans, odd_before[i] + odd_after[i]);
    }
    cout << ans << endl;
    return 0;
}

