#include <bits/stdc++.h>
using namespace std;
using ll  = long long;
using vl  = vector<ll>;
using vvl = vector<vl>;
#define rep(i,n) for(int i = 0; i < int(n); ++i)
#define per(i,n) for(int i = (n)-1; i >= 0; --i)
#define rng(i,a,b) for(int i = (a); i < int(b); ++i)
#define all(v) (v).begin(), (v).end()
#define dmin(a,b) (a = min(a, b))

ll zero_count(const vl& a) {
    return a[0] == 0 ? a.size() : 0LL;
}

ll sum_value(const vl& a) {
    return accumulate(all(a), 0LL);
}

ll waste_count(vl a, bool start=false, bool end=false) {
    ll n = a.size(), odd_cnt = 0;
    rep(i,n) odd_cnt += a[i] % 2;
    ll even_cnt = n - odd_cnt;

    ll res = even_cnt;
    if (start and end) {
        ll left_cost = 0, center_cost = 0, right_cost = odd_cnt;
        ll oc = 0;
        rep(i,n) {
            if (a[i] % 2) {
                right_cost--, oc++;
            } else {
                center_cost++;
                if (center_cost > oc) {
                    left_cost += oc;
                    center_cost = oc = 0;
                }
            }
            dmin(res, left_cost + center_cost + right_cost);
        }
        return res;
    }
    if (start or end) {
        if (end) return 0;
        ll cnt = 0, ec = even_cnt;
        rep(i,n) {
            if (a[i] % 2) cnt++;
            else ec--;
            dmin(res, ec + cnt);
        }
    }
    return res;
}

int main() {
    ll L; cin >> L;
    vl a(L); rep(i,L) scanf("%lld", &a[i]);

    ll prev = 0, N = 0;
    vvl as;
    rep(i,L) {
        if ((prev == 0) xor (a[i] == 0)) {
            as.push_back(vl());
            prev = a[i];
            N++;
        }
        if (N > 0) as[N-1].push_back(a[i]);
    }
    if (N == 0) { cout << 0 << endl; return 0; }

    ll sum = sum_value(a), used_sum = 0, rest_sum = sum, ans = sum;
    ll prev_waste = waste_count(as[0],1,0);
    for (int i = 0; i < N; i += 2) {
        ll now = sum_value(as[i]);
        rest_sum -= now;

        // as[i]だけを使うパターン
        dmin(ans, used_sum + waste_count(as[i],1,1) + rest_sum);

        if (i > 1) {
            // as[i]で終えるパターン
            dmin(ans, prev_waste + zero_count(as[i-1]) + waste_count(as[i],0,1) + rest_sum);

            // i-2までに必要な操作回数の最小値を更新
            ll a = prev_waste + zero_count(as[i-1]) + waste_count(as[i],0,0);
            ll b = used_sum + waste_count(as[i],1,0);
            prev_waste = min(a, b);
        }
        used_sum += now;
    }
    cout << ans << endl;
    return 0;
}

