#include <bits/stdc++.h>
using namespace std;

typedef long long ll;

const int Maxn = 200005;

int n;
int A[Maxn];
ll zer[Maxn], ev[Maxn], od[Maxn];
ll res;

int evCost(int a) { return a == 0? 2: bool(a % 2 != 0); }

int odCost(int a) { return bool(a % 2 != 1); }

int main()
{
    scanf("%d", &n);
    for (int i = 1; i <= n; i++)
        scanf("%d", &A[i]);
    for (int i = n - 1; i >= 0; i--) {
        zer[i] = A[i + 1] + zer[i + 1];
        ev[i] = min(zer[i], evCost(A[i + 1]) + ev[i + 1]);
        od[i] = min(ev[i], odCost(A[i + 1]) + od[i + 1]);
    }
    res = od[0];
    ll myzer = 0, myev = 0;
    for (int i = 1; i <= n; i++) {
        myzer = A[i] + myzer;
        myev = min(myzer, evCost(A[i]) + myev);
        res = min(res, myev + od[i]);
    }
    cout << res << endl;
    return 0;
}

#include <iostream>
using namespace std;
#define ll long long

int main () {
  ll n;
  cin >> n;
  ll a[n];
  ll sum[n], dp[n];
  for (ll i = 0; i < n; i++) {
    a[i] = 0;
    dp[i] = 0;
    sum[i] = 0;  
  }
  for (ll i = 0; i < n; i++) {
    cin >> a[i];
    dp[i] = 0;
    if (i == 0) {
      sum[i] = a[i];  
    }    
    else {
      sum[i] = sum[i - 1] + a[i];  
    }
    if (sum[i] >= 2000000) {
      sum[i] = 2000001;  
    }
  }  
  for (ll i = 0; i < n; i++) {
    ll j = n - 1 - i;
    if (i <= 1) {
      dp[j] = 0;
      if (i == 1 && a[j] == 0 && a[j + 1] != 0) {
        dp[j]++;     
      }    
    }
    else {
      if (a[j] % 2 != a[j + 1] % 2 && a[j + 1] % 2 != a[j + 2] % 2) {
        dp[j] = dp[j + 1] + 1;  
      }
      else {
        dp[j] = dp[j + 1];  
      }
      if (a[j] == 0) {
        dp[j]++;  
      }
    }
  }
  ll min = -1;
  min = dp[0];
  if (min > sum[n - 1]) {
    min = sum[n - 1];  
  }
  for (ll i = 0; i < n - 1; i++) {
    ll sub = sum[i] + dp[i + 1];
    if (sub < min) {
      min = sub;  
    }    
  }
  cout << min << endl;
}

