ll score(ll a, int phase){
  ll result = 0;

  switch (phase){
    case 0 :
    case 4 :
      result = a;
      break;
    case 1 :
    case 3 :
      if (a == 0){
        result = 2;
      }
      else {
        result = a % 2;
      }
      break;
    case 2:
      result = (a + 1) % 2;
      break;
    default:
      assert(false);
  }

  // printf("score(%lld, %d) = %lld\n", a, phase, result);
  return result;
}

