		dpsr[i][0] = dpsr[i-1][0]+a[i];
		if(a[i] == 0){
			dpsr[i][1] = min(dpsr[i-1][0], min(dpsr[i-1][1], dpsr[i-1][2]))+1;
			dpsr[i][2] = min(dpsr[i-1][0], dpsr[i-1][2])+2;
		}
		else{
			dpsr[i][1] = min(dpsr[i-1][0], min(dpsr[i-1][1], dpsr[i-1][2]))+(a[i]+1)%2;
			dpsr[i][2] = min(dpsr[i-1][0], dpsr[i-1][2])+a[i]%2;
		}
	}

	memset(dpsl[L], 0, sizeof(dpsl[L]));
	for(ll i = L-1; i >= 0; i--){
		dpsl[i][0] = dpsl[i+1][0]+a[i+1];
		if(a[i] == 0){
			dpsl[i][1] = min(dpsl[i+1][0],min(dpsl[i+1][1], dpsl[i+1][2]))+1;
			dpsl[i][2] = min(dpsl[i+1][0], dpsl[i+1][2])+2;
		}
		else{
			dpsl[i][1] = min(dpsl[i+1][0], min(dpsl[i+1][1], dpsl[i+1][2]))+(a[i+1]+1)%2;
			dpsl[i][2] = min(dpsl[i+1][0], dpsl[i+1][2])+a[i+1]%2;
		}
	}

	for(ll i = 0; i <= L; i++){
		ll minsr = min(dpsr[i][0], dpsr[i][2]);
		ll minsl = min(dpsl[i][0], dpsl[i][2]);
		ans = min(minsr+min(minsl, dpsl[i][1]), ans);
		ans = min(min(minsr, dpsr[i][1])+minsl, ans);
	}

	cout << ans << endl;
	return 0;
}

