                f[i][0] = f[i - 1][0];
                f[i][1] = 1 + f[i - 1][1];
            } else {
                f[i][0] = 1 + f[i - 1][0];
                f[i][1] = f[i - 1][1];
            }
        }
        f[i][0] = min(f[i][0], f[i][2]); 
        f[i][1] = min(f[i][1], f[i][2]);
        if(a[i] % 2) {
            f[i][0] = min(f[i][0], f[i - 1][2]);
            f[i][1] = min(f[i][1], f[i - 1][2] + 1);
        } else {
            f[i][0] = min(f[i][0], f[i - 1][2] + 1);
            f[i][1] = min(f[i][1], f[i - 1][2]);
        }
    }

    g[n][0] = 0; g[n][2] = a[n];
    if(a[n] % 2) {
        g[n][1] = 1;
    } else g[n][1] = 0;
    PER(i, n - 1, 1) {
        g[i][2] = g[i + 1][2] + a[i];
        if(!a[i]) {
            g[i][0] = 1 + g[i + 1][0]; g[i][1] = 2 + g[i + 1][1];
        } else {
            if(a[i] % 2) {
                g[i][0] = g[i + 1][0];
                g[i][1] = 1 + g[i + 1][1];
            } else {
                g[i][0] = 1 + g[i + 1][0];
                g[i][1] = g[i + 1][1];
            }
        }
        g[i][0] = min(g[i][0], g[i][2]);
        g[i][1] = min(g[i][1], g[i][2]); 
        if(a[i] % 2) {
            g[i][0] = min(g[i][0], g[i + 1][2]);
            g[i][1] = min(g[i][1], g[i + 1][2] + 1);
        } else {
            g[i][0] = min(g[i][0], g[i + 1][2] + 1);
            g[i][1] = min(g[i][1], g[i + 1][2]);
        }
    }
    ans = 1e16;
    REP(i, 1, n - 1) {
        ans = min(ans, min(f[i][0], f[i][1]) + min(g[i + 1][0], g[i + 1][1]));
        //cout << " " << ans << " " << g[i + 1][0] << " " << g[i + 1][1] << endl;
    }
    printf("%lld\n", ans);
	return 0;
}

