        }
    }
    else{
        if(a[x]%2){
            res=dp(x-1, 0);
        }
        else if(a[x]==0){
            res=min(dp(x-1, 0)+1, pr[x]);
        }
        else{
            res=min(dp(x-1, 0)+1, dp(x-1, 1));
        }
    }
    mem[x][l]=res;
    return res;
}
