#include <bits/stdc++.h>
using namespace std;
typedef long long ll;

const int MX = 200005;

int a[MX];
ll SS[MX];
ll S(int L, int R) {
	if (L > R) return 0;
	return SS[R] - SS[L - 1];
}

ll L[MX];
ll R[MX];

ll ans;

void Get(int l, int r)
{
	if (l > r) return;

	int m = (l + r) / 2;

	ll tmpL = L[m - 1];
	ll tmpR = R[m + 1];

	for (int i = m - 1, x = 0; i >= l; i--) {
		x += (a[i] % 2 == 1 ? 0 : 1);
		tmpL = min(tmpL, x + L[i - 1]);
	}

	for (int i = m + 1, x = 0; i <= r; i++) {
		x += (a[i] % 2 == 1 ? 0 : 1);
		tmpR = min(tmpR, x + R[i + 1]);
	}

	ans = min(ans, tmpL + tmpR + (a[m] % 2 == 1 ? 0 : 1));

	Get(l, m - 1);
	Get(m + 1, r);
}

int main()
{
	ios::sync_with_stdio(false);
	cin.tie(0);

	int n;
	cin >> n;

	for (int i = 1; i <= n; i++) {
		cin >> a[i];
		SS[i] = SS[i - 1] + a[i];
	}

	for (int i = 1; i <= n; i++) {
		L[i] = min(S(1, i), (a[i] == 0 ? 2 : a[i] % 2) + L[i - 1]);
	}
	for (int i = n; i >= 1; i--) {
		R[i] = min(S(i, n), (a[i] == 0 ? 2 : a[i] % 2) + R[i + 1]);
	}

	ans = S(1, n);

	for (int i = 1; i <= n; i++) {
		ans = min(ans, L[i] + S(i + 1, n));
	}

	Get(1, n);

	cout << ans << "\n";
}

