    vll accl(L + 1, 0);
    REP(i, L) {
        accl[i + 1] = accl[i] + A[i];
    }
    vll accr(L + 1, 0);
    RREP(i, L) {
        accr[i] = accr[i + 1] + A[i];
    }

//    D2(accl);
//    D2(accr);

    ll res = LINF;
    REP(i, L) {
        chmin(dp[i + 1][0], dp[i][0] + cost(true, A[i]));
        chmin(dp[i + 1][1], dp[i][0] + cost(true, A[i]));

        chmin(dp[i + 1][1], dp[i][1] + cost(false, A[i]));
        chmin(dp[i + 1][2], dp[i][1] + cost(true, A[i]));

        chmin(dp[i + 1][2], dp[i][2] + cost(true, A[i]));

        chmin(dp[i+1][0], accl[i]);
        chmin(dp[i+1][1], accl[i]);

//        D2(accl[i]);
//        D2(accr[i+1]);
        REP(j,3) {
            chmin(res, dp[i][j] + accr[i]);
        }

//        D2(i);
//        REP(j,3) {
//            D2(dp[i + 1][j]);
//        }
    }



//    D2(dp[L]);
//    D2(res);

    ll u = *min_element(all(dp[L]));
    return min(res, u);
}


