class Solve {
public:
    void input() {

    }

    //左を往復して右絵進む
    ll right(vector<ll> L) {
        int n = L.size();
        vector<vector<ll> > dp(n, vector<ll>(5, INFl));
        dp[0][0] = L[0];
        dp[0][1] = L[0] % 2;
        if (L[0] == 0) dp[0][1] = 2;
        dp[0][2] = L[0] % 2 == 0;
        for (int i = 1; i < n; ++i) {
            dp[i][0] = dp[i - 1][0] + L[i];
            if (L[i] == 0) {
                dp[i][1] = min(dp[i - 1][0], dp[i - 1][1]) + 2;
                dp[i][2] = min({dp[i - 1][0], dp[i - 1][1], dp[i - 1][2]}) + 1;
                dp[i][3] = min({dp[i - 1][0], dp[i - 1][1], dp[i - 1][2], dp[i - 1][3]}) + 2;

            } else if (L[i] % 2 == 0) {
                dp[i][1] = min(dp[i - 1][0], dp[i - 1][1]);
                dp[i][2] = min({dp[i - 1][0], dp[i - 1][1], dp[i - 1][2]}) + 1;
                dp[i][3] = min({dp[i - 1][0], dp[i - 1][1], dp[i - 1][2], dp[i - 1][3]});

            } else {
                dp[i][1] = min(dp[i - 1][0], dp[i - 1][1]) + 1;
                dp[i][2] = min({dp[i - 1][0], dp[i - 1][1], dp[i - 1][2]});
                dp[i][3] = min({dp[i - 1][0], dp[i - 1][1], dp[i - 1][2], dp[i - 1][3]}) + 1;

            }
            dp[i][4] = min({dp[i - 1][0], dp[i - 1][1], dp[i - 1][2], dp[i - 1][3], dp[i - 1][4]}) + L[i];
        }

        ll ret = *min_element(all(dp[n - 1]));
        return ret;

    }

    void solve() {
        input();
        int n;
        cin >> n;
        vector<ll> L(n);

        rep(i, 0, n) cin >> L[i];

        ll ans = right(L);

        cout << ans << endl;

    }
};


