int main() {

    scanner >> N;
    scanner.in(A, A + N);
    //repeat(i, N) gsum[i + 1] = gsum[i] + ((A[i] & 1) || A[i] == 0);
    //repeat(i, N) ksum[i + 1] = ksum[i] + ((~A[i] & 1) || A[i] == 0);

    vector<ll> dp1(5), dp2(5);

    repeat(i, N) {
        ll ki = ((A[i] & 1));
        if (A[i] == 0) ki = 2;
        ll gu = ((~A[i] & 1));
        // [0, l1)
        ll m = dp1[0];
        dp2[0] = m + A[i];
        // [l1, r2)
        chmin(m, dp1[1]);
        dp2[1] = m + ki;
        // [r2, l1)
        chmin(m, dp1[2]);
        dp2[2] = m + gu;
        // [l2, r2)
        chmin(m, dp1[3]);
        dp2[3] = m + ki;
        // [r2, N)
        chmin(m, dp1[4]);
        dp2[4] = m + A[i];

        dp1.swap(dp2);
    }

    ll best = *min_element(ALL(dp1));


    printer << best << '\n';

    return 0;
}

