const int N = 2e5+7;
deque<int> q1, q2;
ll g[N], f[N], rg[N], rf[N], sum3[N];
int a[N], pre[N], sum1[N], sum2[N], sum4[N];
ll query3(int l, int r)
{
	return sum3[r]-sum3[l-1];
}
int query1(int l, int r)
{
	return sum1[r]-sum1[l-1];
}
int query2(int l, int r)
{
	return sum2[r]-sum2[l-1];
}
int query4(int l, int r)
{
	return sum4[r]-sum4[l-1];
}
int main()
{
	int n;
	ll ans = 0, res = 0;
	scanf("%d", &n);
	for(int i = 1; i <= n; i++)
	{
		scanf("%d", &a[i]);
		ans += a[i];
		res += a[i];
		sum1[i] = sum1[i-1]+(a[i]==0?2:(a[i]&1));
		sum2[i] = sum2[i-1]+(a[i]==0?3:((a[i]&1)^1));
		sum3[i] = sum3[i-1]+a[i];
		sum4[i] = sum4[i-1]+(a[i]==0);
	}
	for(int i = n; i >= 1; i--)
	{
		if(a[i]==0)
		{
			pre[i] = i;
		}
		else
		{
			pre[i] = i+1;
		}
	}
	q1.push_back(0);
	q2.push_back(0);
	for(int i = 1; i <= n; i++)
	{
		int j = q1.front();
		int k = q2.front();
		f[i] = min(f[i-1]+query2(i, i), g[j]+query2(k+1, i));
		g[i] = min(g[i-1]+query1(i, i), sum3[k]+query1(k+1, i));
		while(!q1.empty()&&g[q1.back()]+query2(q1.back()+1, i)>g[i])
		{
			q1.pop_back();
		}
		q1.push_back(i);
		while(!q2.empty()&&sum3[q2.back()]+query1(q2.back()+1, i)>sum3[i])
		{
			q2.pop_back();
		}
		q2.push_back(i);
	}
	q1.clear();
	q2.clear();
	q1.push_back(n+1);
	q2.push_back(n+1);
	for(int i = n; i >= 1; i--)
	{
		int j = q1.front();
		int k = q2.front();
		rf[i] = min(rf[i+1]+query2(i, i), rg[j]+query2(i, j-1));
		rg[i] = min(rg[i+1]+query1(i, i), query3(k, n)+query1(i, k-1));
		while(!q1.empty()&&rg[q1.back()]+query2(i, q1.back()-1)>rg[i])
		{
			q1.pop_back();
		}
		q1.push_back(i);
		while(!q2.empty()&&query3(q2.back(), n)+query1(i, q2.back()-1)>query3(i, n))
		{
			q2.pop_back();
		}
		q2.push_back(i);
	}
	res = min(res, f[n]);
	res = min(res, g[n]);
	res = min(res, rf[1]);
	res = min(res, rg[1]);
	for(int i = 1; i < n; i++)
	{
		//printf("A:%lld %lld %lld %lld\n", f[i], g[i], rf[i+1], rg[i+1]);
		res = min(res, g[i]+rf[i+1]);
		//printf("%lld ", g[i]+rf[i+1]);
		//printf("%lld ", g[i]+rg[i+1]);
		//printf("%lld ", f[i]+rf[i+1]);
		//printf("%lld\n", f[i]+rg[i+1]);
		res = min(res, g[i]+rg[i+1]);
		res = min(res, f[i]+rf[i+1]);
		res = min(res, f[i]+rg[i+1]);
	}
	printf("%lld\n", res);
    return 0;
}

