            chmin(dp[i + 1][0], dp[i][1] + 1);
          }
        }
        else if (j == 3) {
          if (a[i] == 0) {
            chmin(dp[i + 1][3], dp[i][3] + 2);
            chmin(dp[i + 1][2], dp[i][3]);
          }
          else if (a[i] % 2 == 1) {
            chmin(dp[i + 1][3], dp[i][3] + 1);
          }
          else {
            chmin(dp[i + 1][3], dp[i][3]);
          }
        }
      } 
    }
    rep (i, 4) {
      chmin(ans, dp[l][i]);
    }
    reverse(all(a));
  }

  cout << ans << endl;
}

