using namespace std;

int n;
long long a[500000];

long long g(vector<long long> c)
{
    vector<long long> suff(c.size() + 1);
    for (int i = c.size() - 1; i >= 0; i--)
    {
        suff[i] = suff[i + 1] + c[i];
    }
    long long even = 0, opt = 0, ans = suff[0];
    for (int i = 0; i < c.size(); i++)
    {
        if (c[i] % 2 == 0) even++;
        opt += (c[i] % 2 == 1) * 1 + (c[i] == 0) * 2;
        if (even < opt) opt = even;
        ans = min(ans, opt + suff[i + 1]);
    }
    return ans;
}

long long solve(int l, int r, long long items)
{
    if (l + 1 >= r)
    {
        return items;
    }
    int m = (l + r) / 2;
    long long dl = 0, dr = 0;
    for (int i = m; i < r; i++) dr += a[i];
    for (int i = l; i < m; i++) dl += a[i];
    long long ans = min(solve(l, m, dr), solve(m, r, dl));
    vector<long long> b1(m - l), b2(r - m);
    for (int i = l; i < m; i++) b1[i - l] = a[i];
    for (int i = m; i < r; i++) b2[i - m] = a[i];
    reverse(b1.begin(), b1.end());
    //cout << l << " " << m << " " << r << " " << g(b1) << " " << g(b2) << endl;
    return min(ans, g(b1) + g(b2)) + items;
}

