ll Solve() {
    ll l;
    cin >> l;
    vector<ll> a(l + 1), sum(l + 1);
    for (int i = 1; i <= l; ++i) {
        cin >> a[i];
        sum[i] = a[i] + sum[i - 1];
    }

    const ll INF = LLONG_MAX;
    vector<ll> dp(l + 1, INF);

    ll res = sum[l] - sum[1];
    dp[1] = dp[0] = 0;
    for (int i = 2; i <= l; ++i) {
        dp[i] = min(dp[i], sum[i]);

        if (a[i] == 0) dp[i] = min(dp[i], dp[i - 1] + 1);
        else dp[i] = min(dp[i], dp[i - 1] + (a[i] % 2 == 0));

        if (a[i] == 0 && a[i - 1] == 0) dp[i] = min(dp[i], dp[i - 2] + 4);
        else if (a[i] == 0 && a[i - 1] != 0)
            dp[i] = min(dp[i], dp[i - 2] + (a[i - 1] % 2 == 1) + 2);
        else if (a[i] != 0 && a[i - 1] == 0)
            dp[i] = min(dp[i], dp[i - 2] + (a[i] % 2 == 1) + 2);
        else
            dp[i] = min(dp[i], dp[i - 2] + (a[i - 1] % 2 == 1) + (a[i] % 2 == 1));
        if (a[i] == 0) dp[i] = min(dp[i], sum[i - 1] + 2);
        else dp[i] = min(dp[i], sum[i - 1] + (a[i] % 2 == 1));
        // // i - 1 より左にいかない
        // dp[i] = min(dp[i], dp[i - 1] + (a[i] % 2 == 0));
        // dp[i] = min(dp[i], sum[i - 1] + (a[i] % 2 == 1));

        // // i - 1 より左に行くかも
        // dp[i] = min(dp[i], dp[i - 2] + (a[i - 1] % 2 == 1) + (a[i] % 2 == 1));
        // dp[i] = min(dp[i], dp[i - 2] + (a[i - 1] % 2 == 0) + (a[i] % 2 == 0));

        res = min(res, dp[i] + sum[l] - sum[i]);
    }
    // for (int i = 0; i <= l; ++i)
    //     cout << i << " " << dp[i] << endl;

    return min(res, dp[l]);
}

