int K[4][MAX_L];
int sumK[4][MAX_L];

void setKPos(int k, int a[MAX_L]) 
{
  REP(n,L) {
    K[k][n] = a[n];
    if(a[n]%2==0) {
      K[k][n] -= 1;
    }
  }
  REP(n,L) {
    sumK[k][n+1] = sumK[k][n] + K[k][n];
  }
}

void setKPos2(int k, int a[MAX_L]) 
{
  REP(n,L) {
    int aa = a[n]-2;
    if(aa == -2) {
      K[k][n] = -2;
    } else if(aa==-1) {
      K[k][n] = 0;
    } else {
      K[k][n] = a[n];
      if(a[n]%2==1) {
        K[k][n] -= 1;
      }
    }
  }

  REP(n,L) {
    sumK[k][n+1] = sumK[k][n] + K[k][n];
  }
}

class SlideMaxDeque {
public:
    using LI = pair<long long, int>;
    SlideMaxDeque() {
        deq.clear();
    }

    void add(long long value, int index) {
        while(deq.size() > 0 && deq.back().first < value) {
            deq.pop_back();
        }
        deq.push_back(LI(value, index));
    }

    long long get(int index) {
        while(deq.size()) {
            if(deq.front().second < index) {
                deq.pop_front();
            } else {
                return deq.front().first;
            }
        }
        assert(false);
    }

private:
    deque<LI> deq; 
}smd1,smd2;

