    ll ans = INF;
    for(ll i = 0; i < L; i++){
        ll tmp = re[i] + le[i];
        tmp = min(tmp, ro[i] + le[i]);
        tmp = min(tmp, re[i] + lo[i]);
        ans = min(ans, tmp);
    }
    cout << ans << endl;
    return 0;
}

