            if(fu>=sum||i==0){
                //Cout(cnt);
                ans=cnt+sum;
                break;
            }
            else{
                cnt+=fu;
            }
        }
        else{
            if(a[i]==0)continue;
            if(a[i]%2==0&&(a[i-1]%2==1||a[i-1]==0))cnt++;
            sum-=a[i];
        }
        if(i==0)ans=cnt;
    }

    sum=0;
    rep(i,n)sum+=a[i];
    cnt=0;
    ll anss=0;
    rep(i,n){
        if(a[i+1]==0){
            sum-=a[i];
            ll fu=0;
            if(a[i]%2==0)fu++;
            rrep(j,i+1,n){
                if(a[j]!=0){pos=j;break;}
                fu++;
            }
            i=pos-1;
            //cout<<" fu: "<<pos<<"\n";
            //Cout(pos);
            //cout<<i<<" "<<"fu "<<fu<<"\n";
            if(fu>=sum||i==n-1){
                //Cout(cnt);
                anss=cnt+sum;
                //cout<<i<<"anss"<<anss<<"\n";
                break;
            }
            else{
                cnt+=fu;
            }
        }
        else{
            if(a[i]==0)continue;
            if(a[i]%2==0&&(a[i+1]%2==1||a[i+1]==0))cnt++;
            sum-=a[i];
        }
        if(i==n)anss=cnt;
    }
    Cout(min(ans,anss));
    return 0;
}

