using INT = long long;
using UINT = unsigned long long;

int main()
{
	INT L;
	cin >> L;
	vector<INT> a(L + 1, 0);

	vector<INT> ki(L + 1,0), gu(L + 1,0), zero(L + 1,0), sum(L + 1, 0), scost(L+1, 0), gcost(L+1,0);
	for (size_t i = 1; i < L + 1; i++)
	{
		cin >> a[i];
		for (size_t j = i; j < L + 1; j++)
		{
			if (a[i] == 0)
			{
				zero[j]++;
			}
			else if (a[i] % 2 == 0)
			{
				gu[j]++;
			}
			else
			{
				ki[j]++;
			}
			sum[j] += a[i];
		}
	}

	for (size_t s = 0; s < L + 1; s++)
	{
		INT minc = numeric_limits<INT>::max();
		for (size_t i = 0; i <= s; i++)
		{
			INT tmp = (sum[i] - sum[0]) + (zero[s] - zero[i]) * 2 + (ki[s] - ki[i]);
			if (tmp < minc)
			{
				minc = tmp;
			}
		}
		scost[s] = minc;
	}
	for (size_t g = 0; g < L + 1; g++)
	{
		INT minc = numeric_limits<INT>::max();
		for (size_t i = g; i <= L; i++)
		{
			INT tmp = (sum[L] - sum[i]) + (zero[i] - zero[g]) * 2 + (ki[i] - ki[g]);
			if (tmp < minc)
			{
				minc = tmp;
			}
		}
		gcost[g] = minc;
	}

	auto f = [&](INT s, INT g)
	{
		INT c = scost[s] + (gu[g] - gu[s]) + (zero[g] - zero[s]) + gcost[g];
		return c;
	};

	INT minc = numeric_limits<INT>::max();
	for (size_t i = 0; i < L + 1; i++)
	{
		for (size_t j = i; j < L + 1; j++)
		{
			INT tmp = f(i, j);
			if (minc > tmp)
			{
				minc = tmp;
			}
		}
	}
	cout << minc << endl;
	return 0;
}

