#define ALLOF(c) (c).begin(), (c).end()
typedef long long ll;
typedef unsigned long long ull;

ll dp[200005][2];

ll calc(ll a, int x, ll y){
  if(a == 0) return y;
  return (a%2==0)?x:1-x;
}

ll solve(int L, const vector<ll>& v){
  vector<ll> sum(L+1), sum_rev(L+1);
  sum[0] = v[0];
  sum_rev[L-1] = v[L-1];
  REP(i,1,v.size()){
    sum[i] = sum[i-1] + v[i];
    sum_rev[L-1-i] = sum_rev[L-i] + v[L-1-i];
  }

  rep(i,v.size()){
    //右から入って左へ
    dp[i][0] = ((i>0)?dp[i-1][0]:0) + calc(v[i],0,2);
    ///前までを捨てる
    dp[i][0] = min(dp[i][0], ((i>0)?sum[i-1]:0) + calc(v[i],0,0));
    //左から入って左へ
    dp[i][1] = ((i>0)?(min(dp[i-1][0], dp[i-1][1])):0) + calc(v[i],1,1);
    ///前までを捨てる
    dp[i][1] = min(dp[i][1], ((i>0)?sum[i-1]:0) + calc(v[i],1,1));
  }

  ll ret = 1e18;
  rep(i,L){
    ret = min(ret, dp[i][0] + ((i+1<L)?sum_rev[i+1]:0));
    ret = min(ret, dp[i][1] + ((i+1<L)?sum_rev[i+1]:0));
  }

  return ret;
}

int main(){
  int L;
  cin >> L;
  vector<ll> v;
  rep(i,L){
    ll a;
    cin >> a;
    v.push_back(a);
  }

  ll ret = solve(L, v);
  reverse(ALLOF(v));
  ret = min(ret, solve(L, v));

  cout << ret << endl;

  return 0;
}

