ll calc(ll a, int x, ll y){
  if(a == 0) return y;
  return (a%2==0)?x:1-x;
}

void solve(int L, const vector<ll>& v, vector<vector<ll>>& dp){
  vector<ll> sum(L+1);
  sum[0] = v[0];
  REP(i,1,v.size()){
    sum[i] = sum[i-1] + v[i];
  }

  rep(i,v.size()){
    //右から入って左へ
    dp[i][0] = ((i>0)?dp[i-1][0]:0) + calc(v[i],0,2);
    ///前までを捨てる
    dp[i][0] = min(dp[i][0], ((i>0)?sum[i-1]:0) + calc(v[i],0,0));
    //左から入って左へ
    dp[i][1] = ((i>0)?(min(dp[i-1][0], dp[i-1][1])):0) + calc(v[i],1,1);
    ///前までを捨てる
    dp[i][1] = min(dp[i][1], ((i>0)?sum[i-1]:0) + calc(v[i],1,1));
  }
}

