    ll cnt = (a[l] == 0);
    dp[l] = 0;
    repp(i, l + 1, r) {
        if (a[i] == 0) {
            dp[i] = dp[i - 1];
            cnt++;
        } else {
            dp[i] = min(dp[i - 1] + 1, cnt);
        }
    }
    cnt = 0;
    ll ret = dp[r - 1];
    for (int i = r - 1; i > l; i--) {
        if (a[i] == 0) cnt++;
        ret = min(ret, dp[i - 1] + cnt);
    }
    return ret;
}
