                    if (j != 0) dp[i][j] += min(dp[i - 1][j - 1], dp[i][j - 1]);

                default:
                    break;
            }
        }
    }
    ll mi = LONG_LONG_MAX;
    rep(i, 5) mi = min(mi, dp[i][L - 1]);

    cout << mi << endl;
    return 0;
}

