int main() {
	ll L;
	cin >> L;
	vector<ll> a;
	vector<ll> imos(L + 1);
	bool f = true;
	for (int i = 0;i < L;i++) {
		ll temp;
		cin >> temp;
		if (f && temp == 0) {
			L--;
			i--;
			continue;
		}
		else
			f = false;
		a.push_back(temp);
		imos[i + 1] = a[i] + imos[i];
	}
	while (!a.empty() && a.back() == 0) {
		a.pop_back();
		L--;
	}
	vector<ll> dp(L + 1, INF);
	dp[0] = 0;
	vector<ll> from(L + 1);
	for (int i = 0;i < L;i++) {
		ll nowcost = a[i] % 2;
		if (a[i] == 0)
			nowcost = 2;
		dp[i + 1] = min(imos[i] + nowcost, dp[i] + nowcost);
		if (imos[i] + nowcost <= dp[i] + nowcost)
			from[i + 1] = from[i];
		else
			from[i + 1] = i;
	}
	vector<ll> fromr(L + 1);
	vector<ll> ar(L);
	imos.assign(L + 1, 0);
	for (int i = 0;i < L;i++) {
		ar[i] = a[L - 1 - i];
		imos[i + 1] = ar[i] + imos[i];
	}
	vector<ll> dpr(L + 1, INF);
	dpr[0] = 0;
	for (int i = 0;i < L;i++) {
		ll nowcost = ar[i] % 2;
		if (ar[i] == 0)
			nowcost = 2;
		dpr[i + 1] = min(imos[i] + nowcost, dpr[i] + nowcost);
		if (imos[i] + nowcost <= dpr[i] + nowcost)
			fromr[i + 1] = fromr[i];
		else
			fromr[i + 1] = i;
	}
	vector<ll> base(L+1, 0);
	vector<ll> basenz(L + 1, 0);
	for (int i = 0;i < L;i++) {
		if (a[i] % 2 == 0 || a[i] == 0)
			base[i + 1] = 1;
		if (a[i] % 2 == 0 && a[i] != 0)
			basenz[i + 1] = 1;
		base[i + 1] += base[i];
		basenz[i + 1] += basenz[i];
	}
	vector<ll> bestr(L+1);
	for (int i = 1;i <= L;i++) {
		if (bestr[L - i + 1] < dpr[i] - (base[L] - base[L - i]))
			bestr[L - i] = bestr[L - i + 1];
		else
			bestr[L - i] = i;
	}
	ll bestl = 0;
	ll ans = INF;
	imos.assign(L + 1, 0);
	for (int i = 0;i < L;i++) {
		imos[i + 1] = a[i] + imos[i];
	}
	for (int i = 0;i <= L;i++) {
		bestl = dp[i] - base[i];
		ll rb = dpr[bestr[i]] - (base[L] - base[L - bestr[i]]);
		ans = min(ans, bestl + rb + basenz[from[i]] + base[L - fromr[bestr[i]]] - base[from[i]] + basenz[L] - basenz[L - fromr[bestr[i]]]);
	}
	cout << ans << endl;
	return 0;
}
