    for(int i = 1; i < n+1; i++){
        if(a[i] != 0){
            fidx = i;
            break;
        }
    }
    ll bidx = 0;
    for(int j = n; j > 0; j--){
        if(a[j] != 0){
            bidx = j;
            break;
        }
    }
    x.push_back(0);

    for(int i = fidx; i <= bidx; i++){
        x.push_back(a[i]);
    }

    a = x;
    n = a.size() - 1;

    vector<ll> oddf(n+1,0),oddb(n+1,0);
    for(int i = 1; i < n+1; i++){
        oddf[i] = oddf[i-1];
        if(a[i]%2 == 1){
            oddf[i]++;
        }
    }
    oddb[n] = a[n]%2;
    for(int i = n-1; i >= 0; i--){
        oddb[i] = oddb[i+1] + a[i]%2;
    }

    vector<ll> even(n+1,0);
    for(int i = 1; i < n+1; i++){
        even[i] = even[i-1];
        if(a[i]%2 == 0){
            even[i]++;
        }
