        ll t = pq.top() - even[i] + oddf[i-1] + zero[i-1]*2;
        ll t2 = pq.top() - even[i] + sum[i-1];
        ans = min(min(t2,t),ans);
        pq.push(even[i-1] + oddb[i+1] + (zero[n] - zero[i])*2);
        pq.push(even[i-1] + sum[n] - sum[i]);
    }

    cout << ans << endl;

    return 0;
}

