    if (i == 0) {
      sum[i] = a[i];  
    }    
    else {
      sum[i] = sum[i - 1] + a[i];  
    }
  }  
  for (ll i = 0; i < n; i++) {
    ll j = n - 1 - i;
    if (i <= 1) {
      dp[j] = 0;
      if (i == 1 && a[j] == 0 && a[j + 1] != 0) {
        dp[j]++;     
      }    
    }
    else {
      if (a[j] % 2 != a[j + 1] % 2 && a[j + 1] % 2 != a[j + 2] % 2) {
        dp[j] = dp[j + 1] + 1;  
      }
      else {
        dp[j] = dp[j + 1];  
      }
      if (a[j] == 0) {
        dp[j]++;  
      }
    }
  }
  ll min = -1;
  min = dp[0];
  if (min > sum[n - 1]) {
    min = sum[n - 1];  
  }
  for (ll i = 0; i < n - 1; i++) {
    ll sub = sum[i] + dp[i + 1];
    if (sub < min) {
      min = sub;  
    }    
  }
  cout << min << endl;
}

