long long g(vector<long long> c, int all, int useodd)
{
    vector<long long> suff(c.size() + 1);
    for (int i = c.size() - 1; i >= 0; i--)
    {
        suff[i] = suff[i + 1] + c[i];
    }
    long long even = 0, opt = 0, ans = suff[0];
    for (int i = 0; i < c.size(); i++)
    {
        if (c[i] % 2 == 0) even++;
        opt += (c[i] % 2 == 1) * 1 + (c[i] == 0) * 2;
        if (useodd) if (even < opt) opt = even;
        ans = min(ans, opt + suff[i + 1]);
    }
    if (all == 0)
        return ans;
    else
        return opt;
}

map<pair<int, int>, int> calc[4];

long long solve(int l, int r, int LR)
{
    if (l + 1 >= r)
    {
        return 0;
    }
    if (calc[LR].find({l, r}) != calc[LR].end()) return calc[LR][{l, r}];
    int m = (l + r) / 2;
    long long dl = 0, dr = 0;
    for (int i = m; i < r; i++) dr += a[i];
    for (int i = l; i < m; i++) dl += a[i];
    long long ans = 1e18;
    vector<long long> b1(m - l), b2(r - m);
    for (int i = l; i < m; i++) b1[i - l] = a[i];
    for (int i = m; i < r; i++) b2[i - m] = a[i];
    reverse(b1.begin(), b1.end());
    if (LR == 0)
    {
        ans = min(ans, solve(l, m, 0) + dr);
        ans = min(ans, solve(m, r, 0) + dl);
        ans = min(ans, g(b1, 0, 1) + g(b2, 0, 1));
        ans = min(ans, solve(l, m, 1) + g(b2, 0, 0));
        ans = min(ans, solve(m, r, 2) + g(b1, 0, 0));
    }
    if (LR == 1)
    {
        ans = min(ans, solve(m, r, 1) + dl);
        ans = min(ans, solve(m, r, 3) + g(b1, 0, 0));
        ans = min(ans, g(b1, 0, 1) + g(b2, 1, 1));
        ans = min(ans, solve(l, m, 1) + g(b2, 1, 0));
    }
    if (LR == 2)
    {
        ans = min(ans, solve(l, m, 2) + dr);
        ans = min(ans, solve(l, m, 3) + g(b2, 0, 0));
        ans = min(ans, g(b2, 0, 1) + g(b1, 1, 1));
        ans = min(ans, solve(m, r, 1) + g(b1, 1, 0));
    }
    if (LR == 3)
    {
        ans = min(ans, g(b1, 1, 1) + g(b2, 1, 1));
        ans = min(ans, solve(m, r, 3) + g(b1, 1, 0));
        ans = min(ans, solve(l, m, 3) + g(b2, 1, 0));
    }
    calc[LR][{l, r}] = ans;
    return ans;
}

