int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int L;
    cin >> L;
    vector<int> A(L);
    for(int i = 0; i < L; ++i)  cin >> A[i];
    constexpr ll inf = 1e+17;
    for(int i = 0; i <= L; ++i){
        for(int j = 0; j < 5; ++j){
            for(int k = 0; k < 2; ++k){
                dp[i][j][k] = inf;
            }
        }
    }
    dp[0][0][0] = dp[0][1][1] = 0;
    auto update = [&](int i, int j, int k) -> void {
        if(dp[i][j][k] == inf)  return;
        if(j == 0){
            if(k){
                chmin(dp[i + 1][0][1], dp[i][0][1] + ((A[i] >= 2) ? (A[i] & 1) : (2 - A[i])));
                chmin(dp[i + 1][1][1], dp[i][0][1] + ((A[i] >= 2) ? (A[i] & 1) : (2 - A[i])));
            }
            else{
                chmin(dp[i + 1][0][0], dp[i][0][0] + A[i]);
                chmin(dp[i + 1][0][1], dp[i][0][0] + ((A[i] >= 2) ? (A[i] & 1) : (2 - A[i])));
                chmin(dp[i + 1][1][1], dp[i][0][0] + (A[i] & 1));
            }
        }
        else if(j == 4){
            if(k){
                chmin(dp[i + 1][4][1], dp[i][4][1] + ((A[i] >= 2) ? (A[i] & 1) : (2 - A[i])));
                chmin(dp[i + 1][4][0], dp[i][4][1] + A[i]);
            }
            else{
                chmin(dp[i + 1][4][0], dp[i][4][0] + A[i]);
            }
        }
        else if(j == 1){
            chmin(dp[i + 1][2][1], dp[i][1][1] + (~A[i] & 1));
            chmin(dp[i + 1][3][1], dp[i][1][1] + (~A[i] & 1));
            chmin(dp[i + 1][4][1], dp[i][1][1] + ((A[i] >= 2) ? (A[i] & 1) : (2 - A[i])));
            chmin(dp[i + 1][4][0], dp[i][1][1] + A[i]);
        }
        else if(j == 3){
            chmin(dp[i + 1][4][1], dp[i][3][1] + ((A[i] >= 2) ? (A[i] & 1) : (2 - A[i])));
            chmin(dp[i + 1][4][0], dp[i][3][1] + A[i]);
        }
        else{
            chmin(dp[i + 1][2][1], dp[i][2][1] + (~A[i] & 1));
            chmin(dp[i + 1][3][1], dp[i][2][1] + (~A[i] & 1));
        }
    };
    for(int i = 0; i < L; ++i){
        for(int j = 0; j < 5; ++j){
            for(int k = 0; k < 2; ++k){
                update(i, j, k);
            }
        }
    }
    cout << min({dp[L][1][1], dp[L][3][1], dp[L][4][0], dp[L][4][1]}) << endl;
}

