ll dp(int x, int l){
    if(x==0)
        return 0;
    if(mem[x][l]!=-1)
        return mem[x][l];
    ll res=0;
    if(l){
        if(a[x]%2){
            res=min(1+pr[x-1], 1+dp(x-1, 1));
        }
        else if(a[x]==0){
            res=min(pr[x], 2+dp(x-1, 1));
        }
        else{
            res=min(pr[x-1], dp(x-1, 1));
        }
    }
    else{
        if(a[x]%2){
            res=dp(x-1, 0);
        }
        else if(a[x]==0){
            res=min(dp(x-1, 0)+1, pr[x]);
        }
        else{
            res=min(pr[x-1], min(dp(x-1, 0)+1, dp(x-1, 1)));
        }
    }
    mem[x][l]=res;
    return res;
}
ll mem2[200010][2], sf[200010];
ll dp2(int x, int l){
    if(x==n+1){
        return 0;
