		if(i==0)	C1[i] = 0;
		else{
			if(arr[i-1]==0){
				C1[i] = max((ll)0, C1[i-1]-2);
			}else{
				C1[i] = C1[i-1]+arr[i-1]-(arr[i-1]%2);
			}
		}
	}
	for(int i=L; i>=0; i--){
		if(i==L)	C2[i] = 0;
		else{
			if(arr[i]==0){
				C2[i] = max((ll)0, C2[i+1]-2);
			}else{
