lint n;
vector<lint> a, z, e, o, sum;

int main(){
    cin.tie(0);
    ios::sync_with_stdio(false);

    cin >> n;

    a.resize(n);
    rep(i, n){
        cin >> a[i];
    }

    z.resize(n + 1);
    e.resize(n + 1);
    o.resize(n + 1);
    sum.resize(n + 1);
    REP(i, 1, n + 1){
        z[i] = z[i - 1] + (a[i - 1] == 0);
        e[i] = e[i - 1] + (a[i - 1] > 0 && a[i - 1] % 2 == 0);
        o[i] = o[i - 1] + (a[i - 1] % 2);
        sum[i] = sum[i - 1] + a[i - 1];
    }

    vector<lint> v(n + 1);
    rep(i, n + 1){
        v[i] = e[i] - o[i] - z[i];
    }

    segmentTree seg;
    seg.build(v);

    int first = 0, last = n - 1, l = 0, r = n;
    rep(i, n){
        if(a[i] > 0LL){
            first = i;
            l = i;
            break;
        }
    }
    repr(i, n){
        if(a[i] > 0LL){
            last = i;
            r = i + 1;
            break;
        }
    }
    for(int i = last ; i > first ; --i){
        if(sum[r] - sum[i] <= z[r] - z[i]){
            r = i;
        }
    }
    REP(i, first, r + 1){
        if(sum[i] - sum[l] <= z[i] - z[l]){
            l = i;
        }
    }

    lint ans = LLINF;
    REP(i, l, r + 1){
        int k = seg.getMin(i, r + 1).second;
        lint left, mid, right;
        left = o[i] - o[l] + (z[i] - z[l]) * 2LL;
        mid = e[k] - e[i] + z[k] - z[i];
        right = o[r] - o[k] + (z[r] - z[k]) * 2LL;
        chmin(ans, left + mid + right);
    }
    ans += sum[n] - sum[r] + sum[l];

    cout << ans << endl;

    return 0;
}

