    rep(i, L) total += A[i];

    vl left_odd(L, 0);
    vl left_even(L, 0);
    vi lo(L, 0);
    vi le(L, 0);


    rep(i, L) {
        if (i != 0) {
            lo[i] = lo[i - 1];
            le[i] = le[i - 1];
        }
        if (A[i] == 0) {
            left_odd[i] -= 1;
            left_even[i] -= 2;
        } else {
            left_odd[i] += 1 + ((A[i] - 1) / 2) * 2;
            if (A[i] == 1) {
                left_even[i] -= 1;
            } else {
                left_even[i] += A[i] - A[i] % 2;
            }
        }
        if (i != 0 && left_odd[i - 1] > 0) {
            left_odd[i] += left_odd[i - 1];
            lo[i] = i;
        }
        if (i != 0 && left_even[i - 1] > 0) {
            left_even[i] += left_even[i - 1];
            le[i] = i;
        }
        if (i != 0 && left_odd[i - 1] == 0 && A[i] % 2 == 0) {
            lo[i] = i;
        }
        if (i != 0 && left_even[i - 1] > 0 && A[i] % 2) {
            le[i] = i;
        }
    }

    vl right_odd(L, 0);
    vl right_even(L, 0);
    vi ro(L, L - 1);
    vi re(L, L - 1);


    for (int i = L - 1; i >= 0; i--) {
        if (i != L - 1) {
            ro[i] = ro[i + 1];
            re[i] = re[i + 1];
        }
        if (A[i] == 0) {
            right_odd[i] -= 1;
            right_even[i] -= 2;
        } else {
            right_odd[i] += 1 + ((A[i] - 1) / 2) * 2;
            if (A[i] == 1) {
                right_even[i] -= 1;
            } else {
                right_even[i] += A[i] - A[i] % 2;
            }
        }
        if (i != L - 1 && right_odd[i + 1] > 0) {
            right_odd[i] += right_odd[i + 1];
            ro[i] = i;
        }
        if (i != L - 1 && right_even[i + 1] > 0) {
            right_even[i] += right_even[i + 1];
            re[i] = i;
        }
        if (i != L - 1 && right_odd[i + 1] == 0 && A[i] % 2 == 0) {
            ro[i] = i;
        }
        if (i != L - 1 && right_even[i + 1] == 0 && A[i] % 2) {
            re[i] = i;
        }
    }

    ll mi = LONG_LONG_MAX;
    rep(i, L + 1) {
        //左奇右偶
        ll lr = 0;
        //右奇左偶
        ll rl = 0;
        if (i > 0) {
            lr += max(left_odd[i - 1], (ll) 0);
            rl += max(left_even[i - 1], (ll) 0);
            if (A[lo[i-1]] % 2 == 0) lr += 1;
            if (A[le[i-1]] %2) rl += 1;
        }
        if (i < L) {
            lr += max(right_even[i], (ll) 0);
            rl += max(right_odd[i], (ll) 0);
            if (A[re[i]] % 2) lr += 1;
            if (A[ro[i]] % 2 == 1) rl += 1;
        }
        mi = min(mi, min(total - lr, total - rl));
    }

    cout << mi << endl;

    return 0;
}

