ll Z[300500], S[300500], E[300500], O[300500];
ll mx1[300500], mx2[300500];
ll solve(){
    repp(i,N) Z[i] = S[i] = E[i] = O[i] = 0;
    repp(i,N) mx1[i] = mx2[i] = 0;
    repp(i,N){
        S[i] = S[i-1] + p[i];
        O[i] = O[i-1] + ((p[i]%2==1)?1:0);
        E[i] = E[i-1] + ((p[i]%2==0)?1:0);
        Z[i] = Z[i-1] + (p[i]==0)?1:0;
    }
    repp(i,N) mx1[i] = max(mx1[i-1], Z[i]+E[i]-S[i]);
    for(int i=N;i>=1;i--) mx2[i] = max(mx2[i+1], S[i]-O[i]-2*Z[i]);
    ll ans = 1e18;
    for(int M=1;M<=N;M++){ //M=0,N+1
        ll t1 = Z[M] + E[M] - mx1[M];
        ll t2 = S[N]-O[M]-2*Z[M] - mx2[M];
    //    Debug(M,t1,t2);
        ans = min(ans, t1+t2);
    }
    return ans;
}

