using namespace std;
const int N = 2e5+7;
deque<int> q;
ll g[N], f[N], sum3[N];
int a[N], pre[N], sum1[N], sum2[N], sum4[N];
ll query3(int l, int r)
{
	return sum3[r]-sum3[l-1];
}
int query1(int l, int r)
{
	return sum1[r]-sum1[l-1];
}
int query2(int l, int r)
{
	return sum2[r]-sum2[l-1];
}
int query4(int l, int r)
{
	return sum4[r]-sum4[l-1];
}
int main()
{
	int n;
	ll ans = 0, res = 0;
	scanf("%d", &n);
	for(int i = 1; i <= n; i++)
	{
		scanf("%d", &a[i]);
		ans += a[i];
		res += a[i];
		sum1[i] = sum1[i-1]+(a[i]==0?2:(a[i]&1));
		sum2[i] = sum2[i-1]+(a[i]==0?1:((a[i]&1)^1));
		sum3[i] = sum3[i-1]+a[i];
		sum4[i] = sum4[i-1]+(a[i]==0);
	}
	for(int i = n; i >= 1; i--)
	{
		if(a[i]==0)
		{
			pre[i] = i;
		}
		else
		{
			pre[i] = i+1;
		}
	}
	q.push_back(0);
	for(int i = 1; i <= n; i++)
	{
		int j = q.front();
		f[i] = min(f[i-1]+query2(i, i), query3(1, j)+min(query1(j+1, i), query2(j+1, i)));
		while(!q.empty()&&query3(1, q.back())+min(query1(q.back()+1, i), query2(q.back()+1, i))>query3(1, i))
		{
			q.pop_back();
		}
		q.push_back(i);
	}
	q.clear();
	q.push_back(n+1);
	for(int i = n; i >= 1; i--)
	{
		int j = q.front();
		g[i] = min(g[i+1]+query2(i, i), query3(j, n)+min(query2(i, j-1), query1(i, j-1)));
		while(!q.empty()&&query3(q.back(), n)+min(query1(i, q.back()-1), query2(i, q.back()-1))>query3(q.back(), n))
		{
			q.pop_back();
		}
		q.push_back(i);
	}
	res = min(res, f[n]);
	res = min(res, g[1]);
	for(int i = 1; i < n; i++)
	{
		res = min(res, f[i]+g[i+1]);
	}
	printf("%lld\n", res);
    return 0;
}

