typedef long long int64;
typedef pair<int, int> ii;
const int INF = 1 << 29;
const int MOD = 1e9 + 7;

const int N = 2e5 + 10;
int64 a[N];
int64 sum[N], B[N], C[N];
int64 L[N], R[N];

void solve(int64 a[], int n, int64 A[]) {
  for (int i = 0; i < n; ++i) {
    sum[i + 1] = sum[i] + a[i];
  }
  for (int i = 0; i < n; ++i) {
    C[i] = sum[n] - sum[i];
  }
  B[n] = 0;
  for (int i = n - 1; i >= 0; --i) {
    int x = 0;
    if (a[i] == 0) {
      x = 2;
    } else {
      x = a[i] % 2;
    }
    B[i] = min(C[i], B[i + 1] + x);
  }
  A[n] = 0;
  for (int i = n - 1; i >= 0; --i) {
    int x = 1 - a[i] % 2;
    A[i] = min(B[i], A[i + 1] + x);
  }
}

int main() {
  int n;
  scanf("%d", &n);
  for (int i = 0; i < n; ++i) {
    scanf("%lld", &a[i]);
  }
  solve(a, n, R);
  reverse(a, a + n);
  solve(a, n, L);
  int64 ret = 1LL << 60;
  ret = min(ret, R[0]);
  ret = min(ret, L[0]);
  for (int i = 1; i < n; ++i) {
    ret = min(ret, R[i] + L[n - i]);
  }
  printf("%lld\n", ret);
  return 0;
}

