				else {
					rdp[j][i] = min(rdp[j][i], rdp[k][i + 1] + (A[i] <= 1 ? 1 - A[i] : (A[i] - 1) % 2));
				}
			}
		}
	}
	ll res = INF;
	for (int i = 0; i <= L; i++) {
		ll lv = INF, rv = INF;
		for (int j = 0; j < 3; j++) {
			for (int k = 0; k < 3; k++) {
				lv = min(lv, ldp[j][i]);
				rv = min(rv, rdp[k][i]);
			}
		}
		res = min(res, lv + rv);
	}
	cout << res << endl;
	return 0;
}

