		sufval[i] = sufval[i + 1] + (a[i] < 2 ? 2 - a[i] : (a[i] & 1));
		sufsum[i] = sufsum[i + 1] + a[i];
	}
	for (mx = 0, i = 1; i <= l; ++i) minpre[i] = preval[i] - mx, mx = max(mx, preval[i] - presum[i]);
	for (mx = 0, i = l; i; --i) minsuf[i] = sufval[i] - mx, mx = max(mx, sufval[i] - sufsum[i]);
	for (mn = 0, i = 1; i <= l; ++i) {
		mn = min(mn, minpre[i] - midval[i]);
		ans = min(ans, mn + midval[i] + minsuf[i + 1]);
	}
	printf("%lld\n", ans);
	return 0;
}

