typedef long long ll;
const ll N = 2e5 + 100, inF = 2e16;

ll n, a[N], l[N], l_back[N], r[N], r_back[N], help[N], help_back[N];

ll go(ll l) {
	return !(l & 1);
}

ll come(ll l) {
	return (l == 0? 2: l & 1);
}

void build() {
	fill(help, help + N, inF);
	fill(help_back, help_back + N, inF);
	help[n - 1] = help_back[n - 1] = 0;
	ll sum = 0;
	for (int i = n - 2; i >= 0; i--) {
		ll len = a[i];
		sum += len;
		help[i] = go(len) + help[i + 1];
		help_back[i] = come(len) + help_back[i + 1];
		help_back[i] = min(help_back[i], sum);
		help[i] = min(help[i], help_back[i]);
	}
}

