	ios::sync_with_stdio(false), cin.tie(0);
	cin >> n;
	n++;
	for (int i = 0; i < n - 1; i++)
		cin >> a[i];
	build();
	for (int i = 0; i < n; i++)
		r[i] = help[i], r_back[i] = help_back[i];
	reverse(a, a + n - 1);
	build();
	for (int i = 0; i < n; i++)
		l[i] = help[n - i - 1], l_back[i] = help_back[n - i - 1];
	ll ans = inF;
	for (int i = 0; i < n; i++)
		ans = min(ans, min(l_back[i] + r[i], r_back[i] + l[i]));
	cout << ans;
	return 0;
}

