int a[222222];
int f(int i, int j) {
	int c = 0, m = 0, M = 0, b = 0;
	for (int k = i; k < j; k++) {
		b += a[k] % 2;
		c += a[k] % 2 * 2 - 1;
		M = max(M, c - m);
		m = min(m, c);
	}
	return b - M;
}
int main() {
	int l;
	cin >> l;
	for (int i = 0; i < l; i++)
		scanf("%d", a + i);
	long m = 0, s = 0;
	for (int i = 0; i < l;) {
		int j = find(a + i, a + l, 0) - a;
		long t = 0;
		for (int k = i; k < j; k++)
			t += a[k];
		m = max(m, t - f(i, j));
		s += t;
		i = j + 1;
	}
	cout << s - m << endl;
	return 0;
}

