                {
                    // even -> even
                    chmin(res, rec(i + 1, 1) + (A[i]==0?2:A[i] % 2));
                }
                {
                    // even -> odd
                    chmin(res,rec(i+1,2)+(A[i]+1)%2);
                }
                {
                    // even -> 0
                    chmin(res,rec(i+1,4)+A[i]);
                }
            }
            break;

            case 2: {
                {
                    // odd -> odd
                    chmin(res,rec(i+1,2)+(A[i]+1)%2);
                }
                {
                    // odd -> even
                    chmin(res,rec(i+1,3)+(A[i]==0?2:A[i] % 2));
                }
                {
                    // odd -> 0
                    chmin(res,rec(i+1,4)+A[i]);
                }
