    if (j == 0) {
      amin(dp[i+1][0], dp[i][j] + a[i]);
      amin(dp[i+1][1], dp[i][j] + (eo == 1 ? 0 : 1));
      amin(dp[i+1][2], dp[i][j] + (eo == 0 ? 0 : 1) + (a[i] == 0 ? 2 : 0));
      amin(dp[i+1][3], dp[i][j] + (eo == 0 ? 0 : 1) + (a[i] == 0 ? 2 : 0));
      amin(dp[i+1][4], dp[i][j]);
    }
    if (j == 1) {
      amin(dp[i+1][1], dp[i][j] + (eo == 1 ? 0 : 1));
      amin(dp[i+1][3], dp[i][j] + (eo == 0 ? 0 : 1) + (a[i] == 0 ? 2 : 0));
      amin(dp[i+1][4], dp[i][j]);
    }
    if (j == 2) {
      amin(dp[i+1][1], dp[i][j] + (eo == 1 ? 0 : 1));
      amin(dp[i+1][2], dp[i][j] + (eo == 0 ? 0 : 1) + (a[i] == 0 ? 2 : 0));
      amin(dp[i+1][4], dp[i][j]);
