      amin(dp[i+1][4], dp[i][j] + (eo == 0 ? 0 : 1) + (a[i] == 0 ? 2 : 0));
    }
    if (j == 4) {
      amin(dp[i+1][4], dp[i][j] + a[i]);
    }
  }
  int ans = INF;
  amin(ans, dp[L][0]);
  amin(ans, dp[L][1]);
  amin(ans, dp[L][2]);
  amin(ans, dp[L][4]);
  cout << ans << endl;
}

