int main(int, char**)
{
	ll l, ans = 0;
	cin >> l;
	stack<ll> a;
	stack<ll> b;
	bool isZero = false;
	bool istop = true;

	ll n;
	for (ll i = 0; i < l; ++i) {
		ll x;
		cin >> x;
		if (istop &&(x == 0))
			continue;

		istop = false;
		if (isZero) {
			if (x == 0)	
				++n;
			else {
				isZero = false;
				b.push(n);
				n = x;
			}
		} else {
			if (x == 0) {
				isZero = true;
				a.push(n);
				n = 1;
			} else {
				n += x;
			}
		}
	}

	if (a.size() == b.size())
		a.pop();

	while(! b.empty()) {
		ll t = 0;
		if (! a.empty())
			t = a.top();
		if (b.top() > t) 
			ans += t;
		else {
			ans += b.top();
		}
		b.pop(); a.pop();
	}

	cout << ans << endl;
	return 0;
}

