struct MinMonoid {
  using T = lint;
  static T op(const T& lhs, const T& rhs) { return min(lhs, rhs); }
  static constexpr T e() { return numeric_limits<T>::max(); }
};

template<class Monoid> struct SegmentTree {
  using M = Monoid;
  using T = typename M::T;

  const int n;

  SegmentTree(int n, const T& a = M::e()) : n(n), val(2 * n, a) {
    build();
  }

  template<class Itr> SegmentTree(Itr first, Itr last) :
    n(distance(first, last)), val(2 * n, M::e()) {
    copy(first, last, next(begin(val), n));
    build();
  }

  T& operator[](int i) {
    assert(0 <= i and i < n);
    return val[i + n];
  }

  void build() {
    for (int i = n - 1; i > 0; --i) {
      val[i] = M::op(val[2 * i], val[2 * i + 1]);
    }
  }

  T get(int l, int r) const {
    l = max(l, 0), r = min(r, n);
    T resl = M::e(), resr = M::e();
    for (l += n, r += n; l < r; l >>= 1, r >>= 1) {
      if (l & 1) resl = M::op(resl, val[l++]);
      if (r & 1) resr = M::op(val[--r], resr);
    }
    return M::op(resl, resr);
  }

  void set(int i, const T& a) {
    assert(0 <= i and i < n);
    for (val[i += n] = a, i >>= 1; i > 0; i >>= 1) {
      val[i] = M::op(val[2 * i], val[2 * i + 1]);
    }
  }

private:
  V<T> val;
};
using ST = SegmentTree<MinMonoid>;

int main() {
  cin.tie(nullptr); ios_base::sync_with_stdio(false);
  int n; cin >> n;
  V<> a(n); for (int i = 0; i < n; ++i) cin >> a[i];
  V<lint> zero(n + 1), even(n + 1), odd(n + 1);
  for (int i = 0; i < n; ++i) {
    zero[i + 1] = zero[i] + a[i];
    even[i + 1] = even[i] + (a[i] == 0 ? 2 : a[i] & 1);
    odd[i + 1]  = odd[i]  + !(a[i] & 1);
  }

  ST ze(n + 1);
  for (int i = 0; i <= n; ++i) {
    ze[i] = zero[i] - even[i];
  }
  ze.build();
  ST oe(n + 1), ez(n + 1);
  for (int l = 0; l <= n; ++l) {
    ez[l] = even[l] - zero[l];
  }
  ez.build();
  for (int k = 0; k <= n; ++k) {
    oe[k] = odd[k] - even[k] + ez.get(k, n + 1);
  }
  oe.build();

  lint res = 9e18;
  for (int j = 0; j <= n; ++j) {
    lint curr = even[j] - odd[j] + ze.get(0, j + 1) + oe.get(j, n + 1) + zero[n];
    res = min(res, curr);
  }
  cout << res << '\n';
}

