int main(){
    ll l;
    cin >> l;
    vector<ll> a(l, 0);
    rep(i, l) cin >> a[i];

    while(a[0] == 0 && 2 <= l){
        rep(i, l-1) a[i] = a[i+1];
        l--;
    }
    while(a[l-1] == 0 && 2 <= l) l--;

    if(a.size() <= 1){
        cout << 0 << endl;
        return 0;
    }

    ll minn = 0;
    rep(i, l) minn += a[i];
    vector<bool> isOdd(l, false);
    rep(i, l){
        if(a[i]%2 == 1) isOdd[i] = true;
    }

    ll lcost = 0;
    rep(left, l){
        if(minn <= lcost) break;
        ll rcost = 0;
        for(ll right = l; left < right; right--){
            if(minn <= lcost+rcost) break;
            for(ll mid = left; mid < right; mid++){
                ll cnt = 0;
                ll isZL = 0;
                ll isZR = 0;
                for(ll i = left; i < mid; i++){
                    if(isOdd[i]) cnt++;
                    if(a[i] == 0) isZL++;
                }
                for(ll i = mid; i < right; i++){
                    if(!isOdd[i]) cnt++;
                    if(a[i] == 0) isZR++;
                }
                minn = min(minn, lcost+rcost + cnt + 2*isZL);             // even odd
                minn = min(minn, lcost+rcost + right-left-cnt + 2*isZR);  // odd even
            }

            for(ll lmid = left; lmid < right; lmid++){
                for(ll rmid = lmid+1; rmid < right; rmid++){
                    ll cnt = 0;
                    ll isZL = 0;
                    ll isZR = 0;
                    for(ll i = left; i < lmid; i++){
                        if(isOdd[i]) cnt++;
                        if(a[i] == 0) isZL++;
                    }
                    for(ll i = lmid; i < rmid; i++){
                        if(!isOdd[i]) cnt++;
                    }
                    for(ll i = rmid; i < right; i++){
                        if(isOdd[i]) cnt++;
                        if(a[i] == 0) isZR++;
                    }
                    minn = min(minn, lcost+rcost + cnt + 2*isZL + 2*isZR);
                }
            }
            rcost += abs(a[right-1]);
        }
        lcost += abs(a[left]);
    }


    cout << minn << endl;

    return 0;
}

