template <const int MAXN, const bool ONE_INDEXED> struct SegmentTree_RAM_RQ {
    using Data = ll; using Lazy = ll; int N, H; Data T[2 * MAXN]; Lazy L[MAXN]; // L stores lazy values
    const Data def = 0; // default value
    const Data qdef = INT_INF; // query default value
    const Lazy ldef = 0; // lazy default value
    // operation must be associative (but not necessarily commutative)
    Data merge(const Data &l, const Data &r) { return min(l, r); }
    Lazy getSegmentVal(const Lazy &v, int k) { return v; }
    Lazy mergeLazy(const Lazy &l, const Lazy &r) { return l + r; }
    Data applyLazy(const Data &l, const Lazy &r) { return l + r; }
    void apply(int i, const Lazy &v, int k) {
        T[i] = applyLazy(T[i], getSegmentVal(v, k));
        if (i < N) L[i] = mergeLazy(L[i], v);
    }
    void pushup(int i) {
        for (int k = 2; i > 1; k <<= 1) {
            i >>= 1;
            T[i] = L[i] == ldef ? merge(T[i << 1], T[i << 1 | 1]) : applyLazy(merge(T[i << 1], T[i << 1 | 1]), getSegmentVal(L[i], k));
        }
    }
    void propagate(int i) {
        for (int h = H, k = 1 << (H - 1); h > 0; h--, k >>= 1) {
            int ii = i >> h;
            if (L[ii] != ldef) { apply(ii << 1, L[ii], k); apply(ii << 1 | 1, L[ii], k); L[ii] = ldef; }
        }
    }
    template <class It> void init(It st, It en) {
        N = en - st; H = 0; for (int i = 1; i <= N; H++) i <<= 1;
        for (int i = 0; i < N; i++) { T[N + i] = *(st + i); L[i] = ldef; }
        for (int i = N - 1; i > 0; i--) T[i] = merge(T[i << 1], T[i << 1 | 1]);
    }
    void init(int size) {
        N = size; H = 0;
        for (int i = 1; i <= N; H++) i <<= 1;
        for (int i = 1; i < 2 * N; i++) T[i] = def;
        for (int i = 0; i < N; i++) L[i] = ldef;
    }
    void update(int l, int r, const Lazy &v) {
        int l0 = l += N - ONE_INDEXED, r0 = r += N - ONE_INDEXED, k = 1; propagate(l); propagate(r);
        for (; l <= r; l >>= 1, r >>= 1, k <<= 1) {
            if (l & 1) apply(l++, v, k);
            if (!(r & 1)) apply(r--, v, k);
        }
        pushup(l0); pushup(r0);
    }
    Data query(int l, int r) {
        propagate(l += N - ONE_INDEXED); propagate(r += N - ONE_INDEXED); Data ql = qdef, qr = qdef;
        for (; l <= r; l >>= 1, r >>= 1) {
            if (l & 1) ql = merge(ql, T[l++]);
            if (!(r & 1)) qr = merge(T[r--], qr);
        }
        return merge(ql, qr);
    }
};

const int MAXL = 2e5 + 5;

int L;
ll A[MAXL], dp[MAXL], zero[MAXL];
SegmentTree_RAM_RQ<MAXL, 0> ST;

int main() {
    // setInput("in.txt");
    // setOutput("out.txt");
    // setError("err.txt");
    read(L);
    read(A, A + L);
    ST.init(L + 1);
    FOR(i, L) zero[i] = A[i] == 0;
    ll pre = 0, pre2 = 0;
    dp[0] = 0;
    For(i, 1, L + 1) {
        if (zero[i - 1]) pre += 2;
        pre2 += A[i - 1];
        if (A[i - 1] % 2 == 0) ST.update(0, i - 1, 1);
        else pre++;
        if (zero[i - 1]) pre = min(pre, pre2);
        dp[i] = ST.query(0, i - 1);
        ST.update(i, i, pre);
    }
    ll suf = 0, suf2 = 0;
    REV(i, L - 1) {
        if (zero[i]) suf += 2;
        suf2 += A[i];
        if (A[i] % 2 == 1) suf++;
        if (zero[i - 1]) suf = min(suf, suf2);
        dp[i] += suf;
    }
    writeln(*min_element(dp, dp + L + 1));
    return 0;
}

#include "bits/stdc++.h"
using namespace std;
int Array[200005] , Zeros[200005] , Odd[200005];
int Extra[200005];
long long Prefix[200005];

void PreProcess( int N ){
    for( int i = 1 ; i <= N ; ++i ){
        if( Array[i] == 0 ){
            Zeros[i] = Zeros[i - 1] + 1;
            Odd[i] = Odd[i - 1];
        }
        else{
            if( Array[i] % 2 == 1 ) Odd[i] = Odd[i - 1] + 1;
            else Odd[i] = Odd[i - 1];

            Zeros[i] = Zeros[i - 1];
        }

        Prefix[i] = Prefix[i - 1] + Array[i];
    }

    Prefix[N + 1] = Prefix[N];
}

long long Case1( int N , int index ){
    return Prefix[index - 1] + N - index - ( Odd[N] - Odd[index] );  
}

long long Case2( int N , int index ){
    long long Temp1 = Odd[index] + 2 * Zeros[index];
    long long Temp2 = N - index - ( Odd[N] - Odd[index] );
    return Temp1 + Temp2;
}

long long Case3( int N , int index ){
    long long Temp1 = index - Odd[index];
    long long Temp2 = Odd[N] - Odd[index] + 2 * ( Zeros[N] - Zeros[index] );
    return Temp1 + Temp2;
}

long long Case4( int N , int index ){
    return Prefix[N] - Prefix[index] + index - 1 - ( Odd[index] - Odd[1] );
}

long long FindAns( int N ){
    int i;
    long long Ans = 1e18 , Temp;

    for( i = 1 ; i <= N ; ++i ){
        Temp = min( min( Case1( N , i ) , Case2( N , i ) ) , min( Case3( N , i ) , Case4( N , i ) ) );
        Ans = min( Ans , Temp );
    }   

    return Ans;
}

int main(){
    int N , i , j;
    scanf( "%d" , &N );

    for( i = 1 ; i <= N ; ++i ){
        scanf( "%d" , Array + i );
        Extra[i] = Array[i];
        Prefix[i] = Prefix[i - 1] + Array[i];
    }

    int start = 1 , end = N;
    long long Ans = 0;

    for( i = 1 ; i <= N ; ++i ){
        if( Zeros[i] >= Prefix[i] ) start = i + 1;
    }

    for( i = N ; i >= 1 ; --i ){
        if( Zeros[N] - Zeros[i - 1] >= Prefix[N] - Prefix[i - 1] ) end = i - 1;
    }

    if( start == N + 1 || end == 0 ){
        printf( "%lld\n" , Prefix[N] );
        return 0;
    }

    for( i = start , j = 1 ; i <= end ; ++i , ++j )
        Array[j] = Extra[i];

    Ans = Prefix[start - 1] + ( Prefix[N] - Prefix[end] );
    N = end - start + 1;
    PreProcess( N );
    printf( "%lld\n" , Ans + FindAns( N ) );
    return 0;
}

