int main() {
	int n;
	std::cin >> n;
	std::vector<int> a(n);
	for(int i = 0; i < n; i++) {
		std::cin >> a[i];
	}
	std::vector<long long> pathL(n + 1, 0), cycL(n + 1, 0);
	for(int i = 0; i < n; i++) {
		long long pathCost = a[i] % 2 == 1 ? a[i] : a[i] - 1;
		pathL[i+1] = std::max(pathCost + pathL[i], 0LL);
		long long cycCost = a[i] % 2 == 0 ? a[i] : a[i] - 1;
		if(a[i] == 0) {
			cycCost = -2;
		}
		cycL[i+1] = std::max(cycCost + cycL[i], 0LL);
		pathL[i+1] = std::max(pathCost + cycL[i], pathL[i+1]);
	}
	std::vector<long long> pathR(n + 1, 0), cycR(n + 1, 0);
	for(int i = n-1; i >= 0; i--) {
		long long pathCost = a[i] % 2 == 1 ? a[i] : a[i] - 1;
		pathR[i] = std::max(pathCost + pathR[i+1], 0LL);
		long long cycCost = a[i] % 2 == 0 ? a[i] : a[i] - 1;
		if(a[i] == 0) {
			cycCost = -2;
		}
		cycR[i] = std::max(cycCost + cycR[i+1], 0LL);
		pathR[i] = std::max(pathCost + cycR[i+1], pathR[i]);
	}
	long long ans = 0;
	for(int i = 0; i <= n; i++) {
		//std::cout << "on " << i << " got path (" << pathL[i] << ", " << pathR[i] << ") and cyc (" << cycL[i] << ", " << cycR[i] << ")\n";
		ans = std::max(ans, pathL[i] + cycR[i]);
		ans = std::max(ans, pathR[i] + cycL[i]);
		ans = std::max(ans, cycL[i] + cycR[i]);
		//std::cout << "got ans " << ans << '\n';
	}
	ans = -ans;
	for(int i = 0; i < n; i++) {
		ans += a[i];
	}
	std::cout << ans << '\n';
}

