#include <bits/stdc++.h>
using namespace std;
#define REP(i,a,n) for(int i=(a); i<(int)(n); i++)
#define rep(i,n) REP(i,0,n)
#define FOR(it,c) for(__typeof((c).begin()) it=(c).begin(); it!=(c).end(); ++it)
#define ALLOF(c) (c).begin(), (c).end()
typedef long long ll;
typedef unsigned long long ull;

ll dp[200005][2];

ll calc(ll a, int x){
  if(a == 0){
    if(x==0) return 2;
    else return 1;
  }
  return (a%2==0)?x:1-x;
}

ll solve(int L, const vector<ll>& v){
  vector<ll> sum(L+1);
  sum[0] = v[0];
  REP(i,1,v.size()){
    sum[i] = sum[i-1] + v[i];
  }

  rep(i,v.size()){
    //右から入って左へ
    dp[i][0] = ((i>0)?dp[i-1][0]:0) + calc(v[i],0);
    ///前までを捨てる
    dp[i][0] = min(dp[i][0], ((i>0)?sum[i-1]:0) + calc(v[i],0));
    //左から入って左へ
    dp[i][1] = ((i>0)?(min(dp[i-1][0], dp[i-1][1])):0) + calc(v[i],1);
    ///前までを捨てる
    dp[i][1] = min(dp[i][1], ((i>0)?sum[i-1]:0) + calc(v[i],1));                       
  }


  return min(dp[L-1][0], dp[L-1][1]);
}

int main(){
  int L;
  cin >> L;
  vector<ll> v;
  rep(i,L){
    ll a;
    cin >> a;
    v.push_back(a);
  }

  ll ret = solve(L, v);
  reverse(ALLOF(v));
  ret = min(ret, solve(L, v));

  cout << ret << endl;

  return 0;
}

