using namespace std;

#define MAXN 200001

int n;
long a[MAXN];
long dp[MAXN][5];

int input() {
	if (scanf("%d", &n) < 0) return 0;
	for (int i=0; i<n; i++) scanf("%ld", &a[i]);
	return 1;
}

void init() {
	memset(dp, 0, sizeof(dp));
}

long solve() {
	for (int i=1; i<=n; i++) {
		long x = a[i-1];
		long *z = dp[i-1];
		dp[i][0] = z[0] + x;
		dp[i][1] = min(z[0], z[1]) + (x? x%2: 2);
		dp[i][2] = min(z[1], z[2]) + 1-x%2;
		dp[i][3] = min(z[2], z[3]) + (x? x%2: 2);
		dp[i][4] = min(z[3], z[4]) + x;

	}
	return dp[n][4];
}

void output(long ans) {
	printf("%ld\n", ans);
}

void cleanup() {
}

int main() {
	while (input()) {
		init();
		output(solve());
		cleanup();
		//break;
	}
}

