// [0][偶数][奇数][偶数][0]
// dp[i+1][j] = i番目まで割り当てを確定し, i番目に区間jを割り当てたときの最小コスト
// dp[i+1][j] = min(dp[i][j], dp[i][j-1], ..., dp[i][0]) + cost

const int INF = 1 << 30;

int main() {
    int N;
    cin >> N;
    vector<int> A(N);
    for (int i = 0; i < N; i++) cin >> A[i];

    vector<vector<int>> dp(N + 1, vector<int>(5, INF));
    for (int j = 0; j < 5; j++) dp[0][j] = 0;

    for (int i = 0; i < N; i++) {
        for (int j = 0; j < 5; j++) {
            int mn = INF;
            int cost;
            switch (j) {
                case 0:
                case 4:
                    cost = A[i];
                    break;
                case 1:
                case 3:
                    if (A[i] == 0) cost = 2;
                    else cost = A[i] % 2 == 0 ? 0 : 1;
                    break;
                default:
                    cost = A[i] % 2 == 1 ? 0 : 1;
            }

            for (int k = j; k >= 0; k--) mn = min(mn, dp[i][k]);

            dp[i+1][j] = mn + cost;
        }
    }

    int ret = INF;
    for (int j = 0; j < 5; j++) ret = min(ret, dp[N][j]);
    cout << ret << endl;
}

