            if(j <= 0) chmin(dp[i+1][0], dp[i][j]+v[i]);
            if(j <= 1) chmin(dp[i+1][1], dp[i][j]+v[i]%2 + 2*(v[i] == 0));
            if(j <= 2) chmin(dp[i+1][2], dp[i][j]+(v[i]+1)%2);
