using namespace std;
#define MAX 200000000000000
#define ll long long int
inline int isSameWay(vector<ll> way1, vector<ll> way2)
{ //同じベクトルか？
    if (way1.size() == way2.size())
    {
        for (int i = 0; i < way1.size(); i++)
        {
            if (way1[i] == way2[i])
            {
                continue;
            }
            return 0;
        }
    }
    return 1;
}
int myfind(const vector<pair<vector<ll>, ll>> &memo, const vector<ll> way)
{ //メモに登録済みか?
    for (auto &&i : memo)
    {
        if (isSameWay(i.first, way) == 1)
        {
            return 1;
        }
    }
    return 0;
}
void solve(const vector<ll> &A, vector<pair<vector<ll>, ll>> &memo, vector<ll> thisWay, const int &L)
{
    if (myfind(memo, thisWay) == 0)
    { //答えを計算して登録して再帰
        ll ans = 0;
        for (ll i = 0; i < thisWay[0]; i++)
        { //0->D
            ans += A[i];
        }
        for (ll i = thisWay[0]; i < thisWay[1]; i++)
        { //D->S
            if (A[i] == 0)
            {
                ans += 2;
            }
            else if (A[i] % 2 == 1)
            {
                ans++;
            }
        }
        for (ll i = thisWay[1]; i < thisWay[2]; i++)
        { //S->T
            if (A[i] % 2 == 0)
            {
                ans++;
            }
        }
        for (ll i = thisWay[2]; i < thisWay[3]; i++)
        { //T->U
            if (A[i] == 0)
            {
                ans += 2;
            }
            else if (A[i] % 2 == 1)
            {
                ans++;
            }
        }
        for (ll i = thisWay[3]; i < L; i++)
        { //U->L
            ans += A[i];
        }
        pair<vector<ll>, ll> tmp;
        tmp.first = thisWay;
        tmp.second = ans;
        memo.push_back(tmp);
        for (int i = 0; i < 3; i++)
        {
            vector<ll> newWay(thisWay);
            if (newWay[i] < newWay[i + 1])
            {
                newWay[i]++;
                solve(A, memo, newWay, L);
            }
        }
        vector<ll> newWay(thisWay);
        if (newWay[3] < L)
        {
            newWay[3]++;
            solve(A, memo, newWay, L);
        }
    }
    return;
}
int main()
{
    //cin.tie(0);
    //ios::sync_with_stdio(false);
    ll L;
    cin >> L;
    vector<ll> A;
    for (ll i = 0, tmp; i < L; i++)
    {
        cin >> tmp;
        A.push_back(tmp);
    }
    vector<pair<vector<ll>, ll>> memo;
    vector<ll> way(4);
    for (int i = 0; i < 4; i++)
    {
        way[i] = 0;
    }
    solve(A, memo, way, L);
    ll ans = MAX;
    for (auto &&i : memo)
    {
        if (ans > i.second)
        {
            ans = i.second;
        }
    }
    cout << ans << endl;
    return 0;
}

