	vector<lint> dp2(n+1); // dp2[i] = ([0, i] について, i から始めて i より左で終わるときの最小コスト)
	vector<lint> dp3(n+1); // dp3[i] = ([i, n] について, i から始めて i で終わるときの最小コスト)
	vector<lint> dp4(n+1); // dp4[i] = ([i, n] について, i から始めて i より右で終わるときの最小コスト)
