ll dp[200005][5];

ll score(ll a, int t)
{
	if (t == 0 || t == 4) return a;
	if (t == 1 || t == 3) {
		if (a == 0) return 2;
		return a % 2;
	}

	return (a + 1) % 2;
}

int main()
{
	cin >> l;
	for (int i = 1;i <= l;i++) {
		cin >> a[i];
	}

	for (int i = 1;i <= l;i++) {
		for (int j = 0;j < 5;j++) {
			dp[i][j] = INF;
		}
	}

	for (int i = 0;i <= l;i++) {
		for (int j = 0;j < 5;j++) {
			if(j) dp[i][j] = min(dp[i][j], dp[i][j - 1]);
			dp[i + 1][j] = min(dp[i + 1][j], dp[i][j] + score(a[i], j));
		}
	}

	ll ret = INF;
	for (int j = 0;j < 5;j++) ret = min(ret, dp[l][j]);

	cout << ret << endl;

	return 0;
}

#include<bits/stdc++.h>
using namespace std;
#define nn 65536*4
#define ll long long
#define mod 998244353

ll a[nn];ll n;
ll pre1[nn];ll pre2[nn];
ll smax,smin;ll s[nn];ll ans=0;ll d[nn];
void solve()
{
	pre1[0]=pre2[0]=0;
	for(int i=1;i<=n;i++)
	{	
		if(a[i]%2==0 and a[i]>0) pre1[i]=pre1[i-1]+1;
		else pre1[i]=pre1[i-1]-1;

		pre2[i]=pre2[i-1]+a[i];
		if(a[i]%2==0) pre2[i]--;
	}
	smin=pre2[n];
	for(ll i=n;i>=0;i--)
	{
		ans=max(ans,smin-pre2[i]);
		smin=max(smin,pre2[i]);
	}
	pre2[n+1]=-1e17;
	for(int i=n;i>=1;i--) d[i]=pre1[i-1]+pre2[i-1],pre2[i]=max(pre2[i],pre2[i+1]);
	for(int i=0;i<=n;i++)
		s[i]=pre1[i]+pre2[i];
	smax=s[n];d[0]=0;
	for(ll i=n;i>=1;i--)
	{
		smax=max(smax,s[i]);
		ans=max(smax-d[i],ans);
	}
}
int main()
{
	scanf("%lld",&n);ll bas=0;
	for(int i=1;i<=n;i++) 
	{
		scanf("%lld",&a[i]);bas+=a[i];
	}
	solve();
	reverse(a+1,a+n+1);
	solve();
	cout<<bas-ans;
	return 0;
}

