typedef long long ll;
#define fr(i,n) for(int i=0;i<n;i++)
#define ifr(i,n) for(int i=n-1;i>=0;i--)

ll b0(ll p){
  return 1-(p%2);
}

ll b1(ll p){
  if(p==0) return 2;
  return p%2;
}

ll dat[1000020],n,a[500010]={};
const ll INF=1e17;

void init(ll n_){
  n=1;
  while(n<n_) n*=2;
  fr(i,2*n-1) dat[i]=INF;
}

void ud(ll k,ll c){
  k+=n-1;
  dat[k]=c;
  while(k>0){
    k=(k-1)/2;
    dat[k]=min(dat[2*k+1],dat[2*k+2]);
  }
}

ll mn(ll be,ll en,ll k=0,ll l=0,ll r=n){
  if(r<=be||en<=l) return INF;
  if(be<=l&&r<=en) return dat[k];
  return min(mn(be,en,k*2+1,l,(l+r)/2),mn(be,en,k*2+2,(l+r)/2,r));
}




