int solve(){
  int L;cin>>L;
  int a[L]; rep(i, L) {cin>>a[i];}

  // dp[0][i]: 区間iから1本でstartして左側
  // dp[1][i]: 区間iから2本でstartして左側

  int s[L]={};s[0]=a[0];
  rep(i, 1, L){
    s[i] = s[i-1] + a[i];
  }
  dump_1d(s, L);

  int dp[2][L];
  rep(i, 2)rep(j, L) dp[i][j] = INF;
  dp[0][0] = 0;
  dp[1][0] = 0;
  int res = s[L-1]-s[0];
  rep(i, 1, L){

    if (a[i]==0) {
      chmin(dp[0][i], s[i]); // do nothing
      chmin(dp[0][i], dp[0][i-1] + 1);  // 1

      chmin(dp[1][i], s[i]); // do nothing
      chmin(dp[1][i], dp[0][i-1] + 1);  // 1
      chmin(dp[1][i], dp[1][i-1] + 2);  // 2
    }
    else{
      if (a[i]%2==0) chmin(dp[0][i], s[i-1]);  // return
      else chmin(dp[0][i], s[i-1]+1);  // return
      chmin(dp[0][i], dp[0][i-1] + (a[i]%2==0?1:0));  // 1

      if (a[i]%2==0) chmin(dp[1][i], s[i-1]);  // return
      else chmin(dp[1][i], s[i-1]+1);  // return
      chmin(dp[1][i], dp[1][i-1] + (a[i]%2==0?0:1));  // 1
      chmin(dp[1][i], dp[0][i-1] + (a[i]%2==0?1:0));  // 2
    }

    // uadte res
    chmin(res, dp[1][i]+(s[L-1]-s[i]));
    chmin(res, dp[0][i]+(s[L-1]-s[i]));
  }

  dump_2d(dp, 2, L);
  cout << res << endl;

  return 0;
}

