int gocost(int l,int r){
	int i,j,k,s=0;
	for(i=l;i<=r;++i){
		s+=(a[i]&1);
	}
	return s;
}
LL leavecost(int l,int r){
	int i,j,k;
	LL s=0ll;
	for(i=l;i<=r;++i){
		s+=(LL)a[i];
	}
	return s;
}
int startcost(int l,int r){
	int i,j,k,s=0;
	for(i=l;i<=r;++i){
		s+=(a[i]&1);
	}
	int cl=0,mx=0;
	for(i=l;i<=r;++i){
		if(a[i]&1){
			++cl;
			mx=max(mx,cl);
		}
		else{
			cl=0;
		}
	}
	return s-mx;
}
LL sc[200005],lc[200005],ls[200005],lr[200005],gc[200005];
int ll[200005],rr[200005],cnt;
LL dp[200005][2],res=100000000000ll;
void upd(int i,int j,LL v){
	if(dp[i][j]==-1ll) dp[i][j]=v;
	else dp[i][j]=min(dp[i][j],v);
}
int main(){
	int i,j,k;
	scanf("%d",&n);
	for(i=0;i<n;++i){
		scanf("%d",a+i);
	}
	a[n++]=0;
	int ln=0;
	for(i=0;i<n;++i){
		if(a[i]){
			++ln;
		}
		else{
			if(ln){
				int L=i-ln;
				int R=i-1;
				sc[cnt]=startcost(L,R);
				lc[cnt]=ls[cnt]=lr[cnt]=leavecost(L,R);
				gc[cnt]=gocost(L,R);
				ll[cnt]=L;
				rr[cnt]=R;
				//printf("new %d %lld %d %d %d\n",(int)sc[cnt],lc[cnt],(int)gc[cnt],L,R);
				++cnt;
			}
			ln=0;
		}
	}
	for(i=1;i<cnt;++i) ls[i]+=ls[i-1];
	for(i=cnt-2;i>=0;--i) lr[i]+=lr[i+1];
	lr[cnt]=0ll;
	memset(dp,-1,sizeof(dp));
	dp[0][0]=gc[0];
	dp[0][1]=sc[0];
	res=min(gc[0]+lr[1],sc[0]+lr[1]);
	for(i=1;i<cnt;++i){
		// start here
		upd(i,0,gc[i]+ls[i-1]);
		upd(i,1,sc[i]+ls[i-1]);
		// otherwise
		upd(i,0,dp[i-1][0]+(LL)(ll[i]-rr[i-1]-1)+gc[i]);
		upd(i,1,dp[i-1][0]+(LL)(ll[i]-rr[i-1]-1)+sc[i]);
		upd(i,1,dp[i-1][1]+(LL)(ll[i]-rr[i-1]-1)+gc[i]);
		// update
		res=min(res,dp[i][1]+lr[i+1]);
		res=min(res,dp[i][0]+lr[i+1]);
	}
	printf("%lld\n",res);
	return 0;
}

