void solve() {
    array<array<ll, 4>, 2> dp;
    {
        auto f = A[0];
        bool odd = f % 2;
        bool nonzero = f > 0;
        dp[0] = {
            odd ? 1 : (nonzero ? 0 : 2),
            odd ? 0 : 1,
            odd ? 1 : (nonzero ? 0 : 2),
            f
        };
    }
    ll sum = A[0];
    for (ll i = 1; i < L; i++) {
        bool odd = A[i] % 2 == 1;
        bool nonzero = A[i] > 0;
        auto& pdp = dp[(i - 1) % 2];
        dp[i % 2] = {
            min(sum, pdp[0]) + (odd ? 1 : (nonzero ? 0 : 2)),
            min(pdp[0], pdp[1]) + (odd ? 0 : 1),
            min(pdp[1], pdp[2]) + (odd ? 1 : (nonzero ? 0 : 2)),
            min(pdp[2], pdp[3]) + A[i]
        };
        sum += A[i];
    }
    auto& bdp = dp[(L-1)%2];
    ll ans = *min_element(bdp.begin(), bdp.end());
    cout << ans << endl;
}

