int N;
int A[202020];
ll S[202020];
ll L[202020][3];
ll R[202020];
void solve() {
	int i,j,k,l,r,x,y; string s;

	cin>>N;

	FOR(i,N) {
		cin>>A[i];
		S[i+1]=S[i]+A[i];
	}

	FOR(i,N) {
		if(A[i]==0) {
			L[i+1][0]=min(S[i+1],2+L[i][0]);
		}
		else {
			L[i+1][0]=min({S[i+1],L[i][0]+A[i]%2});
		}
		L[i+1][1]=min(L[i][0],L[i][1])+(1-A[i]%2);
	}
	R[N]=0;
	ll mi=min(L[N][0],L[N][1]);
	for(i=N-1;i>=0;i--) {
		if(A[i]==0) {
			R[i]=min(S[N]-S[i],2+R[i+1]);
		}
		else {
			R[i]=min({S[N]-S[i],(A[i]%2+R[i+1])});
		}
		mi=min({mi,R[i]+L[i][0],R[i]+L[i][1]});
	}
	cout<<mi<<endl;
}


