void Main(){
    int L; cin >> L;
    VL A(L); REP(i,L) cin >> A[i];

    ll dp[L+1][5]; REP(i,L+1)REP(j,5) dp[i][j] = LINF;
    REP(i,5) dp[0][i] = 0;

    REP(i,L)REP(j,5){
        if(j == 0 || j == 4) chmin(dp[i+1][j], dp[i][j]+A[i]);
        else if(j == 2) chmin(dp[i+1][j], dp[i][j] + (A[i]%2 != 1));
        else if(j < 4){
            if(A[i] > 0) chmin(dp[i+1][j], dp[i][j] + (A[i]%2 != 0));
            else chmin(dp[i+1][j], dp[i][j] + 2);
        }

        if(j < 4) chmin(dp[i+1][j+1], dp[i+1][j]);
    }

    ll ans = dp[L][4];
    cout << ans << en;
    return;
}

