int solve(int l, int r) {
	//cerr << 'a';
	//cerr << l << ' ' << r;
	vector<int> b;
	b.push_back(0);
	int s = 0;
	for (int i = l; i <= r; i++) {
		if (a[i] != b.back()) b.push_back(a[i]);
		s += a[i];
	}
	b.push_back(0);
	int x = 0;
	for (int i = 1; i + 1 < b.size(); i++) {
		if (b[i] > b[i - 1] && b[i] > b[i + 1]) x++;
	}
	//cerr << "nd";
	return s - x + 1;
}


