int main(){
  int l;
  cin >> l;

  vector<int> odd(l+1);
  vector<int> zero(l+1);
  vector<int> even(l+1);
  vector<long long> sum(l+1);
  for(int i = 1;i <= l;i++){
    odd[i] = odd[i-1];
    even[i] = even[i-1];
    zero[i] = zero[i-1];
    sum[i] = sum[i-1];
    int a;
    cin >> a;
    if(a%2 == 1){
      odd[i]++;
    }else if(a == 0){
      zero[i]++;
    }else{
      even[i]++;
    }
    sum[i] += a;
  }

  long long ret = 0;
  int lef = 1;
  int tmp = 0;
  for(int i = 1;i <= l+1;i++){
    if(zero[i-1] - sum[i-1] >= tmp){
      tmp = zero[i-1] - sum[i-1];
      lef = i;
    }
  }
  ret += sum[lef-1];
  //cout << ret << endl;
  int righ = l;
  tmp = 0;
  for(int i = l-1;i >= lef;i--){
    if((zero[l] - zero[i]) - (sum[l] - sum[i]) >= tmp){
      tmp = (zero[l] - zero[i]) - (sum[l] - sum[i]);
      righ = i;
    }
  }
  if(lef < righ){
    ret += sum[l] - sum[righ];
  }
  //cout << ret << endl;
  int lee = lef;
  tmp = 0;
  for(int i = lef;i <= righ+1;i++){
    if((even[i-1] - even[lef-1]) - (odd[i-1] - odd[lef-1]) - 2*(zero[i-1] - zero[lef-1]) > tmp){
      tmp = (even[i-1] - even[lef-1]) - (odd[i-1] - odd[lef-1]) - 2*(zero[i-1] - zero[lef-1]);
      lee = i;
    }
  }
  ret += (odd[lee-1] - odd[lef-1]) + 2*(zero[lee-1] - zero[lef-1]);
  //cout << ret << endl;
  int rie = righ;
  tmp = 0;
  for(int i = righ;i >= lee;i--){
    if((even[righ] - even[i]) - (odd[righ] - odd[i]) - 2*(zero[righ] - zero[i]) > tmp){
      tmp = (even[righ] - even[i]) - (odd[righ] - odd[i]) - 2*(zero[righ] - zero[i]);
      rie = i;
    }
  }
  if(rie > lee){
    ret += (odd[righ] - odd[rie]) + 2*(zero[righ] - zero[rie]);
  }
  //cout << ret << endl;

  if(rie > lee){
    ret += (even[rie] - even[lee+1]) + (zero[rie] - even[lee+1]);
  }
  cout << ret << endl;
}

