template <int mod>
struct ModInt {
    int x;

    ModInt() : x(0) {}

    ModInt(int64_t y) : x(y >= 0 ? y % mod : (mod - (-y) % mod) % mod) {}

    ModInt &operator+=(const ModInt &p) {
        if((x += p.x) >= mod)
            x -= mod;
        return *this;
    }

    ModInt &operator-=(const ModInt &p) {
        if((x += mod - p.x) >= mod)
            x -= mod;
        return *this;
    }

    ModInt &operator*=(const ModInt &p) {
        x = (int)(1LL * x * p.x % mod);
        return *this;
    }

    ModInt &operator/=(const ModInt &p) {
        *this *= p.inverse();
        return *this;
    }

    ModInt operator-() const { return ModInt(-x); }

    ModInt operator+(const ModInt &p) const { return ModInt(*this) += p; }

    ModInt operator-(const ModInt &p) const { return ModInt(*this) -= p; }

    ModInt operator*(const ModInt &p) const { return ModInt(*this) *= p; }

    ModInt operator/(const ModInt &p) const { return ModInt(*this) /= p; }

    bool operator==(const ModInt &p) const { return x == p.x; }

    bool operator!=(const ModInt &p) const { return x != p.x; }

    ModInt inverse() const {
        int a = x, b = mod, u = 1, v = 0, t;
        while(b > 0) {
            t = a / b;
            swap(a -= t * b, b);
            swap(u -= t * v, v);
        }
        return ModInt(u);
    }

    ModInt pow(int64_t n) const {
        ModInt ret(1), mul(x);
        while(n > 0) {
            if(n & 1)
                ret *= mul;
            mul *= mul;
            n >>= 1;
        }
        return ret;
    }

    friend ostream &operator<<(ostream &os, const ModInt &p) {
        return os << p.x;
    }

    friend istream &operator>>(istream &is, ModInt &a) {
        int64_t t;
        is >> t;
        a = ModInt<mod>(t);
        return (is);
    }

    static int get_mod() { return mod; }
};

using mint = ModInt<MOD>;

void solve() {
    ll n;
    cin >> n;
    vec<ll> a(n);
    REP(i, n) { cin >> a[i]; }

    vvec<ll> dp(n + 1, vec<ll>(5, INF));
    dp[0][0] = 0;
    REP(i, n) {
        chmin(dp[i + 1][0], dp[i][0] + a[i]);

        chmin(dp[i + 1][1], dp[i][0] + (a[i] == 0 ? 2 : a[i] % 2));
        chmin(dp[i + 1][1], dp[i][1] + (a[i] == 0 ? 2 : a[i] % 2));

        chmin(dp[i + 1][2], dp[i][0] + (1 - a[i] % 2));
        chmin(dp[i + 1][2], dp[i][1] + (1 - a[i] % 2));
        chmin(dp[i + 1][2], dp[i][2] + (1 - a[i] % 2));

        chmin(dp[i + 1][3], dp[i][0] + (a[i] == 0 ? 2 : a[i] % 2));
        chmin(dp[i + 1][3], dp[i][1] + (a[i] == 0 ? 2 : a[i] % 2));
        chmin(dp[i + 1][3], dp[i][2] + (a[i] == 0 ? 2 : a[i] % 2));
        chmin(dp[i + 1][3], dp[i][3] + (a[i] == 0 ? 2 : a[i] % 2));

        chmin(dp[i + 1][4], dp[i][0] + a[i]);
        chmin(dp[i + 1][4], dp[i][1] + a[i]);
        chmin(dp[i + 1][4], dp[i][2] + a[i]);
        chmin(dp[i + 1][4], dp[i][3] + a[i]);
        chmin(dp[i + 1][4], dp[i][4] + a[i]);
    }

    ll ans = INF;
    REP(j, 5) { chmin(ans, dp[n][j]); }
    cout << ans << en;
}

