		scanf("%d", &a[i]);
		midval[i] = midval[i - 1] + (~a[i] & 1);
		preval[i] = preval[i - 1] + (a[i] < 2 ? 2 - a[i] : (a[i] & 1));
		presum[i] = presum[i - 1] + a[i];
	}
	for (i = l; i; --i) {
		sufval[i] = sufval[i + 1] + (a[i] < 2 ? 2 - a[i] : (a[i] & 1));
