    cin >> a[i];
    acc[i] = acc[i-1] + a[i];
  }

  to_left[0] = 0LL;
  for(int i = 1;i <= l;++i){
    if(a[i] == 0) {
      to_left[i] = min(2 + to_left[i-1], acc[i]);
    } else {
      to_left[i] = min(a[i]%2 + to_left[i-1], acc[i]);
    }
