      to_right[i] = min(a[i+1]%2 + to_right[i+1], acc[l] - acc[i]);
    }
  }

  dp[0] = 0LL;
  for(int i = 1;i <= l;++i){
    dp[i] = min((a[i]+1) % 2 + dp[i-1], to_left[i]);
  }
