using namespace std;

long long cost(long long* A, const long long& index, const long long& area){
  if (area==0 || area==4) {
    return A[index];
  } else if (area==1 || area==3) {
    if (A[index]==0) {
      return 2;
    } else if(A[index]%2==0) {
      return 0;
    } else {
      return 1;
    }
  } else if (area==2){
    if (A[index]%2==0){
      return 1;
    } else {
      return 0;
    }
  }
}

int main() {
  long long n;
  cin >> n;

  long long A[n];
  for(long long i=0;i<n;i++){
    cin >> A[i];
  }

  vector< vector<long long> > dp;
  dp.resize(n);
  for(long long i=0; i<n; i++){
    dp[i].resize(5);
  }

  for(int j=0;j<5;j++){
    dp[0][j] = cost(A,0,j);
  }

  for(long long i=1;i<n;i++){
    dp[i][0] = dp[i-1][0]+cost(A,i,0);
    for(int j=1;j<5;j++){
      long long mindp = *std::min_element(dp[i-1].begin(), dp[i-1].begin()+j+1);
      dp[i][j] = min(mindp+cost(A,i,j), dp[i][j-1]);
    }
  }

  long long ans = *std::min_element(dp[n-1].begin(), dp[n-1].end());
  cout << ans << endl;

  return 0;
}

