			f[i][0] = f[i - 1][0];
			f[i][1] = f[i - 1][1] + 2;
			f[i][2] = min(f[i - 1][1], f[i - 1][2]) + 1;
			f[i][3] = min(f[i - 1][2], f[i - 1][3]) + 2;
			f[i][4] = min3(f[i - 1][2], f[i - 1][3], f[i - 1][4]);
