			f[i][2] = min3(f[i - 1][0], f[i - 1][1], f[i - 1][2]);
			f[i][3] = min(f[i - 1][2], f[i - 1][3]) + 1;
			f[i][4] = min(f[i - 1][3], f[i - 1][4]) + a[i];
		}
		else{
			f[i][0] = f[i - 1][0] + a[i];
			f[i][1] = min(f[i - 1][0], f[i - 1][1]);
