typedef long long ll;
const ll INF=1e18+7107;
int n,a[200005];
ll sum[200005],f[200005][2],dpf[200005][2],dpb[200005][2],ans;
int main()
{
	scanf("%d",&n);
	for(int i=1;i<=n;i++) scanf("%d",&a[i]);
	for(int i=1;i<=n;i++) sum[i]=sum[i-1]+a[i];
	for(int i=0;i<=n;i++) dpf[i][0]=dpf[i][1]=dpb[i][0]=dpb[i][1]=f[i][0]=f[i][1]=INF;
	ans=INF;
	dpf[0][0]=0;
	for(int i=1;i<=n;i++)
	{
		dpf[i][0]=sum[i-1]+((a[i]&1)|(!a[i]));
		dpf[i][1]=min(dpf[i-1][0],dpf[i-1][1])+((a[i]&1)|(!a[i]));
		//printf("i=%d dpf=(%lld,%lld)\n",i,dpf[i][0],dpf[i][1]);
	}
	dpb[n+1][0]=0;
	for(int i=n;i>=1;i--)
	{
		dpb[i][0]=sum[n]-sum[i]+((a[i]&1)|(!a[i]));
		dpb[i][1]=min(dpb[i+1][0],dpb[i+1][1])+((a[i]&1)|(!a[i]));
		//printf("i=%d dpb=(%lld,%lld)\n",i,dpb[i][0],dpb[i][1]);
	}
	f[0][0]=0;
	for(int i=1;i<=n;i++)
	{
		f[i][0]=min(min(dpf[i-1][0],dpf[i-1][1]),sum[i-1]);
		f[i][1]=min(f[i-1][0],f[i-1][1])+((a[i]&1)^1);
		//printf("i=%d f=(%lld,%lld)\n",i,f[i][0],f[i][1]);
		ans=min(ans,min(f[i][0],f[i][1])+min(min(dpb[i+1][0],dpb[i+1][1]),sum[n]-sum[i]));
	}
	printf("%lld\n",ans);
	return 0;
}

