unsigned long long hit_pocket(unsigned long long K, unsigned long long A, unsigned long long B){
    if (B <= A+2)
        return K + 1;
    else if (K <= A+1)
        return K + 1;
    else{//換金に意味あり
        unsigned long long first_kankin = A - 1;
        if ((K - first_kankin) %2 == 0){
            return A + (B - A)*((K - first_kankin)/2);
        }else{
            return A + (B - A)*((K - first_kankin -1)/2) + 1;
        }

    }
}

