        left1[i + 1][0] = left1[i][0] + a[i];
        left1[i + 1][1] = min(left1[i][0], min(left1[i][1], left2[i][1])) + 1 - a[i] % 2;
        left2[i + 1][0] = left2[i][0] + a[i];
        left2[i + 1][1] = min(left2[i][0], left2[i][1]) + a[i] % 2;
        if (a[i] == 0) left2[i + 1][1] += 2;
    }

    for (i = l - 1; i >= 0; i--) {
        right1[i][0] = right1[i + 1][0] + a[i];
        right1[i][1] = min(right1[i + 1][0], min(right1[i + 1][1], right2[i + 1][1])) + 1 - a[i] % 2;
        right2[i][0] = right2[i + 1][0] + a[i];
        right2[i][1] = min(right2[i + 1][0], right2[i + 1][1]) + a[i] % 2;
        if (a[i] == 0) right2[i][1] += 2;
    }

    for (i = 0; i <= l; i++) {
        ans = min(ans, min(left1[i][0], left1[i][1]) + min(right2[i][0], right2[i][1]));
        ans = min(ans, min(left2[i][0], left2[i][1]) + min(right1[i][0], right1[i][1]));
    }

    printf("%lld\n", ans);

    return 0;
}

