ll solve(int L, vi& a) {
    vector<vll> dp(L+1, vll(8, LLONG_MAX));
    dp[0][0] = 0;

    rep(i,L){
        int k = (a[i] % 2) ? 0 : 1;
        int g = (a[i] % 2) ? 1 : 0; if (a[i]==0) g=2;

        if (dp[i][0] != LLONG_MAX) {
            amin(dp[i+1][0], dp[i][0] + a[i]);
            amin(dp[i+1][1], dp[i][0] + k);
            amin(dp[i+1][2], dp[i][0] + g);
            amin(dp[i+1][7], dp[i][0] + a[i]);
        }
        if (dp[i][1] != LLONG_MAX) {
            amin(dp[i+1][1], dp[i][1] + k);
            amin(dp[i+1][3], dp[i][1] + g);
            amin(dp[i+1][7], dp[i][1] + a[i]);
        }
        if (dp[i][2] != LLONG_MAX) {
            amin(dp[i+1][2], dp[i][2] + g);
            amin(dp[i+1][4], dp[i][2] + k);
            amin(dp[i+1][7], dp[i][2] + a[i]);
        }
        if (dp[i][3] != LLONG_MAX) {
            amin(dp[i+1][3], dp[i][3] + g);
            amin(dp[i+1][7], dp[i][3] + a[i]);
        }
        if (dp[i][4] != LLONG_MAX) {
            amin(dp[i+1][4], dp[i][4] + k);
            amin(dp[i+1][6], dp[i][4] + g);
            amin(dp[i+1][7], dp[i][4] + a[i]);
        }
        if (dp[i][6] != LLONG_MAX) {
            amin(dp[i+1][6], dp[i][6] + g);
            amin(dp[i+1][7], dp[i][6] + a[i]);
        }
        if (dp[i][7] != LLONG_MAX) {
            amin(dp[i+1][7], dp[i][7] + a[i]);
        }
    }

    return *min_element(ALL(dp[L]));
}

