        b[0] = b[4] = a;
        b[1] = b[3] = a > 0 ? a % 2 : 2;
        b[2] = (a+1) % 2;
        for ( int j = 0; j < 5; j++ ) {
            for ( int k = 0; k <= j; k++ ) {
                dp[i+1][j] = min(dp[i+1][j], dp[i][k] + b[j]);
            }
        }
    }
    ll ans = INF;
    for ( int i = 0; i < 5; i++ ) {
        ans = min(ans, dp[L][i]);
    }
    return ans;
}

