    ll right(vector<ll> L) {
        vector<ll> lcos(L.size());
        vector<ll> rcos(L.size());
        rep(i, 0, L.size()) {
            if (L[i] % 2 == 1) {
                lcos[i] = 1;
            } else {
                rcos[i] = 1;
            }
            if (L[i] == 0) {
                lcos[i] = 2;
            }
        }

        int n = L.size();
        vector<ll> lsum(L.size() + 2);
        vector<ll> rsum(L.size() + 2);
        vector<ll> lcs(L.size() + 2);
        vector<ll> rcs(L.size() + 2);
        for (int i = 0; i < n; ++i) {
            lsum[i + 1] = lsum[i] + L[i];
            rcs[i + 1] = rcs[i] + rcos[i];
        }

        for (int i = n; i > 0; --i) {
//            rsum[i] = rsum[i + 1] + L[i];
//            rcs[i] = rcs[i + 1] + rcos[i];
            rsum[i] = rsum[i + 1] + L[i - 1];
            lcs[i] = lcs[i + 1] + lcos[i - 1];
        }

        vector<ll> lval(n + 2);
        vector<ll> rval(n + 2);

        ll val = INFl;
        for (int i = 2; i <= n; ++i) {
            lval[i] = lsum[i - 2] + lcs[i - 1] - lcs[i];
            rval[i] = rsum[i + 1] + rcs[i] - rcs[i - 1];
//            ll tmp = lval[i] + rval[i];
//            chmin(val, tmp);
        }
        for (int i = 2; i < n; ++i) {
            lval[i] = min(lval[i], lval[i - 1]);
        }
        for (int i = n - 2; i >= 1; --i) {
            rval[i] = min(rval[i], rval[i + 1]);
        }

        for (int i = 3; i < n - 3; ++i) {
            ll tmp = lval[i] + rval[i + 1];
            chmin(val, tmp);
        }

        return val;
    }

