ll calc2(const vector<vector<ll>>& a) {
    int n = a.size();
    vector<ll> sum(n);
    rep(i, n) {
        rep(j, a[i].size()) sum[i] += a[i][j];
    }
    ll ret = 1e18;
    ll ans = 0LL;
    rep(i, n) {
        if(a[i].size() == 0) {
            ret = min(ret, ans + sum[n-1] - sum[i]);
            ++ans;
        }
        else {
            rep(j, a[i].size()-1) {
                if(a[i][j]%2 == 0 && a[i][j+1]%2 == 1) ans++;
            }
        }
    }
    ret = min(ans, ret);
    return ret;
}

