int main() {
	ll L; cin >> L;
	V<ll> A(L+2,0),B(L+2,0),C(L+2,0),F(L+2,0);
	FOR(i,1,L+1) cin >> A[i];
	FOR(i,1,L+1) B[i] = bool(A[i]);

	corner(accumulate(ALL(B),0LL)<=1,0);

	for(int i = 0; i < L + 2; ++i) B[i] = 0;
	for(int i = 1; i < L + 2; ++i) B[i] += B[i-1] + A[i];

	int l,r;
	for(l = 0; l < L; ++l){
		if(A[l]>0) break;
	}
	for(r = L+1; 0 <= r; --r){
		if(A[r] > 0) break;
	}
	for(int i = l; i <= r; ++i){
		if(A[i]%2==0) C[i]++;
	}
	for(int i = 1; i < L + 2; ++i) F[i] += F[i-1] + C[i];


	V<ll> D(L+2,0);
	for(int i = 0; i < L+2; ++i) D[i] = i;
	for(int i = 0; i < L;){
		V<int> v;
		while(i < L && A[i]%2==0 && A[i] > 0) {
			v.push_back(i);
			++i;
		}
		for(auto e:v) D[e] = i;
		++i;
	}

	V<ll> E(L+2,0);
	for(int i = L+1; 0 < i; --i) E[i] = i;
	for(int i = L - 1; 0 < i;){
		V<int> v;
		while( 0 < i && A[i]%2==0&& A[i] > 0) {
			v.push_back(i);
			--i;
		}
		for(auto e:v) E[e] = i;
		--i;
	}
	ll ans = LLINF;
	for(int i = 1; i < L + 1; ++i){
		ll cnt = 0;
		cnt += B[i];
		cnt += F[L] - F[D[i+1]];
		chmin(ans,cnt);
	}
	for(int i = L; 0 < i; --i){
		ll cnt = 0;
		cnt += B[L+1] - B[i];
		cnt += F[E[i]];
		chmin(ans,cnt);
	}
	cout << ans << endl;
	return 0;
}

