signed main(){
	ll n;
	cin >> n;
	vector<ll> a(n);
	for(auto& x : a)
		cin >> x;
	// dp[i][j]: i番目の時点で{未開始,偶数,奇数,奇数終わり}ムーブな時の矛盾の最小値
	// 奇数である範囲は連続でなければならない

	vector<vector<ll>> dp(n + 1, vector<ll>(4, INF));
	dp[0][0] = 0;
	for(ll i = 0; i < n; ++i)
		dp[i + 1][0] = dp[i][0] + a[i];
	ll ans = INF;
	vector<ll> brui(n + 1, 0);
	for(ll i = n - 1; i >= 0; --i)
		brui[i] = brui[i + 1] + a[i];
	for(ll i = 0; i < n; ++i){
		// 偶数部分でスタート
		dp[i + 1][1] = min(dp[i + 1][1], dp[i][0] + (a[i] ? (a[i] % 2) : 2));
		// 奇数部分でスタート a[i]=0の時も挙動変わらない
		dp[i + 1][2] = min(dp[i + 1][2], dp[i][0] + !(a[i] % 2));
		// 奇数離脱部分でスタート
		dp[i + 1][3] = min(dp[i + 1][3], dp[i][0] + (a[i] ? (a[i] % 2) : 2));

		// 偶数部分を続ける
		dp[i + 1][1] = min(dp[i + 1][1], dp[i][1] + (a[i] ? (a[i] % 2) : 2));
		// 奇数部分に突入
		dp[i + 1][2] = min(dp[i + 1][2], dp[i][1] + !(a[i] % 2));
		// 奇数部分を続ける
		dp[i + 1][2] = min(dp[i + 1][2], dp[i][2] + !(a[i] % 2));
		// 奇数部分から離脱
		dp[i + 1][3] = min(dp[i + 1][3], dp[i][2] + (a[i] ? (a[i] % 2) : 2));
		// 奇数離脱部分を続ける
		dp[i + 1][3] = min(dp[i + 1][3], dp[i][3] + (a[i] ? (a[i] % 2) : 2));
	}
	for(ll i = 0; i <= n; ++i){
		ans = min(ans, dp[i][0] + brui[i]);
		ans = min(ans, dp[i][1] + brui[i]);
		ans = min(ans, dp[i][2] + brui[i]);
		ans = min(ans, dp[i][3] + brui[i]);
	}
	cout << ans << endl;
}

