long func(int tar,int flags){
    long res;
    if(flags == 0 || flags == 4){
        res = tar;
    }
    else if(flags == 1 || flags == 3){
        if(tar == 0)res = 2;
        else if(tar % 2 == 1)res = 1;
        else res = 0;
    }
    else{
        if(tar == 0)res = 1;
        else if(tar % 2 == 1)res = 0;
        else res = 1;
    }

    return res;
}

