typedef long long ll;

const ll oo = 1e18;
const int N = 200005;

int n;
int v[N];

int one[N], zero[N];

int solve(int l, int r){

    for(int i = l; i <= r; i++){
        one[i] = v[i] % 2 == 1;
        zero[i] = v[i] % 2 == 0;
    }

    for(int i = l + 1; i <= r; i++){
        one[i] += one[i - 1];
        zero[i] += zero[i - 1];
    }

    int mx = 0;
    int ans = 0;
    for(int i = l; i <= r; i++){
        ans = max(ans, one[i] + mx + zero[r] - zero[i]);
        mx = max(mx, zero[i] - one[i]);
    }

    ans = max(ans, zero[r]);
    ans = max(ans, one[r]);

    return r - l + 1 - ans;
}

ll a[N], p[N];
int sz;

int main(){

    scanf("%d", &n);

    ll tot = 0;
    for(int i = 0; i < n; i++)
        scanf("%d", v + i), tot += v[i];

    ll ans = oo;
    for(int i = 0, last = -1; i < n; i++) if(v[i]){
        a[sz++] = i - last - 1;
        int j = i;
        ll sum = 0;
        while(j < n && v[j]) sum += v[j], j++;
        a[sz++] = -sum + solve(i, j - 1);
        i = j;
        last = j - 1;
    }

    p[0] = a[0];
    for(int i = 1; i < sz; i++) p[i] = p[i - 1] + a[i];

    ll tmp = oo, mx = 0;
    for(int i = 0; i < sz; i++){
        tmp = min(tmp, p[i] - mx);
        mx = max(mx, p[i]);
    }

    ans = min(ans, tot + tmp);

    if(ans == oo) ans = 0;

    printf("%lld\n", ans);

}

