        dp[3][i+1] = min( dp[3][i+1], dp[1][i] + co );
        dp[3][i+1] = min( dp[3][i+1], dp[2][i] + co );
        dp[3][i+1] = min( dp[3][i+1], dp[3][i] + co );

        co = a[i];
