        dp[4][i+1] = min( dp[4][i+1], dp[2][i] + co );
        dp[4][i+1] = min( dp[4][i+1], dp[3][i] + co );
        dp[4][i+1] = min( dp[4][i+1], dp[4][i] + co );

    }

    ll ans = 1e15;

