			{
				dp[i+1][0] = min(dp[i+1][0], v+a[i]);
			}
			else
			{
				dp[i+1][4] = min(dp[i+1][4], v+a[i]);
			}
			//flipping
			if(j<=2)
			{
				dp[i+1][2] = min(dp[i+1][2], v+(a[i]%2==0));
			}
			//even
			if(j<=1)
