}

lli go(lli a, int f) {
	if(!a && f == 1) return 2;
	return a % 2 == f;
}

lli DP(int id,int f) {
	if(id == n) return 0;
	if(vis[id][f] == cont) return memo[id][f];
	vis[id][f] = cont;
	if(f == 0) return memo[id][f] = min(DP(id + 1, 1), DP(id + 1, 0) + sum(id, id));
	if(f == 1) return memo[id][f] = min(DP(id + 1, 1) + go(sum(id, id), 0), min(DP(id + 1, 2) + go(sum(id, id), 1), sum(id, n - 1)));
	return memo[id][f] = min(DP(id + 1, 2) + go(sum(id, id), 1), sum(id, n - 1));
}

