	vector<ll> a(L);
	for (int i = 0; i < L; ++i)
		cin >> a[i];

	vector<vector<ll>> dp(L + 1);
	for (int i = 0; i <= L; ++i)
		dp[i].resize(5, 0LL);

	for (int i = 1; i <= L; ++i) {
		ll ai = a[i - 1];
		// dp[i][0]の決定
		dp[i][0] = dp[i - 1][0] + ai;
		// dp[i][1]の決定
		ll tmp = ai & 1LL;
		if (ai == 0) tmp += 2LL;
		dp[i][1] = min(dp[i - 1][0], dp[i - 1][1]) + tmp;
		// dp[i][2]の決定
		tmp = (ai + 1) & 1LL;
		dp[i][2] = min({ dp[i - 1][0],dp[i - 1][1],dp[i - 1][2] }) + tmp;
		// dp[i][3]の決定
		tmp = ai & 1LL;
		if (ai == 0) tmp += 2LL;
		dp[i][3] = min({
			dp[i - 1][0],dp[i - 1][1],dp[i - 1][2],dp[i - 1][3]
			}) + tmp;
		// dp[i][4]の決定
		dp[i][4] = min({
			dp[i - 1][0],dp[i - 1][1],dp[i - 1][2],dp[i - 1][3],dp[i - 1][4]
			}) + ai;
	}

	ll ans = min({ dp[L][0],dp[L][1],dp[L][2],dp[L][3],dp[L][4] });
	cout << ans << endl;

	return 0;
}

