	for (int i = 0;i < L;i++) {
		ll nowcost = a[i] % 2;
		if (a[i] == 0)
			nowcost = 2;
		dp[i + 1] = min(imos[i] + nowcost, dp[i] + nowcost);
	}
	vector<ll> ar(L);
	imos.assign(L + 1, 0);
	for (int i = 0;i < L;i++) {
		ar[i] = a[L - 1 - i];
		imos[i + 1] = ar[i] + imos[i];
	}
	vector<ll> dpr(L + 1, INF);
	dpr[0] = 0;
	for (int i = 0;i < L;i++) {
		ll nowcost = ar[i] % 2;
		if (ar[i] == 0)
