		base[i + 1] += base[i];
	}
	vector<ll> bestr(L+1);
	for (int i = 1;i <= L;i++) {
		bestr[L-i] = min(bestr[L-i+1], dpr[i] - (base[L] - base[L - i]));
	}
	ll bestl = 0;
	ll ans = INF;
	for (int i = 0;i <= L;i++) {
		bestl = dp[i] - base[i];
		ll rb = bestr[i];
		ans = min(ans, bestl + rb + base[L]);
	}
