#include <bits/stdc++.h>
using namespace std;

typedef long long ll;
const int N = 2e5 + 100;

ll n, m, a[N], l[N], l_back[N], r[N], r_back[N], help[N], help_back[N];

ll go(ll l) {
	return (l & 1? l: l - 1);
}

ll come(ll l) {
	return (l & 1? l - 1: l);
}

void build(int n) {
	for (int i = n - 2; i >= 0; i--) {
		ll len = a[i];
		help[i] = go(len) + help[i + 1];
		help_back[i] = (len == 1? 0: come(len) + help_back[i + 1]);
		help[i] = max(help[i], help_back[i]);
	}
}

ll solve(int n) {
	cerr << '\n';
	build(n);
	for (int i = 0; i < n; i++)
		r[i] = help[i], r_back[i] = help_back[i];
	for (int i = 0; i <= n; i++)
		help[i] = help_back[i] = 0;
	reverse(a, a + n - 1);
	build(n);
	for (int i = 0; i < n; i++)
		l[i] = help[n - i - 1], l_back[i] = l_back[n - i - 1];
	ll ans = 0;
	for (int i = 0; i < n; i++)
		ans = max(ans, max(l_back[i] + r[i], r_back[i] + l[i]));
	return ans;
}

