            dp[i + 1][1] = min1;
            dp[i + 1][2] = min2 + 1;
            dp[i + 1][3] = min3;
            dp[i + 1][4] = min4 + a;
        }
    }
    cout << dp[k][min_element(dp[k], dp[k] + 5) - dp[k]] << endl;

    return 0;
}

