ll solve(vector<ll> a) {
    ll n = (ll)a.size();
    vector<vector<ll>> dp(n, vector<ll>(5));
    REP(i, n) {
        if(i == 0) {
            dp[i][0] = a[i];
            dp[i][1] = (a[i] == 0 ? 2 : (a[i] % 2));
            dp[i][2] = (a[i] == 0 ? 1 : !(a[i] % 2));
            dp[i][3] = (a[i] == 0 ? 2 : (a[i] % 2));
            dp[i][4] = a[i];
        } else {
            dp[i][0] = min({dp[i - 1][0]}) + a[i];
            dp[i][1] = min({dp[i - 1][0], dp[i - 1][1]}) + (a[i] == 0 ? 2 : (a[i] % 2));
            dp[i][2] = min({dp[i - 1][0], dp[i - 1][1], dp[i - 1][2]}) + (a[i] == 0 ? 1 : !(a[i] % 2));
            dp[i][3] = min({dp[i - 1][0], dp[i - 1][1], dp[i - 1][2], dp[i - 1][3]}) + (a[i] == 0 ? 2 : (a[i] % 2));
            dp[i][4] = min({dp[i - 1][0], dp[i - 1][1], dp[i - 1][2], dp[i - 1][3], dp[i - 1][4]}) + a[i];
        }
    }
    return min({dp[n - 1][0], dp[n - 1][1], dp[n - 1][2], dp[n - 1][3], dp[n - 1][4]});
}

