void work()
{
	for (int i=1;i<=n;i++)
	{
		int x=a[i];
		if (!x) s[i][2]=2,s[i][1]=1,s[i][0]=0;
		else if (x&1) s[i][2]=1,s[i][1]=0,s[i][0]=x;
		else s[i][2]=0,s[i][1]=1,s[i][0]=x;
	}
	for (int i=1;i<=n+1;i++)
	{
		LL mn=dp[i-1][0];
		dp[i][0]=dp[i-1][0]+s[i][0];
		mn=std::min(mn,dp[i-1][1]);
		dp[i][1]=mn+s[i][2];
