		dp[i][2]=mn+s[i][1];
		mn=std::min(mn,dp[i-1][3]);
		dp[i][3]=mn+s[i][2];
		mn=std::min(mn,dp[i-1][4]);
		dp[i][4]=mn+s[i][0];
	}
}

