int L;
ll costl, costr;

int search_zero_from(int from) {
    repd(i, from, L) {
        if (A[i] == 0) return i;
    }
    return -1;
}

int search_zero_fromr(int from) {
    for (auto i = from; i >= 0; --i) {
        if (A[i] == 0) return i;
    }
    return -1;
}

int search_even_from(int from) {
    repd(i, from, L) {
        if (A[i] % 2 == 0) return i;
    }
}

int search_even_fromr(int from) {
    for (auto i = from; i >= 0; --i) {
        if (A[i] % 2 == 0) return i;
    }
}

int possible_start_left() {
    ll sum_before = 0;
    int lasti = 0;
    int cost = 0;
    while (true) {
        int zero = search_zero_from(lasti);
        if (zero == -1) return lasti;

        cost += 1;
        repd(i, lasti, zero-1) {
            sum_before += A[i];
        }
        if (sum_before > cost) return lasti;

        lasti = zero + 1;
    }
}

int possible_start_right() {
    ll sum_before = 0;
    int lasti = L-1;
    int cost = 0;
    while (true) {
        int zero = search_zero_fromr(lasti);
        if (zero == -1) return lasti;

        cost += 1;
        for (auto i = lasti; i >= zero; --i) {
            sum_before += A[i];
        }
        if (sum_before > cost) return lasti;

        lasti = zero - 1;
    }
}

int main(int argc, const char * argv[]) {
