        //if (A[i] == 0) r[i] = -1;
    }

    int startl = possible_start_left();
    int startr = possible_start_right();

    repd(i, startl, startr) {
        costl += r[i];
    }

    repd(i, startl + 1, startr + 1) {
        costr += r[i];
    }

    ll add = 0;
    repd(i, 0, startl-1) {
        add += A[i];
    }
    repd(i, startr+1, L) {
        add += A[i];
    }

    ll cost2r = 0;
    ll cost2l = 0;
    int first_even = search_even_from(startl);
    int last_even = search_even_fromr(startr);
    repd(i, first_even, startr + 1) {
        cost2l += (r[i] + 1) % 2;
    }

    repd(i, startl, last_even + 1) {
        cost2r += (r[i] + 1) % 2;
    }

    //printf("%d,%d,%d,%d,%d,%d,%d\n", startl, startr, costl, costr, cost2r, cost2l,add);

    costr += add;
    costl += add;
    cost2r += add;
    cost2l += add;
    ll cost = min(costr, costl);
    cost = min(cost, cost2l);
    cost = min(cost, cost2r);


    output(cost);

    return 0;
}

