	for (int i = 0; i <= l; i++) {
		update(i, ruiseki[i] + ruiseki2[i + 1]);
	}
	long long tmp = query(0, l + 1, 0, 0, n2);
	long long now = 0;
	for (int i = 1; i < l; i++) {
		long long ha = (a[i] == 0) ? -2 : a[i] - (a[i] % 2);
		now = max((long long)0, ha + now);
		tmp = max(tmp, now + query(i + 1, l + 1, 0, 0, n2) - ruiseki[i]);
	}
	cout << ans - tmp;
}

