const long long INF = 1LL<<60;

int L;
vector<long long> A;

long long dp[510000][5][5];

int main() {
    while (cin >> L) {
        A.resize(L);
        for (int i = 0; i < L; ++i) cin >> A[i];
        while (!A.empty() && A.back() == 0) A.pop_back();

        if (A.back() != 0) A.push_back(0);
        L = A.size();

        for (int i = 0; i < 510000; ++i)
            for (int j = 0; j < 5; ++j)
                for (int k = 0; k < 5; ++k)
                    dp[i][j][k] = INF;
        dp[0][0][0] = 0;

        for (int i = 0; i <= L; ++i) {
            for (int j = 0; j <= 2; ++j) {
                for (int k = 0; k < 3; ++k) {
                    if (dp[i][k][j] < INF) {
                        //cout << i << ", " << k << ", " << j << ": " << dp[i][k][j] << endl;
                    }
                }

                if (i == L) continue;

                if (A[i] != 0 || i == L - 1) {
                    chmin(dp[i+1][2][j], dp[i][0][j] + A[i]);
                    chmin(dp[i+1][2][j], dp[i][1][j] + A[i]);
                    chmin(dp[i+1][2][j], dp[i][2][j] + A[i]);

                    if (A[i] % 2 == 0) {
                        chmin(dp[i+1][0][j], dp[i][0][j]);
                        chmin(dp[i+1][1][j], dp[i][1][j] + 1);
                        chmin(dp[i+1][0][j+1], dp[i][1][j]);

                        chmin(dp[i+1][0][j], dp[i][2][j]);
                    }
                    else {
                        chmin(dp[i+1][1][j], dp[i][1][j]);
                        chmin(dp[i+1][0][j], dp[i][0][j] + 1);
                        chmin(dp[i+1][1][j+1], dp[i][0][j]);

                        chmin(dp[i+1][0][j], dp[i][2][j] + 1);
                        chmin(dp[i+1][1][j+1], dp[i][2][j]);
                    }
                }
                else {
                    chmin(dp[i+1][2][j], dp[i][2][j]);
                    chmin(dp[i+1][1][j+1], dp[i][0][j] + 1);
                    chmin(dp[i+1][0][j], dp[i][j][j] + 2);
                    chmin(dp[i+1][1][j], dp[i][1][j] + 1);
                }
            }
        }

        long long res = INF;
        for (int j = 0; j < 3; ++j) {
            for (int k = 0; k < 3; ++k) {
                chmin(res, dp[L][j][k]);
            }
        }
        cout << res << endl;
    }
}

