        if(a[i]==0)
        {
            if(a[i-1]!=0)
            {
                lmax[pos]=l;
                rmax[pos]=i;
                ++pos;
            }
            l=i;
        }
    }
    for(int i2=0; i2<pos; ++i2)
    {
        for(int i=lmax[i2]+1; i<rmax[i2]; ++i)
        {
            if(a[i]%2==0)
            {
                ncnt[i2]+=2;
                a[i]=2;
            }
            else
            {
                ncnt[i2]+=1;
                a[i]=1;
            }
        }
    }
    for(int i2=1; i2<pos; ++i2)
    {
        ltst4[i2]=ltst4[i2-1]+tmp[i2-1];
        if(ltst4[i2]>1e6)
            ltst4[i2]=1e6;
        tmp2=(rmax[i2]-rmax[i2-1])*2-ncnt[i2];
        tst2+=tmp[i2]-tmp2;
        if(tst2>0)
        {
            ltst3[i2]=ltst3[i2-1]+tmp2;
        }
        else
        {
            ltst3[i2]=ltst4[i2];
            tst2=0;
        }
    }
    res=1e6;
    while(rtst2<pos)
    {
        tst=tst2=rtst3=rtst4=0;
        for(int i2=rtst1+1; i2<pos; ++i2)
        {
            rtst4+=tmp[i2];
            tmp2=(rmax[i2]-rmax[i2-1])*2-ncnt[i2];
            tst+=tmp2;
            tst2+=tmp[i2]-tmp2;
            if(tst2>0)
            {
                rtst3+=tst;
                tst=0;
                tst2=0;
                rtst2=i2;
            }
        }
        for(int i2=rtst2+1; i2<pos; ++i2)
            rtst3+=tmp[i2];
        cnt=0;
        ltst=ltst3[rtst1];
        for(int i2=rtst1; i2<=rtst2; ++i2)
        {
            if(i2!=rtst1)
            {
                rtst3-=(rmax[i2]-rmax[i2-1])*2-ncnt[i2];
                rtst4-=tmp[i2];
            }
            a[lmax[i2]]=a[rmax[i2]]=1;
            int i=lmax[i2]+1;
            l=lmax[i2]+1;
            r=lmax[i2];
            if(i2!=0)
                cnt+=lmax[i2]-rmax[i2-1]+1;
            icnt=scnt=cnt2=0;
            for(; i<rmax[i2]; ++i)
            {
                if(a[i]==1)
                {
                    ++scnt;
                    ++icnt;
                }
                else
                {
                    ++cnt;
                    icnt+=2;
                    if(a[i-1]==1)
                    {
                        if(cnt2<0)
                            cnt2-=r-l+1;
                        else
                            cnt2=-(r-l+1);
                        cnt2+=i-r-1;
                        l=i;
                    }
                    if(a[i+1]==1)
                    {
                        r=i;
                        cmax=ltst+cnt-(r-l+1)+min((rmax[i2]-r-1)*2-(ncnt[i2]-icnt)+rtst3,ncnt[i2]-icnt+rtst4);
                        if(cnt2<0)
                            cmax+=cnt2;
                        if(cmax<res)
                            res=cmax;
                        tmp2=min(ltst3[i2]+scnt,ltst4[i2]+icnt-(r-l+1)*2+cnt2);
                        if(tmp2<ltst+cnt)
                        {
                            ltst=tmp2;
                            cnt=0;
                            scnt=0;
                        }
                    }
                }
            }
        }
        cmax=ltst+cnt+rtst3;
        if(cmax<res)
            res=cmax;
        rtst1=rtst2+1;
        rtst2=rtst1;
    }
    cout<<res;

    return 0;
}

