using namespace std;
using ll=long long int;

ll sum(vector<ll> &bit, ll i) {
    ll s = 0;
    while (i > 0) {
        s += bit[i];
        i -= i & -i;
    }
    return s;
}

void add(vector<ll> &bit, ll i, ll x) {
    while (i <= bit.size()) {
        bit[i] += x;
        i += i & -i;
    }
}

int main() {
    int L;
    cin >> L;
    vector<ll> oddn(L*2, 0);
    vector<ll> an(L*2, 0);
    vector<int> zeroes; zeroes.reserve(L);
    vector<pair<int, int>> codd; codd.reserve(L);

    bool prevodd = false;
    int first = 0;
    for (int i = 1; i <= L; ++i) {
        int a;
        cin >> a;
        if (a == 0) zeroes.emplace_back(i);
        if (a % 2 == 1) {
            add(oddn, i, 1);
            if (!prevodd) first = i;
            prevodd = true;
        } else {
            if (prevodd) codd.emplace_back(first, i-1);
            prevodd = false;
        }
        add(an, i, a);
    }
    if (prevodd) codd.emplace_back(first, L);

    ll ans = sum(oddn, L);
    for (auto &&p: codd) {
        ll op = 0;
        auto zi_p = lower_bound(zeroes.begin(), zeroes.end(), p.first);
        if (zi_p != zeroes.begin()) {
            zi_p--;
            op += sum(an, *zi_p);
            op += sum(oddn, p.first-1) - sum(oddn, *zi_p);
        } else {
            op += sum(oddn, p.first-1);
        }
        auto zi_n = upper_bound(zeroes.begin(), zeroes.end(), p.second);
        if (zi_n != zeroes.end()) {
            op += sum(an, L) - sum(an, *zi_n);;
            op += sum(oddn, *zi_n) - sum(oddn, p.second);
        } else {
            op += sum(oddn, L) - sum(oddn, p.second);
        }

        ans = min(ans, op);
    }

    cout << ans << endl;

    return 0;
}

