    vector<array<ll, 4>> dp(L, {0, 0, 0, 0});
    {
        auto f = A[0];
        bool odd = f % 2;
        bool nonzero = f > 0;
        auto& fdp = dp[0];
        fdp[0] = odd ? 1 : (nonzero ? 0 : 2);
        fdp[1] = odd ? 0 : 1;
        fdp[2] = odd ? 1 : (nonzero ? 0 : 2);
        fdp[3] = f;
