        bool odd = A[i] % 2 == 1;
        bool nonzero = A[i] > 0;
        dp[i][0] = min(sum, dp[i-1][0]) + (odd ? 1 : (nonzero ? 0 : 2));
        dp[i][1] = min(dp[i-1][0], dp[i-1][1]) + (odd ? 0 : 1);
        dp[i][2] = min(dp[i-1][1], dp[i-1][2]) + (odd ? 1 : (nonzero ? 0 : 2));
