using namespace std;

const int N = 200005;
const int inf = 1000 * 1000 * 1000;
const int mod = 1000 * 1000 * 1000 + 7;

int n;
int a[N];

long long pref[N] , suf[N];
int cnteven[N] , cntodd[N];

int calceven(int x){
    if(x == 0)return 2;
    return x % 2;
}

int calcodd(int x){
    return 1 - (x % 2);
}

int main() {
    //mt19937 myrand(chrono::steady_clock::now().time_since_epoch().count());
    scanf("%d",&n);
    for(int i=1;i<=n;i++){
        scanf("%d",&a[i]);
        cnteven[i] = cnteven[i - 1] + calceven(a[i]);
        cntodd[i] = cntodd[i - 1] + calcodd(a[i]);
    }
    pref[0] = 0;
    for(int i=1;i<=n;i++){
        pref[i] = pref[i - 1] + a[i];
    }
    suf[n + 1] = 0;
    for(int i=n+1;i>=0;i--){
        suf[i] = suf[i + 1] + a[i];
    }
    long long answ = inf * 1ll * inf;
    for(int i=0;i<=n;i++){
        for(int j=i;j<=n;j++){
            for(int h=j;h<=n;h++){
                for(int t=h;t<=n;t++){
                    /// 0 -> i
                    /// i + 1 -> j
                    /// j + 1 -> h
                    /// h + 1 -> t
                    /// t + 1 -> n
                    long long s = pref[i];
                    s += cnteven[j] - cnteven[i];
                    s += cntodd[h] - cntodd[j];
                    s += cnteven[t] - cnteven[h];
                    s += suf[t + 1];
                    answ = min(answ , s);
                }
            }
        }
    }
    cout<<answ<<endl;
	return 0;
}
