                cost[i][j] = a[i];
            } else if(j == 1 || j == 3) {
                if(a[i] == 0) cost[i][j] = 2;
                else if(a[i] % 2 == 1) cost[i][j] = 1;
                else cost[i][j] = 0;
            } else {
                if(a[i] % 2 == 1) cost[i][j] = 0;
                else cost[i][j] = 1;
            }
        }
    }
    rep(i, l + 1) {
        rep(j, 5) {
            dp[i][j] = INF;
        }
    }
