            chmin(dp[i + 1][j], dp[i][j] + cost[i][j]);
            chmin(dp[i + 1][j + 1], dp[i][j] + cost[i][j + 1]);
        }
    }
    cout << min({dp[l][0], dp[l][1], dp[l][2], dp[l][3], dp[l][4]}) << endl;
}

