void calc(const vector<ll> &A, vector<vector<ll>> &dp) {
	int L = sz(A);
	dp = vector<vector<ll>>(2, vector<ll>(L + 1));

	fora(i, L) {
		ll v = A[i];
		ll sub = 0;
		if (v == 0) sub = 1;
		if (v % 2 == 0) {
			dp[0][i + 1] = max(0ll, dp[0][i] + A[i] - 1);
			dp[1][i + 1] = max({0ll, dp[1][i] + A[i] - 2 * sub, dp[0][i] + A[i] - 1});
		} else {
			dp[0][i + 1] = max(0ll, dp[0][i] + A[i]);
			dp[1][i + 1] = max({0ll, dp[0][i] + A[i], dp[1][i] + A[i] - 1});
		}
	}
}

