int main(){
    scanf("%d", &L);
    sum[0] = sum1[0] = sum2[L + 1] = sum3[0] = 0;
    for(int i = 1; i <= L; ++i){
        scanf("%d", &a[i]);
        sum[i] = sum[i - 1] + a[i];
        if(a[i] == 0){
            sum1[i] = sum1[i - 1] + 2;
            sum3[i] = sum3[i - 1] + 1;
        }else{
            sum1[i] = sum1[i - 1] + (a[i] & 1);
            sum3[i] = sum3[i - 1] + ((a[i] - 1) & 1);
        }
    }
    for(int i = L; i >= 1; --i){
        if(a[i] == 0){
            sum2[i] = sum2[i + 1] + 2;
        }else{
            sum2[i] = sum2[i + 1] + (a[i] & 1);
        }
    }
    ll mini = 0;
    for(int i = 1; i <= L; ++i)
        mini = min(mini, sum[i] - sum1[i]), f1[i] = sum1[i] + mini;
    mini = 0;
    for(int i = L; i >= 1; --i)
        mini = min(mini, sum1[i] - sum[i]), f2[i] = sum[L] - sum1[i] + mini;
    ans = sum[L];
    mini = 0;
    for(int i = 1; i <= L; ++i){
        ans = min(ans, f2[i] + sum3[i] + mini), mini = min(mini, f1[i] - sum3[i]);
    }
    printf("%lld\n", ans);
