        dp[0][i] = 0;
    }

    for (int i = 0; i < L; i++) {
        int m = a[i] % 2;

        dp[i + 1][0] = dp[i][0] + a[i];

        for (int j = 0; j < 5; j++) {
            if (j <= 1) {
                if (a[i] != 0) {
                    dp[i + 1][1] = min(dp[i + 1][1], dp[i][j] + m);
                } else {
                    dp[i + 1][1] = min(dp[i + 1][1], dp[i][j] + 2);
                }
            }

            if (j <= 2) {
                if (a[i] != 0) {
                    dp[i + 1][2] = min(dp[i + 1][2], dp[i][j] + !m);
                } else {
                    dp[i + 1][2] = min(dp[i + 1][2], dp[i][j] + 1);
