            }

            if (j <= 3) {
                if (a[i] != 0) {
                    dp[i + 1][3] = min(dp[i + 1][3], dp[i][j] + m);
                } else {
                    dp[i + 1][3] = min(dp[i + 1][3], dp[i][j] + 2);
