        if (a[i] % 2 == 1 || a[i] == 0) scl[i]--;
        else scl[i]++;
        dl[i] = min(dl[i - 1] + (a[i] % 2 == 0), sl[i]);
        if (sl[i] == dl[i] && scl[i] - scl[l-1] < 0) l = i + 1;
    }

    //calc dr
    for (int i = r; i >= l; i--) {
        scr[i] = scr[i + 1];
        if (a[i] % 2 == 1 || a[i] == 0) scr[i]--;
        else scr[i]++;
        sr[i] = sr[i + 1] + a[i];
        dr[i] = min(dr[i + 1] + (a[i] % 2 == 0), sr[i]);
