	long long int res;

	std::cin >> L;

	for(int i=0;i<L;i++){
		int A_;
		std::cin >> A_;
		A.emplace_back(A_);
		odd_sum+=(A_%2);
	}
	even_sum=L-odd_sum;

	left=0;
	right=even_sum;
	if(A.front()%2==0) right--;
	res=right;
	for(int i=0;i<L-1;i++){
		left+=A[i];
		if(A[i]%2==0 && i!=0) right--;
		long long int sub=0;
		for(int j=i+1;j<L;j++){
			if(A[j]==0 || A[j]%2==1) break;
			sub++;
		}
		if(res>left+right-sub) res=left+right-sub;
	}


	left=even_sum;
	right=0;
	if(A.back()%2==0) left--;
	for(int i=L-1;i>0;i--){
		right+=A[i];
		if(A[i]%2==0 && i!=L-1) left--;
		long long int sub=0;
		for(int j=i-1;j>=0;j--){
			if(A[j]==0 || A[j]%2==1) break;
			sub++;
		}
		if(res>left+right-sub) res=left+right-sub;
	}

	std::cout << res << std::endl;
	return 0;
}

