int64 L[N], R[N];

void solve(int64 a[], int n, int64 A[]) {
  for (int i = 0; i < n; ++i) {
    sum[i + 1] = sum[i] + a[i];
  }
  for (int i = 0; i < n; ++i) {
    C[i] = sum[n] - sum[i];
  }
  B[n] = 0;
  for (int i = n - 1; i >= 0; --i) {
    int x = 0;
    if (a[i] == 0) {
      x = 2;
    } else {
      x = a[i] % 2;
    }
    B[i] = min(C[i], B[i + 1] + x);
  }
  A[n] = 0;
  for (int i = n - 1; i >= 0; --i) {
    int x = 1 - a[i] % 2;
    A[i] = min(B[i], A[i + 1] + x);
  }
}

