int main(){
    ll l;
    cin >> l;
    vector<ll> a(2*l, 0);
    rep(i, l) cin >> a[i];

    ll isZ = 0;
    ll lcost = 0;
    ll rcost = 0;
    ll p = -1;
    rep(i, l){
        if(a[i] == 0) isZ++;
        else          isZ--;
        if(0 <= isZ) p = i;        
    }
    if(0 <= p){
        rep(j, p+1) lcost += a[j];
        rep(j, p-1) a[j] = a[j+p+1];
        l -= p+1;
    }

    isZ = 0;
    p = -1;
    for(ll i = l-1; 0 <= i; i--){
        if(a[i] == 0) isZ++;
        else          isZ--;
        if(0 <= isZ) p = i;        
    }
    if(0 <= p){
        rep(j, l-p) rcost += a[p+j];
        l -= l-p;
    }

    if(a.size() <= 1){
        cout << lcost+rcost << endl;
        return 0;
    }

    ll minn = 0;
    rep(i, l) minn += a[i];

    vector<ll> isOdds(l+1, 0);
    rep(i, l) isOdds[i+1] += (a[i]%2==1? 1:0) + isOdds[i];

    vector<ll> isZeros(l, 0);
    rep(i, l) isOdds[i+1] += (a[i]==0? 1:0) + isZeros[i];

    minn = min(minn, isOdds[l]);
    minn = min(minn, l-isOdds[l]);

    ll left = 0;
    ll right = l;
    for(ll lmid = left; lmid < right; lmid++){
        ll cosL = isOdds[lmid]-isOdds[left];
        ll isZL = isZeros[lmid]-isZeros[left];
        if(minn <= lcost+rcost + cosL + 2*isZL) break;

        for(ll rmid = lmid+1; rmid <= right; rmid++){
            ll cnt = 0;

            cnt += cosL;

            cnt += (rmid-lmid - (isOdds[rmid]-isOdds[lmid]));

            cnt += isOdds[right]-isOdds[rmid];
            ll isZR = isZeros[right]-isZeros[rmid];
            minn = min(minn, lcost+rcost + cnt + 2*isZL + 2*isZR);
        }
    }

    cout << minn << endl;

    return 0;
}

