void solve() {
    //const i64 mod = 1'000'000'007;
    i64 L;
    cin >> L;

    vector<i64> A(L);
    rep(i,0,L){
        cin >> A[i];
    }

    vector<i64> even(L),odd(L);
    even[0]=(A[0]+1)%2;
    odd[0]=A[0]%2;
    rep(i,1,L){
        even[i]=even[i-1];
        even[i]+=(A[i]+1)%2;

        odd[i]=odd[i-1];
        odd[i]+=A[i]%2;
    }

    vector<i64> s(L);
    s[0]=A[0];
    rep(i,1,L){
        s[i]=s[i-1]+A[i];
    }

    auto sum=[&](i64 l,i64 r){
        if(r<l) return i64(0);
        i64 res=s[r];
        if(l-1>=0) res-=s[l-1];
        return res;
    };

    vector<i64> z(L);
    z[0]=A[0]==0;
    rep(i,1,L){
        z[i]=z[i-1]+(A[i]==0);
    }

    auto zero=[&](i64 l,i64 r){
        if(r<l) return i64(0);
        i64 res=z[r];
        if(l-1>=0) res-=z[l-1];
        return res;
    };

    auto even_sum=[&](i64 l,i64 r){
        if(r<l) return i64(0);
        i64 res=even[r];
        if(l-1>=0) res-=even[l-1];
        return res;
    };

    auto odd_sum=[&](i64 l,i64 r){
        if(r<l) return i64(0);
        i64 res=odd[r];
        if(l-1>=0) res-=odd[l-1];
        return res;
    };

    const i64 maxL=200000;
    static i64 memo[maxL][5];
    static bool done[maxL][5];
    fill_n((i64*)memo,maxL*5,inf64);
    fill_n((bool*)done,maxL*5,false);
    // 0 even odd even 0
    // 0 1    2   3    4
    function<i64(i64,i64)> rec=[&](i64 i,i64 s){
        if(i==L) return i64(0);

        auto& res=memo[i][s];
        if(done[i][s]){
            return res;
        }
        done[i][s]=true;

        switch(s){
            case 0: {
                {
                    // 0 -> 0
                    chmin(res, rec(i + 1, 0) + A[i]);
                }
                {
                    // 0 -> even
                    chmin(res, rec(i + 1, 1) + (A[i]==0?2:A[i] % 2));
                }
                {
                    // 0 -> odd
                    chmin(res, rec(i + 1, 2) + (A[i] + 1) % 2);
                }
            }
            break;

            case 1: {
                {
                    // even -> even
                    chmin(res, rec(i + 1, 1) + (A[i]==0?2:A[i] % 2));
                }
                {
                    // even -> odd
                    chmin(res,rec(i+1,2)+(A[i]+1)%2);
                }
                {
                    // even -> 0
                    chmin(res,rec(i+1,4)+A[i]);
                }
            }
            break;

            case 2: {
                {
                    // odd -> odd
                    chmin(res,rec(i+1,2)+(A[i]+1)%2);
                }
                {
                    // odd -> even
                    chmin(res,rec(i+1,3)+(A[i]==0?2:A[i] % 2));
                }
                {
                    // odd -> 0
                    chmin(res,rec(i+1,4)+A[i]);
                }
            }
            break;

            case 3: {
                {
                    // even -> even
                    chmin(res,rec(i+1,3)+(A[i]==0?2:A[i] % 2));
                }
                {
                    // even -> 0
                    chmin(res,rec(i+1,4)+A[i]);
                }
            }
            break;

            case 4: {
                {
                    // 0 -> 0
                    chmin(res, rec(i+1,4)+A[i]);
                }
            }
            break;

            default:
                assert(false);
        }

        return res;
    };

    cout << rec(0,0) << endl;
}

