void solve()
{
	pre1[0]=pre2[0]=0;
	for(int i=1;i<=n;i++)
	{	
		if(a[i]%2==0 and a[i]>=0) pre1[i]=pre1[i-1]+1;
		else pre1[i]=pre1[i-1]-1;

		pre2[i]=pre2[i-1]+a[i];
		if(a[i]%2==0) pre2[i]--;
	}
	smin=pre2[n];
	for(ll i=n;i>=0;i--)
	{
		ans=max(ans,smin-pre2[i]);
		smin=max(smin,pre2[i]);
	}
	pre2[n+1]=-1e17;
	for(int i=n;i>=1;i--) d[i]=pre1[i-1]+pre2[i-1],pre2[i]=max(pre2[i],pre2[i+1]);
	for(int i=1;i<=n;i++)
		s[i]=pre1[i]+pre2[i];
	smax=s[n];d[0]=0;
	for(ll i=n;i>=1;i--)
	{
		smax=max(smax,s[i]);
		ans=max(smax-d[i],ans);
	}
