int memo[N][5];
int go(int from, int stage) {
    if (stage >= 5) return INF;
    if (from >= n) return 0;

    int &res = memo[from][stage];
    if (res != -1) return res;

    res = go(from,stage+1);
    res = min(res, go(from+1, stage) + cost(a[from], stage));
    return res;
}

