void update(ll &a, ll b) {
    if (a > b) {
        a = b;
    }
}

int main() {
    scanf("%d", &n);
    for (int i = 1; i <= n; ++i) {
        scanf("%d", a + i);
    }
    memset(dp, 0x3f, sizeof(dp));
    ll inf = dp[0][0];
    dp[0][0] = 0;
    for (int i = 1; i <= n; ++i) {
        ll tmp = dp[i - 1][0];
        update(dp[i][0], tmp + a[i]);

        tmp = std::min(tmp, dp[i - 1][1]);
        update(dp[i][1], tmp + (a[i] ? (a[i] & 1) : 2));

        tmp = std::min(tmp, dp[i - 1][2]);
        update(dp[i][2], tmp + !(a[i] & 1));

        tmp = std::min(tmp, dp[i - 1][3]);
        update(dp[i][3], tmp + (a[i] ? (a[i] & 1) : 2));

        tmp = std::min(tmp, dp[i - 1][4]);
        update(dp[i][4], tmp + a[i]);
    }

    ll ans = LLONG_MAX;
    for (int j = 0; j < 5; ++j) {
        if (dp[n][j] != inf) {
            update(ans, dp[n][j]);
        }
    }
    printf("%lld\n", ans);
    return 0;
}

