		f[i]+=d[i];
		g[n-i-1]-=d[n-i-1];
		g[n-i-1]=min(g[n-i-1],g[n-i]);
	}
	ll ans=f[0]+g[0];
	for(int i=1;i<=n;i++){
		ans=min(ans,f[i]+g[i]);
	}
	cout<<ans<<endl;
	return 0;
}

