const llong inf = 1e18;
int n;
int A[200001];
llong sum[200001];
int E[200001];
int O[200001];
int L[200001];
int R[200001];
llong solve(int s, int e) {
    if (s > e) return inf;
    int m = (s + e) / 2;
    llong Lv = inf;
    for (int i = s; i <= m; ++i) {
        int j = L[i - 1];
        Lv = min(Lv, sum[j] + E[i - 1] - E[j] + O[m - 1] - O[i - 1]);
    }
    llong Rv = inf;
    for (int i = m; i <= e; ++i) {
        int j = R[i];
        Rv = min(Rv, sum[n] - sum[j] + E[j] - E[i] + O[i] - O[m]);
    }
    llong ret = Lv + Rv;
    if ((A[m] & 1) == 0) ++ret;
    ret = min({ ret, solve(s, m - 1), solve(m + 1, e) });
    return ret;
}

pll seg[1 << 20];
void update(int i, int s, int e, int x, llong v) {
    if (s == e) {
        seg[i] = pll(v, x);
        return;
    }
    int m = (s + e) / 2;
    if (x <= m) update(i << 1, s, m, x, v);
    else update(i << 1 | 1, m + 1, e, x, v);
    seg[i] = min(seg[i << 1], seg[i << 1 | 1]);
}

pll query(int i, int s, int e, int x, int y) {
    if (e < x || y < s) return pll(inf, -1);
    if (x <= s && e <= y) return seg[i];
    int m = (s + e) / 2;
    return min(query(i << 1, s, m, x, y), query(i << 1 | 1, m + 1, e, x, y));
}

int main() {
    ios_base::sync_with_stdio(0); cin.tie(0);
    cin >> n;
    for (int i = 1; i <= n; ++i) {
        cin >> A[i];
        sum[i] = sum[i - 1] + A[i];
    }
    int e = 0, o = 0;
    for (int i = 0; i <= n; ++i) {
        if (i) {
            if (A[i] & 1) ++e;
            else ++o;
            if (A[i] == 0) e += 2;
        }
        E[i] = e;
        O[i] = o;
        update(1, 0, n, i, sum[n] - sum[i] + e);
    }
    for (int i = 0; i <= n; ++i) R[i] = query(1, 0, n, i, n).se;
    e = 0;
    for (int i = n; 0 <= i; --i) {
        update(1, 0, n, i, sum[i] + e);
        if (i) {
            if (A[i] & 1) ++e;
            if (A[i] == 0) e += 2;
        }
    }
    for (int i = 0; i <= n; ++i) L[i] = query(1, 0, n, 0, i).se;
    llong ret = sum[n];
    for (int i = 1; i <= n; ++i) {
        int Li = L[i], Ri = R[i];
        ret = min(ret, sum[n] - sum[Ri] + E[Ri] - E[Li] + sum[Li]);
    }
    ret = min(ret, solve(1, n));
    printf("%lld\n", ret);
    return 0;
}

