            chmin(dp[i + 1][1], dp[i][0] + d[i] % 2);
            chmin(dp[i + 1][1], dp[i][1] + d[i] % 2);
            chmin(dp[i + 1][3], dp[i][2] + d[i] % 2);
            chmin(dp[i + 1][3], dp[i][3] + d[i] % 2);
        }
        if (d[i] >= 1) {
            chmin(dp[i + 1][2], dp[i][0] + 1 - d[i] % 2);
            chmin(dp[i + 1][2], dp[i][1] + 1 - d[i] % 2);
            chmin(dp[i + 1][2], dp[i][2] + 1 - d[i] % 2);
        }
        chmin(dp[i + 1][4], dp[i][0] + d[i]);
        chmin(dp[i + 1][4], dp[i][1] + d[i]);
        chmin(dp[i + 1][4], dp[i][2] + d[i]);
        chmin(dp[i + 1][4], dp[i][3] + d[i]);
        chmin(dp[i + 1][4], dp[i][4] + d[i]);
    }
    return dp;
}

