#include <bits/stdc++.h>
using i64 = long long;

i64 solve(const std::vector<i64> &a) {
    int n = a.size();
    std::vector<i64> b(n + 1), s(n + 1), z(n + 1);
    for (int i = 1; i <= n; i++) {
        b[i] = b[i - 1] + a[i - 1] % 2;
        s[i] = s[i - 1] + a[i - 1];
        z[i] = z[i - 1] + (a[i - 1] == 0);
    }

    std::vector<i64> l(n + 1), r(n + 1);
    for (int i = 1; i <= n; i++) {
        l[i] = s[i] + b[i] - i;
        r[i] = s[i] - b[i] - 2 * z[i];
    }

    for (int i = 1; i <= n; i++) l[i] = std::min(l[i], l[i - 1]);
    for (int i = n - 1; i >= 0; i--) r[i] = std::max(r[i], r[i + 1]);

    i64 ret = std::numeric_limits<i64>::max();
    for (int i = 1; i <= n; i++) {
        i64 tmp = s[n] + i - 2 * b[i] - 2 * z[i] + l[i] - r[i];
        ret = std::min(ret, tmp);
    }

    return ret;
}

int main() {
    int n;
    std::cin >> n;
    std::vector<i64> a(n);
    for (int i = 0; i < n; i++) {
        std::cin >> a[i];
    }

    i64 ret = solve(a);
    std::reverse(a.begin(), a.end());
    ret = std::min(ret, solve(a));

    std::cout << ret << std::endl;

    return 0;
}

