const int N = 2e5 + 10;
const ll inf = (ll)1e18 + 10;

int l;
int a[N];
ll lef[N], lef2[N], rig[N], cost[N];
ll d[N];

ll get(int a) {
    if (a == 0) return 1;
    if (a % 2 == 0) return 1;
    return 0;
}

ll getsum(int l, int r) {
    if (l > r) return 0;
    return d[r] - d[l - 1];
}

int get2(int a) {
    if (a == 0) return 2;
    if (a % 2 == 0) return 0;
    return 1;
}

void run() {
    scanf("%d", &l);
    for (int i = 1; i <= l; ++i) {
        scanf("%d", a + i);
    }
    for (int i = 1; i <= l; ++i) {
        d[i] = d[i - 1] + a[i];
    }
    for (int i = 1; i <= l; ++i) {
        lef2[i] = min(lef2[i - 1] + get2(a[i]), getsum(1, i));
    }
    for (int i = 1; i <= l; ++i) {
        lef[i] = lef[i - 1] + get(a[i]);
    }
    for (int i = l - 1; i >= 0; --i) {
        rig[i] = min(rig[i + 1] + get2(a[i + 1]), getsum(i + 1, l));
    }

    for (int i = 0; i <= l; ++i) {
        cost[i] = lef[i] + rig[i];
    }

    debug(vector <ll> (rig + 1, rig + 8));
    debug(vector <ll> (cost + 1, cost + 8));

    set < pair <ll, int> > st;
    for (int i = 0; i <= l; ++i) {
        st.insert(make_pair(cost[i], i));
    }

    ll ans = inf;
    ll bs = 0;
    mini(ans, bs + st.begin()->X);

    for (int i = 1; i <= l; ++i) {
        st.erase(make_pair(cost[i - 1], i - 1));
        bs += lef2[i] - (lef2[i - 1] + get(a[i]));
        mini(ans, bs + st.begin()->X);
    }

    printf("%lld\n", ans);
}

int main() {
    run();
    return 0;
}

