int ans[MAX_N];
long long nech[MAX_N], chet[MAX_N];

long long calc(int l, int r) {
	long long bad = 0;
	long long sum = 0;
	for (int i = l; i <= r; i++) sum += ans[i];
	for (int i = l; i <= r; i++) ans[i] %= 2;
	nech[l] = ans[l];
	for (int i = l + 1; i <= r; i++) nech[i] = nech[i - 1] + ans[i];
	chet[r] = ans[r] == 0;
	for (int i = r - 1; i >= l; i--) chet[i] = chet[i + 1] + (ans[i] == 0);
	int len = r - l + 1;
	long long mx = len-chet[l];
	mx = min(mx, len-nech[r]);
	for (int i = l + 1; i <= r; i++)
		mx = min(mx, len-(nech[i - 1] + chet[i]));
	for (int i = l; i <= r; i++) ans[i] = 1-ans[i];
	nech[l] = ans[l];
	for (int i = l + 1; i <= r; i++) nech[i] = nech[i - 1] + ans[i];
	chet[r] = ans[r] == 0;
	for (int i = r - 1; i >= l; i--) chet[i] = chet[i + 1] + (ans[i] == 0);
	mx = min(mx, len - chet[l]);
	mx = min(mx, len - nech[r]);
	for (int i = l + 1; i <= r; i++)
		mx = min(mx, len - (nech[i - 1] + chet[i]));
	return sum - mx;
}

