vector<ll> solve(const vector<ll>& A) {
  int L = A.size();
  vec<ll, 2> dp = make_v(L + 1, 2, 0ll);
  vector<ll> res(L + 1, 0);
  ll sum = 0;
  for (int i = 0; i < L; i++) {
    ll cur = A[i];
    if (cur == 0) {
      dp[i + 1][0] = min(dp[i][0] + 2, sum);
      dp[i + 1][1] = min(min(dp[i][0], dp[i][1]) + 1, sum);
    } else {
      dp[i + 1][0] = dp[i][0] + (cur % 2 != 0);
      dp[i + 1][1] = min(dp[i][0], dp[i][1]) + (cur % 2 != 1);
    }
    res[i + 1] = min(dp[i + 1][0], dp[i + 1][1]);
    sum += cur;
  }
  return res;
}

