long long gcd(long long a, long long b) {
	if (a < b) gcd(b, a);
	long long  r;
	while ((r = a%b)) {
		a = b;
		b = r;
	}
	return b;
}
long long lcm(long long a, long long b) {
	return a / gcd(a, b) * b;
}
long long modpow(long long a, long long n, long long mod) {
	long long res = 1;
	while (n > 0) {
		if (n & 1) res = res * a % mod;
		a = a * a % mod;
		n >>= 1;
	}
	return res;
}

long long modinv(long long a, long long mod) {
	long long b = mod, u = 1, v = 0;
	while (b) {
		long long t = a / b;
		a -= t*b; swap(a, b);
		u -= t*v; swap(u, v);
	}
	u %= mod;
	if (u < 0) u += mod;
	return u;
}
namespace NTT {
	const int MOD = 998244353;  // to be set appropriately
	const long long PR = 3;     // to be set appropriately

	void trans(vector<long long> &v, bool inv = false) {
		int n = (int)v.size();
		for (int i = 0, j = 1; j < n - 1; j++) {
			for (int k = n >> 1; k >(i ^= k); k >>= 1);
			if (i > j) swap(v[i], v[j]);
		}
		for (int t = 2; t <= n; t <<= 1) {
			long long bw = modpow(PR, (MOD - 1) / t, MOD);
			if (inv) bw = modinv(bw, MOD);
			for (int i = 0; i < n; i += t) {
				long long w = 1;
				for (int j = 0; j < t / 2; ++j) {
					int j1 = i + j, j2 = i + j + t / 2;
					long long c1 = v[j1], c2 = v[j2] * w % MOD;
					v[j1] = c1 + c2;
					v[j2] = c1 - c2 + MOD;
					while (v[j1] >= MOD) v[j1] -= MOD;
					while (v[j2] >= MOD) v[j2] -= MOD;
					w = w * bw % MOD;
				}
			}
		}
		if (inv) {
			long long inv_n = modinv(n, MOD);
			for (int i = 0; i < n; ++i) v[i] = v[i] * inv_n % MOD;
		}
	}

	// C is A*B
	vector<long long> mult(vector<long long> A, vector<long long> B) {
		int size_a = 1; while (size_a < A.size()) size_a <<= 1;
		int size_b = 1; while (size_b < B.size()) size_b <<= 1;
		int size_fft = max(size_a, size_b) << 1;

		vector<long long> cA(size_fft, 0), cB(size_fft, 0), cC(size_fft, 0);
		for (int i = 0; i < A.size(); ++i) cA[i] = A[i];
		for (int i = 0; i < B.size(); ++i) cB[i] = B[i];

		trans(cA); trans(cB);
		for (int i = 0; i < size_fft; ++i) cC[i] = cA[i] * cB[i] % MOD;
		trans(cC, true);

		vector<long long> res((int)A.size() + (int)B.size() - 1);
		for (int i = 0; i < res.size(); ++i) res[i] = cC[i];
		return res;
	}
};
const int maxn = 1 << 24;
int n2;
long long dat[2 * maxn - 1];
void init(int n_) {
	n2 = 1;
	while (n2 < n_)n2 *= 2;
	for (int i = 0; i < 2 * n2 - 1; i++) {
		dat[i] = 0;
	}
}
void update(long long  k, long long a) {
	k += n2 - 1;
	dat[k] = a;
	while (k > 0) {
		k = (k - 1) / 2;
		dat[k] = max(dat[k * 2 + 1], dat[k * 2 + 2]);
	}
}
long long query(int a, int b, int k, int l, int r) {
	if (r <= a || b <= l)return 0;
	if (a <= l&&r <= b)return dat[k];
	else {
		int vl = query(a, b, k * 2 + 1, l, (l + r) / 2);
		int vr = query(a, b, k * 2 + 2, (l + r) / 2, r);
		return max(vl, vr);
	}
}
signed main()
{
	cin.tie(0);
	ios::sync_with_stdio(false);
	int l;
	long long a[200005];
	cin >> l;
	long long ans = 0;
	for (int i = 1; i <= l; i++) {
		cin >> a[i];
		ans += a[i];
	}
	long long ruiseki[200005];
	ruiseki[0] = 0;
	long long ruiseki2[200005];
	ruiseki2[l + 1] = 0;
	for (int i = 1; i <= l; i++) {
		ruiseki[i] = ruiseki[i - 1] + (a[i] - ((a[i] + 1) % 2));
	}
	for (int i = l; i >= 1; i--) {
		long long tmp = (a[i] == 0) ? (long long)-2 : a[i]-(a[i] % 2);
		ruiseki2[i] = max((long long)0, ruiseki2[i + 1] + tmp);
	}
	init(l + 1);
	for (int i = 0; i <= l; i++) {
		update(i, ruiseki[i] + ruiseki2[i + 1]);
	}
	long long tmp = max(query(0,l+1,0,0,n2),(long long)0);
	long long now = 0;
	for (int i = 1; i < l; i++) {
		long long ha = (a[i] == 0) ? (long long)-2 : a[i] - (a[i] % 2);
		now = max((long long)0, ha + now);
		tmp = max(tmp, now + query(i + 1, l + 1, 0, 0, n2) - ruiseki[i]);
	}
	cout << ans - tmp;
}

