void make_divlist(V<V<ll>> &divlist, V<ll> &distances, const V<ll> &alist)
{
    ll zerocount = 0LL;
    V<ll> now;

    distances.pb(0LL);

    for (auto a : alist) {
        if (a == 0LL) {
            if (!now.empty()) {
                divlist.pb(now);
                now.clear();
            }
            zerocount++;
            continue;
        }

        if (zerocount) {
            distances.pb(zerocount);
            zerocount = 0LL;
        }

        now.pb(a);
    }

    if (!now.empty()) divlist.pb(now);
    if (alist[0] == 0LL) distances.erase(distances.begin());

    assert(divlist.size() == distances.size());
    rep (i, divlist.size()) {
        debug_printf("---- divlist %lld\n", i); debug_print(divlist[i]);
    }
    debug_printf("---- distances\n"); debug_print(distances);
}

ll solve_eoe(const V<ll> &vallist)
{
    ll l_even = 0LL;
    ll odd = 0LL;
    ll r_even = 0LL;

    for (auto val : vallist) {
        ll l_even_new = l_even + ((val & 1LL) ? 1LL : 0LL);

        ll odd_new = l_even + ((val & 1LL) ? 0LL : 1LL);
        odd_new = min(odd_new, odd + ((val & 1LL) ? 0LL : 1LL));

        ll r_even_new = l_even + ((val & 1LL) ? 1LL : 0LL);
        r_even_new = min(r_even_new, odd + ((val & 1LL) ? 1LL : 0LL));
        r_even_new = min(r_even_new, r_even + ((val & 1LL) ? 1LL : 0LL));

        l_even = l_even_new;
        odd = odd_new;
        r_even = r_even_new;
    }

    return min({l_even, odd, r_even});
}

void make_costs(V<ll> &costs_sum, V<ll> &costs_odd, V<ll> &costs_even,
                V<ll> &costs_oddeven, V<ll> &costs_evenodd,
                V<ll> &costs_eoe,
                const V<V<ll>> &divlist)
{
    for (auto vallist : divlist) {

        ll sum = 0LL;
        V<ll> oddcounts; oddcounts.pb(0LL);
        V<ll> evencounts; evencounts.pb(0LL);
        for (auto val : vallist) {
            sum += val;
            if (val & 1LL) {
                oddcounts.pb(*(oddcounts.end() - 1) + 1LL);
                evencounts.pb(*(evencounts.end() - 1));
            }
            else {
                oddcounts.pb(*(oddcounts.end() - 1));
                evencounts.pb(*(evencounts.end() - 1) + 1LL);
            }
        }

        costs_sum.pb(sum);
        costs_odd.pb(*(evencounts.end() - 1));
        costs_even.pb(*(oddcounts.end() - 1));

        ll len = vallist.size();
        ll min_oddeven = 1e18;
        ll min_evenodd = 1e18;
        rep (i, len + 1LL) {
            min_oddeven = min(min_oddeven,
                              evencounts[i] + (oddcounts[len] - oddcounts[i]));
            min_evenodd = min(min_evenodd,
                              oddcounts[i] + (evencounts[len] - evencounts[i]));
        }

        costs_oddeven.pb(min_oddeven);
        costs_evenodd.pb(min_evenodd);
        costs_eoe.pb(solve_eoe(vallist));

    }

    debug_printf("---- costs_sum\n"); debug_print(costs_sum);
    debug_printf("---- costs_odd\n"); debug_print(costs_odd);
    debug_printf("---- costs_even\n"); debug_print(costs_even);
    debug_printf("---- costs_oddeven\n"); debug_print(costs_oddeven);
    debug_printf("---- costs_evenodd\n"); debug_print(costs_evenodd);
    debug_printf("---- costs_eoe\n"); debug_print(costs_eoe);

    assert(divlist.size() == costs_sum.size());
    assert(divlist.size() == costs_odd.size());
    assert(divlist.size() == costs_even.size());
    assert(divlist.size() == costs_oddeven.size());
    assert(divlist.size() == costs_evenodd.size());
}

