void solve()
{
    ll n;
    cin>>n;
    vl v;
    v.pb(0);
    ll zero=0;
    ll pref[n+1]={0};
    for(int i=1;i<=n;i++)
    {
        ll c;
        cin>>c;
        v.pb(c);
        if(c==0)
            zero++;
        pref[i]=pref[i-1]+v[i];
    }
    if(zero==n)
    {
        cout<<0<<'\n';
        return;
    }
    ll dp[n][3];
    memset(dp,0,sizeof(dp));
    ll total=pref[n];
    ll ans=1e18;
    for(int i=1;i<=n;i++)
    {
        if(v[i]==0)
            continue;
        int j;
        for(j=i;j<=n;j++)
        {
            if(v[j]==0)
                break;
        }
        j--;
        dp[i-1][0]=0;
        dp[i-1][1]=0;
        dp[i-1][2]=0;
        for(int k=i;k<=j;k++)
        {
            dp[k][0]=dp[k-1][0]+v[k]%2;
            dp[k][1]=min(dp[k-1][0],dp[k-1][1])+1-v[k]%2;
            dp[k][2]=min3(dp[k-1][0],dp[k-1][1],dp[k-1][2])+v[k]%2;
        }
        ll red=pref[j]-pref[i-1]-min3(dp[j][0],dp[j][1],dp[j][2]);
        ans=min(ans,total-red);
        i=j;
    }
    cout<<ans<<'\n';
}
