using namespace std;
int main(){
	intl n;
	cin>>n;
	vector <intl> v;
	intl totsum=0;
	for(intl i=0;i<n;i++){
		intl a;
		cin>>a;
		v.push_back(a);
		totsum+=a;
	}
	intl maxi=0,current=0;
	bool zero=true;
	for(intl i=0;i<n;i++){

		if(v[i]==0){
			zero=true;
			current--;
		}
		else{
			if(zero){
				zero=false;
				intl aux=i,cpar=0,par=0,sump=0;
				while(aux<n&&v[aux]>0){
				if(v[aux]%2==0){
					cpar++;
					sump+=v[aux]-1;
				}
				else{
					par=maximo(par,cpar);
					cpar=0;
					sump+=v[aux];
					}
				aux++;
				}
				par=maximo(par,cpar);

				i=aux-1;

				maxi=maximo(maxi,maximo(current+sump,sump+par));
				current=maxi;
			}
		}
	}
	cout<<totsum-maxi<<endl;
}

