void solve()    {
    FOR(i, 1, n) FOR(j, 0, 4) dp[i][j] = oo;

    FOR(i, 1, n)    {
        // j = 0
        upd(dp[i][0], dp[i - 1][0] + a[i]);
        // j = 1
        upd(dp[i][1], dp[i][0]);
        if(a[i])    {
            upd(dp[i][1], dp[i - 1][1] + a[i] % 2);
            upd(dp[i][1], dp[i - 1][0] + a[i]);
        } else {
            upd(dp[i][1], dp[i - 1][1] + 2);
            upd(dp[i][1], dp[i - 1][0] + a[i]);
        }
        // j = 2
        upd(dp[i][2], dp[i][1]);
        if(a[i])    {
            upd(dp[i][2], dp[i - 1][1] + a[i] % 2);
            upd(dp[i][2], dp[i - 1][2] + (1 - a[i] % 2));
        } else {
            upd(dp[i][2], dp[i - 1][1] + 2);
            upd(dp[i][2], dp[i - 1][2] + 1);
        }
        // j = 3
        upd(dp[i][3], dp[i][2]);
        if(a[i]) {
            upd(dp[i][3], dp[i - 1][2] + (1 - a[i] % 2));
            upd(dp[i][3], dp[i - 1][3] + a[i] % 2);
        } else {
            upd(dp[i][3], dp[i - 1][2] + 1);
            upd(dp[i][3], dp[i - 1][3] + 2);
