        if(a[i])    upd(dp[i][4], dp[i - 1][3] + a[i] % 2);
        else upd(dp[i][4], dp[i - 1][3] + 2);
        upd(dp[i][4], dp[i - 1][4] + a[i]);
    }
    //FOR(i, 1, 4) cout << dp[1][i] << ' '; cout << '\n';
    upd(ans, dp[n][4]);
}

