vector<int> solve(vector<int> A)
{
	int N = A.size();
	vector<int> sum = A;
	FOR(i,1,N){
		sum[i] += sum[i-1];
	}

	vector<int> odd = A;
	for(auto &a:odd){
		a = (a+1)%2;
	}
	vector<int> even = A;
	for(auto &a:even){
		if(a == 0) a = 2;
		else a = a % 2;
	}

	vector<vector<int> > dp(N, vector<int>(3)); //[index][zero, even, odd]

	dp[0][0] = A[0];
	dp[0][1] = even[0];
	dp[0][2] = odd[0];
	FOR(i,1,N){
		dp[i][0] = dp[i-1][0] + A[i];
		dp[i][1] = min(dp[i-1][0], dp[i-1][1]) + even[i];
		dp[i][2] = min({dp[i-1][0], dp[i-1][1], dp[i-1][2]}) + odd[i];
	}

	vector<int> res(N);
	REP(i,N){
		res[i] = min({dp[i][0], dp[i][1], dp[i][2]});
	}

	return res;
}


