      sum[i] = sum[i - 1] + a[i];  
    }
  }  
  for (ll i = 0; i < n; i++) {
    ll j = n - i - 1;
    if (i == 0) {
      sum[j] = a[j];  
    }  
    else {
      sum[j] = sum[j + 1] + a[j];  
    }
  }
  for (ll i = 0; i < n; i++) {
    ll j = n - 1 - i;
    if (i <= 1) {
      dp[j] = 0;
      if (i == 1 && a[j] == 0 && a[j + 1] != 0) {
        dp[j]++;     
      }    
    }
    else {
      if (a[j] % 2 != a[j + 1] % 2 && a[j + 1] % 2 != a[j + 2] % 2) {
        dp[j] = dp[j + 1] + 1;  
      }
      else {
        dp[j] = dp[j + 1];  
      }
      if (a[j] == 0) {
        dp[j]++;  
      }
    }
  }
  for (ll i = 0; i < n; i++) {
    if (i <= 1) {
      dp2[i] = 0;
      if (i == 1 && a[i] == 0 && a[i - 1] != 0) {
        dp2[i]++;    
      }  
    }  
    else {
      if (a[i] % 2 != a[i - 1] % 2 && a[i - 1] % 2 != a[i - 2] % 2) {
        dp2[i] = dp2[i - 1] + 1;  
      }  
      else {
        dp2[i] = dp2[i - 1];  
      }
      if (a[i] == 0) {
        dp2[i]++;  
      }
    }
  }
  ll min = -1;
  min = dp[0];
  if (min > sum[n - 1]) {
    min = sum[n - 1];  
  }
  for (ll i = 0; i < n - 1; i++) {
    ll sub = sum[i] + dp[i + 1];
    if (sub < min) {
      min = sub;  
    }    
  }
  if (min > dp2[n - 1]) {
    min = dp2[n - 1];    
  }
  for (ll i = 0; i < n - 1; i++) {
    ll sub = dp2[i] + sum2[i + 1];
    if (sub < min) {
      min = sub;  
    }  
  }
  cout << min << endl;
}

