    for(ll i=0; i<L; i++) cin >> A[i];
    vector<ll> even(L+1, 0), odd(L+1, 0), Asum(L+1, 0);
    for(ll i=0; i<L; i++){
        Asum[i+1] = Asum[i] + A[i];
        if(A[i]%2 == 1){
            even[i+1] = even[i] + 1;
            odd[i+1] = odd[i];
        }
        else{
            even[i+1] = even[i];
            odd[i+1] = odd[i] + 1;
        }
    }
    ll before = min(Asum[1],even[1]) + odd[1]-odd[0] + min(Asum[L]-Asum[0], even[L]-even[0]);
    ll goal=1;
    ll ans = before;
    for(ll start=0; start<L; start++){
        while(goal < L && min(Asum[start+1],even[start+1]) + odd[goal+1]-odd[start] + min(Asum[L]-Asum[goal], even[L]-even[goal])-before < 0){
            before = min(Asum[start+1],even[start+1]) + odd[goal+1]-odd[start] + min(Asum[L]-Asum[goal], even[L]-even[goal]);
            goal += 1;
        }
        ans = min(ans, before);
    }
