void Cal::Solve() {
  // DPテーブル作成
  Dp[L - 1] = NumEven(A[L - 1]);
  for (int i = L - 2; i >= 0; --i) {
    if (A[i] == 0) {
      Dp[i] = Dp[i + 1] - 1;
    }
    //
    else {
      Dp[i] = Dp[i + 1] + NumEven(A[i]);
    }
  }

  ll maxDP = -300000;
  ll maxPos = 0;
  //もっともDPが大きくなるところ
