int l;
ll dp_r[2][200000];
ll dp_l[2][200000];
ll k_r[200000];
ll k_l[200000];
vector<ll> a;
vector<ll> rui;
ll ans = MAX;

int main(void){
	cin >> l;
	a.resize(l+10); rui.resize(l+10);
	for(int i = 0 ; i < l; ++i){
		cin >> a[i];
	}
	rui[0] = a[0];
	for(int i = 1 ; i < l; ++i){
		rui[i] = rui[i-1] + a[i];
	}
	// calc_right();
	for(int i = l-1; i >= 0; --i){
		k_r[i] = rui[l-1] - rui[i];
	}
	// calc_left();
	for(int i = 0; i < l; ++i){
		k_l[i] = rui[i];
	}


	for(int i = 0; i < 2; ++i){
		for(int j = 0; j < 200000; ++j){
			dp_r[i][j] = MAX;
			dp_l[i][j] = MAX;
		}
	}
	// make_dp_r();
	dp_r[0][l-1] = a[l-1]%2; dp_r[1][l-1] = !(a[l-1]%2);
	for(int i = l-2; i >= 0; --i){
		dp_r[0][i] = min(dp_r[0][i+1] + a[i]%2, k_r[i]);
		dp_r[1][i] = min(dp_r[1][i+1] + !(a[i]%2), k_r[i]);
	}
	// make_dp_l();
	dp_l[0][0] = a[0]%2; dp_l[1][0] = !(a[0]%2);
	for(int i = 1; i < l; ++i){
		dp_l[0][i] = min(dp_l[0][i-1] + a[i]%2, k_l[i]);
		dp_l[1][i] = min(dp_l[1][i-1] + !(a[i]%2), k_l[i]);
	}


	for(int i = 0; i < l-1; ++i){
		ans = min(ans, (ll)min(dp_r[0][i+1]+dp_l[1][i], dp_r[1][i+1]+dp_l[0][i]));
	}
	cout << ans << endl;
	return 0;
}

