void solve(int i, int l,int r){
  int add;
  if(l==0){
    if(r==0)add=a[i];
    else add = -1;
  } else if(l==1){
    if(r==0)add=a[i]&1;
    else if(r==1)add=(a[i]+1)&1;
    else if(r==2||r==3){
      add=-1;
    }
    else{
      if(a[i]<2)add=2-a[i];
      else add=a[i]&1;
    }
  } else if(l==2){
    if(r==0)add=a[i]&1;
    else if(r==1)add=(a[i]+1)&1;
    else if(r==2){
      if(a[i]<2)add=2-a[i];
      else add=a[i]&1;
    } else add = -1;
  } else if(l==3){
    if(r==0||r==2){
      if(a[i]<2)add=2-a[i];
      else add=a[i]&1;
    } else if(r==1){
      add=(a[i]+1)&1;
    } else if (r==3){
      add=a[i];
    } else {
      if(a[i]<2)add=2-a[i];
      else add=a[i]&1;
    }
  } else {
    if(r==0){
      add=a[i]&1;
    } else if(r==4){
      if(a[i]<2)add=2-a[i];
      else add=a[i]&1;
    } else add = -1;
  }
  if(add!=-1)pd(f[i][r],f[i-1][l]+add);
}

