vl f(vl a, int t) {
  if (t) reverse(a.begin(), a.end());
  int n = a.size();
  vl s(n + 1), v(n);
  for (int i = 0; i < n; ++i) {
    s[i + 1] = s[i] + a[i];
  }
  for (int i = 1; i < n; ++i) {
    ll add = a[i-1] % 2 + 2 * (int)(a[i-1] == 0);
    v[i] = min(s[i], v[i-1] + add);
  }
  if (t) reverse(v.begin(), v.end());
  return v;
}

