    //if((A[i] % 2 == 0 && A[i - 1] % 2 == 0) || (A[i] % 2 == 0 && A[i - 1] % 2 == 0)|| A[i] == 0){
    if(A[i] % 2 == 0){
      ccost++;
    }
    //cerr << "t " << i << " " << ccost - odd << " " << rcost[i] << " " << odd << endl;
    ans = min(ans, ccost + rcost[i] - odd);
  }

  start = L - 2;
  ccost = 0;
  if(A[L - 1] == 0)while(A[start] == 0) start--;
  for(int i = start; i >= 0; i--){
    int odd = 0;
    if(i + 2 < L && A[i + 2] != 0 && A[i + 1] != 0 && A[i] != 0 &&  odd < 2 && A[i + 2] % 2 == 0 && A[i + 1] % 2 == 1 && A[i] % 2 == 0) odd = 2;
