    if(A[i] % 2 == 0){
      ccost++;
    }
    //cerr << "rcost " << i << " " << ccost - odd << " " << odd << endl;
    ans = min(ans, ccost + cost[i] - odd);
  }


  cout << ans << endl;
  return 0;
}

