int gs(int a, int b) {
  if (a < 0 || a > 2)
    return -1;
  return a << 1 | b;
}

void load(int a) {
  static ll tmp[8];
  memcpy(tmp, dp, sizeof(dp));
  fill(dp, dp + 8, INF);
  if (a) {
    dp[6] = tmp[6] + a;
    dp[7] = tmp[7] + a;
    for (int i = 0; i < 3; ++i) {
      for (int j = 0; j < 2; ++j) {
        int u = gs(i, j);
        for (int t = 0; t < 2; ++t) {
          int inc = (j ^ t ^ a) & 1;
          int v = gs(i + inc, (t ^ a) & 1);
          if (v != -1)
            upd(dp[v], tmp[u] + t);
        }
      }
    }
    upd(dp[6], dp[3]);
  } else {
    dp[6] = tmp[6];
    dp[7] = tmp[7];
    for (int i = 0; i < 3; ++i) {
      for (int j = 0; j < 2; ++j) {
        int u = gs(i, j);
        for (int t = 1; t <= 2; ++t) {
          int inc = (j ^ t) & 1;
          int v = gs(i + inc, t & 1);
          if (v != -1)
            upd(dp[v], tmp[u] + t);
        }
      }
    }
  }
  upd(dp[0], dp[7]);
  upd(dp[6], dp[0]);
  upd(dp[6], dp[4]);
}

