#include <bits/stdc++.h>

int ri() {
	int n;
	scanf("%d", &n);
	return n;
}

int calc2(int n) {
	if (!n) return 2;
	else return n & 1;
}

int calc1(int n) {
	return !(n & 1);
}

int main() {
	int n = ri();
	int a[n];
	for (int i = 0; i < n; i++) a[i] = ri();

	int64_t dp[n + 1][5];
	for (int i = 0; i <= n; i++)
		for (int j = 0; j < 5; j++) dp[i][j] = 1000000000000000000;
	dp[0][0] = 0;
	for (int i = 0; i < n; i++) {
		for (int j = 0; j < 5; j++) {
			int64_t next;
			if (j == 0 || j == 4) next = dp[i][j] + a[i];
			else if (j == 1 || j == 3) next = dp[i][j] + calc2(a[i]);
			else next = dp[i][j] + calc1(a[i]);
			dp[i + 1][j] = std::min(dp[i + 1][j], next);
			if (j < 4) dp[i][j + 1] = std::min(dp[i][j + 1], dp[i][j]);
		}
	}
	std::cout << *std::min_element(dp[n], dp[n] + 5) << std::endl;

	return 0;
}

