	/*main function start*/
	int l;
	scanf("%d",&l);
	for(int i=0;i<l;i++){
		scanf("%lld",a+i);
	}
	for(int i=0;i<=l;i++){
		dp[i][0]=dp[i][1]=dp[i][2]=dp[i][3]=dp[i][4]=INF;
	}
