	for(int i=1;i<=l;i++){
		if(a[i-1]==0){
			long long p=dp[i-1][0];
			dp[i][0]=p;
			p=min(p,dp[i-1][1]);
			dp[i][1]=p+1;
			p=min(p,dp[i-1][2]);
			dp[i][2]=p+1;
			p=min(p,dp[i-1][3]);
			dp[i][3]=p+1;
			p=min(p,dp[i-1][4]);
			dp[i][4]=p;
		}
		else if(a[i-1]%2==0){
			long long p=dp[i-1][0];
			dp[i][0]=p+a[i-1];
			p=min(p,dp[i-1][1]);
			dp[i][1]=p;
			p=min(p,dp[i-1][2]);
			dp[i][2]=p+1;
			p=min(p,dp[i-1][3]);
			dp[i][3]=p;
			p=min(p,dp[i-1][4]);
			dp[i][4]=p+a[i-1];
		}
		else{
			long long p=dp[i-1][0];
			dp[i][0]=p+a[i-1];
			p=min(p,dp[i-1][1]);
			dp[i][1]=p+1;
			p=min(p,dp[i-1][2]);
			dp[i][2]=p;
			p=min(p,dp[i-1][3]);
			dp[i][3]=p+1;
			p=min(p,dp[i-1][4]);
			dp[i][4]=p+a[i-1];
		}
		if(dp[i][0]>INF) dp[i][0]=INF;
		if(dp[i][1]>INF) dp[i][1]=INF;
		if(dp[i][2]>INF) dp[i][2]=INF;
		if(dp[i][3]>INF) dp[i][3]=INF;
		if(dp[i][4]>INF) dp[i][4]=INF;
		if(dp[i][0]<0) dp[i][0]=INF;
		if(dp[i][1]<0) dp[i][1]=INF;
		if(dp[i][2]<0) dp[i][2]=INF;
		if(dp[i][3]<0) dp[i][3]=INF;
		if(dp[i][4]<0) dp[i][4]=INF;
	}
	long long ans=min(min(min(dp[l][0],dp[l][1]),min(dp[l][2],dp[l][3])),dp[l][4]);
	printf("%lld\n",ans);
	return 0;
}

