void solve(long long L, std::vector<long long> A){
    vector<vector<int>> dp(L + 1, vector<int>(5, INF));
    for(int i = 0; i < 5; ++i) {
        dp[0][i] = 0;
    }

    for(int i = 0; i < L; ++i) {
        dp[i + 1][0] = dp[i][0] + A[i];

        int c = A[i] % 2 == 0 ? (A[i] == 0 ? 2 : 0) : 1;
        dp[i + 1][1] = min(dp[i][1] + c, dp[i + 1][0]);

        int d = A[i] % 2 == 1 ? 0 : 1;
        dp[i + 1][2] = min(dp[i][2] + d, dp[i + 1][1]);

        dp[i + 1][3] = min(dp[i][3] + c, dp[i + 1][2]);

        dp[i + 1][4] = min(dp[i][4] + A[i], dp[i + 1][3]);
    }

    int res = dp[L][0];
    for(int i = 0; i < 5; ++i) {
        res = min(dp[L][i], res);
    }
    cout << res << endl;
}

