			closed_sum += A[i];
		}
		else {

			max_elim = max<lint>(max_elim, closed_sum - max<lint>(odd_num / 2 - 1, 0));

			closed_sum = 0;
			odd_num = 0;
		}
	}

	odd_num += A[L - 1] % 2;
	max_elim = max<lint>(max_elim, closed_sum - max<lint>(odd_num / 2 - 1, 0));

	cout << sum - max_elim;
