{
    ll ears; llin(ears);
    V<ll> alist; llinl1(alist, ears);

    V<V<ll>> divlist;
    V<ll> distances;
    make_divlist(divlist, distances, alist);

    if (divlist.empty()) {
        cout << 0 << endl;
        return 0;
    }

    V<ll> costs_sum;
    V<ll> costs_odd;
    V<ll> costs_even;
    V<ll> costs_oddeven;
    V<ll> costs_evenodd;
    make_costs(costs_sum, costs_odd, costs_even, costs_oddeven, costs_evenodd,
               divlist);

    ll init = costs_sum[0];
    ll l_even = costs_even[0];
    ll evenodd = costs_evenodd[0];
    ll odd = costs_odd[0];
    ll oddeven = costs_oddeven[0];
    ll r_even = costs_even[0];
    ll done = costs_sum[0];

    srep (i, 1LL, divlist.size()) {
        ll init_next = init + costs_sum[i];

        ll l_even_next = init + costs_even[i];
        l_even_next = min(l_even_next, l_even + distances[i] * 2LL + costs_even[i]);

        ll evenodd_next = init + costs_evenodd[i];
        evenodd_next = min(evenodd_next, l_even + distances[i] * 2LL + costs_evenodd[i]);

        ll odd_next = init + costs_odd[i];
        odd_next = min(odd_next, l_even + distances[i] + costs_odd[i]);
        odd_next = min(odd_next, evenodd + distances[i] + costs_odd[i]);
        odd_next = min(odd_next, odd + distances[i] + costs_odd[i]);

        ll oddeven_next = init + costs_oddeven[i];
        oddeven_next = min(oddeven_next, l_even + distances[i] + costs_oddeven[i]);
        oddeven_next = min(oddeven_next, evenodd + distances[i] + costs_oddeven[i]);
        oddeven_next = min(oddeven_next, odd + distances[i] + costs_oddeven[i]);

        ll r_even_next = init + costs_even[i];
        r_even_next = min(r_even_next, l_even + distances[i] + costs_even[i]);
        r_even_next = min(r_even_next, evenodd + distances[i] + costs_even[i]);
        r_even_next = min(r_even_next, odd + distances[i] + costs_even[i]);
        r_even_next = min(r_even_next, oddeven + distances[i] * 2LL + costs_even[i]);
        r_even_next = min(r_even_next, r_even + distances[i] * 2LL + costs_even[i]);

        ll done_next = init + costs_sum[i];
        done_next = min(done_next, l_even + costs_sum[i]);
        done_next = min(done_next, evenodd + costs_sum[i]);
        done_next = min(done_next, odd + costs_sum[i]);
        done_next = min(done_next, oddeven + costs_sum[i]);
        done_next = min(done_next, r_even + costs_sum[i]);
        done_next = min(done_next, done + costs_sum[i]);

        init = init_next;
        l_even = l_even_next;
        evenodd = evenodd_next;
        odd = odd_next;
        oddeven = oddeven_next;
        r_even = r_even_next;
        done = done_next;
    }

    cout << min({init, l_even, evenodd, odd, oddeven, r_even, done}) << endl;

    return 0;
}

