  for (ll i = 0; i < l; i++) scanf("%lld", &a[i]);
  if (l == 1) {
    printf("0\n");
    return 0;
  }
  ll ans = 0;
  for (ll i = 0; i < l; i++) if (a[i] % 2 == 0) ans++;
  ll sum = 0, score = 0, t = 0, a1 = 0;
  for (ll i = 0; i < l; i++) {
    ll x = 1;
    if (a[i] % 2 == 0 && a[i] != 0) x = -1;
    score += x;
    sum += a[i] - x + ((a[i] % 2 == 0) ? -1 : 0);
    t = lmin(t, sum);
    if (a1 > score) {
      a1 = score;
    }
    if (a1 > score + t) {
      a1 = score + t;
    }
    left[i] = a1;
    if (i > 0) left[i] = lmin(left[i], left[i-1]);
    else left[i] = lmin(0, left[i]);
  }
  sum = 0, score = 0, t = 0, a1 = 0;
  for (ll i = l-1; i >= 0; i--) {
    ll x = 1;
    if (a[i] % 2 == 0 && a[i] != 0) x = -1;
    score += x;
    sum += a[i] - x + ((a[i] % 2 == 0) ? -1 : 0);
    t = lmin(t, sum);
    a1 = min(score, a1);
    a1 = min(score + t, a1);
    right[i] = a1;
    if (i != l-1) right[i] = lmin(right[i], right[i+1]);
    else right[i] = lmin(0, right[i]);
  }
  ll tmp = 0;
  for (ll i = 0; i < l - 1; i++) tmp = lmin(tmp, left[i] + right[i+1]);
  ans += tmp;
  printf("%lld\n", ans);
}

