using ld = long double;

ll solve(vector<ll> a) {
    ll n = (ll)a.size();
    vector<vector<ll>> dp(n, vector<ll>(4));
    REP(i, n) {
        if(i == 0) {
            dp[i][0] = a[i];
            dp[i][1] = 0;
            dp[i][2] = inf * inf;
            dp[i][3] = inf * inf;
        } else {
            dp[i][0] = dp[i - 1][0] + a[i];
            dp[i][1] = min(dp[i - 1][0], dp[i - 1][1] + !(a[i] % 2));
            if(a[i] == 0) dp[i][2] = min(dp[i - 1][1], dp[i - 1][2]) + 2;
            else if(a[i] == 1) dp[i][2] = min(dp[i - 1][1], dp[i - 1][2]) + 1;
            else dp[i][2] = min(dp[i - 1][1], dp[i - 1][2]) + (a[i] % 2);
            dp[i][3] = min({dp[i - 1][0], dp[i - 1][1], dp[i - 1][2], dp[i - 1][3]}) + a[i];
        }
    }
    return min({dp[n - 1][0], dp[n - 1][1], dp[n - 1][2], dp[n - 1][3]});
}

