ll score(ll a,int t)
{
  if(t==0||t==4) return a;
  if(t==1||t==3)
  {
    if(a==0) return 2;
    else return a%2;
  }
  return (a+1)%2;
}

int main()
{
  int n;
  scanf("%d",&n);
  for(ll i=0;i<n;i++) scanf("%lld",&A[i]);
  for(ll i=0;i<=n;i++) for(int j=0;j<5;j++) dp[i][j]=INF;
  for(int j=0;j<5;j++) dp[0][j]=0;
  for(ll i=0;i<n;i++)
  {
    for(int j=0;j<5;j++)
    {
      if(j>0) dp[i][j]=min(dp[i][j],dp[i][j-1]);
      dp[i+1][j]=min(dp[i+1][j],dp[i][j]+score(A[i],j));
    }
  }
  ll ret=INF;
  for(int j=0;j<n;j++) ret=min(ret,dp[n][j]);
  printf("%lld",ret);
  return 0;
}

