void solve() {
    int n;
    SI(n);
    vl rec;
    REP(i, n) {
        ll x;
        SL(x);
        rec.push_back(x);
    }
    vvl dp(n+1, vl(5, 0));
    REPP(i, 1, n) {
        // c1
        dp[i][0] = dp[i-1][0] + rec[i-1];
        // c2
        dp[i][1] = min(dp[i-1][0], dp[i-1][1]) + (rec[i-1] == 0 ? 2 : rec[i-1] % 2);
        // c3
        dp[i][2] = MN3(dp[i-1][0], dp[i-1][1], dp[i-1][2]) + (rec[i-1] + 1) % 2;
        // c4
        dp[i][3] = MN4(dp[i-1][0], dp[i-1][1], dp[i-1][2], dp[i-1][3]) + (rec[i-1] == 0 ? 2 : rec[i-1] % 2);
        // c5
        dp[i][4] = MN5(dp[i-1][0], dp[i-1][1], dp[i-1][2], dp[i-1][3], dp[i-1][4]) + rec[i-1];
    }
    printf("%lld\n", MN5(dp[n][0], dp[n][1], dp[n][2], dp[n][3], dp[n][4]));
}

