      if(A[i] == 0){
	B[i] = 1;
	C[i] = 2;
      }else{
	B[i] = (A[i]%2?0:1);
	C[i] = (A[i]%2?1:0);
      }
    }

    dp[0][0] = 1;
    dp[0][1] = dp[0][2] = 2;

    REP(i,L){
      chmin(dp[i+1][0], min({sum[i], dp[i][0], dp[i][1]}) + B[i]);
      chmin(dp[i+1][1], min({sum[i], dp[i][1]}) + C[i]);
      chmin(dp[i+1][2], min({sum[i], dp[i][0], dp[i][1], dp[i][2]}) + C[i]);
    }

    LLI ans = s;

    FORE(i,1,L){
      LLI t = min({dp[i][0], dp[i][1], dp[i][2]}) + s-sum[i];
      chmin(ans, t);
