                icnt+=2;
                if(a[i-1]==1)
                {
                    if(cnt2<0)
                        cnt2-=r-l+1;
                    else
                        cnt2=-(r-l+1);
                    cnt2+=i-r-1;
                    if(cnt2>=0)
                        t11=0;
                    l=i;
                }
                if(a[i+1]==1)
                {
                    r=i;
                    if(t11!=0)
                    {
                        cmax=min(t12[t11]+cnt2,ltst);
                        cmax+=cnt-(r-l+1)+min((rmax[i2]-r-1)*2-(ncnt[i2]-icnt)+rtst3,ncnt[i2]-icnt+rtst4);
                    }
                    else
                    {
                        cmax=ltst+cnt-(r-l+1)+min((rmax[i2]-r-1)*2-(ncnt[i2]-icnt)+rtst3,ncnt[i2]-icnt+rtst4);
                        if(cnt2<0)
                            cmax+=cnt2;
                    }
                    if(cmax<res)
                        res=cmax;
                    if(cnt2<0)
                        tmp2=min(ltst3[i2]+scnt,ltst4[i2]+icnt-(r-l+1)*2+cnt2);
                    else
                        tmp2=min(ltst3[i2]+scnt,ltst4[i2]+icnt-(r-l+1)*2);
                    if(tmp2<ltst+cnt)
                    {
                        if(i2==spos)
                        {
