// 0 -> Ignore, 1 -> Odd, 2 -> Event
long long cost(int x, int t){
	if(t == 0) return x;
	else if(t == 1){
		if(x == 0) return 1;
		else return 1 - (x%2);
	}else{
		if(x == 0) return 2;
		else return x%2;
	}
}
