ll a[maxn+5],s[maxn+5],odd[maxn+5],z[maxn+5];
ll pre[maxn+5],suf[maxn+5];
int n;
int main()
{

    cin>>n;
    for(int i=1;i<=n;++i) scanf("%lld",&a[i]);
    for(int i=1;i<=n;++i)
    {
        s[i]=s[i-1]+a[i];
        odd[i]=odd[i-1]+(a[i]&1);
        z[i]=z[i-1]+(a[i]==0);
    }
    for(int i=1;i<=n;++i)
        if(a[i]==0) pre[i]=min(pre[i-1]+2,s[i]);
        else
            if(a[i]&1) pre[i]=pre[i-1]+1;
            else pre[i]=pre[i-1];
    for(int i=n;i>=1;--i)
        if(a[i]==0) suf[i]=min(suf[i+1]+2,s[n]-s[i]);
        else
            if(a[i]&1) suf[i]=suf[i+1]+1;
            else suf[i]=suf[i+1];
    ll ans=inf;
    ll mi=0;
    for(int i=1;i<=n;++i)
    {
        ans=min(ans,pre[i]+suf[i+1]);
        ans=min(ans,mi+i-odd[i]+2*z[i]+suf[i+1]);
        mi=min(mi,odd[i]-i-2*z[i]+pre[i]);
    }
    cout<<ans<<endl;
    return 0;
}

