vector<vector<ll>> dp;
vector<ll> A;

ll dfs(int n, int dir) {
    if (dp[n][dir] != -1) return dp[n][dir];
    if (n == 0 && dir == 0) {
        return dp[n][dir] = 0;
    }
    if (n == A.size() && dir == 1) {
        return dp[n][dir] = 0;
    }

    int d = dir == 0 ? -1 : 1;
    int yo = dir == 0 ? -1 : 0;
    ll temp = 0;
    if (A[n + yo] >= 2) {
        if (A[n + yo] % 2 == 0) {
            temp = A[n + yo] - 2;
        } else {
            temp = A[n + yo] - 1;
        }
    }

    ll ret = dfs(n + d, dir);
    if (A[n + yo] == 0) {
        return dp[n][dir] = max({0LL, temp - 1 + ret, temp - 2 + ret});
    } else if (A[n + yo] % 2 == 0) {
        return dp[n][dir] = max({0LL, temp + 1 + ret, temp + ret + 2});
    } else {
        return dp[n][dir] = max({0LL, temp + ret + 1, temp + ret});
    }
}

void solve() {
    int N;
    cin >> N;
    A.resize(N);
    ll sum = 0;
    for (int i = 0; i < N; i++) {
        cin >> A[i];
        sum += A[i];
    }
    dp.resize(N + 1);
    for (int i = 0; i < N + 1; i++) {
        dp[i].resize(2);
    }
    for (int i = 0; i < N + 1; i++) {
        for (int j = 0; j < 2; j++) {
            dp[i][j] = -1;
        }
    }

    dfs(N, 0);
    dfs(0, 1);

    ll ans = 1LL << 60;
    for (int i = 0; i < N + 1; i++) {
        ans = min(ans, sum - dp[i][0] + dp[i][1]);
    }
    cout << ans << endl;
    //cout << dp << endl;
}

