int cost(int stage, int v) {
   if (stage == 0 || stage == 4) return v;
   if (stage == 1 || stage == 3) {
       if (v == 0) return 2;
       return v % 2;
   }
   return (v + 1) % 2;
}

void upd(ll& x, ll y) {
    if (x == -1 || x > y) x = y;
}

void solve() {
    F0(i, n) cin >> a[i];
    ll ans = 0;

    CL(-1, dp);
    dp[0][0] = 0;
    F0(j, 5) F0(i, n) if (dp[j][i] != -1) {
        upd(dp[j][i + 1], dp[j][i] + cost(j, a[i]));
        if (j + 1 < 5) upd(dp[j + 1][i], dp[j][i]);
    }
    ans = -1;
    F0(j, 5) if (dp[j][n] != -1) upd(ans, dp[j][n]);
    cout << ans << endl;
}

