using namespace std;

typedef long long ll;

namespace rmq1 {
  const int N = 1 << 18;
  const ll INF = 2e18;
  ll data[2*N-1];
  void init(const vector<ll> &vs) {
    REP(i, N) {
      data[N-1+i] = INF;
    }
    int n = vs.size();
    REP(i, n) {
      data[N-1+i] = vs[i];
    }
    for(int i = N-2; i >= 0; --i) {
      data[i] = min(data[2*i+1], data[2*i+2]);
    }
  }
  ll getMinImpl(int bg, int ed, int k, int left, int right) {
    if(ed <= left || right <= bg) return INF;
    if(bg == left && ed == right) return data[k];
    int md = (left + right) / 2;
    if(ed <= md) return getMinImpl(bg, ed, 2*k+1, left, md);
    if(md <= bg) return getMinImpl(bg, ed, 2*k+2, md, right);
    ll lmin = getMinImpl(bg, md, 2*k+1, left, md);
    ll rmin = getMinImpl(md, ed, 2*k+2, md, right);
    return min(lmin, rmin);
  }
  ll getMin(int bg, int ed) {
    return getMinImpl(bg, ed, 0, 0, N);
  }
}
