  vector<ll> ls(L+1, 0); // 左から折り返し
  REP(i, L) {
    if(vs[i] == 0) {
      ls[i+1] = ls[i] + 2;
    } else if(vs[i] % 2 == 1) {
      ls[i+1] = ls[i] - vs[i] + 1;
    } else {
      ls[i+1] = ls[i] - vs[i];
    }
  }
