ll dp(ll i, ll state){
    if(i == n)return 0;
    if(DPC[i][state])return DP[i][state];
    ll ans = val(i,state) + dp(i+1,state);
    if(state < 4)ans = min(ans, dp(i,state+1));
    DPC[i][state] = 1;
    DP[i][state] = ans;
    return ans;
}


