void solve() {
	int64_t min_f0, min_f1, min_f2, min_f3;

	min_f0 = min_f1 = min_f2 = min_f3 = 0;

	for (int i=1; i<=n; ++i) {
		cost0[i] = cost0[i-1] + (a[i]==0 ? 2 : a[i]%2);
		cost1[i] = cost1[i-1] + (a[i]+1)%2;

		f0[i] = f0[i-1] + a[i];
		min_f0 = min(min_f0, -cost0[i]+f0[i]);

		f1[i] = cost0[i] + min_f0;
		min_f1 = min(min_f1, -cost1[i]+f1[i]);

		f2[i] = cost1[i] + min_f1;
