void Get(int *sa,int *sb,int *val)
{
	int p=0;
	for(int i=1;i<=n;i++)
	{
		ss[i]=sa[i]-sb[i];
		if(ss[i]<ss[p]) p=i;
		val[i]=sb[i]+ss[p];
	}
}
signed main()
{
	cin>>n;
	for(int i=1;i<=n;i++) cin>>A[i];
	//Get L
	for(int i=1;i<=n;i++)
	{
		suma[i]=suma[i-1]+A[i];
		sumb[i]=sumb[i-1]+(A[i]==0?2:(A[i]&1));
	}
	Get(suma,sumb,L);

	//Get R
	reverse(A+1,A+n+1);	
	for(int i=1;i<=n;i++)
	{
		suma[i]=suma[i-1]+A[i];
		sumb[i]=sumb[i-1]+(A[i]==0?2:(A[i]&1));
	}
	Get(suma,sumb,R);
	reverse(R+1,R+n+1);
	reverse(A+1,A+n+1);

	//Get Ans
	for(int i=1;i<=n;i++)
		sumc[i]=sumc[i-1]+1-(A[i]&1);
	Get(L,sumc,sumL);
	for(int i=0;i<=n;i++)
		Ans=min(Ans,sumL[i]+R[i+1]);
	cout<<Ans<<endl;
}

