ll cal(vector<ll>v){
    ll n=v.size();
    ll a[n+1];rep(i,0,n-1)a[i+1]=v[i]%2;
    ll dp[n+1][3];//rep(i,0,n)rep(j,0,2)dp[i][j]=inf;
    rep(j,0,2)dp[0][j]=0;
    rep(i,1,n){
        if(a[i]%2==1){
            dp[i][0]=dp[i-1][0]+1;
            dp[i][1]=min(dp[i-1][1],dp[i-1][0]);
            dp[i][2]=min(dp[i-1][1],dp[i-1][2]+1);
        }else{
            dp[i][0]=dp[i-1][0];
            dp[i][1]=min(dp[i-1][0]+1,dp[i-1][1]+1);
            dp[i][2]=min(dp[i-1][1],dp[i-1][2]);
        }
    }
    ll res=inf;rep(j,0,2)Min(res,dp[n][j]);
    return res;
}
ll fincal(vector<l_l>v){
    ll n=v.size();
    ll dp[n+1][3];//rep(i,0,n)rep(j,0,2)dp[i][j]=inf;
    rep(j,0,2)dp[0][j]=0;
    rep(i,1,n){
        if(i%2==1){//0じゃないやつ
            dp[i][0]=dp[i-1][0]+v[i-1].second;
            dp[i][1]=min(dp[i-1][1],dp[i-1][0])+v[i-1].first;
            dp[i][2]=min(dp[i-1][1],dp[i-1][2]+1)+v[i-1].second;
        }else{
            dp[i][0]=dp[i-1][0];
            dp[i][1]=min(dp[i-1][0],dp[i-1][1])+v[i-1].first;
            dp[i][2]=min(dp[i-1][1],dp[i-1][2]);
        }
    }
    ll res=inf;rep(j,0,2)Min(res,dp[n][j]);
    return res;
}

