                c++;
            }
            if(res.size()==0)continue;
            res.pb(l_l(c,0));
        }else{
            vector<ll>v;
            v.pb(a[pos]);
            ll sum=a[pos];
            while(pos+1<=n-1&&a[pos+1]!=0){
                pos++;
