// sum(a[x1] ... a[x2 - 1])
ll sum_range(int x1, int x2) {
    int left = min(x1, x2);
    int right = max(x1, x2);
    return sumarr[right] - sumarr[left];
}

int even_cost(int i) {
    if (a[i] == 0) return 2;
    return a[i] % 2;
}


ll memo_cost[100001][2];
// ear[x] -- x -- ear[x + 1]
//    -1 <- dir -> 1
ll cover_cost(int x, int dir) {
    int code = (dir == 1 ? 1 : 0);
    int next_ear = (dir == 1 ? x : x - 1);
    if (memo_cost[x][code] != -1) return memo_cost[x][code];
    ll ans = 0;
    if (x == l && dir == 1) {
        ans = 0;
    } else if (x == 0 && dir == -1) {
        ans = 0;
    } else {
        ll ans1 = cover_cost(x + dir, dir) + even_cost(next_ear);
        ll ans2 = (dir == 1) ? sum_range(x, l) : sum_range(0, x);
        ans = min(ans1, ans2);
    }
    memo_cost[x][code] = ans;
    return ans;
}

ll memo_cost_odd[100001][2];

ll cover_cost_odd(int x, int dir) {
    // PP(x, dir);
    int code = (dir == 1 ? 1 : 0);
    int next_ear = (dir == 1 ? x : x - 1);
    if (memo_cost_odd[x][code] != -1) return memo_cost_odd[x][code];
    ll ans = 0;
    if (x == l && dir == 1) {
        ans = 0;
    } else if (x == 0 && dir == -1) {
        ans = 0;
    } else {
        ll ans1 = cover_cost_odd(x + dir, dir) + (a[next_ear] + 1) % 2;
        ll ans2 = cover_cost(x, dir);
        // PP(x, dir);
        // PPP(ans1, ans2, a[next_ear]);
        ans = min(ans1, ans2);
    }
    memo_cost_odd[x][code] = ans;
    return ans;
}

