const int M = 2e5+5;
ll a[M],ans,dp[M][3][2],csEven[M],csVal[M];
void pre(int L)
{
	for(int i=1;i<=L;i++)
	{
		csEven[i] = csEven[i-1];
		if(a[i] % 2 == 0)
			csEven[i]++;
		csVal[i] = csVal[i-1];
		if(a[i] == 0)
			csVal[i] += 2;
		if(a[i] % 2)
			csVal[i] += 1;
	}
}
void solve(int L,int f)
{
	pre(L);
	ll sum = 0;
	ll mnEven = csEven[L];
	ll mnRet = csVal[L];
	for(int i = L-1;i>=0;i--)
	{
		sum += a[i+1];
		// forward	
		dp[i][0][0] = min(sum, mnEven - csEven[i]);
		// return
		dp[i][1][0] = min(sum, mnRet - csVal[i]);
		mnRet = min(mnRet, csVal[i] + sum);
		mnEven = min(mnEven, csEven[i] + min(dp[i][0][0], dp[i][1][0]));
	}
	sum = 0;
	mnEven = 0;
	mnRet = 0;
	for(int i=1;i<=L;i++)
	{
		sum += a[i];
		dp[i][0][1] = min(sum, mnEven + csEven[i]);
		dp[i][1][1] = min(sum, mnRet + csVal[i]);
		mnRet = min(mnRet, sum - csVal[i]);
		mnEven = min(mnEven, -csEven[i] + min(dp[i][0][1], dp[i][1][1]));
	}
}
