  rep(i, 1, L){
    s[i] = s[i-1] + a[i];
  }
  dump_1d(s, L);

  int dp[2][L];
  dp[0][0] = 0;
  dp[1][0] = 0;
  int res = s[L-1]-s[0];
  rep(i, 1, L){
    if (a[i]==0) {
      dp[0][i] = dp[0][i-1] + 1;
      dp[1][i] = dp[1][i-1] + 2;
    }
    else{
      dp[0][i] = dp[0][i-1] + (a[i]%2==0?1:0);
      dp[1][i] = dp[1][i-1] + (a[i]%2==0?0:1);
      chmin(dp[1][i], dp[0][i-1] + (a[i]%2==0?1:0));
    }

    chmin(dp[0][i], s[i]); // do nothing
    if (a[i]%2==0) chmin(dp[0][i], s[i-1]);  // return

    chmin(dp[1][i], dp[0][i]);
    chmin(res, dp[1][i]+(s[L-1]-s[i]));
    dump(i, res);
  }

  dump_2d(dp, 2, L);
  cout << res << endl;

  return 0;
}

