        while (pv < n && a[pv] == 0) pv++;
        sum = 0;
        int s = pv;
        while (pv < n && a[pv]) sum += a[pv++];
        Va.push_back({sum, {s, pv}});
    }
    sort(all(Va));
    auto last = Va.back();
    Va.pop_back();
    for (auto x : Va) ans += x.first;
    ans += solve(last.second);
    cout << ans << endl;
}

