long func(int tar,int flags){
    int res;
    if(flags == 0 || flags == 4){
        res = tar;
    }
    else if(flags == 1 || flags == 3){
        if(tar == 0)res = 2;
        else if(tar % 2 == 1)res = 1;
        else res = 0;
    }
    else{
        if(tar == 0)res = 1;
        else if(tar % 2 == 1)res = 0;
        else res = 1;
    }

    return res;
}

int main(void){
    int n; cin >> n;
    int a[n + 10];
    rep(i, n)cin >> a[i];

    long dp[n + 10][10];
    rrep(i, 1, n + 5){
        rep(j, 9){
            dp[i][j] = 1e18;
        }
    }
    rrep(i, 1, n + 1){
        rep(j, 5){
            long cost = 1e18;
            rep(k, j + 1){
                cost = min(cost, dp[i - 1][k]);
            }
            dp[i][j] = cost + func(a[i - 1], j);
        }
    }

    long ans = 1e18;
    rep(i, 5){
        ans = min(ans, dp[n][i]);
    }

    cout << ans << "\n";
    return 0;
}

