#define maxn 200010
#define cmin(_a, _b) (_a > (_b) ? _a = (_b) : 0)
int a[maxn];
int f0[maxn], f1[maxn], g0[maxn], g1[maxn];
int main()
{
	int n; scanf("%d", &n);
	for (int i = 1; i <= n; ++i) scanf("%d", a + i);
	memset(f0, 63, sizeof (f0));
	memset(f1, 63, sizeof (f1));
	memset(g0, 63, sizeof (g0));
	memset(g1, 63, sizeof (g1));
	f0[0] = f1[0] = g0[n] = g1[n] = 0;
	int sum = 0;
	for (int i = 1; i <= n; ++i)
	{
		sum += a[i]; cmin(sum, n + 1);
		if (a[i] % 2 == 0)
		{
			f0[i] = f0[i - 1] + (!a[i] ? 2 : 0);
			cmin(f0[i], sum);
			f1[i] = f1[i - 1] + 1;
		}
		else
		{
			f0[i] = f0[i - 1] + 1;
			f1[i] = f1[i - 1];
		}
	}
	sum = 0;
	for (int i = n; i; --i)
	{
		sum += a[i]; cmin(sum, n + 1);
		if (a[i] % 2 == 0)
		{
			g0[i - 1] = g0[i] + (!a[i] ? 2 : 0);
			cmin(g0[i - 1], sum);
			g1[i - 1] = g1[i] + 1;
		}
		else
		{
			g0[i - 1] = g0[i] + 1;
			g1[i - 1] = g1[i];
		}
	}
	int ans = 0x7fffffff;
	for (int i = 0; i <= n; ++i)
	{
		cmin(ans, f0[i] + g1[i]),
		cmin(ans, f1[i] + g0[i]),
		cmin(ans, f0[i] + g0[i]);
		// printf("i = %d %d %d %d %d\n", i, f0[i], f1[i], g0[i], g1[i]);
	}
	printf("%d\n", ans );
	return 0;
}

