ll b0(ll p){
  return 1-(p%2);
}

ll b1(ll p){
  if(p==0) return 2;
  return p%2;
}

ll co(ll p,ll j){
  if(j==2) return b0(p);
  if(j==1||j==3) return b1(p);
  return p;
}

int main(){
  ll l,a[200010],dp[200010][5],k[5]={};
