    k[0]=dp[i][0];
    fr(j,4) k[j+1]=min(k[j],dp[i][j+1]);
    fr(j,5) dp[i+1][j]=k[j]+co(a[i],j);
  }
  ll ans=dp[l][4];
  fr(j,4) ans=min(ans,dp[l][j]);
  cout<<ans<<endl;
}

