using it_t = std::vector<long>::iterator;

bool is_positive_even(long x) { return (x != 0) && (x%2 == 0); }

long ops_contiguous(it_t first, it_t last)
{
	auto first_oddit = std::find_if_not(first, last, is_positive_even);
	if (first_oddit == last)
		return 0;
	auto last_oddit = std::find_if_not(std::make_reverse_iterator(last), std::make_reverse_iterator(first_oddit), is_positive_even).base();

	long emo = 0;
	long max_emo = 0;
	for (auto it = first_oddit; it != last_oddit; ++it) {
		if (is_positive_even(*it)) {
			++emo;
		} else {
			--emo;
		}
		if (max_emo < emo) {
			first_oddit = it+1;
			max_emo = emo;
		}
	}

	emo = 0;
	max_emo = 0;
	for (auto it = std::make_reverse_iterator(last_oddit); it != std::make_reverse_iterator(first_oddit); ++it) {
		if (is_positive_even(*it)) {
			++emo;
		} else {
			--emo;
		}
		if (max_emo < emo) {
			last_oddit = it.base()-1;
			max_emo = emo;
		}
	}

	long n = 0;
	for (auto it = first; it != first_oddit; ++it) {
		if (*it == 0)
			n += 2;
		else if (*it % 2 == 1)
			++n;
	}
	for (auto it = first_oddit; it != last_oddit; ++it) {
		if (*it % 2 == 0)
			++n;
	}
	for (auto it = last_oddit; it != last; ++it) {
		if (*it == 0)
			n += 2;
		else if (*it % 2 == 1)
			++n;
	}
	return n;
}

long min_ringo_ops(it_t first, it_t last)
{
	auto zeroit = std::find(first, last, 0);
	if (zeroit == last)
		return ops_contiguous(first, last);
	auto nonzeroit = std::find_if_not(zeroit, last, [](auto x)->bool{return x == 0;});
	return std::min(std::min(
		ops_contiguous(first, zeroit) + std::accumulate(nonzeroit, last, 0),
		ops_contiguous(nonzeroit, last) + std::accumulate(first, zeroit, 0)),
		ops_contiguous(first, last));
}

int main()
{
	long L;
	std::vector<long> A;

	std::cin >> L;
	A.resize(L);
	for (auto& a : A) {
		std::cin >> a;
	}

	auto first = A.begin();
	auto last = A.end();
	while (first != last && *first == 0)
		++first;
	while (last != first && *(last-1) == 0)
		--last;

	std::cout << min_ringo_ops(first, last) << "\n";
}

