constexpr ll TEN(int n) { return (n == 0) ? 1 : 10 * TEN(n - 1); }
template <class T> using V = vector<T>;
template <class T> using VV = V<V<T>>;


using A = array<ll, 3>;

V<A> solve(V<ll> a) {
    int n = int(a.size());
    V<A> dp(n + 1, A{});
    for (int i = 0; i < n; i++) {
        dp[i+1][0] = dp[i][0] + a[i];
        dp[i+1][2] = min(dp[i][0], dp[i][2]) + max(1LL, a[i]) % 2;
        dp[i+1][1] = min({dp[i][0], dp[i][2], dp[i][1]}) + 1 - a[i] % 2;
    }
    return dp;
}

int main() {
    int n;
    cin >> n;
    V<ll> a(n);
    for (int i = 0; i < n; i++) {
        cin >> a[i];
    }
    auto s1 = solve(a);
    reverse(a.begin(), a.end());
    auto s2 = solve(a);
    reverse(s2.begin(), s2.end());
    ll mi = TEN(18);
    for (int i = 0; i < n; i++) {
        for (int x = 0; x < 9; x++) {
            mi = min(mi, s1[i][x/3] + s2[i][x%3]);
        }
    }
    cout << mi << endl;
    return 0;
}

