#define N 200010
int n, a[N];
ll f[N][5];

int main()
{
	while (scanf("%d", &n) != EOF)
	{
		for (int i = 1; i <= n; ++i) scanf("%d", a + i);
		memset(f, 0x3f, sizeof f);
		for (int i = 0; i < 5; ++i) f[0][i] = 0;
		// 0 左边零碎
		// 1 左边偶数
		// 2 奇数
		// 3 右边偶数
		// 4 右边零碎
		for (int i = 1; i <= n; ++i)
		{
			ll Min = (ll)1e18, cost;
			cost = a[i];
			Min = min(Min, f[i - 1][0]);
			f[i][0] = Min + cost;

			cost = a[i] == 0 ? 2 : (a[i] % 2);
			Min = min(Min, f[i - 1][1]);
			f[i][1] = Min + cost;

			cost = a[i] == 0 ? 1 : (a[i] % 2 == 0);
			Min = min(Min, f[i - 1][2]);
			f[i][2] = Min + cost;

			cost = a[i] == 0 ? 2 : (a[i] % 2);
			Min = min(Min, f[i - 1][3]);
			f[i][3] = Min + cost;

			cost = a[i];
			Min = min(Min, f[i - 1][4]);
			f[i][4] = Min + cost;
		}
		ll res = (ll)1e18;
		for (int i = 0; i < 5; ++i)
			res = min(res, f[n][i]);
		printf("%lld\n", res);
	}
	return 0;
}

