const int MAX = 2e5 + 41;
const ll INF = 1e18;

int n;
int a[MAX];
ll pref[MAX];
ll suf[MAX];
ll d[MAX][5];

int geteven(int x) {
	if (x == 0) return 2;
	return x % 2;
}

int getodd(int x) {
	return 1 - (x % 2);
}

void solve() {
	fi(1, n) {
		pref[i] = pref[i - 1] + a[i];
	}
	fdi(n, 1) {
		suf[i] = suf[i + 1] + a[i];
	}
	ll ans = accumulate(a + 1, a + n + 1, 0LL);

	fill_n(&d[0][0], MAX * 5, INF);
	d[1][0] = 0;
	fi(1, n) {
		fj(0, 4) {
			if (d[i][j] < 0) continue;
			if (j == 0) {
			  d[i + 1][0] = min(d[i + 1][0], d[i][0] + a[i]);
			  d[i + 1][1] = min(d[i + 1][1], d[i][0] + geteven(a[i]));
				d[i + 1][2] = min(d[i + 1][2], d[i][0] + getodd(a[i]));
				d[i + 1][3] = min(d[i + 1][3], d[i][0] + geteven(a[i]));
				d[i + 1][4] = min(d[i + 1][4], d[i][0] + a[i]);
			} else if (j == 1) {
				d[i + 1][1] = min(d[i + 1][1], d[i][1] + geteven(a[i]));
				d[i + 1][2] = min(d[i + 1][2], d[i][1] + getodd(a[i]));
				d[i + 1][3] = min(d[i + 1][3], d[i][1] + geteven(a[i]));
				d[i + 1][4] = min(d[i + 1][4], d[i][1] + a[i]);
			} else if (j == 2) {				
				d[i + 1][2] = min(d[i + 1][2], d[i][2] + getodd(a[i]));
				d[i + 1][3] = min(d[i + 1][3], d[i][2] + geteven(a[i]));
				d[i + 1][4] = min(d[i + 1][4], d[i][2] + a[i]);
			} else if (j == 3) {
				d[i + 1][3] = min(d[i + 1][3], d[i][3] + geteven(a[i]));
				d[i + 1][4] = min(d[i + 1][4], d[i][3] + a[i]);
			} else if (j == 4) {				
				d[i + 1][4] = min(d[i + 1][4], d[i][4] + a[i]);
			}
		}
	}

	fi(0, 4) {
		ans = min(ans, d[n + 1][i]);
	}

	printf("%lld\n", ans);
}

int main() {
#ifdef LOCAL
	freopen("input.txt", "r", stdin);
	freopen("output.txt", "w", stdout);
	START_TIME = (double)clock();
#endif

	scanf("%d", &n);
	fi(1, n) {
		scanf("%d", &a[i]);
	}
	solve();

	exit();
	return 0;
}

