ll run(ll x, int parity) {
	if (x == 0) return parity;
	else return x % parity;
}

vll solve_even(const vll a) {
	int n = a.size();
	vll s(n);
	Loop(i, n) {
		if (i == 0) s[i] = a[i];
		else s[i] = a[i] + s[i - 1];
	}
	vll ret(n + 1);
	Loop1(i, n) {
		ret[i] = min(ret[i - 1] + run(a[i - 1], 2), s[i - 1]);
	}
	return ret;
}

vll solve_v(const vll a) {
	int n = a.size();
	vll ret(n + 1);
	vll rev = a;
	reverse(rev.begin(), rev.end());
	vll evens = solve_even(rev);
	reverse(evens.begin(), evens.end());
	ll cnt = 0;
	Loop(i, n + 1) {
		ret[i] = evens[i] + cnt;
		if (i < n) cnt += (a[i] + 1) % 2;
	}
	return ret;
}

int main() {
	int n; cin >> n;
	vll a(n);
	Loop(i, n) cin >> a[i];
	vll v = solve_v(a);
	map<ll, int> mp;
	Loop(i, v.size()) mp[v[i]]++;
	ll margin = 0;
	ll ans = LLONG_MAX;
	vll evens = solve_even(a);
	Loop(i, n + 1) {
		ans = min(ans, mp.begin()->first + evens[i] - margin);
		mp[v[i]]--;
		if (mp[v[i]] == 0) mp.erase(v[i]);
		if (i < n) margin += (a[i] + 1) % 2;
	}
	cout << ans << endl;
}

