		f[i][1] = std::min(f[i - 1][0], std::min(f[i - 1][1], s[i - 1])) + (a[i] == 0 ? 1 : ((a[i] & 1) ? 0 : 1));
		f[i][2] = std::min(f[i - 1][1], f[i - 1][2]) + (a[i] == 0 ? 2 : ((a[i] & 1) ? 1 : 0));		
		ans = std::min(ans, std::min(std::min(f[i][0], f[i][1]), f[i][2]) + s[n] - s[i]);
	}
	printf("%lld\n", ans);
}

