template <class T> using reversed_priority_queue = priority_queue<T, vector<T>, greater<T> >;
template <class T, class U> inline void chmax(T & a, U const & b) { a = max<T>(a, b); }
template <class T, class U> inline void chmin(T & a, U const & b) { a = min<T>(a, b); }
template <typename X, typename T> auto vectors(X x, T a) { return vector<T>(x, a); }
template <typename X, typename Y, typename Z, typename... Zs> auto vectors(X x, Y y, Z z, Zs... zs) { auto cont = vectors(y, z, zs...); return vector<decltype(cont)>(x, cont); }
template <typename T> ostream & operator << (ostream & out, vector<T> const & xs) { REP (i, int(xs.size()) - 1) out << xs[i] << ' '; if (not xs.empty()) out << xs.back(); return out; }

ll solve(int l, vector<ll> const & a) {
    vector<ll> acc(l + 1);
    partial_sum(ALL(a), acc.begin() + 1);
    // 0: no flow
    // 1: one flow
    // 2: two flows, left connected
    // 3: two flows, right connected
    array<ll, 4> cur = {}, prv;
    ll answer = acc[l];
    REP (i, l) {
        swap(cur, prv);
        fill(ALL(cur), LLONG_MAX);
        chmin(cur[0], prv[0] + a[i]);
        chmin(cur[1], prv[0]);
        chmin(cur[1], prv[1] + (a[i] == 0 ? 1 : a[i] % 2 == 0 ? 1 : 0));
        chmin(cur[1], prv[2] + (a[i] == 0 ? 1 : a[i] % 2 == 0 ? 1 : 0));
        chmin(cur[2], prv[0] + a[i] % 2);
        chmin(cur[2], prv[2] + (a[i] == 0 ? 2 : a[i] % 2 == 0 ? 0 : 1));
        chmin(cur[3], prv[0]);
        chmin(cur[3], prv[1] + (a[i] == 0 ? 1 : 0));
        chmin(cur[3], prv[3] + (a[i] == 0 ? 2 : a[i] % 2 == 0 ? 0 : 1));

        chmin(answer, *min_element(ALL(cur)) + acc[l] - acc[i + 1]);
// cerr << i << " : " << a[i] <<  " : " << cur[0] << ' ' << cur[1] << ' ' << cur[2] << ' ' << cur[3]<< endl;
    }
    return answer;
}

int main() {
    int l; cin >> l;
    vector<ll> a(l);
    REP (i, l) cin >> a[i];
    cout << solve(l, a) << endl;
    return 0;
}

