ll sum(vector<ll> &bit, ll i) {
    ll s = 0;
    while (i > 0) {
        s += bit[i];
        i -= i & -i;
    }
    return s;
}

void add(vector<ll> &bit, ll i, ll x) {
    while (i < bit.size()) {
        bit[i] += x;
        i += i & -i;
    }
}

int main() {
    ll L;
    cin >> L;
    vector<ll> A(L+1);
    vector<ll> abit(L+1, 0);
    for (int i = 1; i <= L; ++i) {
        cin >> A[i];
        add(abit, i, A[i]);
    }

    vector<ll> oddn(L+1, 0);
    vector<ll> zeroes; zeroes.reserve(L);
    vector<pair<ll, ll>> codd; codd.reserve(L);

    bool prevodd = false;
    ll first = 0;
    for (ll i = 1; i <= L; ++i) {
        if (A[i] == 0) zeroes.emplace_back(i);
        if (A[i] % 2 == 1) {
            add(oddn, i, 1);
            if (!prevodd) first = i-1;
            prevodd = true;
        } else {
            if (prevodd) codd.emplace_back(first, i-1);
            else codd.emplace_back(i-1, i-1);
            prevodd = false;
        }
    }
    if (prevodd) codd.emplace_back(first, L);
    else codd.emplace_back(L, L);

    ll ans = sum(abit, L);
    for (auto &&p: codd) {
        ll op = 0;
        auto zi_p = upper_bound(zeroes.begin(), zeroes.end(), p.first);
        if (zi_p != zeroes.begin()) {
            zi_p--;
            op += sum(abit, *zi_p);
            op += sum(oddn, p.first) - sum(oddn, *zi_p);
        } else {
            op += sum(oddn, p.first);
        }
        auto zi_n = lower_bound(zeroes.begin(), zeroes.end(), p.second+1);
        if (zi_n != zeroes.end()) {
            op += sum(abit, L) - sum(abit, *zi_n);;
            op += sum(oddn, *zi_n) - sum(oddn, p.second);
        } else {
            op += sum(oddn, L) - sum(oddn, p.second);
        }

        ans = min(ans, op);
    }

    cout << ans << endl;

    return 0;
}

