            left_odd[i] += left_odd[i - 1];
        }
        if (i != 0 && left_even[i - 1] > 0) {
            left_even[i] += left_even[i - 1];
        }
    }

    vl right_odd(L, 0);
    vl right_even(L, 0);

    for (int i = L - 1; i >= 0; i--) {
        if (A[i] == 0) {
            right_odd[i] -= 1;
            right_even[i] -= 2;
        } else {
            right_odd[i] += 1 + ((A[i] - 1) / 2) * 2;
            if (A[i] == 1) {
                right_even[i] -= 1;
            } else {
                right_even[i] += A[i] - A[i] % 2;
            }
        }
        if (i != L - 1 && right_odd[i + 1] > 0) {
            right_odd[i] += right_odd[i + 1];
        }
        if (i != L - 1 && right_even[i + 1] > 0) {
            right_even[i] += right_even[i + 1];
