/*
・BIT (BinaryIndexedTree)
  > O(logN)
[備考] ある要素に値を加える操作と, 区間和を求める操作に関してlogNで行うデータ構造
[使用例]
BinaryIndexedTree<int> bit(N);      // 要素数NのBIT
bit.add(k, x);                      // 要素kに値xを加算
bit.sum(k);                         // 閉区間[0,k]の和を求める
*/

template<typename T> struct BinaryIndexedTree {
  vector<T> data;
  BinaryIndexedTree(int sz) { data.assign(++sz, 0); }
  T sum(int k) {
    T ret = 0;
    for (++k; k > 0; k -= k & -k) ret += data[k];
    return (ret);
  }
  void add(int k, T x) { for (++k; k < data.size(); k += k & -k) data[k] += x; }
};

signed main() {

  SS(ll, L);
  SV(ll, A, L);

  // [from, to]
  ll from = 0, to = L - 1;
  while (A[from] == 0) from++;
  while (A[  to] == 0)   to--;

  vector<vl> islands;
  vl tmp;
  ll cnt = 0;
  vl zeros;
  REP(i, from, to + 1) {
    if (A[i] != 0) {
      if (cnt != 0) {
        zeros.PB(cnt);
        cnt = 0;
      }
      tmp.PB(A[i]);
    } else {
      cnt++;
      if (int(tmp.size()) != 0) {
        islands.PB(tmp);
        vl().swap(tmp);
      }
    }
  }
  if (int(tmp.size()) != 0) {
    islands.PB(tmp);
  }
  ll islands_num = islands.size();

  vl left_to_right, right_to_left;
  vl to_right, to_left;
  vl both;

  // left_to_right
  REP(i, islands_num) {
    ll tmp = 0;
    EACH(e, islands[i]) tmp += (e % 2 == 0);
    left_to_right.PB(tmp);
  }

  // right_to_left
  REP(i, islands_num) {
    ll tmp = 0;
    int sz = islands[i].size();
    REP(e, sz - 1, 0) tmp += (islands[i][e] % 2 == 0);
    right_to_left.PB(tmp);
  }

  // to_right
  REP(i, islands_num) to_right.PB(max<ll>(0, left_to_right[i] - (islands[i][0] % 2 == 0)));

  // to_left
  REP(i, islands_num) to_left.PB(max<ll>(0, right_to_left[i] - (islands[i][int(islands[i].size()) - 1] % 2 == 0)));

  // both
  REP(i, islands_num) {
    ll lr = to_right[i], rl = to_left[i];
    if (islands[i][int(islands[i].size()) - 1] % 2 == 0) lr--;
    if (islands[i][0] % 2 == 0) rl--;
    both.PB(max<ll>(0, min<ll>(lr, rl)));
  }

  if (islands_num == 1) {
    print(both[0]);
    return 0;
  }

  debug(islands);
  debug(zeros);
  debug(left_to_right);
  debug(right_to_left);
  debug(to_right);
  debug(to_left);
  debug(both);

  BinaryIndexedTree<ll> bit(islands_num);
  REP(i, islands_num) {
    ll sum = 0;
    EACH(e, islands[i]) {
      sum += e;
    }
    bit.add(i, sum);
  }

  // bit.sum(k);                         // 閉区間[0,k]の和を求める

  ll res = INFF;
  // 閉区間
  REP(i, islands_num) {
    REP(j, i, islands_num) {
      ll cnt = bit.sum(islands_num - 1);
      if (i - 1 != 0) cnt += bit.sum(i - 1);
      cnt -= bit.sum(j);
      REP(p, i, j + 1) {
        if (p == i) {
          cnt += to_right[p];
        } else if (p == j) {
          cnt += left_to_right[p];
          if (islands[p][int(islands[p].size()) - 1] % 2 == 0) cnt--;
        } else {
          cnt += left_to_right[p];
        }
        if (p != j) {
          cnt += zeros[p];
        }
      }
      res = min<ll>(res, cnt);
    }
  }
  REP(i, islands_num) {
    REP(j, i, islands_num) {
      ll cnt = bit.sum(islands_num - 1);
      if (i - 1 != -1) cnt += bit.sum(i - 1);
      cnt -= bit.sum(j);
      REP(p, i, j + 1) {
        if (p == i) {
          cnt += right_to_left[p];
          if (islands[p][0] % 2 == 0) cnt--;
        } else if (p == j) {
          cnt += to_left[p];
        } else {
          cnt += right_to_left[p];
        }
        if (p != i) {
          cnt += zeros[p];
        }
      }
      res = min<ll>(res, cnt);
    }
  }

  print(max<ll>(0, res));

}

