#include <iostream>
#include <vector>
using namespace std;
const long long INF = 1e18;

struct SegmentTree {
private:
  int n;
  vector< long long > node;//min,max
public:
  SegmentTree(vector<long long> v, vector<long long> u){
    int sz = v.size();
    n = 1;
    while(n < sz) n *= 2;
    node.resize(2*n-1,INF);
    for(int i = 0; i < sz; ++i){
      node[i+n-1] = v[i];
      if(i > 0) node[i+n-1] += u[i-1];
    }
    for(int i = n-2; i >= 0; --i)
      node[i] = min(node[2*i+1],node[2*i+2]);
  }
  void update(int idx, int val){
    idx += n-1;
    node[idx] = val;
    while(idx > 0){
      idx = (idx-1)/2;
      node[idx] = min(node[2*idx+1],node[2*idx+2]);
    }
  }
  long long get_min(int a, int b, int k=0, int l=0, int r=-1){
    if(r < 0) r = n;
    if(r <= a or b <= l) return INF;
    if(a <= l and r <= b) return node[k];
    long long vl = get_min(a,b,2*k+1,l,(l+r)/2);
    long long vr = get_min(a,b,2*k+2,(l+r)/2,r);
    return min(vl,vr);
  }
};

int main(){
  int L;
  cin >> L;
  vector<long long> A(L), F(L+1,0), B(L+1,0), C(L+1,0), O(L+1,0);
  for(int i = 0; i < L; ++i) cin >> A[i];
  for(int i = 0; i < L; ++i) C[i+1] += A[i] + C[i];
  for(int i = 0; i < L; ++i) O[i+1] += 1-(A[i]%2) + O[i];
  for(int i = 0; i < L; ++i){
    long long t = A[i]%2;
    if(A[i] < 2) t = 2-A[i];
    F[i+1] = min(F[i]+t,C[i+1]);
  }
  for(int i = L-1; i >= 0; --i){
    long long t = A[i]%2;
    if(A[i] < 2) t = 2-A[i];
    B[i] = min(B[i+1]+t,C[L]-C[i]);
  }
  // fprintf(stderr,"F : "); for(int i = 0; i <= L; ++i) cerr << F[i] << " "; cerr << endl;
  // fprintf(stderr,"B : "); for(int i = 0; i <= L; ++i) cerr << B[i] << " "; cerr << endl;
  // fprintf(stderr,"O : "); for(int i = 0; i <= L; ++i) cerr << O[i] << " "; cerr << endl;
  SegmentTree st(B,O);
  long long ans = F[L];
  for(int i = 0; i < L; ++i){
    long long t = F[i] + st.get_min(i+1,L) - O[i];
    // fprintf(stderr,"F[%d] = %lld, st.get_min(%d) = %lld\n",i,F[i],i+1,st.get_min(i+1,L));
    // fprintf(stderr,"O[%d] = %lld\n",i,O[i]);
    // cerr << i << " " << t << endl;
    ans = min(ans,t);
  }
  cout << ans << endl;
}

