		else if ((v[i] & 1) == 0 && !r)
			ret = min(ret, 1 + calcL(i - 1, r));
		else
			ret = min(ret, calcL(i - 1, r));
	}
	return ret;
}
ll calcR(int i, bool r) {
	ll &ret = dpR[i][r];
	if (ret != -1)
		return ret;
	ret = cs[n] - cs[i];
	if (i != n) {
		if (v[i + 1] == 0)
			ret = min(ret, 1 + r + calcR(i + 1, r));
		else if ((v[i + 1] & 1) && r)
