void solve(int n) {
    dp[1][0] = 0;
    LL sum = 0;
    for (int i = 1; i <= n; i++) {
        sum += nums[i];
        dp[1][i] = sum;
        if (nums[i] % 2 == 1) {
            dp[1][i] = min(dp[1][i], dp[1][i-1]);
        } else {
            dp[1][i] = min(dp[1][i], dp[1][i-1] + 1);
        }
    }
