    dp[0][n+1] = 0;
    for (int i = n; i >= 1; i--) {
        sum += nums[i];
        dp[0][i] = sum;
        if (nums[i] == 0) {
            dp[0][i] = min(dp[0][i], dp[0][i+1] + 2);
        } else if (nums[i] % 2 == 0) {
            dp[0][i] = min(dp[0][i], dp[0][i+1]);
        } else {
            dp[0][i] = min(dp[0][i], dp[0][i+1] + 1);
        }
    }
}





