LL solve(LL n, vector<LL>& a){
    vector<LL> left(n+1);
    vector<LL> right(n+1);
    for(LL i = 0; i < n; ++i){
        left[i+1] = left[i] + a[i];
        right[n-i-1] = right[n-i] + a[n-1-i];
    }
    LL ans = accumulate(a.begin(), a.end(), 0LL);
    vector<vector<LL>> dp(n+1, vector<LL>(3));
    for(LL i = 0; i < n; ++i){
        dp[i+1][0] = dp[i][0] + a[i] % 2 + ((a[i]==0)?2:0);
        dp[i+1][1] = dp[i][1] + (a[i]+1) % 2 + ((a[i]==0)?1:0);
        dp[i+1][2] = dp[i][2] + a[i] % 2 + ((a[i]==0)?2:0);
        // start
        dp[i+1][0] = min<LL>(dp[i+1][0], left[i] + a[i] % 2);
        dp[i+1][1] = min<LL>(dp[i+1][1], left[i]);
        // 0 -> 1
        dp[i+1][1] = min<LL>(dp[i+1][1], dp[i][0] + (a[i]+1) % 2 + ((a[i]==0)?1:0));
        // 1 -> 2
        dp[i+1][2] = min<LL>(dp[i+1][2], dp[i][1] + a[i] % 2 + ((a[i]==0)?2:0));

        ans = min<LL>(ans, dp[i+1][0] + right[i+1]);
        ans = min<LL>(ans, dp[i+1][1] + right[i+1]);
        ans = min<LL>(ans, dp[i+1][2] + right[i+1]);
        //cerr << "debug:" << i << ":" << cur << ", " << rest <<", " << ans<< endl;
    }
    return ans;
}

int main(){
    LL n;
    cin >> n;
    vector<LL> a(n);
    for(LL i = 0; i < n; ++i){
        cin >> a[i];
    }
    LL ans = solve(n, a);
    reverse(a.begin(), a.end());
    ans = min<LL>(ans, solve(n, a));
    cout << ans << endl;
    return 0;
}

