int main() {
  ios_base::sync_with_stdio(false);
  cin.tie(nullptr);
  Z L;
  cin >> L;
  vector<Z> as(L);
  cin >> as;
  vector<vector<Z>> dp(L + 1, vector<Z>(5, INF));
  ix(dp, 0).assign(5, 0);
  for (auto i = 0; i < L; i++) {
    Z zero_cost = ix(as, i) == 0 ? 1 : 0;
    ix(dp, i + 1, 0) = min(ix(dp, i + 1, 0), ix(dp, i, 0) + ix(as, i));
    ix(dp, i + 1, 1) = min(ix(dp, i + 1, 1), ix(dp, i, 1) + ix(as, i) % 2 + zero_cost * 2);
    ix(dp, i + 1, 2) = min(ix(dp, i + 1, 2), ix(dp, i, 2) + 1 - ix(as, i) % 2 + zero_cost);
    ix(dp, i + 1, 3) = min(ix(dp, i + 1, 3), ix(dp, i, 3) + ix(as, i) % 2 + zero_cost * 2);
    ix(dp, i + 1, 4) = min(ix(dp, i + 1, 4), ix(dp, i, 4) + ix(as, i));
    for (auto j = 0; j < 4; j++)
      ix(dp, i + 1, j + 1) = min(ix(dp, i + 1, j + 1), ix(dp, i + 1, j));
  }
  dump(dp);
  cout << ix(dp, L, 4) << endl;
}

