int main(){
  cin.tie(0);
  ios::sync_with_stdio(false);

  LLI L;
  while(cin >> L){
    vector<LLI> A(L); cin >> A;

    LLI s = accumulate(ALL(A), 0LL);

    vector<LLI> sum(L+1);
    REP(i,L) sum[i+1] = sum[i] + A[i];

    fill_array(dp,1e9);

    vector<LLI> B(L), C(L);
    REP(i,L){
      if(A[i] == 0){
	B[i] = 1;
	C[i] = 2;
      }else{
	B[i] = (A[i]%2?0:1);
	C[i] = (A[i]%2?1:0);
      }
    }

    dp[0][0] = 1;
    dp[0][1] = dp[0][2] = 2;

    REP(i,L){
      chmin(dp[i+1][0], min({sum[i]+B[i], dp[i][0]+B[i], dp[i][1]+B[i]}));
      chmin(dp[i+1][1], min({sum[i]+C[i], dp[i][1]+C[i]}));
      chmin(dp[i+1][2], min({sum[i]+C[i], dp[i][0]+C[i], dp[i][1]+C[i], dp[i][2]+C[i]}));
      dump(dp[i+1][1]);
    }

    LLI ans = 1e9;
    FORE(i,1,L){
      auto t = min({dp[i][0], dp[i][1], dp[i][2]}) + s-sum[i];
      //dump(t);
      chmin(ans, t);
    }
    cout << ans << endl;
  }

  return 0;
}

