namespace Problem {
using namespace std;
struct RangeMax {
  using T = long long;
  T operator()(const T &a, const T &b) { return max(a, b); }
  static constexpr T id() { return T(-LINF); };
};
struct RangeSet {
  using T = long long;
  T operator()(const T &a, const T &b) { return min(a, b); };
  static constexpr T id() { return T(LINF); };
};

struct Max_Set {
  using V = RangeMax;
  using A = RangeSet;
  V::T operator()(const V::T &a, const A::T &b, const int &h) { return min(a, b); };
};

template <typename M>
struct LazySegmentTree {
  using Val = typename M::V::T;
  using Del = typename M::A::T;
  typename M::V calc;
  typename M::A composite;
  M act;
  vector<Val> val;
  vector<Del> delay;

  int n, height;
  explicit LazySegmentTree(int size) : n(1), height(0) {
    while (n < size) {
      n <<= 1;
      ++height;
    }
    val = vector<Val>(n << 1, calc.id());
    delay = vector<Del>(n << 1, composite.id());
  }
  explicit LazySegmentTree(const vector<Val> &v) : n(1), height(0) {
    while (n < v.size()) {
      n <<= 1;
      ++height;
    }
    val = vector<Val>(n << 1, calc.id());
    delay = vector<Del>(n << 1, composite.id());
    copy(v.begin(), v.end(), val.begin() + n);
    for (int i = n - 1; i > 0; --i) {
      val[i] = calc(val[i * 2], val[i * 2 + 1]);
    }
  }
  void propagate(int k, int h) {
    val[k] = act(val[k], delay[k], h);
    if (h > 0) {
      delay[2 * k] = composite(delay[2 * k], delay[k]);
      delay[2 * k + 1] = composite(delay[2 * k + 1], delay[k]);
    }
    delay[k] = composite.id();
  }
  inline void update(int l, int r, Del v) { update(l, r, v, 1, 0, n, height); }
  void update(int l, int r, Del v, int k, int a, int b, int h) {
    if (l <= a && b <= r) {
      delay[k] = composite(delay[k], v);
      propagate(k, h);
      return;
    }
    propagate(k, h);
    if (b <= l || r <= a) {
      return;
    }  //
    update(l, r, v, 2 * k, a, (a + b) / 2, h - 1);
    update(l, r, v, 2 * k + 1, (a + b) / 2, b, h - 1);
    val[k] = calc(val[2 * k], val[2 * k + 1]);
  }
  inline Val query(int l, int r) { return query(l, r, 1, 0, n, height); }
  Val query(int l, int r, int k, int a, int b, int h) {
    if (b <= l || r <= a) {
      return calc.id();
    }  //
    propagate(k, h);
    if (l <= a && b <= r) {
      return val[k];
    }
    Val vall = query(l, r, 2 * k, a, (a + b) / 2, h - 1);
    Val valr = query(l, r, 2 * k + 1, (a + b) / 2, b, h - 1);
    return calc(vall, valr);
  }
};

class Solver {
 public:
  int n;
  vector<LL> a;
  vector<LL> rEven, r;
  //LazySegmentTree<Max_Set> rEven;
  Solver(LL n) : n(n), a(n), rEven(n + 1), r(n + 1){};

  void solve() {
    LL sum = 0;
    for (int i = 0; i < n; ++i) {
      cin >> a[i];
      sum += a[i];
    }
    LL ans = calc();
    cout << sum - ans << endl;
  }
  LL calc() {
    rEven[n] = 0;
    for (int i = n - 1; i >= 0; --i) {
      LL tmp = rEven[i + 1];
      if (a[i] < 2) {
        tmp -= (2 - a[i]);
      } else {
        tmp += a[i] - (a[i] % 2);
      }
      rEven[i] = max(0ll, tmp);
    }
    DBG(rEven)
    for (int i = n - 1; i >= 0; --i) {
      LL tmp = r[i + 1];
      if (a[i] < 1) {
        tmp -= (1 - a[i]);
      } else {
        tmp += a[i] - ((a[i] + 1) % 2);
      }
      r[i] = max({0ll, tmp, rEven[i]});
    }
    DBG(r)
    for (int i = n - 1; i >= 0; --i) {
      LL tmp = r[i + 1];
      if (a[i] < 2) {
        tmp -= (2 - a[i]);
      } else {
        tmp += a[i] - (a[i] % 2);
      }
      r[i] = max({0ll, tmp, r[i]});
    }
    DBG(r)
    return *max_element(r.begin(), r.end());
  }
};

