const int MAXL = 2e5 + 5;

int L;
ll A[MAXL], dp[MAXL], zero[MAXL];

int main() {
    // setInput("in.txt");
    // setOutput("out.txt");
    // setError("err.txt");
    read(L);
    read(A, A + L);
    FOR(i, L) zero[i] = A[i] == 0;
    ll pre = 0, pre2 = 0, mn = 0;
    dp[0] = 0;
    For(i, 1, L + 1) {
        if (zero[i - 1]) pre += 2;
        pre2 += A[i - 1];
        if (A[i - 1] % 2 == 0) mn++;
        else pre++;
        MIN(pre, pre2);
        MIN(mn, pre);
        dp[i] = mn;
    }
    ll suf = 0, suf2 = 0;
    REV(i, L - 1) {
        if (zero[i]) suf += 2;
        suf2 += A[i];
        if (A[i] % 2 == 1) suf++;
        MIN(suf, suf2);
        dp[i] += suf;
    }
    writeln(*min_element(dp, dp + L + 1));
    return 0;
}

