using namespace std;
typedef long long intl;
intl maximo(intl a,intl b ){
	if(a>b){
		return a;
	}
	return b;
}
using namespace std;
int main(){
	intl n;
	cin>>n;
	vector <intl> v;
	intl totsum=0;
	for(intl i=0;i<n;i++){
		intl a;
		cin>>a;
		v.push_back(a);
		totsum+=a;
	}
	intl maxi=0,current=0;
	bool zero=true;
	for(intl i=0;i<n;i++){

		if(v[i]==0){
			zero=true;
			current--;
		}
		else{
			if(zero){
				zero=false;
				intl aux=i,impar=0,par=0,sump=0,save=0;
				while(aux<n&&v[aux]>0){
				if(v[aux]%2==0){
					par++;
					sump+=v[aux]-1;
				}
				else{
					impar++;
					sump+=v[aux];
					}
					aux++;
					save=maximo(save,par-impar);
				}

				i=aux-1;

				maxi=maximo(maxi,maximo(current+sump,sump+save));
				current=maxi;
			}
		}
	}	
	current=0;
	for(intl i=n-1;i>=0;i--){

		if(v[i]==0){
			zero=true;
			current--;
		}
		else{
			if(zero){
				zero=false;
				intl aux=i,impar=0,par=0,sump=0,save=0;
				while(aux>=0&&v[aux]>0){
				if(v[aux]%2==0){
					par++;
					sump+=v[aux]-1;
				}
				else{
					impar++;

					sump+=v[aux];
					}
					aux--;
					save=maximo(save,par-impar);
				}

				i=aux+1;

				maxi=maximo(maxi,maximo(current+sump,sump+save));
				current=maxi;
			}
		}
	}

	cout<<totsum-maxi<<endl;
}

