	for (i=1 ; i<=n ; i++) {
		scanf("%lld",&a[i]);
		sum += a[i];
	}

	ans = sum;
	for (i=n ; i>=1 ; i--) {
		mem[i][0] = -1;
		mem[i][1] = -1;
		pre[i] = pre[i+1] + a[i];
	}

	ctr = 0;
	for (i=1 ; i<=n ; i++) {
		ans = min(ans,ctr+DP1(i,0));
		ans = min(ans,ctr+DP1(i,1));
		ctr += a[i];
	}

	for (i=1 ; i<=n ; i++) {
		mem[i][0] = -1;
		mem[i][1] = -1;
		pre[i] = pre[i-1] + a[i];
	}

	ctr = 0;
	for (i=n ; i>=1 ; i--) {
		ans = min(ans,ctr+DP2(i,0));	
		ans = min(ans,ctr+DP1(i,1));
		ctr += a[i];
	}

	printf("%lld\n",ans);
}

