ll n;
ll ans = INF;

ll a[MAX_N];
ll pref[MAX_N];

ll ask(int l, int r)
{
    if (r < l)
    {
        return 0;
    }
    return pref[r] - pref[l - 1];
}

ll dpPref[2][MAX_N];
ll dpSuf[2][MAX_N];

ll lastPref[2][MAX_N];
ll lastSuf[2][MAX_N];

int solve()
{
    cin >> n;
    for (int i = 1; i <= n; ++i)
    {
        cin >> a[i];
    }
    pref[0] = 0;
    for (int i = 1; i <= n; ++i)
    {
        pref[i] = pref[i - 1] + a[i];
    }
    ans = pref[n];
    int l = 1;
    int r = n;
    for (int i = 1; i <= n; ++i)
    {
        if (a[i] == 0)
        {
            l = i + 1;
        }
        else
        {
            break;
        }
    }
    for (int i = n; i >= 1; --i)
    {
        if (a[i] == 0)
        {
            r = i - 1;
        }
        else
        {
            break;
        }
    }
    if (r < l)
    {
        cout << ans << '\n';
        return 0;
    }
    dpPref[0][l - 1] = 0;
    for (int i = l; i <= r; ++i)
    {
        dpPref[0][i] = dpPref[0][i - 1];
        if (a[i] == 0)
        {
            dpPref[0][i] += 2;
        }
        else if (a[i] % 2 == 1)
        {
            dpPref[0][i]++;
        }
    }
    dpPref[1][l - 1] = 0;
    lastPref[0][l - 1] = l;
    lastPref[1][l - 1] = l;
    for (int i = l; i <= r; ++i)
    {
        lastPref[0][i] = lastPref[0][i - 1];
        lastPref[1][i] = lastPref[1][i - 1];
        if (a[i] == 0 || a[i] % 2 == 1)
        {
            lastPref[0][i] = i + 1;
        }
        if (a[i] % 2 == 0)
        {
            lastPref[1][i] = i + 1;
        }
        dpPref[1][i] = dpPref[1][i - 1];
        if (a[i] % 2 == 0 && i != l)
        {
            dpPref[1][i]++;
        }
    }
    dpSuf[0][r] = 0;
    for (int i = r - 1; i >= l - 1; --i)
    {
        dpSuf[0][i] = dpSuf[0][i + 1];
        if (a[i + 1] == 0)
        {
            dpSuf[0][i] += 2;
        }
        else if (a[i + 1] % 2 == 1)
        {
            dpSuf[0][i]++;
        }
    }
    dpSuf[1][r] = 0;
    lastSuf[0][r] = r;
    lastSuf[1][r] = r;
    for (int i = r - 1; i >= l - 1; --i)
    {
        if (a[i + 1] == 0 || a[i + 1] % 2 == 1)
        {
            lastSuf[0][i] = i;
        }
        if (a[i + 1] % 2 == 0)
        {
            lastSuf[1][i] = i;
        }
        dpSuf[1][i] = dpSuf[1][i + 1];
        if (a[i + 1] % 2 == 0 && i + 1 != r)
        {
            dpSuf[1][i]++;
        }
    }
    //cerr << dpPref[0][2] << ' ' << dpPref[1][2] << ' ' << dpSuf[0][2] << ' ' << dpSuf[1][2] << '\n';
    for (int i = l - 1; i <= r; ++i)
    {
        ans = min(ans, dpPref[0][i] + dpSuf[0][i]);
        ans = min(ans, dpPref[0][i] + dpSuf[1][i]);
        ans = min(ans, dpPref[1][i] + dpSuf[0][i]);
        ans = min(ans, pref[i] + dpSuf[0][i]);
        ans = min(ans, pref[i] + dpSuf[1][i]);
        ans = min(ans, dpPref[0][i] + ask(i + 1, n));
        ans = min(ans, dpPref[1][i] + ask(i + 1, n));
        if (lastPref[0][i] != i + 1)
        {
            ans = min(ans, ask(1, lastPref[0][i] - 1) + min(dpSuf[0][i], dpSuf[1][i]));
        }
        if (lastPref[1][i] != i + 1)
        {
            ans = min(ans, ask(1, lastPref[1][i] - 1) + dpSuf[0][i]);
        }
        if (lastSuf[0][i] != i)
        {
            ans = min(ans, ask(lastSuf[0][i] + 1, n) + min(dpPref[0][i], dpPref[1][i]));
        }
        if (lastSuf[1][i] != i)
        {
            ans = min(ans, ask(lastSuf[1][i] + 1, n) + dpPref[0][i]);
        }
    }
    cout << ans << '\n';
    return 0;
}

