    cin >> L;
    ll A[L];
    ll even[L], sums[L];
    LREP(i, 0, L){
        cin >> A[i];
        if(i == 0){
            if(A[i] % 2 == 0) even[i] = 1;
            else even[i] = 0;
        }else if(A[i] % 2 == 0){
            even[i] = even[i-1] + 1;
        }else if(A[i] % 2 == 1){
            even[i] = even[i-1];
        }
        if(i == 0) sums[i] = A[i];
        else sums[i] = min(sums[i-1] + A[i], INF);
    }
    ll ans = INF;
    ll tmp_ans;
    LREP(i, 0, L){
        LREPR(j, L - 1, i){
            if(even[j]-even[i] - 2 >= 0) tmp_ans = even[j] - even[i] - 2;
            else if(even[j]-even[i] == 1) tmp_ans = 0;
            else tmp_ans = 1;

            if(i > 0) tmp_ans += sums[i-1];
            if(j + 1 < L) tmp_ans += sums[L-1] - sums[j + 1];
            ans = min(ans, tmp_ans);
        }
    }

    cout << ans + 1 << endl;
}

