inline int isSameWay(const ll *way1, const ll *way2)
{ //同じベクトルか？
    for (int i = 0; i < 4; i++)
    {
        if (way1[i] == way2[i])
        {
            continue;
        }
        return 0;
    }
    return 1;
}
int myfind(const vector<pair<ll *, ll>> &memo, const ll *way)
{ //メモに登録済みか?
    for (auto &&i : memo)
    {
        if (isSameWay(i.first, way) == 1)
        {
            return 1;
        }
    }
    return 0;
}
void solve(const vector<ll> &A, vector<pair<ll *, ll>> &memo, ll *thisWay, const int &L)
{
    if (myfind(memo, thisWay) == 0)
    { //答えを計算して登録して再帰
        ll ans = 0;
        for (ll i = 0; i < thisWay[0]; i++)
        { //0->D
            ans += A[i];
        }
        for (ll i = thisWay[0]; i < thisWay[1]; i++)
        { //D->S
            if (A[i] == 0)
            {
                ans += 2;
            }
            else if (A[i] % 2 == 1)
            {
                ans++;
            }
        }
        for (ll i = thisWay[1]; i < thisWay[2]; i++)
        { //S->T
            if (A[i] % 2 == 0)
            {
                ans++;
            }
        }
        for (ll i = thisWay[2]; i < thisWay[3]; i++)
        { //T->U
            if (A[i] == 0)
            {
                ans += 2;
            }
            else if (A[i] % 2 == 1)
            {
                ans++;
            }
        }
        for (ll i = thisWay[3]; i < L; i++)
        { //U->L
            ans += A[i];
        }
        pair<ll *, ll> tmp;
        tmp.first = thisWay;
        tmp.second = ans;
        memo.push_back(tmp);
        for (int i = 0; i < 3; i++)
        {
            if (thisWay[i] < thisWay[i + 1])
            {
                ll *newWay = (ll *)malloc(sizeof(ll) * 4);
                memcpy(newWay, thisWay, sizeof(ll) * 4);
                newWay[i]++;
                /*
                for (int j = 0; j < 4; j++)
                {
                    cout << newWay[j] << ",";
                }
                cout << endl;
                */
                solve(A, memo, newWay, L);
            }
        }
        if (thisWay[3] < L)
        {
            ll *newWay = (ll *)malloc(sizeof(ll) * 4);
            memcpy(newWay, thisWay, sizeof(ll) * 4);
            newWay[3]++;
            solve(A, memo, newWay, L);
        }
    }
    return;
}
