#include <boost/range/irange.hpp>

using namespace std;
using namespace boost;

main() {
    int64_t l;
    cin >> l;

    vector<int64_t> a(l);
    int64_t sum = 0;
    for (auto&& aa : a) {
        cin >> aa;
        sum += aa;
    }

    int64_t unreached = 0;
    int64_t ended = 0;
    int64_t turned = 0;
    int64_t ans = sum;
    for (auto i : irange(0L, l)) {
        auto is_even = (a[i] % 2 == 0);
        auto next_unreached = min({unreached, ended, turned}) + a[i];
        auto next_ended = ended + (is_even ? 1 : 0);
        auto next_turned = min({ended, turned}) + (is_even ? 0 : 1);

        sum -= a[i];
        auto next_min = min({next_unreached, next_ended, next_turned}) + sum;
        ans = min(ans, next_min);

        unreached = next_unreached;
        ended = next_ended;
        turned = next_turned;
    }

    cout << ans << endl;
}

