typedef long long ll;
using namespace std;
ll L;
ll a[200005];
ll dp[200005][6];
const ll inf = 1e16;
ll solve(ll id, ll st)
{
        if(id == L + 1) {
                if(st == 4) return 0;
                if(st == 2) return 0;
                if(st == 0) return 0;
                return inf;
        }
        if(dp[id][st] != -1) return dp[id][st];
        ll &ret = dp[id][st];
        ret = inf;
        if(a[id] == 0) {
                if(st == 1 || st == 3) return ret = inf;
        }
        if(st == 0) {
                ret = min(ret , solve(id+1,0) + a[id]);
                if(a[id + 1] != 0) {
                        ret = min(ret , solve(id+1, 1) + (a[id]));
                }
        }else if(st == 1) {
                ret = min(ret , solve(id+1,1) + (a[id]%2));
                ret = min(ret , solve(id+1,2) + (a[id]%2));
        }else if(st == 2) {
                ret = min(ret , solve(id+1, 2) + (1 - (a[id]%2)));
                if(a[id+1] != 0)
                ret = min(ret , solve(id+1, 3) + (1 - (a[id]%2)));
        }else if(st == 3) {
                ret = min(ret , solve(id+1,3) + (a[id]%2));
                ret = min(ret , solve(id+1,4) + (a[id]%2));
        }else if(st == 4) ret = min(ret , solve(id+1, 4) + a[id]);
        return ret;
}
int main()
{
        cin >> L;
        a[L+1] = 100000000;
        for(ll i=1;i<=L;i++) {
                cin >> a[i];
        }
        memset(dp,-1,sizeof dp);
        ll ans = solve(1 , 0);
        ans = min(ans , solve(1,1));
        ans = min(ans , solve(1,2));
        ans = min(ans , solve(1,4));
        cout << ans << endl;
        return 0;
}

