int main() {
	int n;
	cin >> n;
	vector<int> a(n);
	rep(i, n) {
		cin >> a[i];
	}
	vector<vector<ll>> dp(n+1);
	rep(i, n+1) {
		dp[i].resize(5);
		rep(j, 5) {
			dp[i][j] = pow(inf,2);
		}
	}
	rep(j, 5) {
		dp[0][j] = 0;
	}
	rep(i, n) {
		rep(j, 5) {
			ll base = inf;
			rep(k, j + 1) {
				base = min(base, dp[i][k]);
			}
			ll add = 0;
			if (j == 0 || j == 4)add = a[i];
			if (j == 1 || j == 3) {
				if (a[i] == 0) add = 2;
				else add=(a[i] % 2 ? 1 : 0);
			}
			if (j == 2) {
				if (a[i] == 0) add = 1;
				else add = (a[i] % 2 ? 0 : 1);
			}
			dp[i + 1][j] = base + add;
		}
	}
	ll ans = pow(inf,2);
	rep(i, 5) {
		ans = min(ans, dp[n][i]);
	}
	cout << ans << endl;
	return 0;
}

