using namespace templates;

int main(){
  int n = in();
  vector<ll> line(n);
  vector<ll> sum(n);
  foreach(i,line)i=in();
  sum[0] = line[0];
  rep(i,n-1){
    sum[i+1]=sum[i]+line[i+1];
  }
  function<ll(int,int)> func1 =
    [&](int place,int back)->ll{
      if(place==n)return 0;
      static vvector<ll> dp(n+1,vector<ll>(2,-1));
      ll &it = dp[place][back];
      if(it>=0)return it;
      it = (sum[n-1]-sum[place]) + ((back and (line[place]&1))?1:0);
      if(line[place]&1){
        chmin(it,1+func1(place+1,true));
      }else{
        chmin(it,max(0LL,2-line[place]) + func1(place+1,true));
      }
      if(!back){
        if(line[place]&1){
          chmin(it,func1(place+1,false));
        }else{
          chmin(it,1+func1(place+1,false));
        }
      }
      return it;
    };
  function<ll(int,int)> func2 =
    [&](int place,int back)->ll{
      if(place==-1)return 0;
      static vvector<ll> dp(n+1,vector<ll>(2,-1));
      ll &it = dp[place][back];
      if(it>=0)return it;
      it = (place?sum[place-1]:0)  + ((back and (line[place]&1))?1:0);
      if(line[place]&1){
        chmin(it,1+func2(place-1,true));
      }else{
        chmin(it,max(0LL,2-line[place]) + func2(place-1,true));
      }
      if(!back){
        if(line[place]&1){
          chmin(it,func2(place-1,false));
        }else{
          chmin(it,1+func2(place-1,false));
        }
      }
      return it;
    };
  ll ans = INFLL;
  rep(i,1,n){
    chmin(ans,func2(i-1,false)+func1(i,false));
  }
  chmin(ans,func1(0,false));
  chmin(ans,func2(n-1,false));
  cout << ans << endl;
  return 0;
}

