class Solve {
public:
    void solve() {
        Int L;
        cin >> L;
        vector<Int> A(L + 1);
        for (int i = 0; i < L; ++i) {
            cin >> A[i + 1];
        }

        vector<vector<Int>> dp(5, vector<Int>(L + 1));

        for (int idx = 1; idx <= L; ++idx) {
            dp[0][idx] = dp[0][idx - 1] + A[idx];

            Int add1 = A[idx] % 2;
            if (A[idx] == 0) add1 = 2;
            dp[1][idx] = min(dp[0][idx - 1], dp[1][idx - 1]) + add1;

            Int add2 = 1 - A[idx] % 2;
            dp[2][idx] = min({dp[1][idx - 1], dp[2][idx - 1]}) + add2;

            dp[3][idx] = min({dp[2][idx - 1], dp[3][idx - 1]}) + add1;

            dp[4][idx] = min({dp[3][idx - 1], dp[4][idx - 1]}) + A[idx];

        }

        Int ans = INFl;
        for (int i = 0; i < 5; ++i) {
            chmin(ans, dp[i][L]);
        }
        cout << ans << endl;

    }

};


