int cost(int a, int b)
{
    if(b == 0 || b == 4)
        return a;
    else if(b == 2)
    {
        if(a== 0 || a % 2 == 0)
            return 1;
        return 0;

    }
    else
    {
        if(a == 0)
            return 2;
        if(a % 2 == 1)
            return 1;
        return 0;
    }
}
main()
{
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    //dp[i][j] - len i, last in group j
    //dp[0][j] = 0 dp[1][j] - can easily fill
    //answer min(dp[n][j])
    //dp[i][j] = min(dp[i][k]) (k <= j) + check
    long long n;
    cin >> n;
    vector<long long> v(n + 1, 0);
    vector<vector<long long> > dp(n + 1, vector<long long>(5, 0));
    for(long long i = 1; i <= n; ++i)
        cin >> v[i];

    for(long long i = 0; i < 5; ++i)
        dp[0][i] = 0;

    dp[1][0] = dp[1][4] = v[1], dp[1][1] = dp[1][3] = (v[1] & 1), dp[1][2] = !(v[1] & 1);

    for(int i = 2; i <= n; ++i)
    {
        for(int j = 0; j < 5; ++j)
        {
            dp[i][j] = dp[i - 1][0] + cost(v[i], 0);
            for(int k = 1; k <= j; ++k)
                dp[i][j] = min(dp[i - 1][k] + cost(v[i], k), dp[i][j] );
        }
    }

    long long answer = INF;
