ll dp[200005][5];   //0 : zero left, 1 : even left, 2 : odd, 3 : even right, 4 : zero right

int main()
{
    int l;
    cin >> l;
    ll a[200005];
    for(int i = 0; i < l; i++) cin >> a[i];
    for(int i = 0; i < l; i++) for(int j = 0; j < 5; j++) dp[i][j] = INF;
    for(int j = 0; j < 5; j++) dp[0][j] = 0;
    for(int i = 1; i <= l; i++){
        dp[i][0] = dp[i - 1][0] + a[i - 1];
        if(a[i - 1] == 0) dp[i][1] = min(dp[i][0], dp[i - 1][1] + 2);
        else dp[i][1] = min(dp[i][0], dp[i - 1][1] + a[i - 1] % 2);
        dp[i][2] = min(dp[i][1], dp[i - 1][2] + (a[i - 1] + 1) % 2);
        if(a[i - 1] == 0) dp[i][3] = min(dp[i][2], dp[i - 1][3] + 2);
        else dp[i][3] = min(dp[i][2], dp[i - 1][3] + a[i - 1] % 2);
        dp[i][4] = min(dp[i][3], dp[i - 1][4] + a[i - 1]);
    }
    cout << dp[l][4] << endl;
}

