inline bool poe(ll val) {
    if (val == 0) {
        return 2;
    } else {
        return val & 1;
    }
}

ll mn (vector<ll> idx,ll i) {
    ll ret = INF;
    for (auto x : idx) {
        ret = min(ret,dp[i][x]);
    }
    return ret;
}
