long long int process(vector<ll>v){
    if(v.size()==0){
        return 0;
    }
    ll val = 0;
    ll curr = 0;
    int state =0;
    vector<ll>p;
    for(int i=0;i<v.size();i++){
        if(state == v[i]%2){
            curr+=v[i];
        }else{
            p.push_back(curr);
            curr = v[i];
            state = v[i]%2;
        }
    }
    p.push_back(curr);
    ll ans = 0;
    for(int i=0;i<p.size();i+=2){
        if(i+1>=p.size()){
            ans = max(ans,v[i]);
        }else if(i+2>=p.size()){
            ans = max(ans,v[i]+v[i+1]);
        }else{
            ans = max(ans,v[i]+v[i+1]+v[i+2]);
        }
    }
    return ans;
}
