void solve(){
    ll n;cin>>n;
    ll arr[n+1];
    for(int i=0;i<n;i++){
        cin>>arr[i+1];
    }
    for(int i=1;i<=n;i++){
        dp[0][i] = dp[0][i-1] + arr[i];
        ll oo = min(dp[1][i-1],dp[0][i-1]);
        if(arr[i]==0){
            dp[1][i] = oo + 2; 
        }else if(arr[i]%2==0){
            dp[1][i] = oo;
        }else{
            dp[1][i] = oo + 1;
        }
        oo = min(oo,dp[2][i-1]);
        if(arr[i]==0){
            dp[2][i] = oo + 1; 
        }else if(arr[i]%2==1){
            dp[2][i] = oo;
        }else{
            dp[2][i] = oo + 1;
        }
        oo = min(oo,dp[3][i-1]);
        if(arr[i]==0){
            dp[3][i] = oo + 2; 
        }else if(arr[i]%2==0){
            dp[3][i] = oo;
        }else{
            dp[3][i] = oo + 1;
        }
        oo = min(oo,dp[4][i-1]);
        dp[4][i] = oo+arr[i];
    }
    ll ans = 1e18;
    for(int j=0;j<5;j++){
        ans = min(ans,dp[j][n]);
    }
