signed main() {
	INIT;

	VAR(int, n);
	VEC(int, a, n);

	FILL(dp, INFLL);
	dp[0][0] = 0;
	REP(i, n) REP(j, 5) {
		if (dp[i][j] >= INFLL) continue;
		if (j == 0) {
			CHMIN(dp[i + 1][0], dp[i][0] + a[i]);
			CHMIN(dp[i + 1][1], dp[i][0] + (a[i] == 0 ? 2LL : a[i] % 2));
			CHMIN(dp[i + 1][2], dp[i][0] + (1 - a[i] % 2));
			CHMIN(dp[i + 1][3], dp[i][0] + (a[i] == 0 ? 2LL : a[i] % 2));
			CHMIN(dp[i + 1][4], dp[i][0] + a[i]);
		}
		else if (j == 1) {
			CHMIN(dp[i + 1][1], dp[i][1] + (a[i] == 0 ? 2LL : a[i] % 2));
			CHMIN(dp[i + 1][2], dp[i][1] + (1 - a[i] % 2));
			CHMIN(dp[i + 1][3], dp[i][1] + (a[i] == 0 ? 2LL : a[i] % 2));
			CHMIN(dp[i + 1][4], dp[i][1] + a[i]);
		}
		else if (j == 2) {
			CHMIN(dp[i + 1][2], dp[i][2] + (1 - a[i] % 2));
			CHMIN(dp[i + 1][3], dp[i][2] + (a[i] == 0 ? 2LL : a[i] % 2));
			CHMIN(dp[i + 1][4], dp[i][2] + a[i]);
		}
		else if (j == 3) {
			CHMIN(dp[i + 1][3], dp[i][3] + (a[i] == 0 ? 2LL : a[i] % 2));
			CHMIN(dp[i + 1][4], dp[i][3] + a[i]);
		}
		else {
			CHMIN(dp[i + 1][4], dp[i][4] + a[i]);
		}
	}
	int ans = INFLL;
	REP(j, 5) CHMIN(ans, dp[n][j]);
	OUT(ans)BR;
	return 0;
}

