vector<LL> getVal(vector<LL> a)
{
	vector<LL> ans(a.size());
	LL poku = 0;
	LL suma = 0 , suma2 = 0;
	for(LL i = 0; i < a.size(); i++)
	{
		poku += a[i];
		if(a[i] == 0)
			suma2 += 2;
		suma2 += a[i] & 1;
		if(poku < suma + suma2)
		{
			ans[i] = poku;
			suma = poku;
			suma2 = 0;
		}
		else
			ans[i] = suma + suma2;
	}
	return ans;
}
vector<LL> getVal2(vector<LL> prev , vector<LL> a)
{
	vector<LL> ans(a.size());
	LL poku = 0;
	LL suma = 0 , suma2 = 0;
	for(LL i = a.size() - 1; i >= 0; i--)
	{
		poku = prev[i];
		suma2 += !(a[i] & 1);
		if(poku < suma + suma2)
		{
			ans[i] = poku;
			suma = poku;
			suma2 = 0;
		}
		else
			ans[i] = suma + suma2;
	}
	return ans;
}
