	dp[1] = getVal(a);	
	reverse(dp[1].begin() , dp[1].end());
	reverse(a.begin() , a.end());
	LL ans = dp[0][n - 1];
	dp2 = getVal2(dp[1] , a);
	for(LL i = 0; i < n; i++)
	{
		if(!i)
		{
			ans = min(ans , dp2[0]);
		}
		else
			ans = min(ans , dp[0][i - 1] + dp2[i]);
	}
	cout << ans;
}

