#define ll long long int

ll const MOD = 1000000007;
ll const INF = (long long int)1 << 61;

int main(){
    cin.tie(0);
    ios::sync_with_stdio(false);

    ll n;
    cin >> n;

    vector<ll> a(n+1,0);
    for(int i = 1; i < n+1; i++){
        cin >> a[i];
    }

    vector<ll> oddf(n+1,0),oddb(n+1,0);
    for(int i = 1; i < n+1; i++){
        oddf[i] = oddf[i-1];
        if(a[i]%2 == 1){
            oddf[i]++;
        }
    }
    oddb[n] = a[n]%2;
    for(int i = n-1; i >= 0; i--){
        oddb[i] = oddb[i+1] + a[i]%2;
    }

    vector<ll> even(n+1,0);
    for(int i = 1; i < n+1; i++){
        even[i] = even[i-1];
        if(a[i]%2 == 0){
            even[i]++;
        }
    }

    vector<ll> sum(n+1,0);
    for(int i = 1; i < n+1; i++){
        sum[i] = a[i] + sum[i-1];
    }

    vector<ll> zero(n+1,0);
    for(int i = 1; i < n+1; i++){
        zero[i] = zero[i-1];
        if(a[i] == 0){
            zero[i]++;
        }
    }

    priority_queue<ll,vector<ll>,greater<ll>> pq,bret;
    priority_queue<pair<ll,ll>,vector<pair<ll,ll>>,greater<pair<ll,ll>>> fret;

    for(int i = 1; i < n; i++){
        fret.push(make_pair(sum[i-1] + (zero[n] - zero[i-1])*2 + oddf[n] - oddf[i-1],(ll)i));
    }
    pq.push(even[n-1]);
    bret.push(zero[n]*2 + oddf[n]);
    ll ans = sum[n] - a[n];
    for(int i = n-1; i > 0; i--){
        while(fret.top().second > i){
            fret.pop();
        }
        ll t = pq.top() - even[i] + fret.top().first - (zero[n] - zero[i])*2 -(oddf[n] - oddf[i]);
        ll t2 = pq.top() - even[i] + sum[i-1];
        if(a[i] > 2 && a[i]%2 == 1){
            t--;
        }
        ans = min(ans,min(t2,t));
        bret.push(zero[i]*2 + oddf[i] + sum[n] - sum[i]);
        pq.push(even[i-1] + bret.top() - zero[i-1]*2 - oddf[i-1] - (a[i] > 2 && a[i]%2 == 1 ? 1 : 0));
        pq.push(sum[n] - sum[i] + even[i-1]);
    }

    cout << ans << endl;

    return 0;
}

