ll solve(const list<ll>& t) {
	auto v = t;
	for (auto& x : v) {
		x %= 2;
	}
	ll max = 0;
	ll tmp = 0;
	ll ans = 0;
	REPC(x, v) {
		tmp += (x) ? -1 : 1;
		ans += x;
		tmp = std::max(ll(0), tmp);
		max = std::max(tmp, max);
	}
	return t.size() - (ans + max);
}

