			++zeroNum;
			point += 2;
		}
	}
	if (zeroNum > 0) {
		VL zeroL;
		zeroL.reserve(zeroNum);
		ll lNum = 0;
		REPC(x, v) {
			if (x == 0) {
				lNum -= 2;
				zeroL.emplace_back(lNum);
			} else {
				lNum += x;
			}
		}
		VL zeroR;
		zeroR.reserve(zeroNum);
		ll rNum = 0;
		RREPI(it, v) {
			if (*it == 0) {
				rNum -= 2;
				zeroR.emplace_back(rNum);
			} else {
				rNum += *it;
			}
		}

		auto lMinItr = std::min_element(ALL(zeroL));
		auto rMinItr = std::min_element(ALL(zeroR));
		if (*lMinItr >= 0 && *rMinItr >= 0) {

		} else if (*lMinItr < 0 && *rMinItr >= 0) {
			point += *lMinItr;
		} else if (*lMinItr >= 0) {
			point += *rMinItr;
		} else {
			ll ln = lMinItr - zeroL.begin();
			ll rn = --zeroR.end() - rMinItr;
			if (ln < rn) {
				point += *lMinItr;
				point += *rMinItr;
			} else {
				ll lminEx = 0;
				REP(i, rn) {
					lminEx = std::min(lminEx, zeroL[i]);
				}
				ll rminEX = 0;
				FOR(i, ln + 1, zeroNum) {
					rminEX = std::min(rminEX, zeroR[i]);
				}
				point += std::min(*rMinItr + lminEx, *lMinItr + rminEX) - 1;
			}
		}
	}

	cout << solve(v) + point << endl;;
}

