  // (3以上の奇数),...,(3以上の奇数),
  // 1,...,1
  // 0,...,0
  vvl DP = VVL(L + 1, 7, llINF);
  REP(i, 7) DP[0][i] = 0;
  REP(i, L) {
    REP(k, 7) {
      if (k <= 0) {
        DP[i + 1][0] = min(DP[i + 1][0], A[i] + DP[i][k]);
      }
      if (k <= 1) {
        DP[i + 1][1] = min(DP[i + 1][1], abs(A[i] - 1) + DP[i][k]);
      }
      if (k <= 2) {
        if (A[i] >= 3) {
          DP[i + 1][2] = min(DP[i + 1][2], ((A[i] + 1) % 2) + DP[i][k]);
        } else {
          DP[i + 1][2] = min(DP[i + 1][2], abs(A[i] - 3) + DP[i][k]);
        }
      }
      if (k <= 3) {
        if (A[i] >= 2) {
          DP[i + 1][3] = min(DP[i + 1][3], (A[i] % 2) + DP[i][k]);
        } else {
          DP[i + 1][3] = min(DP[i + 1][3], abs(A[i] - 2) + DP[i][k]);
        }
      }
      if (k <= 4) {
        if (A[i] >= 3) {
          DP[i + 1][4] = min(DP[i + 1][4], ((A[i] + 1) % 2) + DP[i][k]);
        } else {
          DP[i + 1][4] = min(DP[i + 1][4], abs(A[i] - 3) + DP[i][k]);
        }
      }
      if (k <= 5) {
        DP[i + 1][5] = min(DP[i + 1][5], abs(A[i] - 1) + DP[i][k]);
      }
      if (k <= 6) {
        DP[i + 1][6] = min(DP[i + 1][6], A[i] + DP[i][k]);
      }
    }
  }
  ll ans = llINF;
  REP(i, 7) { ans = min(ans, DP[L][i]); }

  cout << ans << endl;

  return 0;
}

