  if (num == 0) {
    return 0;
  }
  if (num % 2 == 0) {
    --num;
  } else {
    // do nothing
  }
  return num;
}

class Cal {
private:
  ll L;
  vector<ll> A;
  vector<ll> Dp;
  ll ans = 0;
  ll fullNum = 0;

private:
  void Solve();
  void Output() {
    cout << ans << endl;
  }

