#define ll long long
#define N 200010
int n, a[N], b[N];
ll res;

namespace SEG
{
	ll Min[N << 2];
	void init() { memset(Min, 0x3f, sizeof Min); }
	void update(int id, int l, int r, int pos, ll val)
	{
		if (l == r)
		{
			Min[id] = val;
			return;
		}
		int mid = (l + r) >> 1;
		if (pos <= mid) update(id << 1, l, mid, pos, val);
		else update(id << 1 | 1, mid + 1, r, pos, val);
		Min[id] = min(Min[id << 1], Min[id << 1 | 1]);
	}
	ll query(int id, int l, int r, int ql, int qr)
	{
		if (qr < 1 || ql > n) return 0;
		if (l >= ql && r <= qr) return Min[id];
		int mid = (l + r) >> 1;
		ll res = 0;
		if (ql <= mid) res = min(res, query(id << 1, l, mid, ql, qr));
		if (qr > mid) res = min(res, query(id << 1 | 1, mid + 1, r, ql, qr));
		return res;
	}
}

void work()
{
	ll base = 0; 	
	SEG::init();
	for (int i = 1; i <= n; ++i)
	{
		if (a[i] == 0) b[i] = 0;
		else if (a[i] & 1) b[i] = 1;
		else b[i] = 2;
	}
	for (int i = n; i >= 1; --i)   
	{
		base += 2 - b[i];
		SEG::update(1, 1, n, i, a[i] - (2 - b[i]) + SEG::query(1, 1, n, i + 1, i + 1));
	}
	res = min(res, base + SEG::query(1, 1, n, 1, n));
	for (int i = 1; i <= n; ++i)
	{
		base -= 2 - b[i];
		base += 1 - b[i] % 2;
		SEG::update(1, 1, n, i, a[i] - (1 - b[i] % 2) + SEG::query(1, 1, n, i - 1, i - 1));
		res = min(res, base + SEG::query(1, 1, n, i + 1, n) + SEG::query(1, 1, n, 1, i)); 	
	}
}

int main()
{
	while (scanf("%d", &n) != EOF)
	{
		for (int i = 1; i <= n; ++i) 
			scanf("%d", a + i);
		res = 0;
		for (int i = 1; i <= n; ++i) res += a[i];
		work();
		reverse(a + 1, a + 1 + n);
		work();
		printf("%lld\n", res);
	}
	return 0;
}

