ll solve() {
    for (int i = 0; i <= n; i++) {
        for (int j = 0; j < 5; j++) {
            dp[i][j] = INF;
        }
    }

    dp[0][0] = 0;

    for (int i = 0; i < n; i++) {
        for (int j = 0; j < 5; j++) {
            if (j + 1 < 5) {
                dp[i][j + 1] = min(dp[i][j + 1], dp[i][j]);
