    vector<int> x1(l + 1), x2(l + 1);
    x1[l] = 0;
    repr(i, l - 1)
    {
        int tmp = 0;
        if (a[i] % 2 == 0)
            tmp = 1;
        x1[i] = min(c[i], x1[i + 1] + tmp);
        if (a[i] % 2 == 0 && i <= l - 2)
            x1[i] = min(x1[i], c[i + 1]);
    }
    x2[0] = 0;
    Rep(i, 1, l + 1)
    {
        int tmp = 0;
        if (a[i - 1] % 2 == 0)
            tmp = 1;
        x2[i] = min(b[i - 1], x2[i - 1] + tmp);
        if (a[i - 1] % 2 == 0 && i >= 2)
            x2[i] = min(x2[i], b[i - 2]);
    }
    vector<int> y1(l + 1), y2(l + 1);
    y1[l] = 0;
    repr(i, l - 1)
    {
        int tmp = 0;
        if (a[i] % 2 == 1)
            tmp = 1;
        else if (a[i] == 0)
            tmp = 2;
        y1[i] = min(c[i], y1[i + 1] + tmp);
    }
    y2[0] = 0;
    Rep(i, 1, l + 1)
    {
        int tmp = 0;
        if (a[i - 1] % 2 == 1)
            tmp = 1;
        else if (a[i - 1] == 0)
            tmp = 2;
        y2[i] = min(b[i - 1], y2[i - 1] + tmp);
    }
    int ans = INF;
    rep(i, l + 1)
    {
        ans = min(min(ans, y1[i] + y2[i]), min(x1[i] + y2[i], x2[i] + y1[i]));
    }
    cout << ans << endl;
}

