const int maxn = 2e5 + 5;
int n, p[maxn];

LL t[maxn], st[maxn], g[maxn];

int main() {
  ios::sync_with_stdio(false);
  cin >> n;
  rep(i, n) cin >> p[i];


  LL res = maxn;

  rep(_, 2) {
    LL sum = 0;
    rep(i, n) {
      sum += p[i];
    }

    t[0] = sum;
    rep(i, n) {
      t[i + 1] = t[i] + (p[i] == 0 ? 2 : p[i] % 2) - p[i];
    }

    st[n] = t[n];
    drep(i, n, 0) {
      st[i] = min(t[i], st[i + 1]);
    }

    LL ds = 0, dm = 0, dq = 0; 

    g[0] = 0;
    rep(i, 0, n) {
      ds += (p[i] == 0 ? 2 : p[i] % 2);
      dm += (1 - p[i] % 2);
      dq += p[i];
      smin(dm, dq);
      g[i + 1] = ds - dm;
    }

    rep(i, 1, n + 1) {
      smax(g[i + 1], g[i]);
    }

    rep(i, 0, n + 1) {
      smin(res, st[i] - g[i]);
    }

    reverse(p, p + n);
  }

  cout << res << endl;


  return 0;
}

