long long REV_C[MAX_L], REV_L[MAX_L], REV_R[MAX_L];
long long ARB_L[MAX_L], ARB_R[MAX_L];


int main(int argc, char **argv) {
    std::cin >> L;

    for (int i = 1; i <= L; i++) {
        std::cin >> A[i];
    }

