        AC_L[i] = AC_L[i-1] + A[i];
        REV_L[i] = std::min(AC_L[i], REV_C[i] + REV_L[i-1]);
        ARB_L[i] = std::min(REV_L[i], ARB_L[i-1] + 1 - (A[i] % 2) );
    }

    for (int i = L; 1 <= i; i--) {
        AC_R[i] = AC_R[i+1] + A[i];
        REV_R[i] = std::min(AC_R[i], REV_C[i] + REV_R[i+1]);
        ARB_R[i] = std::min(REV_R[i], ARB_R[i+1] + 1 - (A[i] % 2) );
    }

    long long ret = AC_L[L];
    for (int i = 0; i <= L; i++) {
        ret = std::min(ret, ARB_L[i] + ARB_R[i+1]);
    }

    std::cout << ret << std::endl;

    return 0;
}

