ll A[300100];
ll Z[300100];
ll C[300100];
ll SUM[300100];

int main(){
    ll L;
    cin >> L;
    ll sum = 0;
    REP(i, L){
        ll a;
        cin >> a;
        A[i] = a;
        sum += a;
        if(i == 0) {
            SUM[0] = a;
            continue;
        }
        Z[i] = Z[i-1] + (a==0);
        SUM[i] = SUM[i-1] + a;
    }

    bool last;
    C[0] = 0;
    for(int i = 0; i < L; i++){
        ll a = A[i];
        if(i != 0){
            bool x = a%2;
            //printf("%d, %d, x&last:%d\n", x, last, x&&last);
            if((x == last) == false){
                C[i] = C[i-1] + 1;
            }
            else
                C[i] = C[i-1];
        }
        last = a%2;
    }

    int left = 0;
    int right = L;
    ll ans = sum;
    ll num = ans;
    bool even = true;
    int lidx = L;
    for(int left = L-1; left >= 0; left--){
        ll a = A[left]; 
        num -= a;
        bool e = false;

        if(a == 0){
            num++;
            even = false;
        }
        else if(a%2 == 0){
            if(even){
                continue;
            }
            else{
                e = true;
            }
        }
        else{
            even = false;
        }

        if(num < ans){
            ans = num;
            lidx = left;
        }
        if(e) num++;
    }

   // printf("ans:%lld, lidx:%d\n", ans, lidx);

    left = lidx;
    bool all_even = true;
    for(int i = left; i < right; i++){
        ll a = A[i];
        if(a%2){
            all_even = false;
            break;
        }
    }

    int ridx = L;
    num = ans;
    even = true;
    for(int right = L-1; right >= 0; right--){
        ll a = A[right]; 
        num += a;
        if(a == 0) num--;

        bool e = false;
        if(!all_even && right-1 >= left && A[right-1] % 2 == 0){
            num--;
        }

        if(num < ans){
            ans = num;
            ridx = right;
        }
    }

    //printf("lidx:%d, ridx:%d\n", lidx, ridx);

    ll c = C[ridx-1] - C[lidx];
    ll cc = (c-1)/2;
    ll z = Z[ridx-1] - Z[lidx];
    cc += z*2;
    //cout << cc << endl;
    cc += (SUM[L-1] - SUM[ridx-1]);

    if(lidx > 0) cc += SUM[lidx-1];

    ans = min(ans, cc);
    //printf("ans:%lld, cc:%lld\n", ans, c);

    cout << ans << endl;
    return 0;
}

