	for (int i = left; i < right; ++i) {
		if (a[i] == 0) { odd++; }
		tmp += a[i];
		if (a[i] % 2 == 1) odd++;
	}

	ans = tmp - max(0ll, odd - 2);
	dump(sum - ans);
}

