            dp[i + 1][1] = min1 - (A[i] - (A[i] + 1) % 2);
        } else {
            dp[i + 1][1] = min1 + 1;
        }
        ll min0 = dp[i][0];
        if (A[i] >= 2) {
            dp[i + 1][0] = min(min0 - (A[i] - A[i] % 2), sum);
        } else if (A[i] == 1) {
            dp[i + 1][0] = min(min0, sum);
        } else {
            dp[i + 1][0] = min(min0 + 2, sum);
        }
    }
    ll ans = inf;
    REP(i, 0, 4) {
        ans = min(ans, dp[L][i]);
    }
    // REP(i, 0, 3) {
    //     REP(j, 0, L + 1) {
    //         cout << dp[j][i] << " ";
    //     }
