void upd(int &x, int y) { x = min(x, y); }

void solve()    {
    FOR(i, 0, n) FOR(j, 0, 4) dp[i][j] = oo;
    dp[0][0] = 0;
    FOR(i, 1, n)    {
        // j = 0
        dp[i][0] = dp[i - 1][0] + a[i];
        // j = 1
        dp[i][1] = dp[i - 1][0] + a[i];
        upd(dp[i][1], dp[i - 1][1] + ((a[i] % 2) ? 1 : 0));
        upd(dp[i][1], dp[i][0]);
        //j = 2
        dp[i][2] = dp[i - 1][1] + ((a[i] % 2) ? 1 : 0);
        upd(dp[i][2], dp[i - 1][2]+ ((a[i] % 2) ? 0 : 1));
        upd(dp[i][2], dp[i][1]);
        // j = 3
        dp[i][3] = dp[i - 1][2] + ((a[i] % 2) ? 0 : 1);
        upd(dp[i][3], dp[i - 1][3] + ((a[i] % 2) ? 1 : 0));
        upd(dp[i][3], dp[i][2]);
