        dp[i][4] = dp[i - 1][3] + ((a[i] % 2) ? 1 : 0);
        upd(dp[i][4], dp[i - 1][4] + a[i]);
        upd(dp[i][4], dp[i][3]);
    }

    upd(ans, dp[n][4]);
}

