int main() {
	int n; scanf("%d", &n); std::vector<i64> a(n);
	for(int i = 0; i < n; i++) {
		scanf("%lld", &a[i]);
	}
	std::vector<i64> b(n);
	for(int i = 0; i < n; i++) {
		b[i] = a[i];
		if(a[i] == 0) continue;
		else if(a[i] % 2 == 1) a[i] = 1;
		else a[i] = 2;
	}

	std::vector<i64> A(n), B(n);
	for(int i = 0; i < n; i++) A[i] = std::abs(a[i] - 1);
	for(int i = 0; i < n; i++) B[i] = std::abs(a[i] - 2);
	std::vector<std::vector<i64>> dp(n + 1, std::vector<i64>(3, 1LL << 60));
	i64 tmp = 0;
	for(int i = 0; i < n; i++) {
		dp[i + 1][0] = std::min({dp[i][0], tmp}) + B[i];
		dp[i + 1][1] = std::min({dp[i][0], dp[i][1], tmp}) + A[i];
		dp[i + 1][2] = std::min({dp[i][1], dp[i][2], tmp}) + B[i];
		tmp += b[i];
	}
	i64 sum = 0, ans = 1LL << 60;
	for(int i = n - 1; i >= 0; i--) {
		ans = std::min({ans, dp[i + 1][0] + sum, dp[i + 1][1] + sum, dp[i + 1][2] + sum});
		sum += b[i];
	}
	printf("%lld\n", ans);
	return 0;
}

