int main() {
	int l;	cin >> l;
	vint a(l);	cin >> a;
	vll cost(l + 1);
	ll ad = 0;
	int lastUse = l;
	// 0 to 0
	rrep(i, l) {
		if (a[i] == 0 && ad < 2) {
			lastUse = i;
			ad = 0;
			continue;
		}
		if (a[i] == 0) {
			cost[0] += 2;
			ad -= 2;
		}
		else {
			ad += max(0, a[i] - (a[i] & 1));
			cost[0] += a[i] & 1;
		}
	}
	// 0 to i
	SREP(i, 1, l) {
		if (a[i - 1] == 0 && i <= lastUse) {
			cost[i] = cost[i - 1] - 1;
		}
		else	cost[i] = (a[i - 1] & 1 ? cost[i - 1] - 1 : cost[i - 1] + 1);
	}
	ll change = 0;
	map<ll, set<int>> mp;
	REP(i, l) {
		mp[cost[i]].insert(i);
	}
	ll ret = inf;
	ad = 0;
	REP(i, l) {
		ret = min(ret, mp.begin()->first + change);
		if (i < l) {
			ad += a[i] - (a[i] & 1);
			if (a[i] == 0) {
				if (ad < 2) {
					change += ad;
					ad = 0;
				}
