    }
    f3[0] = 0;
    for (int i = 1; i <= n; i++)
    {
        f3[i] = f3[i - 1] + (ll)((a[i - 1] % 2) == 0);
        f3[i] = min(f3[i], f2[i]);
    }
    ll ans = INF;
    for (int i = 0; i <= n; i++)
        ans = min(ans, f3[i] + f1[i]);
    cout << ans;
    return 0;
}

