int a[N],b[N];
void Solve(int n, ll ans[2][N])
{
	int l=1,l2=1;
	ll bal=0,sum=0,b1=0,b2=0,as=0,s1=0,as1=0;
	for(int i=1;i<=n;i++)
	{
		bal+=2-a[i];
		b1+=2-a[i];
		sum+=b[i];
		s1+=b[i];
		if(a[i]==0) b2--;
		else if(a[i]==1) b2--;
		else if(a[i]==2) b2++;
		if(b2>0) b2=0;
		//printf("%lld %lld %lld %lld\n",b1,b2,s1,as1);
		if(b1+b2-s1>0) b1=b2=0,l2=i+1,as1+=s1,s1=0;
		if(bal-sum>0) l=i+1,bal=0,as+=sum,sum=0;
		if(l>i) ans[0][i]=as;
		else ans[0][i]=bal+as;
		if(l2>i) ans[1][i]=min(as1,as);
		else ans[1][i]=min(bal+as,b1+b2+as1);
	}
}
