	reverse(a+1,a+1+n);
	reverse(b+1,b+1+n);
	Solve(n,r);
	reverse(r[0]+1,r[0]+1+n);
	reverse(r[1]+1,r[1]+1+n);
	ll ans=inf;
	for(i=0;i<=n;i++)
	{
		ans=min(ans,l[0][i]+r[1][i+1]);
		ans=min(ans,l[1][i]+r[0][i+1]);
	}
	//for(i=1;i<=n;i++) printf("l[0][%i]:%lld l[1][%i]:%lld\n",i,l[0][i],i,l[1][i]);
	//for(i=1;i<=n;i++) printf("r[0][%i]:%lld r[1][%i]:%lld\n",i,r[0][i],i,r[1][i]);
