int main() {
	ll L;
	cin >> L;
	vector<ll> As(L);
	rep(i,0,L) {
		cin >> As[i];
	}
	vector<ll> zeros(L+1);
	vector<ll> evens(L+1);
	vector<ll> odds(L+1);
	vector<ll> sums(L+1);
	rep(n,1,L+1) {
		zeros[n] = zeros[n-1] + (As[n-1] == 0);
		evens[n] = evens[n-1] + (As[n-1] > 0 && As[n-1] % 2 == 0);
		odds[n] = odds[n-1] + (As[n-1] > 0 && As[n-1] % 2 == 1);
		sums[n] = sums[n-1] + As[n-1];
	}
	vector<ll> odd_loss(L+1);
	vector<ll> even_loss(L+1);
	rep(i,0,L+1) {
		odd_loss[i] = zeros[i] + evens[i];
		even_loss[i] = 2*zeros[i] + odds[i];
	}
	vector<ll> min_even_loss_right(L+1);
	min_even_loss_right[L] = even_loss[L];
	rrep(i,L,0) {
		min_even_loss_right[i] = min(min_even_loss_right[i+1], even_loss[i] + sums[L] - sums[i]);
	}
	rep(i,0,L+1) {
		min_even_loss_right[i] -= even_loss[i];
	}
	vector<ll> min_even_loss_left(L+1);
	min_even_loss_left[0] = even_loss[L];
	rep(i,1,L+1) {
		min_even_loss_left[i] = min(min_even_loss_left[i-1], even_loss[L] - even_loss[i] + sums[i]);
	}
	rep(i,0,L+1) {
		min_even_loss_left[i] -= (even_loss[L] - even_loss[i]);
	}
	vector<ll> right_loss(L+1);
	rep(i,0,L+1) {
		right_loss[i] = odd_loss[i] + min_even_loss_right[i];
	}
	vector<ll> right_loss_min(L+2, numeric_limits<ll>::max()); // これいるか？
	rrep(i,L+1,0) { 
		right_loss_min[i] = min(right_loss_min[i+1], right_loss[i]);
	}
	rep(i,0,L+1) { 
		right_loss_min[i] -= odd_loss[i];
	}
	ll loss = numeric_limits<ll>::max();
	rep(i,0,L) {
		ll loss_loc = 0;
		loss_loc += min_even_loss_left[i];
		loss_loc += right_loss_min[i];
		loss = min(loss, loss_loc);
	}
	cout << loss << endl;
}

