	dp[0][1]=0;//inside included
	dp[0][2]=0;//begin
	dp[0][3]=INT_MAX;//b/w mid and end
	dp[0][4]=INT_MAX;
	REP(i,1,n)
	{
		dp[i][0]=(dp[i-1][0]+inp[i]);
		dp[i][1]=MIN((dp[i-1][0]+inp[i]),((dp[i-1][1]+((inp[i]==0)?2:(inp[i]%2)) )));
