                //if(a[id + 1] != 0) {
                        ret = min(ret , solve(id+1, 1) + (a[id]));
                //}
                ret = min(ret , solve(id+1 , 2) + a[id]);
                ret = min(ret , solve(id+1 , 3) + a[id]);

        }else if(st == 1) {
                ret = min(ret , solve(id+1,1) + (a[id]%2) + 2*(a[id] == 0));
                ret = min(ret , solve(id+1,2) + (a[id]%2) + 2*(a[id] == 0));
