using namespace std;


#define Seg_Max_N (1<<20) 

using Value =long long int;
const Value ini =1e18;
struct segtree {
	int N;
	vector<Value>dat;

	segtree() {}
	segtree(int n) :dat(2 * Seg_Max_N) {
		N = 1;
		while (N < n) N *= 2;
		for (int i = 0; i < 2 * N - 1; i++) {
			dat[i] = ini;
		}
	}
	Value connect(const Value&l, const Value&r) {
		return min(l,r);
	}
	// update k th element
	void update(int k, Value a) {
		k += N - 1;
		dat[k] = a;

		while (k > 0) {
			k = (k - 1) / 2;
			const Value al(dat[k * 2 + 1]);
			const Value ar(dat[k * 2 + 2]);
			dat[k] = connect(al, ar);
		}
	}
	// min [a, b)
	Value  query(int a, int b) { return query(a, b, 0, 0, N); }
	Value  query(int a, int b, int k, int l, int r) {
		if (r <= a or b <= l) return ini;
		if (a <= l and r <= b) return dat[k];
		const int m = (l + r) / 2;
		const Value al(query(a, b, k * 2 + 1, l, m));
		const Value ar(query(a, b, k * 2 + 2, m, r));
		return connect(al, ar);
	}
};
int main() {
	int N;cin>>N;
	vector<long long int>v(N);
	for(int i=0;i<N;++i)cin>>v[i];

	vector<long long int>l_memo(N+1),r_memo(N+1);
	l_memo[0]=0;
	{
		long long int sum = 0;
		for (int i = 0; i < N; ++i) {
			sum += v[i];
			l_memo[i + 1] = min(sum, l_memo[i] + (v[i] % 2)+(v[i]==0?2:0));
		}
	}
	r_memo[N]=0;
	{
		long long int sum=0;
		for (int i = N - 1; i >= 0; --i) {
			sum+=v[i];
			r_memo[i]=min(sum,r_memo[i+1]+(v[i]%2) + (v[i] == 0 ? 2 : 0));
		}
	}
	long long int answer=1e18;

	segtree seg(N+1);

	long long int odd_num=0;
	vector<long long int>even_nums(N+1);
	for (int i = 0; i < N; ++i) {
		even_nums[i+1]=even_nums[i]+((1+v[i])%2);
	}
	for (int i = 0; i <= N; ++i) {
		seg.update(i,even_nums[i]+r_memo[i]);
	}

	long long int odd_cnt=0;
	for (int l = 0; l <= N; ++l) {
		long long int nanswer=l_memo[l];
		nanswer+=seg.query(l,N+1);
		nanswer-=odd_cnt;

		answer=min(answer,nanswer);

		if(l!=N&&v[l]%2==0)odd_cnt++;
	}

	cout<<answer<<endl;
	return 0;
}

