#define mod 1000000007 //1e9+7(prime number)
#define INF 1000000000 //1e9
#define LLINF 2000000000000000000LL //2e18
#define SIZE 200010


ll eL[SIZE], eR[SIZE], eL2[SIZE], eR2[SIZE];

int main(){
  int L;
  ll a[SIZE];


  scanf("%d", &L);

  for(int i=0;i<L;i++) scanf("%lld", a+i);

  for(int i=0;i<L;i++){
    eL2[i] += a[i]%2 == 0;
    eL2[i+1] += eL2[i];
  }

  for(int i=0;i<L;i++){
    eR2[i] = eL2[L] - eL2[i-1];
  }

  ll p = 0, q = 0, r1 = 0, r2 = 0;
  for(int i=0;i<L;i++){
    if (a[i] == 0) {
      q += 2;
      if (r1 < q + p) {
        r2 += r1;
        r1 = 0;
        q = p = 0;
      }
    } else {
      p += a[i] % 2;
      r1 += a[i];
    }
    eL[i+1] = p + q + r2;
  }

  p = 0, q = 0, r1 = 0, r2 = 0;
  for(int i=0;i<L;i++){
    if (a[L-i-1] == 0) {
      q += 2;
      if (r1 < q) {
        r2 += r1;
        r1 = 0;
        q = 0;
      }
    } else {
      p += a[L-i-1] % 2;
      r1 += a[L-i-1];
    }
    eR[L-i-1] = p + q + r2;
  }

  for(int i=0;i<L;i++) eL[i+1] -= eL2[i];
  for(int i=0;i<L;i++) eR[i] -= eR2[i];

  eR[L] = eL2[L];
  for(int i=L-1;i>=0;i--){
    eR[i] = min(eR[i]+eL2[L], eR[i+1]);
  }

  ll ans = LLINF;

  for(int i=0;i<=L;i++){
    ans = min(ans, eL[i] + eR[i]);
  }

  cout << ans << endl;

  return 0;
}

