ll ineven(ll a)
{
    if (a == 0LL) return 2LL;
    return ((a & 1LL) ? 1LL : 0LL);
}

ll inodd(ll a)
{
    if (a == 0LL) return 1LL;
    return ((a & 1LL) ? 0LL : 1LL);
}

int _main()
{
    ll ears; llin(ears);
    V<ll> alist; llinl1(alist, ears);

    ll init = 0LL;
    ll l_even = 0LL;
    ll odd = 0LL;
    ll r_even = 0LL;
    ll done = 0LL;

    for (auto a : alist) {
        ll init_new = init + a;

        ll l_even_new = init + ineven(a);
        l_even_new = min(l_even_new, l_even + ineven(a));

        ll odd_new = init + inodd(a);
        odd_new = min(odd_new, l_even + inodd(a));
        odd_new = min(odd_new, odd + inodd(a));

        ll r_even_new = init + ineven(a);
        r_even_new = min(r_even_new, l_even + ineven(a));
        r_even_new = min(r_even_new, odd + ineven(a));
        r_even_new = min(r_even_new, r_even + ineven(a));

        ll done_new = init + a;
        done_new = min(done_new, l_even + a);
        done_new = min(done_new, odd + a);
        done_new = min(done_new, r_even + a);
        done_new = min(done_new, done + a);

        init = init_new;
        l_even = l_even_new;
        odd = odd_new;
        r_even = r_even_new;
        done = done_new;
    }

    cout << min({init, l_even, odd, r_even, done}) << endl;

    return 0;
}

