	int n;
	scanf("%d", &n);
	for (int i = 0; i < n; i++) scanf("%d", &ans[i]);
	int bg = -1, en = -2;
	long long sum = 0;
	vector<long long> sz, ee;
	for (int i=0; i<n; i++)
		if (ans[i] > 0) {
			if (bg < 0) bg = i;
			en = i;
			sum += ans[i];
		}
		else {
			if (bg <= en) {
				ee.push_back(calc(bg, en));
				sz.push_back(sum);
			}
			bg = -1; en = -2; sum = 0;
		}
	if (bg <= en) {
		ee.push_back(calc(bg, en));
		sz.push_back(sum);
	}

	sum = 0;
	for (int i = 0; i < (int)sz.size(); i++) sum += sz[i];

	long long mn = 1000000000000000000LL;
	for (int i = 0; i < (int)sz.size(); i++)
		mn = min(mn, sum - ee[i]);
	cout << mn;
	return 0;
}

