            ans=min(ans, pre[last]+nxt[i]+solve2(last+1, i-1));
            f=min(f+c[i]-c[last], pre[last]+solve3(last+1, i-1));
            f++;
            last=i;
        }
    }
    printf("%lld\n", ans);
    return 0;
}

