const ll INF = 1001001001001001LL;
const ll MOD = 1000000007LL;

// idx, (未処理、偶数左、奇数、偶数右)
const int VARI = 5;
int dp[200010][VARI];
signed main() {
    int N; cin >> N;
    vector<int> v(N);
    for(int i=0; i<N; i++) {
        cin >> v[i];
    }

    // DP
    const int M1 = 0;
    const int M2 = 1;
    const int E1 = 2;
    const int E2 = 3;
    const int O  = 4;
    fill(dp[0], dp[N+1], INF);
    for(int i=0; i<VARI; i++) dp[0][i] = 0;
    for(int i=0; i<N; i++) {
        /*
        vector<string> vs = {"M1", "M2", "E1", "E2", "O "};
        for(int k=0; k<VARI; k++) {
            fprintf(stderr, "dp[%lld][%s] = %lld\n", i, vs[k].c_str(), dp[i][k]);
        }
        */

        // 未処理左 (未処理左につづく)
        chmin(dp[i+1][M1], dp[i][M1] + v[i]);

        // 偶数左 (偶数左か未処理左につづく)
        int cost1 = (v[i] == 0 ? 2 : (v[i] % 2));
        chmin(dp[i+1][E1], min(dp[i][E1], dp[i][M1]) + cost1);

        // 偶数右 (奇数か偶数右につづく)
        int cost2 = (v[i] == 0 ? 2 : (v[i] % 2));
        chmin(dp[i+1][E2], min(dp[i][O], dp[i][E2]) + cost2);

        // 奇数 (偶数左か奇数か未処理左につづく)
        int cost3 = 1 - (v[i] % 2);
        int mi = min({dp[i][E1], dp[i][O], dp[i][M1]});
        chmin(dp[i+1][O], mi + cost3);

        // 未処理右 (未処理左以外のすべてにつづく)
        int mi2 = min({dp[i][E1], dp[i][E2], dp[i][O], dp[i][M2]});
        chmin(dp[i+1][M2], mi2 + v[i]);
    }

    int ans = INF;
    for(int i=0; i<VARI; i++) {
        chmin(ans, dp[N][i]);
    }
    cout << ans << endl;
    return 0;
}

