using namespace std;

using ll = long long;

ll Solve() {
    ll l;
    cin >> l;

    vector<ll> a(l + 1);
    for (int i = 1; i <= l; ++i) cin >> a[i];

    constexpr int N = 5;
    vector<vector<ll>> dp(l + 1, vector<ll>(N, 1e11));
    dp[0][0] = dp[0][1] = 0;

    for (int i = 1; i <= l; ++i) {
        dp[i][0] = dp[i - 1][0] + a[i];
        dp[i][1] = min(dp[i - 1][0], dp[i - 1][1])
            + (a[i] == 0 ? 2 : (a[i] % 2 == 1));
        dp[i][2] = min({dp[i - 1][0], dp[i - 1][1], dp[i - 1][2]})
            + (a[i] == 0 ? 1 : (a[i] % 2 == 0));
        dp[i][3] = min({dp[i - 1][0], dp[i - 1][1], dp[i - 1][2], dp[i - 1][3]})
            + (a[i] == 0 ? 2 : (a[i] % 2 == 1));
        dp[i][4] = min({dp[i - 1][0], dp[i - 1][1], dp[i - 1][2],
                    dp[i - 1][3], dp[i - 1][4]}) + a[i];
    }

    return min({dp[l][0], dp[l][1], dp[l][2], dp[l][3], dp[l][4]});
}

int main() {
    cin.tie(0); ios::sync_with_stdio(false);

    cout << Solve() << endl;

    return 0;
}

