  rep(i,1,L) cin >> A[i];
  int l = 1;
  int r = L;
  while(l <= L && A[l] == 0) l++;
  while(r >= 1 && A[r] == 0) r--;
  if(l > r) {
    cout << 0 << endl;
    return 0;
  }
  l = 1;
  r = L;
  {
    i64 sum = 0;
    rep(i,l,r) {
      i64 x = A[i] & 1;
      if(A[i] == 0) x = 2;
      sum += A[i];
      eel[i] = min(eel[i - 1] + x, sum);
    }
  }
  {
    i64 sum = 0;
    rep(i,l,r) {
      i64 x = A[i] & 1;
      x = x ^ 1;
      sum += A[i];
      ool[i] = min(ool[i - 1] + x, sum);
    }
  }
  {
    i64 sum = 0;
    for(int i = r;i >= l;i--) {
      i64 x = A[i] & 1;
      if(A[i] == 0) x = 2;
      sum += A[i];
      eer[i] = min(eer[i + 1] + x, sum);
    }
  }
  {
    i64 sum = 0;
    for(int i = r;i >= l;i--){
