long A[200001];
long DP[5*200001];
void Calc(){
	int N = rei();
	for(int i=1;i<=N;i++){
		A[i] = rel();
	}
	for(int i=0;i<5*N+5;i++){
		DP[i] = 100000000000000;
	}
	DP[0] = 0;
	for(int i=1;i<=N;i++){
		DP[i*5] = DP[i*5-5] + A[i];
		DP[i*5+4] = min({DP[i*5-5],DP[i*5-5+1],DP[i*5-5+2],DP[i*5-5+3],DP[i*5-5+4]}) + A[i];
		if(A[i] >= 2){
			DP[i*5+1] = min(DP[i*5-5],DP[i*5-5+1]) + A[i] % 2;
			DP[i*5+3] = min({DP[i*5-5],DP[i*5-5+1],DP[i*5-5+2],DP[i*5-5+3]}) + A[i] % 2;
		}
		if(A[i] >= 1){
			DP[i*5+2] = min({DP[i*5-5],DP[i*5-5+1],DP[i*5-5+2]}) + (A[i] - 1) % 2;
		}
	}
	cout << min({DP[N*5],DP[N*5+1],DP[N*5+2],DP[N*5+3],DP[N*5+4]}) << endl;
}
