const ll INF = 1LL << 60;

ll cost(int i, int s, const vector<ll> &A) {
  if (s == 0)
    return A[i];
  else if (s == 4)
    return A[i];
  else if (s == 1 || s == 3) {
    if (A[i] % 2 == 0 && A[i] > 0)
      return 0;
    else if (A[i] > 0)
      return 1;
    else
      return 2;
  } else {
    if (A[i] % 2 == 0)
      return 1;
    else
      return 0;
  }
}

int main() {
  ios::sync_with_stdio(false);
  cin.tie(0);
  int L;
  cin >> L;
  vector<vector<ll>> dp(510000, vector<ll>(5, INF));
  vector<ll> A(L);
  for (int i = 0; i < L; i++)
    cin >> A[i];
  dp[0][0] = 0;
  for (int i = 0; i < L; i++) {
    for (int j = 0; j < 5; j++) {
      for (int k = j; k < 5; k++) {
        dp[i + 1][k] = min(dp[i + 1][k], dp[i][j] + cost(i, k, A));
      }
    }
  }
  ll res = INF;
  for (int i = 0; i < 5; i++)
    res = min(res, dp[L][i]);
  cout << res << '\n';
  return 0;
}

