ll solve(vector<vector<ll> > &data) {
  ll ans = 1LL << 62;
  int size = data.size();
  vector<ll> rem(size, 0);
  vector<ll> cand(size, 0);
  ll remsum = 0;
  REP(i, data.size()) {
    //        cout << i << ":" ;
    REP(j, data[i].size()) {
      //      cout << data[i][j] << " ";
      rem[i] += data[i][j];
    }
    //        cout << endl;
    remsum += rem[i];
  }
  REP(i, data.size()) {
    int oddcnt = 0, evencnt = 0;
    data[i].push_back(0LL);
    vector<bool> work(data[i].size());
    REP(j, data[i].size()) {
      ll v = 0;
      if(j == 0) { v = data[i][0]; }
      else { v = data[i][j] + data[i][j-1]; }
      work[j] = v % 2LL == 0LL;
      if(work[j]) evencnt++;
      else oddcnt++;
    }
    cand[i] = remsum - rem[i];
    //    cout << i << ":" << evencnt << " " << oddcnt << " " << cand[i] << endl;
    ll tmp = 0;
    if(oddcnt == 1) tmp = 1;
    else if(oddcnt > 2) {
      for(int j = 1; j < work.size(); j++) {
	if(work[j-1] == false && work[j] == false) {
	  work[j-1] = true; work[j] = true;
	  tmp++;
	  oddcnt -= 2;
	  if(oddcnt <= 2) break;
	}
      }
      tmp += (oddcnt - 1) / 2;
    }
    cand[i] += tmp;
    ans = min(ans, cand[i]);
    //    cout << i << " " << tmp << " " << cand[i] << " " << ans << endl;
  }
  return ans;
}

