    {
        //cout << i << ":" << LE[i] << ":" << LO[i] << ":" << RE[i] << ":" << RO[i] << endl;
        //! 右に行ってから左に行く
        ll m0 = RE[i] + std::min(LE[i], LO[i]);
        min = std::min(min, m0);
        //! 左に行ってから右に行く
        ll m1 = LE[i] + std::min(RE[i], RO[i]);
        min = std::min(min, m1);
    }
