using namespace std;

int main(void){
    int L;
    cin >> L;
    vector<long long> A(L);
    for(int i = 0; i < L; i++) cin >> A[i];

    vector<long long> LO(L + 1), LR(L + 1), RO(L + 1), RR(L + 1), S(L + 1);

    LO[0] = 0;
    LR[0] = 0;
    S[0] = 0;
    for(int i = 1; i <= L; i++){
        long long a = A[i - 1];
        S[i] = S[i - 1] + a;
        LO[i] = min((a + 1) % 2 + LO[i - 1], (a == 0 ? 1 : 0) + LR[i - 1]);
        if(a == 0){
            LR[i] = min(S[i], 2 + LR[i - 1]);
        }else{
            LR[i] = a % 2 + LR[i - 1];
        }
    }

    RO[L] = 0;
    RR[L] = 0;
    S[L] = 0;
    for(int i = L - 1; i >= 0; i--){
        S[i] = S[i + 1] + A[i];
        RO[i] = min((A[i] + 1) % 2 + RO[i + 1], (A[i] == 0 ? 1 : 0) + RR[i + 1]);
        if(A[i] == 0){
            RR[i] = min(S[i], 2 + RR[i + 1]);
        }else{
            RR[i] = A[i] % 2 + RR[i + 1];
        }
    }

    long long ans = LLONG_MAX;
    for(int i = 0; i <= L; i++) ans = min(ans, min(LO[i] + RR[i], LR[i] + RO[i]));
    cout << ans << endl;
    return 0;
}

