const ll INF = 1e18;
const int N = 2e5 + 5;
ll dp[N][5], a[N];
int n;

ll solve() {
    for (int i = 0; i <= n; i++) {
        for (int j = 0; j < 5; j++) {
            dp[i][j] = INF;
        }
    }

    dp[0][0] = 0;

    for (int i = 0; i < n; i++) {
        for (int j = 0; j < 5; j++) {
            if (j + 1 < 5) {
                dp[i][j + 1] = min(dp[i][j + 1], dp[i][j]);
            }

            ll w = a[i];

            if (j == 1 || j == 3) {
                w = a[i] - 2;
                if (w > 0)
                    w &= 1;
                else
                    w = -w;
            }
            else if (j == 2) {
                w = a[i] - 1;
                if (w > 0)
                    w &= 1;
                else
                    w = -w;
            }

            dp[i + 1][j] = min(dp[i + 1][j], dp[i][j] + w);
        }
    }

    ll ans = INF;
    for (int i = 0; i < 5; i++)
        ans = min(ans, dp[n][i]);
    return ans;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    cin >> n;

    for (int i = 0; i < n; i++) {
        cin >> a[i];
    }

    ll ans = solve();

    cout << ans << "\n";

    return 0;
}

