ll sum[3][200010];

// TLE

ll calc(int a, int b, int c, int d)
{
  ll ans = 0;
  ans += sum[0][a] - sum[0][0];
  ans += sum[1][b] - sum[1][a];
  ans += sum[2][c] - sum[2][b];
  ans += sum[1][d] - sum[1][c];
  ans += sum[0][L] - sum[0][d];
  return ans;
}

int main()
{
  cin >> L;
  ll mini = 0;
  for (auto i = 0; i < L; i++)
  {
    cin >> A[i];
    mini += A[i];
  }
