  for (auto i = 0; i < L; i++)
  {
    if (A[i] > 0)
    {
      zero = false;
      break;
    }
  }
  if (zero)
  {
    cout << 0 << endl;
    return 0;
  }
  for (auto i = 0; i < L; i++)
  {
    if (A[i] == 0)
    {
      B[i] = 2;
    }
    else if (A[i] % 2 == 0)
    {
      B[i] = 0;
    }
    else
    {
      B[i] = 1;
    }
  }
  for (auto i = 0; i < L; i++)
  {
    if (A[i] % 2 == 1)
    {
      C[i] = 0;
    }
    else
    {
      C[i] = 1;
    }
  }
  sum[0][0] = sum[0][1] = sum[0][2] = 0;
  for (auto i = 0; i < L; i++)
  {
    sum[0][i + 1] = sum[0][i] + A[i];
    sum[1][i + 1] = sum[1][i] + B[i];
    sum[2][i + 1] = sum[2][i] + C[i];
  }
  for (auto a = 0; a <= L; a++)
  {
    for (auto b = a; b <= L; b++)
    {
      for (auto c = b; c <= L; c++)
      {
        for (auto d = c; d <= L; d++)
        {
          ll t = calc(a, b, c, d);
          mini = min(mini, t);
          // cerr << "calc(" << a << ", " << b << ", " << c << ", " << d << ") = " << t << endl;
        }
      }
    }
  }
  cout << mini << endl;
