const ll mod = 998244353;

ll add(ll a, ll b) {
	a += b;
	if(a >= mod) return a - mod;
	return a;
}

ll mul(ll a, ll b) {
	a *= b;
	if(a >= mod) return a % mod;
	return a;
}

ll power(ll a, ll b) {
	if(b == 0) return 1;
	ll p = 1;
	while(b) {
		if(b&1) p = mul(p, a);
		a = mul(a, a);
		b /= 2;
	}
	return p;
}

const int N = 2e5 + 5;

int n;
ll a[N];
ll sum[N];
ll dp[N][5];

ll memo(int idx, int st) {

	if(idx == n+1) {
		return 0;
	}

	if(dp[idx][st] != -1) return dp[idx][st];
	ll res = 1e18;
	if(st == 0) {
		res = min(res, memo(idx+1, st) + a[idx]);
		res = min(res, memo(idx, 1));
	}
	else if(st == 1) {
		if(a[idx] > 0) res = min(res, memo(idx+1, st) + (a[idx]%2));
		else res = min(res, memo(idx+1, st) + 2);
		res = min(res, memo(idx, 2));
	}
	else if(st == 2) {
		res = min(res, memo(idx+1, st) + (a[idx]%2 == 0));
		res = min(res, memo(idx, 3));
	}
	else if(st == 3) {
		if(a[idx] > 0) res = min(res, memo(idx+1, st) + (a[idx]%2));
		else res = min(res, memo(idx+1, st) + 2);
		res = min(res, memo(idx, 4));
	}
	else {
		res = min(res, memo(idx+1, st) + a[idx]);
	}
return dp[idx][st] = res;

}

