    sum[i + 1] = sum[i] + E[i];
  }
  for (int i = 0; i < N; i ++) {
    if (E[i] != 0) {
      bac[i + 1] = bac[i] + (E[i] % 2);
    } else {
      bac[i + 1] = min(bac[i] + 2, sum[i + 1]);
    }
  }
  ll fro[200002];
  fro[N] = 0;
  for (int i = N - 1; i >= 0; i --) {
    if (E[i] != 0) {
      fro[i] = fro[i + 1] + (E[i] % 2);
    } else {
      fro[i] = min(fro[i + 1] + 2, sum[N] - sum[i]);
    }
  }
  ll odd[200002];
  odd[0] = 0;
  for (int i = 0; i < N; i ++) {
    odd[i + 1] = odd[i] + 1ll - (E[i] % 2);
  }
  int r = 0;
