        m2+=sr[rz]-sr[0];
        chmin(res,m2);
    }
    ll m2 = 0;
    m2+=se[n-rz]-se[lz];
    m2+=(sz[n-rz]-se[lz])*1;
    m2+=sl[lz]-sl[0];
    m2+=sr[rz]-sr[0];
    chmin(res,m2);
    m2 = 0;
    m2+=so[n-rz]-so[lz];
    m2+=(sz[n-rz]-sz[lz])*2;
    m2+=sl[lz]-sl[0];
    m2+=sr[rz]-sr[0];
    chmin(res,m2);

    put(res);
    return 0;
}

