void solve(){
	LL i,x;
	for(i=1;i<=n;i++){
		t[i][0]=max({0LL,t[i-1][0],t[i-1][1]})+(V[i]%2?V[i]:V[i]-1);
		if(V[i]==0)	x=-2;
		else if(V[i]==1)	x=0;
