    } else {
      s1[i] = 1;
      s2[i] = !arr[i] ? 2 : 0;
    }
  }
  partial_sum(s0.begin(), s0.end(), s0.begin());
  partial_sum(s1.begin(), s1.end(), s1.begin());
  partial_sum(s2.begin(), s2.end(), s2.begin());
  ll cur = 0, ans = s0[n - 1];
  for (int i = 0; i < n; i++) {
    ans = min(ans, s0[n - 1] - s0[i] + s2[i] + cur);
