int32_t main() {
  ios::sync_with_stdio(0);
  cin.tie(0);
  cout.tie(0);

  read(n);
  rep(i, 1, n + 1) {
    cin >> a[i];
    z[i] = z[i - 1] + ((~a[i]) & 1);
  }

  int sum = 0;
  rep(i, 1, n + 1) {
    sum += a[i];
    if (!a[i])
      L[i] = min(L[i - 1] + 2, sum);
    else
      L[i] = min((a[i] & 1) + L[i - 1], sum);
  }

  sum = 0;
  for (int i = n; i; i--) {
    sum += a[i];
    if (!a[i])
      R[i] = min(R[i + 1] + 2, sum);
    else
      R[i] = min((a[i] & 1) + R[i + 1], sum);
  }

  int best = z[n];

  int local = 0;
  rep(i, 1, n + 1) {
    smin(local, L[i] - z[i]);
    smin(best, R[i + 1] + z[i] + local);
  }

  write(best);

  return 0;
}

