  vector<int> best_left(L + 1), best_right(L + 1, L);
  for(int s = 1; s <= L; s++){
    if(A_sum[best_left[s - 1]] + (A_turn_sum[s] - A_turn_sum[best_left[s - 1]]) <= A_sum[s]){
              best_left[s] = best_left[s - 1];      
    }else{
      best_left[s] = s;
    }
  }
  for(int e = L - 1; e >= 0; e--){
    if((A_sum[L] - A_sum[best_right[e + 1]]) + (A_turn_sum[best_right[e + 1]] - A_turn_sum[e]) <= (A_sum[L] - A_sum[e])){
      best_right[e] = best_right[e + 1];
    }else{
      best_right[e] = e;
    }
  }
  /*
  for(int i = 0; i <= L; i++){
    cout << "i: " << i << ", best_left: " << best_left[i] << ", best_right: " << best_right[i] << endl;
  }
  */

  long long ans = 1e18;
  int best_end = L;
  for(int s = L; s >= 0; s--){
    long long best_end_cost =
      A_sum[best_left[s]] +
      (A_turn_sum[s] - A_turn_sum[best_left[s]]) +
      (A_go_sum[best_end] - A_go_sum[s]) +
      (A_turn_sum[best_right[best_end]] - A_turn_sum[best_end]) +
      (A_sum[L] - A_sum[best_right[best_end]]);
    long long start_end_equal_cost =
      A_sum[best_left[s]] +
      (A_turn_sum[best_right[s]] - A_turn_sum[best_left[s]]) +
      (A_sum[L] - A_sum[best_right[s]]);
    if(start_end_equal_cost <= best_end_cost){
      best_end = s;
    }
    //cout << "start: " << s << ", cost: " << min(start_end_equal_cost, best_end_cost) << endl;
    //cout << start_end_equal_cost << endl;
    //cout << best_end << ", " << best_end_cost << endl;
    ans = min(ans, min(start_end_equal_cost, best_end_cost));
  }
  cout << ans << endl;
}

