ll a[nn];ll n;
ll pre1[nn];ll pre2[nn];ll bas=0;
ll smax,smin;ll s[nn];ll ans=0;ll d[nn];
ll extra[nn];ll pre3[nn];
void solve()
{
	pre1[0]=pre2[0]=pre3[0]=0;
	for(int i=1;i<=n;i++)
	{	
		if(a[i]%2==0 and a[i]>0) pre1[i]=pre1[i-1]+1;
		else pre1[i]=pre1[i-1]-1;

		pre2[i]=pre2[i-1]+a[i];
		if(a[i]%2==0) pre2[i]--;

		pre3[i]=pre3[i-1]+a[i];
		if(a[i]%2==1) pre3[i]--;
		else if(a[i]==0) pre3[i]-=2; 
	}
	smin=pre2[n];
	for(ll i=n;i>=0;i--)
	{
		ans=max(ans,smin-pre2[i]);
		smin=max(smin,pre2[i]);
	}
	pre2[n+1]=-1e17;
	for(int i=n;i>=1;i--) d[i]=pre1[i-1]+pre2[i-1],pre2[i]=max(pre2[i],pre2[i+1]);
	for(int i=1;i<=n;i++)
		s[i]=pre1[i]+pre2[i];
	smax=s[n];d[0]=0;
	ll now=pre3[0];
	for(int i=1;i<=n;i++)
	{
		now=min(now,pre3[i]);
		extra[i]=pre3[i]-now;
	}
	for(ll i=n;i>=1;i--)
	{
		smax=max(smax,s[i]);
		ans=max(smax-d[i]+extra[i-1],ans);
	//	if(smax-d[i]+extra[i-1]==bas-2) cout<<i<<"\n";
	}
}
