const int N = 2e5+5;

int n,a[N];
long long dp[N][2][3],suf[N];

long long rec(int pos, int now, int change){
	if (pos == n){
		return ((!change || (change == 1 && now)) ? 0 :
		(now != (a[pos] & 1)));
	}
	long long &ret = dp[pos][now][change];
	if (ret != -1){
		return ret;
	}
	ret = min(suf[pos], (now != (a[pos] & 1)) +
	((!now && !a[pos]) ? 2 : 0) + rec(pos+1, now, change));
	if (!change || (change == 1 && now)){
		ret = min(ret, (!now != (a[pos] & 1)) +
		((now && !a[pos]) ? 2 : 0) +
		rec(pos+1, !now, change + 1));
	}
	return ret;
}

