int arr[MAX+5],n;
ll dp[MAX+5][5];

ll solve(int pos,int seg)
{
    if(pos==n+1)
        return 0;
    ll&ret=dp[pos][seg];
    if(ret!=-1)
        return ret;
    if(seg==0)  //[0,M]
    {
        ret=solve(pos+1,1)+arr[pos];
        ret=min(ret,solve(pos+1,0)+arr[pos]);
        ret=min(ret,solve(pos+1,2)+arr[pos]%2);
        ret=min(ret,solve(pos+1,3)+arr[pos]%2);
        ret=min(ret,solve(pos+1,4)+arr[pos]%2);
    }
    else if(seg==1) // [M+1,S]
    {
        ret=solve(pos+1,1)+arr[pos]%2;
        ret=min(ret,solve(pos+1,2)+arr[pos]%2);
        ret=min(ret,solve(pos+1,3)+arr[pos]%2);
        ret=min(ret,solve(pos+1,4)+arr[pos]%2);
    }
    else if(seg==2) // [S+1,D]
    {
        ret=solve(pos+1,2)+!(arr[pos]%2);
        ret=min(ret,solve(pos+1,3)+!(arr[pos]%2));
        ret=min(ret,solve(pos+1,4)+!(arr[pos]%2));
    }
    else if(seg==3) // [D+1,M]
    {
        ret=solve(pos+1,3)+arr[pos]%2;
        ret=min(ret,solve(pos+1,4)+arr[pos]%2);
    }
    else // [M+1,L]
        ret=solve(pos+1,4)+arr[pos];
    return ret;
}
