const int MAXN = 1000001;

int gcd(int a, int b) { return b ? gcd(b, a%b) : a; }

int n;
lli A[MAXN];
lli num[MAXN];
lli memo[MAXN][4];
bool vis[MAXN][4];

lli sum(int i,int j) {
	return num[j] - (i ? num[i - 1] : 0);
}

lli go(lli a, int f) {
	if(!a && f == 1) return 2;
	return a % 2 == f;
}

lli DP(int id,int f) {
	if(id == n) return 0;
	if(vis[id][f]) return memo[id][f];
	vis[id][f] = 1;
	lli ans = 1LL<<60;
	if(f == 0) ans = min(min(DP(id + 1, 1) + go(sum(id, id), 1), DP(id + 1, 2) + go(sum(id, id), 0)), DP(id + 1, 0) + sum(id, id));
	if(f == 1) ans = min(DP(id + 1, 1) + go(sum(id, id), 1), DP(id + 1, 2) + go(sum(id, id), 0));
	if(f == 2) ans = min(DP(id + 1, 2) + go(sum(id, id), 0), DP(id + 1, 3) + go(sum(id, id), 1));
	if(f == 3) ans = DP(id + 1, 3) + go(sum(id, id), 1);
	ans = min(ans, sum(id, n - 1));
	return memo[id][f] = ans;
}

