using namespace std;

const int N = 200 * 1000 + 17;
const int MOD = 1000 * 1000 * 1000 + 7;

int n;
int a[N];
long long dp[N][5];

bool read() {
    if (!(cin >> n))
        return false;

    for (int i = 1; i <= n; ++i)
        cin >> a[i];

    return true;
}

long long calc(int i, int f) {
    if (f == 0 || f == 4)
        return a[i];

    if (f == 2)
        return 1 ^ (a[i] & 1);

    return a[i] == 0 ? 2 : (a[i] & 1);
}

void solve() {
    for (int i = 1; i <= n; ++i) {
        for (int j = 0; j < 5; ++j) {
            dp[i][j] = static_cast<long long>(MOD) * MOD;

            for (int k = 0; k <= j; ++k)
                dp[i][j] = min(dp[i][j], dp[i - 1][k] + calc(i, j));
        }
    }

    auto ans = dp[n][0];

    for (int i = 1; i < 5; ++i)
        ans = min(ans, dp[n][i]);

    cout << ans << endl;
}

int32_t main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    while (read())
        solve();

    return 0;
}

