	ll L;
	cin >> L;
	vector<ll> a(L);
	vector<ll> imos(L + 1);
	for (int i = 0;i < L;i++) {
		cin >> a[i];
		imos[i + 1] = a[i] + imos[i];
	}
	vector<ll> dp(L + 1, INF);
	dp[0] = 0;
	for (int i = 0;i < L;i++) {
		ll nowcost = a[i] % 2;
		if (a[i] == 0)
			nowcost = 2;
		dp[i + 1] = min(imos[i] + nowcost, dp[i] + nowcost);
	}
	vector<ll> ar(L);
	imos.assign(L + 1, 0);
	for (int i = 0;i < L;i++) {
		ar[i] = a[L - 1 - i];
		imos[i + 1] = ar[i] + imos[i];
	}
	vector<ll> dpr(L + 1, INF);
	dpr[0] = 0;
	for (int i = 0;i < L;i++) {
		ll nowcost = ar[i] % 2;
		if (ar[i] == 0)
			nowcost = 2;
		dpr[i + 1] = min(imos[i] + nowcost, dpr[i] + nowcost);
	}
	vector<ll> base(L+1, 0);
	for (int i = 0;i < L;i++) {
		if (a[i] % 2 == 0 || a[i] == 0)
			base[i + 1] = 1;
		base[i + 1] += base[i];
	}
	vector<ll> bestr(L+1);
	for (int i = 1;i <= L;i++) {
		bestr[L-i] = min(bestr[L-i+1], dpr[i] - (base[L] - base[L - i]));
	}
	ll bestl = 0;
	ll ans = INF;
	for (int i = 0;i <= L;i++) {
		bestl = dp[i] - base[i];
		ll rb = bestr[i];
		ans = min(ans, bestl + rb + base[L]);
	}
	cout << ans << endl;
	return 0;
}

