const int nn = 2e5+5;
int a[nn], dp[nn][10];

void robin(){
    int n;
    cin >> n;
    for(int i = 1; i <= n; i++) cin >> a[i];

    // D   S  T   U    or   D  T   S   U  (editorial)    => 5 states for any point i
    // dp[i][j] : min no. of operation upto point i, if point i is in jth state
    // states : ... ->  D, D -> S,  S -> T (vice versa),  T -> U, U -> ...

    dp[0][0] = 0;
    for(int i = 0; i < n; i++){
        for(int j = 0; j < 5; j++){

            if(j > 0) dp[i][j] = min(dp[i][j], dp[i][j-1]);
            int here = 0;
            if(j == 0 || j == 4) here = a[i+1];
            else if(j == 2){
                here = (a[i+1] % 2 ? 0 : 1);
            }
            else{
                here = (a[i+1] % 2);
                if(! a[i+1]) here = 2;                  // ---->       // as it lies in the even range, so we have to remove 2 that will be generated
                                                       //  <----
            }                                         // any distance(a[i]) can be traversed for an ear by running b/w two consecutive points i-1 to i

            dp[i+1][j] =  dp[i][j] + here;
        }
    }

    int ans = 1e18;
    for(int j = 0; j < 5; j++) ans = min(ans, dp[n][j]);
    cout << ans;
}

