int n;
vi a;
ll dp[5][222222];

ll solve(int st, int p)
{
	if (dp[st][p] >= 0) return dp[st][p];
	if (p == n) return 0;
	ll res = 1e9;
	if (st == 0)
	{
		chmin(res, solve(0, p + 1) + a[p]);
	}
	if (st <= 1)
	{
		if(a[p] == 0) chmin(res, solve(1, p + 1) + 2);
		else chmin(res, solve(1, p + 1) + a[p] % 2);
	}
	if (st <= 2)
	{
		if (a[p] == 0) chmin(res, solve(2, p + 1) + 1);
		chmin(res, solve(2, p + 1) + (1 - a[p] % 2));
	}
	if (st <= 3)
	{
		if(a[p] == 0) chmin(res, solve(3, p + 1) + 2);
		else chmin(res, solve(3, p + 1) + a[p] % 2);
	}
	if (st <= 4)
	{
		chmin(res, solve(4, p + 1) + a[p]);
	}
	return dp[st][p] = res;
}

