constexpr ll TEN(int n) { return (n == 0) ? 1 : 10 * TEN(n - 1); }
template <class T> using V = vector<T>;
template <class T> using VV = V<V<T>>;


ll solve(V<ll> a) {
    ll sm = 0;
    for (auto d: a) sm += d / 2 * 2;
    ll mi = 0, nw = 0, ma = 0;
    for (auto d: a) {
        if (d % 2) nw++;
        else nw--;
        mi = min(mi, nw);
        ma = max(ma, nw - mi);
    }
    return sm + ma;
}

int main() {
    int n;
    cin >> n;
    V<ll> a(n);
    ll sm = 0;
    for (int i = 0; i < n; i++) {
        cin >> a[i];
        sm += a[i];
    }

    ll ma = 0;
    int l = 0;
    while (l < n) {
        if (a[l] == 0) {
            l++;
            continue;
        }
        V<ll> b;
        int r = l;
        while (r < n && a[r]) {
            b.push_back(a[r]);
            r++;
        }
        l = r;
        ma = max(ma, solve(b));
    }
    cout << sm - ma << endl;
    return 0;
}

