  cin.tie(nullptr);
  std::ios::sync_with_stdio(false);
  int l;
  cin>>l;
  vector<lint> a(l),odd(l),even(l),cum(l);
  for(int i=0;i<l;i++){
    cin>>a[i];
    if(a[i]==0){
      odd[i]=1;
      even[i]=2;
    }else{
      odd[i]=(a[i]%2==0)?1:0;
      even[i]=(a[i]%2==0)?0:1;
    }
    cum[i]=a[i];
    if(i!=0){
      cum[i]+=cum[i-1];
    }

  }
  const lint INF=INT64_MAX-10;
  vector2d<lint> dp(l,vector<lint>(5,INF));
  dp[0][0]=a[0];
  dp[0][1]=even[0];
  dp[0][2]=odd[0];
  for(int i=1;i<l;i++){
    dp[i][0]=dp[i-1][0]+a[i];
    dp[i][1]=min(dp[i-1][0],dp[i-1][1])+even[i];
    dp[i][2]=min({dp[i-1][0],dp[i-1][1],dp[i-1][2]})+odd[i];
    dp[i][3]=min(dp[i-1][2],dp[i-1][3])+even[i];
  }
  lint result=min({dp[l-1][0],dp[l-1][1],dp[l-1][2],dp[l-1][3],dp[l-1][4]});
  for(int i=1;i<l;i++){
    for(int j=0;j<4;j++){
      if(dp[i-1][j]==INF) continue;
      lint tmp_result=dp[i-1][j]+cum[l-1]-cum[i-1];
      UpdateMin(result,tmp_result);
    }
  }
  cout<<result<<endl;

  return 0;
}

