#include <bits/stdc++.h>
using namespace std;

int main() {
    int l; cin >> l;
    vector<long long> a(l), prev(l), post(l);
    long long all = 0;
    for (int i = 0; i < l; i++) {
        cin >> a[i];
        prev[i] = a[i];
        if (i > 0) prev[i] += prev[i-1];
    }
    for (int i = l-1; i >= 0; i--) {
        post[i] = a[i];
        if (i < l-1) post[i] += post[i+1];
    }
    vector<long long> dp(l+1, 0), dp2(l+1, 0);
    long long one = 0; long long pp = 0;
    for (int i = 0; i < l; i++) {
        if (i == 0) {
            dp[i] = 0;
            dp2[i] = 0;
        } else {
            if (a[i] % 2 == 1) one++;
            if (a[i] < 2) one = 0, pp = i;  
            dp[i] = dp[i-1] + (a[i] % 2 == 0);
            dp[i] = min(dp[i], prev[i-1]);
            dp2[i] = dp[pp] + one; 
        }
    }
    long long ans = 1e18;
    for (int i = 0; i < l; i++) {
        if (i == 0) {
            ans = min(ans, post[i+1]);
        } else if (i < l-1) {
            ans = min(ans, dp[i] - (a[i] % 2 == 0) + post[i+1]);
            ans = min(ans, dp2[i] - (a[i] % 2 == 0) + post[i+1]);
        } else {
            ans = min(ans, dp[i] - (a[i] % 2 == 0));
            ans = min(ans, dp2[i]);
        }
    }
    cout << ans << endl;
    return 0;
}

