typedef long long ll;
#define rep(i,a) for(int i=0;i<(a);i++)
const ll MOD=1000000007;

ll A[202020];
int sumE[202020],sumO[202020];

int main(){
  int L; cin>>L;
  for(int i=1;i<=L;i++){
    cin>>A[i];
  }
  int l=1,r=L;
  for(int i=1;i<=L;i++){
    if(A[i]==0) l++;
    else break;
  }
  for(int i=L;i>=l;i--){
    if(A[i]==0) r--;
    else break;
  }
  if(l==r){
    cout<<0<<endl;
    return 0;
  }

  int cnt=0;
  while(l<r){
    if(A[l+1]==0) l=l+2,cnt++;
    else break;
  }
  while(l<r){
    if(A[r-1]==0){r=r-2;cnt++;}
    else break;
  }

  int Z=0;
  for(int i=l;i<=r;i++){
    sumE[i]=sumE[i-1]+(A[i]%2==0);
    sumO[i]=sumO[i-1]+(A[i]%2);
    Z+=(A[i]==0);
  }

  int ans=min(sumE[r],sumO[r]);

  for(int i=l;i<r;i++){
    int tmp=sumE[i]+(sumO[r]-sumO[i])+Z;
    tmp=min(tmp,sumO[i]+(sumE[r]-sumE[i])+Z);
    ans=min(ans,tmp);
  }

  cout<<ans+cnt<<endl;
  return 0;
}

#include "bits/stdc++.h"
#define in std::cin
#define out std::cout
#define rep(i,N) for(LL i=0;i<N;++i)
typedef long long int LL;

const LL inf = 11234567890123456;
LL L;
std::vector<LL>A, A_imosL, A_imosR, memoR1, memoR2, memoL1, memoL2;

// 右へ行ったまま
LL dpR1(LL i)
{
	if (i == L) return 0;
	if (memoR1[i] != -1) return memoR1[i];
	LL res1 = dpR1(i + 1) + (A[i] % 2 == 0 ? 1 : 0);
	LL res2 = A_imosR[L] - A_imosR[i];
	return memoR1[i] = std::min(res1, res2);
}

// 右へ行って戻る
LL dpR2(LL i)
{
	if (i == L) return 0;
	if (memoR2[i] != -1) return memoR2[i];
	LL res1 = dpR2(i + 1) + (A[i] % 2 == 1 ? 1 : 0) + (A[i] == 0 ? 2 : 0);
	LL res2 = A_imosR[L] - A_imosR[i];
	return memoR2[i] = std::min(res1, res2);
}

// 左へ行ったまま
LL dpL1(LL i)
{
	if (i == 0) return 0;
	if (memoL1[i] != -1) return memoL1[i];
	LL res1 = dpL1(i - 1) + (A[i - 1] % 2 == 0 ? 1 : 0);
	LL res2 = A_imosL[0] - A_imosL[i];
	return memoL1[i] = std::min(res1, res2);
}

// 左へ行って戻る
LL dpL2(LL i)
{
	if (i == 0) return 0;
	if (memoL2[i] != -1) return memoL2[i];
	LL res1 = dpL2(i - 1) + (A[i - 1] % 2 == 1 ? 1 : 0) + (A[i - 1] == 0 ? 2 : 0);
	LL res2 = A_imosL[0] - A_imosL[i];
	return memoL2[i] = std::min(res1, res2);
}

int main()
{
	in >> L;
	A.resize(L);
	rep(i, L) in >> A[i];

	A_imosL.resize(L + 1); A_imosR.resize(L + 1);
	rep(i, L) A_imosR[i + 1] = A_imosR[i] + A[i];
	for (LL i = L - 1; i >= 0; --i) A_imosL[i] = A_imosL[i + 1] + A[i];

	memoR1.resize(L + 1, -1); memoR2.resize(L + 1, -1); memoL1.resize(L + 1, -1); memoL2.resize(L + 1, -1);
	LL ans = inf;
	for (LL i = 0; i <= L; ++i)
	{
		LL res1 = dpL1(i) + dpR2(i), res2 = dpL2(i) + dpR1(i);
		ans = std::min(ans, std::min(res1, res2));
	}
	out << ans << std::endl;
}

