  int N;
  cin >> N;
  VL xs(N);
  cin >> xs;

  fill((LL*)dp, (LL*)dp+200010*5, INF);
  dp[0][0] = 0;

  REP(i,N){
    LL x = xs[i];
    LL b = x % 2;
    LL be = b ^ 1;

    if(x == 0){
      b = 2;
      be = 1;
    }

    dp[i+1][0] = dp[i][0] + x;
    dp[i+1][1] = min(dp[i][0] + b, dp[i][1] + b);
    dp[i+1][2] = min({dp[i][0] + be, dp[i][1] + be, dp[i][2] + be});
    dp[i+1][3] = min({dp[i][2] + b, dp[i][3] + b});
    dp[i+1][4] = min({dp[i][1] + x, dp[i][2] + x, dp[i][3] + x, dp[i][4] + x});
  }
//DEBUG(dp[N][0], dp[N][2], dp[N][3], dp[N][4] );

  cout << min({dp[N][0], dp[N][1], dp[N][2], dp[N][3], dp[N][4] }) << endl;

