  for(int i=1;i<=n;i++){
    rl[i]=rl[i-1]+a[i-1];
  }
  for(int i=n-1;i>=0;i--){
    rr[i]=rr[i+1]+a[i];
  }
  vector<LL> gl(n+1,LINF),gr(n+2,LINF);
  gl[0]=0;
  for(int i=1;i<=n;i++){
