using namespace std;

pair<long, int> left(long long a[], int l){
    long long cum_cost = 0;
    for(int i=0;i<l;i++){
        cum_cost += a[i];
        if(i<l-1 && a[i+1]==0){
            int z = 0;
            for(int j=i+1;j<l;j++){
                if(a[j]==0){
                    z++;
                }else{
                    if(cum_cost<z){
                        return make_pair(cum_cost, j);
                    }else{
                        return make_pair(z, j);
                    }
                }
            }
        }else{
            return make_pair(0,0);
        }
    }
}

pair<long, int> right(long long a[],int l){
    long long cum_cost = 0;
    for(int i=l-1;i>=0;i--){
        cum_cost += a[i];
        if(i>0 && a[i-1]==0){
            int z = 0;
            for(int j=i-1;j>=0;j--){
                if(a[j]==0){
                    z++;
                }else{
                    if(cum_cost<z){
                        return make_pair(cum_cost, j);
                    }else{
                        return make_pair(z, j);
                    }
                }
            }
        }else{
            return make_pair(0,l-1);
        }
    }
}

int main(){
    int l;
    cin >> l;
    long long a[l];
    for(int i=0;i<l;i++){
        cin >> a[i];
    }
    auto le = left(a, l);
    auto ri = right(a, l);
    long long cost = le.first+ri.first;
    int odd = 0, even = 0;
    for(int i=le.second;i<ri.second;i++){
        if(a[i]%2==0){
            if(i+1 < ri.second && a[i+1]%2==0){
                continue;
            }else{
                even+=1;
            }
        }
    }
    cout << max(0, even-1) + cost << endl;
    return 0;
}

