#include "bits/stdc++.h"
using namespace std;
int Array[200005] , Zeros[200005] , Odd[200005];
int Extra[200005];
long long Prefix[200005];

void PreProcess( int N ){
    for( int i = 1 ; i <= N ; ++i ){
        if( Array[i] == 0 ){
            Zeros[i] = Zeros[i - 1] + 1;
            Odd[i] = Odd[i - 1];
        }
        else{
            if( Array[i] % 2 == 1 ) Odd[i] = Odd[i - 1] + 1;
            else Odd[i] = Odd[i - 1];

            Zeros[i] = Zeros[i - 1];
        }

        Prefix[i] = Prefix[i - 1] + Array[i];
    }

    Prefix[N + 1] = Prefix[N];
}

long long Case1( int N , int index ){
    return Prefix[index - 1] + N - index - ( Odd[N] - Odd[index] );  
}

long long Case2( int N , int index ){
    long long Temp1 = Odd[index] + 2 * Zeros[index];
    long long Temp2 = N - index - ( Odd[N] - Odd[index] );
    return Temp1 + Temp2;
}

long long Case3( int N , int index ){
    long long Temp1 = index - Odd[index];
    long long Temp2 = Odd[N] - Odd[index] + 2 * ( Zeros[N] - Zeros[index] );
    return Temp1 + Temp2;
}

long long Case4( int N , int index ){
    return Prefix[N] - Prefix[index] + index - 1 - ( Odd[index] - Odd[1] );
}

long long FindAns( int N ){
    int i;
    long long Ans = 1e18 , Temp;

    for( i = 1 ; i <= N ; ++i ){
        Temp = min( min( Case1( N , i ) , Case2( N , i ) ) , min( Case3( N , i ) , Case4( N , i ) ) );
        Ans = min( Ans , Temp );
    }   

    return Ans;
}

int main(){
    int N , i , j;
    scanf( "%d" , &N );

    for( i = 1 ; i <= N ; ++i ){
        scanf( "%d" , Array + i );
        Extra[i] = Array[i];
        Prefix[i] = Prefix[i - 1] + Array[i];
        if( Array[i] == 0 ) Zeros[i] = Zeros[i - 1] + 1;
        else Zeros[i] = Zeros[i - 1];
    }

    int start = 1 , end = N;
    long long Ans = 0;

    for( i = 1 ; i <= N ; ++i ){
        if( Zeros[i] >= Prefix[i] ) start = i + 1;
    }

    for( i = N ; i >= 1 ; --i ){
        if( Zeros[N] - Zeros[i - 1] >= Prefix[N] - Prefix[i - 1] ) end = i - 1;
    }

    if( start == N + 1 || end == 0 ){
        printf( "%lld\n" , Prefix[N] );
        return 0;
    }

    for( i = start , j = 1 ; i <= end ; ++i , ++j )
        Array[j] = Extra[i];

    Ans = Prefix[start - 1] + ( Prefix[N] - Prefix[end] );
    N = end - start + 1;
    PreProcess( N );
    printf( "%lld\n" , Ans + FindAns( N ) );
    return 0;
}

