ll cs[N];
ll dpL[N][2];
ll dpR[N][2];
ll calcL(int i, bool r) {
	ll &ret = dpL[i][r];
	if (ret != -1)
		return ret;
	ret = cs[i];
	if (v[i] % 2 && r)
		ret = min(ret, cs[i - 1] + 1);
	else
		ret = min(ret, cs[i - 1]);
	if (i) {
		if (v[i] == 0)
			ret = min(ret, 1 + r + calcL(i - 1, r));
		else if ((v[i] & 1) && r)
			ret = min(ret, 1 + calcL(i - 1, r));
		else if ((v[i] & 1) == 0 && !r)
			ret = min(ret, 1 + calcL(i - 1, r));
		else
			ret = min(ret, calcL(i - 1, r));
	}
	return ret;
}
ll calcR(int i, bool r) {
	ll &ret = dpR[i][r];
	if (ret != -1)
		return ret;
	ret = cs[n] - cs[i];
	if (i != n) {
		if (v[i + 1] % 2 && r)
			ret = min(ret, cs[n] - cs[i + 1] + 1);
		else
			ret = min(ret, cs[n] - cs[i + 1]);
		if (v[i + 1] == 0)
			ret = min(ret, 1 + r + calcR(i + 1, r));
		else if ((v[i + 1] & 1) && r)
			ret = min(ret, 1 + calcR(i + 1, r));
		else if ((v[i + 1] & 1) == 0 && !r)
			ret = min(ret, 1 + calcR(i + 1, r));
		else
			ret = min(ret, calcR(i + 1, r));
	}
	return ret;
}
