                        else
                            cmax=min(t12[t11]+cnt2,ltst);
                        cmax+=cnt-(r-l+1)+min((rmax[i2]-r-1)*2-(ncnt[i2]-icnt)+rtst3[i2],ncnt[i2]-icnt+rtst4[i2]);
                    }
                    else
                    {
                        cmax=ltst+cnt-(r-l+1)+min((rmax[i2]-r-1)*2-(ncnt[i2]-icnt)+rtst3[i2],ncnt[i2]-icnt+rtst4[i2]);
                        if(cnt2-flg2<0)
                            cmax+=cnt2-flg2;
                    }
                    if(cmax<res)
