int solve(vector<int> A)
{
	int N = A.size();
	int L =A.size();

	vector<int> sum = A;
	FOR(i,1,N){
		sum[i] += sum[i-1];
	}

	vector<int> odd = A;
	vector<int> even = A;

	REP(i,N){
		odd[i] = (odd[i]%2 == 0);
	}

	REP(i,N){
		if(even[i] == 0) even[i] = 2;
		else{
			even[i] = even[i]%2;
		}
	}

	vector<int> sumodd = odd;
	vector<int> sumeven = even;
	FOR(i,1,N){
		sumodd[i] += sumodd[i-1];
		sumeven[i] += sumeven[i-1];
	}

	vector<int> left(N);
	REP(i,N){
		int prev = (i-1 >= 0 ? left[i-1] : 0);
		if(prev + odd[i] < sum[i]){
			left[i] = odd[i];
			if(i-1 >= 0)
				left[i] += left[i-1];
		}
		else{
			left[i] = sum[i];
		}
	}


	vector<int> right(N);
	reverse(ALL(even));
	reverse(ALL(sum));
	reverse(ALL(A));
	vector<int> revsum = A;
	FOR(i,1,N){
		revsum[i] += revsum[i-1];
	}
	REP(i,N){
		int prev = (i-1 >= 0 ? right[i-1] : 0);
		if(prev + even[i] < revsum[i]){
			right[i] = even[i];
			if(i-1 >= 0)
				right[i] += right[i-1];
		}
		else{
			right[i] = revsum[i];
		}
	}
	reverse(ALL(A));
	reverse(ALL(even));
	reverse(ALL(sum));
	reverse(ALL(right));

	int res = right[0];
	REP(i,N-1){
		res = min(res, left[i] + right[i+1]);
	}
	res = min(res, left[N-1]);
	return res;
}


void solve(){
	int L; cin >> L;
	int N = L;
	vector<int> A(L); for(auto &a:A) cin >> a;
	int res = solve(A);
	reverse(ALL(A));
	res = min(solve(A), res);
	cout << res << endl;
}

