	for (int i = 1; i <= L; ++ i) sumpre[i] = sumpre[i - 1] + A[i];
	for (int i = L; i >= 1; -- i) sumsuf[i] = sumsuf[i + 1] + A[i];
	for (int i = 1; i <= L; ++ i) pre[i] = min(pre[i - 1] + (A[i] < 2 ? 2 - A[i] : A[i] % 2), sumpre[i]);
	for (int i = L; i >= 0; -- i) suff[i] = min(suff[i + 1] + (A[i + 1] < 2 ? 2 - A[i + 1] : A[i + 1] % 2), sumsuf[i + 1]);
	for (int i = L; i >= 0; -- i) suf[i] = min(suf[i + 1] + !(A[i + 1] % 2), suff[i + 1]);
	for (int i = 0; i <= L; ++ i) ans = min(ans, pre[i] + suf[i]);
}

