template< typename T >
class CumulativeSum
{
public:
    CumulativeSum() {}
    CumulativeSum(int sz) : m_Data(sz, T(0)) {};

    void Init(int sz) { m_Data.assign(sz, T(0)); }

    // k に x を加える O(1)
    void Add(int k, T x) {
        assert(static_cast<int>(m_Data.size()) >= k);
        if(static_cast<int>(m_Data.size()) <= k) { m_Data.push_back(x); }
        else { m_Data[k] = (m_Data[k] + x); }
    }

    // 累積和の構築 O(m_Data.size())
    void Build() {
        for(int i = 1; i < static_cast<int>(m_Data.size()); i++) {
            m_Data[i] = (m_Data[i] + m_Data[i - 1]);
        }
    }

    // 区間 [0, k] の和を返す O(1)
    // 閉区間なので k が含まれることに注意
    T Query(int k) {
        if(k < 0) { return T(0); }
        return (m_Data[min(k, static_cast<int>(m_Data.size()) - 1)]);
    }

    // 区間 [l, h] の和を返す O(1)
    // 閉区間なので k が含まれることに注意
    T Query(int l, int h) {
        return (this->Query(h) - this->Query(l-1));
    }
private:
    vector< T > m_Data;
};

ll L;
vector<ll> A;

ll solve() {

    // すべてが 0 なら 0
    bool isAllZero = true;
    REP(i, L) {
        if(A[i] > 0) {
            isAllZero = false;
            break;
        }
    }
    if(isAllZero) { return 0; }

    CumulativeSum<ll> cs(L);
    REP(i, L) { cs.Add(i, A[i]); }
    cs.Build();

    CumulativeSum<ll> cs2(L);
    CumulativeSum<ll> cs0(L);
    CumulativeSum<ll> cs1(L);
    REP(i, L) {
        if(A[i] == 0) { cs0.Add(i, 1); }
        else if(A[i] % 2 == 0) { cs2.Add(i, 1); }
        else { cs1.Add(i, 1); }
    }
    cs2.Build();
    cs1.Build();
    cs0.Build();

    // group の作成
    // <0>: 単体でのコスト <1>: 開始インデックス <2>: 終了インデックス
    vector< tuple<ll, ll, ll> > group;
    REP(i, L) {
        if(A[i] != 0) {
            ll ind = i;
            ll cost = 0;
            while(i < L && A[i] != 0) {
                if(A[i] % 2 == 0) { cost++; }
                i++;
            }
            for(int j = ind; j < i; ++j) {
                if(A[i] % 2 != 0) { break; }
                if(cost == 0) { break; }
                cost--;
            }
            for(int j = i-1; j >= ind; --j) {
                if(A[i] % 2 != 0) { break; }
                if(cost == 0) { break; }
                cost--;
            }
            if(0 <= ind - 1) {
                cost += cs.Query(0, ind-1);
            }
            if(i <= L-1) {
                cost += cs.Query(i, L-1);
            }
            group.push_back(make_tuple(cost, ind, i-1));
        }
    }
    SORT(group);

    vector<ll> group_id(L, -1);    // 要素 i のグループ id
    for(auto& g : group) {
        for(int i = get<1>(g); i <= get<2>(g); ++i) {
            group_id[i] = get<0>(g);
        }
    }

    // 開始点を決める
    ll start_pos = get<1>(group[0]);
    ll zero = 0;
    for(int i = start_pos; i >= 0; --i) {
        if(group_id[i] > 0) {
            ll cost = cs.Query(get<1>(group[group_id[i]]), get<2>(group[group_id[i]]));
            i = get<1>(group[group_id[i]]);
            DBG("cost: %lld id: %lld[%lld, %lld]\n",
                    cost, group_id[i], get<1>(group[group_id[i]]), get<2>(group[group_id[i]]));
            if(cost >= zero) {
                // 0 を超えても入れたほうがいいなら、追加する。
                start_pos = i;
            }
            zero = 0;
        }
        else if(A[i] == 0) {
            zero++;
        }
    }
    // 終了点を決める
    ll end_pos = get<2>(group[0]);
    zero = 0;
    for(int i = end_pos; i < L; ++i) {
        if(group_id[i] > 0) {
            ll cost = cs.Query(get<1>(group[group_id[i]]), get<2>(group[group_id[i]]));
            i = get<2>(group[group_id[i]]);
            if(cost >= zero) {
                // 0 を超えても入れたほうがいいなら、追加する。
                end_pos = i;
            }
            zero = 0;
        }
        else if(A[i] == 0) {
            zero++;
        }
    }
    DBG("[%lld, %lld]\n", start_pos, end_pos);

    ll ret = 0;
    for(int i = start_pos; i <= end_pos; ++i) {
        if(A[i] == 0 || A[i] % 2 == 0) { ret++; }
    }

    ll border = start_pos;
    ll cand = ret;
    for(int i = start_pos; i <= end_pos; ++i) {
        ll tmp = ret + cs0.Query(start_pos, i) + cs1.Query(start_pos, i) - cs2.Query(start_pos, i);
        if(cand > tmp) {
            cand = tmp;
            border = i;
        }
    }
    DBG("border: %lld\n", border);
    ret = cand;
    for(int i = end_pos; i > border; --i) {
        ll tmp = ret + cs0.Query(i, end_pos) + cs1.Query(i, end_pos) - cs2.Query(i, end_pos);
        cand = min(cand, tmp);
    }
    ret = cand;

    return ret + cs.Query(0, start_pos-1) + cs.Query(end_pos + 1, L - 1);
}

signed main()
{
    cin >> L;
    A.resize(L);
    REP(i, L) {
        cin >> A[i];
    }
    ll ans = solve();
    printf("%lld\n", ans);
    return 0;
}

