    // 0 ... 0 | 偶 ... 偶 ≥ 2 | 奇 ... 奇 | 偶 ... 偶 ≥ 2| 0 ... 0
    DP[0] = {0, 0, 0, 0, 0};
    REP(i, n){
        int a; scanf("%d", &a);
        DP[i+1][0] = DP[i][0] + diff(a, 0);
        for(int j = 1; j < 5; ++j){
            DP[i+1][j] = std::min(DP[i][j-1], DP[i][j]) + diff(a, j);
        }
    }
    lli res = DP[n][0]; for(int j = 1; j < 5; ++j) if(res > DP[n][j]) res = DP[n][j];
    printf("%lld\n", res);
    return 0;
}

