const int MAXN = (int)2e5 + 77;
ll a[MAXN], p[MAXN];
int n;

ll get(int l, int r) {
	if(l <= r) {
		return p[r] - (l == 0 ? 0 : p[l - 1]);
	} else {
		return 0;
	}
}

void solve() {
	cin >> n;

	for(int i = 0; i < n; ++i) {
		cin >> a[i];
		p[i] = a[i] + (i == 0 ? 0 : p[i - 1]);
	}

	ll answ = INT_INF;

	for(int l = 0; l < n;) {
		if(!a[l]) {
			++l;
		} else {
			int r = l;

			while(r + 1 < n && a[r + 1]) {
				++r;
			}

			for(int bad = 0; bad < 2; ++bad) {
				ll local = get(0, l - 1) + get(r + 1, n - 1);

				for(int i = l; i <= r; ++i) {
					if((a[i] & 1) == bad) {
						++local;
					}
				}

				int badpref = 0, badsuff = 0;
				int sz = r - l + 1;

				while(badpref < sz && (a[l + badpref] & 1) == bad) {
					++badpref;
				}

				while(badsuff < sz && (a[r - badsuff] & 1) == bad) {
					++badsuff;
				}

				local -= max(badpref, badsuff);
				answ = min(answ, local);
			}

			l = r + 1;
		}
	}

	cout << answ << '\n';
}

int main() {
	fast_io();
	solve();

	return 0;
}

