#define ll long long
using namespace std;
const int N = 2e5+7;
deque<int> q;
int a[N], f[N], sum1[N], sum2[N];
int query1(int l, int r)
{
	return sum1[r]-sum1[l-1];
}
int query2(int l, int r)
{
	return sum2[r]-sum2[l-1];
}
int dp(int l, int r)
{
	int res;
	for(int i = l-1; i <= r; i++)
	{
		f[i] = 0;
	}
	q.push_back(l-1);
	for(int i = l; i <= r; i++)
	{
		int m = q.front();
		f[i] = min(f[i-1]+query2(i, i), query1(l, m)+query2(m+1, i));
		while(!q.empty()&&query1(l, q.back())+query2(q.back()+1, i)>query1(l, i))
		{
			q.pop_back();
		}
		q.push_back(i);
	}
	res = f[r];
	for(int i = l; i < r; i++)
	{
		res = min(res, f[i]+query1(i+1, r));
	}
	return res;
}
int main()
{
	int n;
	ll ans = 0, res = 0;
	scanf("%d", &n);
	for(int i = 1; i <= n; i++)
	{
		scanf("%d", &a[i]);
		ans += a[i];
		res += a[i];
		sum1[i] = sum1[i-1]+(a[i]&1);
		sum2[i] = i-sum1[i];
	}
	for(int i = 1; i <= n; i++)
	{
		ll det = 0;
		int j = i, cnt;
		while(j<=n&&a[j]>0)
		{
			det += a[j++];
		}
		if(i==j)
		{
			continue;
		}
		j--;
		cnt = min(query1(i, j), query2(i, j));
		for(int k = i; k < j; k++)
		{
			cnt = min(cnt, query1(i, k)+query2(k+1, j));
			cnt = min(cnt, query2(i, k)+query1(k+1, j));
		}
		cnt = min(cnt, dp(i, j));
		i = j;
		res = min(res, ans-det+cnt);
	}
	printf("%lld\n", res);
    return 0;
}

