  CumulativeSum(Int n):n(n), sum(n+1), A(n+1),added(0){}
  CumulativeSum(const vector<T> &B):n(B.size()), sum(n+1), A(n+1),added(0){
    for(Int i=1;i<=n;i++) sum[i] = sum[i-1] + B[i-1];
  }

  void apply(){
    for(Int i=1;i<=n;i++) A[i] = A[i] + A[i-1];
    for(Int i=1;i<=n;i++) A[i] = A[i] + A[i-1];
    for(Int i=1;i<=n;i++) sum[i] = sum[i] + A[i-1];
    added = 0; A.clear(); A.resize(n+1);
  }

  //[l, r)にxを加算
  void add(Int l, Int r, T x){
    added = 1;
    assert(l <= r && 0 <= l && r <= n);
    A[l] = A[l] + x;
    A[r] = A[r] - x;
  }

  //[l, r)の和を得る
  T get(Int l,Int r){
    assert(l<=r && 0<=l && r<=n);
    if(added) apply();
    return sum[r] - sum[l];
  }
};
const Int SIZE = 200010;
Int N;
vector<Int> A;
CumulativeSum <Int> Asum;


Int memL[SIZE], usedL[SIZE];
Int dfsL(Int pos){ //左に行って戻ってくる
  if(pos == 0) return 0;
  if(usedL[pos]++) return memL[pos];

  Int a = Asum.get(0, pos);
  Int b = (A[pos-1]%2) + 2 * (A[pos-1] == 0) + dfsL(pos-1);
  return memL[pos] = min(a, b);
}

Int memR[SIZE], usedR[SIZE];
Int dfsR(Int pos){ //右に行って戻ってくる
  if(pos == N) return 0;
  if(usedR[pos]++) return memR[pos];

  Int a = Asum.get(pos, N);
  Int b = (A[pos]%2) + 2 * (A[pos] == 0) + dfsR(pos+1);
  return memR[pos] = min(a, b);
}

Int mem[SIZE], used[SIZE];
Int dfs(Int pos){//右に行って好きに終わる
  if(pos == N) return 0;
  if(used[pos]++) return mem[pos];
  Int a = dfsR(pos);
  Int b = (A[pos]%2 != 1) + dfs(pos+1);
  return mem[pos] = min(a, b);
}

Int solve(){
  memset(memL, 0, sizeof(memL));
  memset(usedL, 0, sizeof(usedL));
  memset(memR, 0, sizeof(memR));
  memset(usedR, 0, sizeof(usedR));
  memset(mem, 0, sizeof(mem));
  memset(used, 0, sizeof(used));

  Asum = CumulativeSum<Int> (A);

  Int ans = INF;
  for(Int i=0;i<N;i++){
    Int a = dfsL(i);
    Int b = dfs(i);
    Int cost = (a + b);
    Min(ans, cost);
  }
  return ans;
}

