  cout << fixed << setprecision(12);
  cin>>N;
  A.resize(N);
  cin>>A;

  Int a = solve();
  reverse(A.begin(), A.end());
  Int b = solve();
  Int ans = min(a, b);
  cout<<ans<<endl;
  return 0;
}

