int a[maxn];
ll c[maxn],tot[maxn],f[maxn],g[maxn],dis[maxn],pre[maxn],suf[maxn],l[maxn],r[maxn];
ll ans=INF;
vector<int> blk[maxn];

inline void calcCost(int id){
//	FOR(i,0,blk[id].size()) printf("%d ",blk[id][i]);
//	puts("");
	FOR(i,0,blk[id].size()) if(!(blk[id][i]&1)) ++c[id];
	ll cnt=0;
	FOR(i,0,blk[id].size()){
		if(blk[id][i]&1) --cnt;
		else ++cnt;
		l[id]=max(l[id],cnt);
	}
	cnt=0;
	for(int i=blk[id].size()-1;i>=0;--i){
		if(blk[id][i]&1) --cnt;
		else ++cnt;
		r[id]=max(r[id],cnt);
	}
	return;
}

int main(){
	scanf("%d",&n);
	FOR(i,0,n) scanf("%d",a+i);
	for(int i=0;i<n;){
		for(;i<n&&a[i];++i) blk[m].PB(a[i]);
		for(;i<n&&!a[i];++i) ++dis[m];
		++m;
	}
	FOR(i,0,m){
		calcCost(i);
		FOR(j,0,blk[i].size()) tot[i]+=blk[i][j];
		pre[i]=(i)?(pre[i-1]+tot[i]):(tot[i]);
	}
/*	FOR(i,0,m) printf("%d ",c[i]);
	puts("");
	FOR(i,0,m) printf("%d ",l[i]);
	puts("");
	FOR(i,0,m) printf("%d ",r[i]);
	puts("");
*/	for(int i=m-1;i>=0;--i) suf[i]=(i!=m-1)?(suf[i+1]+tot[i]):(tot[i]);
	FOR(i,0,m){
		if(i){
			f[i]=pre[i-1]+c[i]-l[i];
			f[i]=min(f[i],f[i-1]+dis[i-1]+c[i]);
		}else f[i]=c[i]-l[i];
	}
//	FOR(i,0,m) printf("%d ",f[i]);
//	puts("");
	for(int i=m-1;i>=0;--i){
		if(i!=m-1){
			g[i]=suf[i+1]+c[i]-r[i];
			g[i]=min(g[i],g[i+1]+dis[i]+c[i]);
		}else g[i]=c[i]-r[i];
	}
//	FOR(i,0,m) printf("%d ",g[i]);
//	puts("");
	FOR(i,0,m){
		if((i&&f[i]!=f[i-1]+dis[i-1]+c[i])||(!i)){
			if(i!=m-1) ans=min(ans,f[i]+suf[i+1]);
			else ans=min(ans,f[i]);
		}else{
			if(i!=m-1) ans=min(ans,f[i]-r[i]+suf[i+1]);
			else ans=min(ans,f[i]-r[i]);
		}
//		printf("%lld\n",ans);
		if((i!=m-1&&g[i]!=g[i+1]+dis[i]+c[i])||(i==m-1)){
			if(i) ans=min(ans,g[i]+pre[i-1]);
			else ans=min(ans,g[i]);
		}else{
			if(i) ans=min(ans,g[i]-l[i]+pre[i-1]);
			else ans=min(ans,g[i]-l[i]);
		}
//		printf("%lld\n",ans);
	}
	printf("%lld\n",ans);
	return 0;
}

