using namespace std;
#define int long long

vector<int> calc1(int L, vector<int> &A) {
	vector<int> dp(L + 2);
	int sum = 0;
	for(int i = 1; i <= L + 1; ++i) {
		if (A[i] == 0) {
			dp[i] = min(sum, dp[i - 1] + 2);
		} else if(A[i] % 2 == 0) {
			dp[i] = min(sum, dp[i - 1]);
		} else {
			dp[i] = min(sum, dp[i - 1] + 1);
		}
		sum += A[i];
	}
	return dp;
}
vector<int> calc2(int L, vector<int> &A, vector<int> &B) {
	vector<int> dp(L + 2);
	for(int i = 1; i <= L + 1; ++i) {
		int c;
		if(A[i] == 0) {
			c = 2;
		} else if(A[i] % 2 == 0) {
			c = 1;
		} else {
			c = 0;
		}
		dp[i] = min(B[i], A[i - 1] + c);
	}
	return dp;
}

