ll L;
vector<ll> A;

void input() {
    cin >> L;
    A.resize(L);
    for (auto& a : A)
        cin >> a;
}

void solve() {
    vector<array<ll, 4>> dp(L, {0, 0, 0, 0});
    ll sum = A[0];
    dp[0] = {A[0] % 2, A[0] % 2 == 0, A[0] % 2, A[0]};
    for (ll i = 1; i < L; i++) {
        bool odd = A[i] % 2 == 1;
        bool nonzero = A[i] > 0;
        dp[i][0] = min(sum, dp[i-1][0]) + (odd ? 1 : (nonzero ? 0 : 2));
        dp[i][1] = min(dp[i-1][0], dp[i-1][1]) + (odd ? 0 : 1);
        dp[i][2] = min(dp[i-1][1], dp[i-1][2]) + (odd ? 1 : (nonzero ? 0 : 2));
        dp[i][3] = min(dp[i-1][2], dp[i-1][3]) + A[i];
        sum += A[i];
        cerr << dp[i][0] << ' ' << dp[i][1] << ' ' << dp[i][2] << ' ' << dp[i][3] << endl;
    }
    auto& bdp = dp.back();
    ll ans = *min_element(bdp.begin(), bdp.end());
    cout << ans << endl;
}

