	    }
	    REP (a, 3) {
		amax(dp[i+1][a], A[i] - (a==1? 0: 1));
	    }
	}
    }

    LL ans = sum;
    REP (i, L+1) REP (a, 3) amin(ans, sum - dp[i][a]);
    printf("%lld\n", ans);
}

