int const MAX_N = 512 * 1024;

int ans[MAX_N];
long long nech[MAX_N], chet[MAX_N], dp[MAX_N][2];

long long calc(int l, int r) {
	long long sum = 0;
	for (int i = l; i <= r; i++) sum += ans[i];

	if (r - l + 1 <= 2)
		return sum;

	for (int i = l; i <= r; i++) ans[i] %= 2;

	long long mx = 0;
	int bg = -1, en = -2;
	for (int i=l; i<=r; i++)
		if (ans[i]) {
			if (bg < 0) bg = i;
			en = i;
		}
		else {
			if (bg <= en) {
				mx = max(mx, en - bg + 1LL);
			}
			bg = -1, en = -2;
		}
	if (bg <= en) {
		mx = max(mx, en - bg + 1LL);
	}

	long long bad = 0;
	for (int i = l; i <= r; i++) bad += ans[i];
	bad -= mx;

	mx = bad;

	bad = 0;
	nech[l] = 1;
	for (int i = l + 1; i <= r; i++) nech[i] = nech[i - 1] + ans[i];

	chet[r] = ans[r] == 0;
	for (int i = r - 1; i >= l; i--) chet[i] = chet[i + 1] + (ans[i] == 0);

	int len = r - l + 1;

	mx = min(mx, len - nech[r]);
	for (int i = l + 1; i <= r; i++)
		mx = min(mx, len - (nech[i - 1] + chet[i]));

	for (int i = l; i <= (l + r) / 2; i++)
		swap(ans[i], ans[r - (i - l)]);

	nech[l] = 1;
	for (int i = l + 1; i <= r; i++) nech[i] = nech[i - 1] + ans[i];
	chet[r] = ans[r] == 0;
	for (int i = r - 1; i >= l; i--) chet[i] = chet[i + 1] + (ans[i] == 0);

	mx = min(mx, len - nech[r]);
	for (int i = l + 1; i <= r; i++)
		mx = min(mx, len - (nech[i - 1] + chet[i]));

	long long old_ans = mx;


	mx = 0;
	nech[r] = ans[r];
	for (int i = r - 1; i >= l; i--) nech[i] = nech[i + 1] + ans[i];
	dp[l][0] = ans[l] != 0;
	dp[l][1] = ans[l] != 1;
	for (int i = l + 1; i <= r; i++) {
		dp[i][0] = dp[i - 1][0] + (ans[i] != 0);
		dp[i][1] = dp[i - 1][1] + (ans[i] != 1);
		dp[i][1] = min(dp[i][1], dp[i - 1][0] + (ans[i] != 1));
	}
	mx = nech[l];
	for (int i = l + 1; i <= r; i++)
		mx = min(mx, min(dp[i - 1][0], dp[i - 1][1]) + nech[i]);

	old_ans = min(old_ans, mx);

	for (int i = l; i <= (l + r) / 2; i++)
		swap(ans[i], ans[r - (i - l)]);

	mx = 0;
	nech[r] = ans[r];
	for (int i = r - 1; i >= l; i--) nech[i] = nech[i + 1] + ans[i];
	dp[l][0] = ans[l] != 0;
	dp[l][1] = ans[l] != 1;
	for (int i = l + 1; i <= r; i++) {
		dp[i][0] = dp[i - 1][0] + (ans[i] != 0);
		dp[i][1] = dp[i - 1][1] + (ans[i] != 1);
		dp[i][1] = min(dp[i][1], dp[i - 1][0] + (ans[i] != 1));
	}
	mx = nech[l];
	for (int i = l + 1; i <= r; i++)
		mx = min(mx, min(dp[i - 1][0], dp[i - 1][1]) + nech[i]);

	old_ans = min(old_ans, mx);

	return sum - old_ans;
}

