const long long inf = 1e15;

int L;
int A[200200];

void input(){
	scanf("%d", &L);
	for(int i = 0; i < L; ++i){
		scanf("%d", A + i);
	}
}

long long dp[200200][5];

int getCost(int a, int i){
	if(a == 0){
		if(i == 0 || i == 4) return 0;
		else if(i == 1 || i == 3) return 2;
		else return 1;
	}else{
		if(i == 0 || i == 4) return a;
		int x = a % 2;
		int v = (i == 2 ? 1 : 0);
		return x ^ v;
	}
}

long long solve(){
	for(int i = 0; i <= L; ++i){
		for(int j = 0; j < 5; ++j){
			dp[i][j] = inf;
		}
	}
	for(int i = 0; i < 5; ++i) dp[0][i] = 0;
	for(int i = 0; i < L; ++i){
		for(int j = 0; j < 5; ++j){
			for(int k = 0; k <= j; ++k){
				long long tmp = dp[i][k] + getCost(A[i], j);
				dp[i + 1][j] = min(dp[i + 1][j], tmp);
			}
		}
	}
	long long ans = inf;
	for(int j = 0; j < 5; ++j){
		ans = min(ans, dp[L][j]);
	}
	return ans;
}

int main(){
	input();
	long long ans = solve();
	printf("%lld\n", ans);
	return 0;
}

