vector<ll> f(const vector<ll> &a) {
	const int n = (int) a.size();
	vector<ll> dp(n + 1, 0);
	ll sum = 0;
	for (int i = 1; i <= n; ++i) {
		const ll x = a[i - 1];
		sum += x;
		dp[i] = min(sum, dp[i - 1] + (x - 2 < 0 ? 2 - x : x & 1));
	}
	return dp;
}

