    return accumulate(all(a), 0LL);
}

ll waste_count(vl a, bool start=false, bool end=false) {
    ll n = a.size(), odd_cnt = 0;
    rep(i,n) odd_cnt += a[i] % 2;
    ll even_cnt = n - odd_cnt;

    if (start and end) {
        ll res = even_cnt;
        vl dp1(n+1,0), dp2(n+1,0);
        vl dp3(n+1,0), dp4(n+1,0);
        rep(i,n) dp1[i+1] = dp1[i] + (a[i] % 2);
        per(i,n) dp2[i] = dp2[i+1] + (a[i] % 2);
        rep(i,n) dp3[i+1] = dp3[i] + 1 - (a[i] % 2);
        per(i,n) dp4[i] = dp4[i+1] + 1 - (a[i] % 2);
        rep(i,n) dmin(res, min(dp1[i],dp3[i]) + min(dp2[i],dp4[i]));
        return res;
    }
    ll res = even_cnt;
    if (start or end) {
        if (end) reverse(all(a));
        ll cnt = 0;
        rep(i,n) {
            if (a[i] % 2) cnt++, odd_cnt--;
            else even_cnt--;
            dmin(res, even_cnt + cnt);
        }
    }
    return res;
}

int main() {
    ll L; cin >> L;
    vl a(L); rep(i,L) scanf("%lld", &a[i]);

    ll prev = 0, N = 0;
    vvl as;
    rep(i,L) {
        if ((prev == 0) xor (a[i] == 0)) {
            as.push_back(vl());
            prev = a[i];
            N++;
        }
        if (N > 0) as[N-1].push_back(a[i]);
    }
    if (N == 0) { cout << 0 << endl; return 0; }

    ll sum = sum_value(a), used_sum = 0, rest_sum = sum, ans = sum;
    ll prev_waste = waste_count(as[0],1,0);
    for (int i = 0; i < N; i += 2) {
        ll now = sum_value(as[i]);
        rest_sum -= now;

        // as[i]だけを使うパターン
        dmin(ans, used_sum + waste_count(as[i],1,1) + rest_sum);

        if (i > 1) {
            // as[i]で終えるパターン
            dmin(ans, prev_waste + zero_count(as[i-1]) + waste_count(as[i],0,1) + rest_sum);

            // i-2までに必要な操作回数の最小値を更新
            ll a = prev_waste + zero_count(as[i-1]) + waste_count(as[i],0,0);
            ll b = used_sum + waste_count(as[i],1,0);
            prev_waste = min(a, b);
        }
        used_sum += now;
    }
    cout << ans << endl;
    return 0;
}

