		mx = max(mx, ps2[i] - ps1[i]);
		L[i] = ps2[i] - mx;
	}
	// PR(L, n);
}

void calcRight() {
	int64_t mx = 0;

	for (int64_t i=n; i>=1; --i) {
		ps1[i] = ps1[i+1] + a[i];
		ps2[i] = ps2[i+1] + (a[i]==0 ? 2 : a[i]%2);
		mx = max(mx, ps2[i] - ps1[i]);
		R[i] = ps2[i] - mx;
	}
}

int64_t solve() {
	calcLeft();
	calcRight();

	int64_t res = INF;

	for (int64_t i=1; i<=n+1; ++i) {
		res = min(res, L[i-1] + R[i]);
	}

	return res;
}

