      // mode 0, 4
      if (j == 0 || j == 4) {
        chmin(dp[i+1][j], dp[i][j] + a[i]);
      }
      // mode 1, 3
      if (j == 1 || j == 3) {
        ll cost = a[i] == 0 ? 2 : a[i] == 1 ? 1 : a[i] % 2;
        chmin(dp[i+1][j], dp[i][j] + cost);
      }
      // mode 2
      if (j == 2) {
        ll cost = a[i] == 0 ? 1 : 1 - a[i] % 2;
        chmin(dp[i+1][j], dp[i][j] + cost);
      }
    }
  }
  ll ans = linf;
  rep(j, 5) chmin(ans, dp[n][j]);
  cout << ans << endl;
}

