// 実行メイン
int
fMain(
)
{
	int i;
	char lc1Buf[1024];

	// 位置数 - 取得
	fgets(lc1Buf, sizeof(lc1Buf), szpFpI);
	sscanf(lc1Buf, "%d", &siPCnt);

	// 石数 - 取得
	for (i = 0; i < siPCnt; i++) {
		fgets(lc1Buf, sizeof(lc1Buf), szpFpI);
		sscanf(lc1Buf, "%d", &si1SCnt[i]);
	}

	// 操作回数 - 左方向
	sl1OCntL0[0] = 0;
	si1OCntL1[0] = 0;
	si1OCntL2[0] = 0;
	for (i = 1; i <= siPCnt; i++) {

		// なし
		sl1OCntL0[i] = sl1OCntL0[i - 1] + (long long)si1SCnt[i - 1];

		// 片道
		si1OCntL1[i] = si1OCntL1[i - 1] + (si1SCnt[i - 1] + 1) % 2;
		si1OCntL1[i] = (int)fGetMinL(si1OCntL1[i], sl1OCntL0[i]);

		// 往復
		if (si1SCnt[i - 1] == 0) {
			si1OCntL2[i] = si1OCntL2[i - 1] + 2;
		}
		else {
			si1OCntL2[i] = si1OCntL2[i - 1] + si1SCnt[i - 1] % 2;
		}
		si1OCntL2[i] = (int)fGetMinL(si1OCntL2[i], sl1OCntL0[i]);
	}

	// 操作回数 - 右方向
	sl1OCntR0[siPCnt] = 0;
	si1OCntR1[siPCnt] = 0;
	si1OCntR2[siPCnt] = 0;
	for (i = siPCnt - 1; i >= 0; i--) {

		// なし
		sl1OCntR0[i] = sl1OCntR0[i + 1] + (long long)si1SCnt[i];

		// 片道
		si1OCntR1[i] = si1OCntR1[i + 1] + (si1SCnt[i] + 1) % 2;
		si1OCntR1[i] = (int)fGetMinL(si1OCntR1[i], sl1OCntR0[i]);

		// 往復
		if (si1SCnt[i] == 0) {
			si1OCntR2[i] = si1OCntR2[i + 1] + 2;
		}
		else {
			si1OCntR2[i] = si1OCntR2[i + 1] + si1SCnt[i] % 2;
		}
		si1OCntR2[i] = (int)fGetMinL(si1OCntR2[i], sl1OCntR0[i]);
	}

	// 最小値 - 取得
	int liMin = INT_MAX;
	for (i = 0; i <= siPCnt; i++) {

		// 左往復 + 右片道
		int liOCnt = si1OCntL2[i] + si1OCntR1[i];
		liMin = fGetMinI(liMin, liOCnt);

		// 右往復 + 左片道
		liOCnt = si1OCntR2[i] + si1OCntL1[i];
		liMin = fGetMinI(liMin, liOCnt);
	}

	return liMin;
}

