int64 calc(const int *a,int n){
  int64 *dp=(int64 *)calloc(5*2,sizeof(int64));
  int now=0;
  for(int i=0;i<n;i++){
    int next=now^1;
    int v=a[i];
    if(v>0){
      dp[POS(next,0)]=dp[POS(now,0)]+v;
      dp[POS(next,1)]=MIN(dp[POS(now,0)]+(v&1),dp[POS(now,1)]+(v&1));
      dp[POS(next,2)]=MIN(dp[POS(now,1)]+((v+1)&1),dp[POS(now,2)]+((v+1)&1));
      dp[POS(next,3)]=MIN(dp[POS(now,2)]+(v&1),dp[POS(now,3)]+(v&1));
      dp[POS(next,4)]=MIN(dp[POS(now,3)]+v,dp[POS(now,4)]+v);
    } else {
      dp[POS(next,0)]=dp[POS(now,0)]+v;
      dp[POS(next,1)]=MIN(dp[POS(now,0)]+1,dp[POS(now,1)]+1);
      dp[POS(next,2)]=MIN(dp[POS(now,1)]+1,dp[POS(now,2)]+1);
