public class Main {
    InputStream is;
    PrintWriter out;
    String INPUT = "";

    static int mod = 1_000_000_007;
    // int mod = 998244353;
    long inf = Long.MAX_VALUE/2;

    long[] a;
    int l;

    void solve(){
        l = ni();
        a = new long[l];
        for(int i = 0; i < l; i++){
            a[i] = nl();
        }

        long[][] dp = new long[l][5];
        dp[0][0] = a[0];
        dp[0][1] = (a[0]==0 ? 2 : (a[0]%2==1 ? 1 : 0));
        dp[0][2] = (a[0]==0 ? 1 : (a[0]%2==0 ? 1 : 0));
        dp[0][3] = (a[0]==0 ? 2 : (a[0]%2==1 ? 1 : 0));
        dp[0][4] = a[0];

        for(int i = 1; i < l; i++){
            dp[i][0] = dp[i-1][0] + a[i];
            dp[i][1] = Math.min(dp[i-1][0], dp[i-1][1]) + (a[i]==0 ? 2 : (a[i]%2==1 ? 1 : 0));
            dp[i][2] = Math.min(Math.min(dp[i-1][0], dp[i-1][1]), dp[i-1][2]) + (a[i]==0 ? 1 : (a[i]%2==0 ? 1 : 0));
            dp[i][3] = Math.min(Math.min(Math.min(dp[i-1][0], dp[i-1][1]), dp[i-1][2]), dp[i-1][3]) + (a[i]==0 ? 2 : (a[i]%2==1 ? 1 : 0));
            dp[i][4] = Math.min(Math.min(Math.min(Math.min(dp[i-1][0], dp[i-1][1]), dp[i-1][2]), dp[i-1][3]), dp[i-1][4]) + a[i];
        }
        long ans = inf;
        for(int i = 2; i < 5; i++){
            ans = Math.min(ans, dp[l-1][i]);
            // out.println(dp[l-1][i]);
        }
        out.println(ans);

    }

    void run() throws Exception
    {
        is = INPUT.isEmpty() ? System.in : new ByteArrayInputStream(INPUT.getBytes());
        out = new PrintWriter(System.out);
        long s = System.currentTimeMillis();
        solve();
        out.flush();
        if(!INPUT.isEmpty())tr(System.currentTimeMillis()-s+"ms");
    }

    public static void main(String[] args) throws Exception { new Main().run(); }

    private byte[] inbuf = new byte[1024];
    private int lenbuf = 0, ptrbuf = 0;

    private int readByte()
    {
        if(lenbuf == -1)throw new InputMismatchException();
        if(ptrbuf >= lenbuf){
            ptrbuf = 0;
            try { lenbuf = is.read(inbuf); } catch (IOException e) { throw new InputMismatchException(); }
            if(lenbuf <= 0)return -1;
        }
        return inbuf[ptrbuf++];
    }

    private boolean isSpaceChar(int c) { return !(c >= 33 && c <= 126); }
    private int skip() { int b; while((b = readByte()) != -1 && isSpaceChar(b)); return b; }

    private double nd() { return Double.parseDouble(ns()); }
    private char nc() { return (char)skip(); }

    private String ns()
    {
        int b = skip();
        StringBuilder sb = new StringBuilder();
        while(!(isSpaceChar(b) && b != ' ')){
            sb.appendCodePoint(b);
            b = readByte();
        }
        return sb.toString();
    }

    private char[] ns(int n)
    {
        char[] buf = new char[n];
        int b = skip(), p = 0;
        while(p < n && !(isSpaceChar(b))){
            buf[p++] = (char)b;
            b = readByte();
        }
        return n == p ? buf : Arrays.copyOf(buf, p);
    }

    private char[][] nm(int n, int m)
    {
        char[][] map = new char[n][];
        for(int i = 0;i < n;i++)map[i] = ns(m);
        return map;
    }

    private int[] na(int n)
    {
        int[] a = new int[n];
        for(int i = 0;i < n;i++)a[i] = ni();
        return a;
    }

    private int ni()
    {
        int num = 0, b;
        boolean minus = false;
        while((b = readByte()) != -1 && !((b >= '0' && b <= '9') || b == '-'));
        if(b == '-'){
            minus = true;
            b = readByte();
        }

        while(true){
            if(b >= '0' && b <= '9'){
                num = num * 10 + (b - '0');
            }else{
                return minus ? -num : num;
            }
            b = readByte();
        }
    }

    private long nl()
    {
        long num = 0;
        int b;
        boolean minus = false;
        while((b = readByte()) != -1 && !((b >= '0' && b <= '9') || b == '-'));
        if(b == '-'){
            minus = true;
            b = readByte();
        }

        while(true){
            if(b >= '0' && b <= '9'){
                num = num * 10 + (b - '0');
            }else{
                return minus ? -num : num;
            }
            b = readByte();
        }
    }

    private static void tr(Object... o) { System.out.println(Arrays.deepToString(o)); }

}

