	static class TaskX {

		int back, fore;
		public void solve(int testNumber, MyInput in, PrintWriter out) {

			int l = in.nextInt();
			long[] a = in.nextLongArray(l);
			int n = a.length;
			long[] arev = new long[n];
			for (int i = 0; i < n; i++) {
				arev[n-1-i] = a[i];
			}
			back = 0;
			fore = 0;
			for (int i = a.length-1; i >= 0; i--) {
				if (a[i] == 0) {
					back++;
				} else {
					break;
				}
			}

			for (int i = 0; i < a.length; i++) {
				if (a[i] == 0) {
					fore++;
				} else {
					break;
				}
			}

			long ng = -1, ok = LINF;
			while (ok - ng > 1) {
				long k = (ok + ng) / 2;

				if (check(k, a.clone()) || check2(k, arev)) {
					ok = k;
				} else {
					ng = k;
				}
			}

			out.println(ok);

		}

		// k 回の操作で条件を満たすことが可能かどうか
		boolean check(long k, long[] a) {
