    }
    public static long min(long a, long b, long c, long d, long e, long f) {
        return Math.min(Math.min(Math.min(Math.min(Math.min(a, b), c), d), e), f);
    }
    public static long min(long a, long b, long c, long d, long e, long f, long g) {
        return Math.min(Math.min(Math.min(Math.min(Math.min(Math.min(a, b), c), d), e), f), g);
    }
    public static long min(long a, long b, long c, long d, long e, long f, long g, long h) {
        return Math.min(Math.min(Math.min(Math.min(Math.min(Math.min(Math.min(a, b), c), d), e), f), g), h);
    }
    public static long min(long a, long... vals) {
        long ret = a; for (long e : vals) ret = Math.min(ret, e);
        return ret;
    }
    public static long fold(final LongBinaryOperator func, final long... a) {
        long ret = a[0]; for (int i = 1; i < a.length; i++) ret = func.applyAsLong(ret, a[i]);
        return ret;
    }
    public static boolean isPowerOfTwo(final long n) {return n != 0 && (-n & n) == n;}
    public static int ceilExponent(final long n) {return 63 - Long.numberOfLeadingZeros(n) + (isPowerOfTwo(n) ? 0 : 1);}
    public static int floorExponent(final long n) {return 63 - Long.numberOfLeadingZeros(n) + (n == 0 ? 1 : 0);}
    public static int ceilExponent(final long n, final int base) {
        if (base == 2) return ceilExponent(n);
        int i = 0;
        long m = 1;
        while (m < n) {
            i++;
            final long r = m * base;
            if ((m | base) >> 31 != 0 && r / base != m) break;
            m = r;
        }
        return i;
    }
    /**
     * Caluculate the ceil of a/b. Returns the smallest integer greater than or
     * equal to a/b while 'a/b' rounds fractional parts to ZERO.
     * @param a
     * @param b
     * @return the smallest integer greater than or equal to a/b
     */
    public static long cld(final long a, final long b) {
        if (a > 0 && b > 0) return (a + b - 1) / b;
        if (a < 0 && b < 0) return (a + b + 1) / b;
        return a / b;
    }

    /**
     * Caluculate the floor of a/b. Returns the largest integer less than or equal
     * to a/b while 'a/b' rounds fractional parts to ZERO.
     * @param a
     * @param b
     * @return the largest integer less than or equal to a/b
     */
    public static long fld(final long a, final long b) {
        if (a <= 0 && b > 0) return (a - b + 1) / b;
        if (a > 0 && b <= 0) return (a - b - 1) / b;
        return a / b;
    }
    public static String join(final String sep, final long... a) {
        final StringBuilder sb = new StringBuilder();
        for (int i = 0; i < a.length; i++) {
            sb.append(a[i]);
            if (i < a.length - 1) sb.append(sep);
        }
        return sb.toString();
    }
}

import java.io.*;
import java.util.Arrays;
import java.util.StringJoiner;
import java.util.StringTokenizer;
import java.util.function.Function;

public class Main {

    static int N;
    static int[] A;

    public static void main(String[] args) {
        FastScanner sc = new FastScanner(System.in);
        N = sc.nextInt();
        A = sc.nextIntArray(N);

        System.out.println(solve());
    }

    static long solve() {
        long[] C = new long[N+1];
        for (int i = 0; i < N; i++) {
            C[i+1] = A[i] + C[i];
        }
        // iから初めて右にいって帰ってくるコスト
        long[] RRET = new long[N+1];
        for (int i = N-1; i >= 0; i--) {
            int cost;
            if( A[i] == 0 ) {
                cost = 2;
            } else {
                cost = A[i]%2 == 0 ? 0 : 1;
            }

            RRET[i] = Math.min(RRET[i+1] + cost, C[N] - C[i]);
        }

        // iから初めて右に行って帰ってこないでもよいコスト
        long[] RGO = new long[N+1];
        for (int i = N-1; i >= 0; i--) {
            int cost;
            if( A[i] == 0 ) {
                cost = 1;
            } else {
                cost = A[i]%2 == 1 ? 0 : 1;
            }
            RGO[i] = Math.min(RGO[i+1] + cost, C[N] - C[i]);
            RGO[i] = Math.min(RGO[i], RRET[i]);
        }
        // debug(RGO, RRET);
        long[] LRET = new long[N+1];
        for (int i = 1; i <= N; i++) {
            int cost;
            if( A[i-1] == 0 ) {
                cost = 2;
            } else {
                cost = A[i-1]%2 == 0 ? 0 : 1;
            }
            LRET[i] = Math.min(LRET[i-1] + cost, C[i]);
        }
        long[] LGO = new long[N+1];
        for (int i = 1; i <= N; i++) {
            int cost;
            if( A[i-1] == 0 ) {
                cost = 1;
            } else {
                cost = A[i-1]%2 == 1 ? 0 : 1;
            }
            LGO[i] = Math.min(LGO[i-1] + cost, C[i]);
            LGO[i] = Math.min(LGO[i], LRET[i]);
        }
        // debug(LGO, LRET);


        long ans = Long.MAX_VALUE;
        for (int i = 0; i <= N; i++) {
            // debug(i, RRET[i] + LGO[i], LRET[i] + RGO[i]);
            ans = Math.min(ans, RRET[i] + LGO[i]);
            ans = Math.min(ans, LRET[i] + RGO[i]);
        }
        return ans;
    }

    @SuppressWarnings("unused")
    static class FastScanner {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        FastScanner(InputStream in) {
            reader = new BufferedReader(new InputStreamReader(in));
            tokenizer = null;
        }

        String next() {
            if (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        String nextLine() {
            if (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    return reader.readLine();
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken("\n");
        }

        long nextLong() {
            return Long.parseLong(next());
        }

        int nextInt() {
            return Integer.parseInt(next());
        }

        int[] nextIntArray(int n) {
            int[] a = new int[n];
            for (int i = 0; i < n; i++)
                a[i] = nextInt();
            return a;
        }

        int[] nextIntArray(int n, int delta) {
            int[] a = new int[n];
            for (int i = 0; i < n; i++)
                a[i] = nextInt() + delta;
            return a;
        }

        long[] nextLongArray(int n) {
            long[] a = new long[n];
            for (int i = 0; i < n; i++)
                a[i] = nextLong();
            return a;
        }
    }

    static <A> void writeLines(A[] as, Function<A, String> f) {
        PrintWriter pw = new PrintWriter(System.out);
        for (A a : as) {
            pw.println(f.apply(a));
        }
        pw.flush();
    }

    static void writeLines(int[] as) {
        PrintWriter pw = new PrintWriter(System.out);
        for (int a : as) pw.println(a);
        pw.flush();
    }

    static void writeLines(long[] as) {
        PrintWriter pw = new PrintWriter(System.out);
        for (long a : as) pw.println(a);
        pw.flush();
    }

    static int max(int... as) {
        int max = Integer.MIN_VALUE;
        for (int a : as) max = Math.max(a, max);
        return max;
    }

    static int min(int... as) {
        int min = Integer.MAX_VALUE;
        for (int a : as) min = Math.min(a, min);
        return min;
    }

    static void debug(Object... args) {
        StringJoiner j = new StringJoiner(" ");
        for (Object arg : args) {
            if (arg instanceof int[]) j.add(Arrays.toString((int[]) arg));
            else if (arg instanceof long[]) j.add(Arrays.toString((long[]) arg));
            else if (arg instanceof double[]) j.add(Arrays.toString((double[]) arg));
            else if (arg instanceof Object[]) j.add(Arrays.toString((Object[]) arg));
            else j.add(arg.toString());
        }
        System.err.println(j.toString());
    }
}

import java.util.Arrays;
import java.util.Scanner;

public class Main {

    void run() {

        Scanner sc = new Scanner(System.in);

        int l = sc.nextInt();
        int[] A = new int[l];
        for (int i = 0; i < l; i++) {
            A[i] = sc.nextInt();
        }

        // 0:<D, 1:D<=S, 2:S<=T, 3:T<=U, 4:U>
        long[][] dp = new long[l][5];
        dp[0][0] = A[0];
        dp[0][1] = add(1, A[0]);
        dp[0][2] = add(2, A[0]);
        dp[0][3] = add(3, A[0]);
        dp[0][4] = add(4, A[0]);
//        debug(dp[0]);

        for (int i = 1; i < l; i++) {
            dp[i][0] = dp[i - 1][0] + add(0, A[i]);
            dp[i][1] = min(dp[i - 1][0], dp[i - 1][1]) + add(1, A[i]);
            dp[i][2] = min(dp[i - 1][0], dp[i - 1][1], dp[i - 1][2]) + add(2, A[i]);
            dp[i][3] = min(dp[i - 1][0], dp[i - 1][1], dp[i - 1][2], dp[i - 1][3]) + add(3, A[i]);
            dp[i][4] = min(dp[i - 1][0], dp[i - 1][1], dp[i - 1][2], dp[i - 1][3], dp[i - 1][4]) + add(4, A[i]);
//            debug(dp[i]);
        }
        long ans = 1L << 50;
        for (int i = 0; i < 5; i++) {
            ans = Math.min(dp[l - 1][i], ans);
        }

        System.out.println(ans);
    }

    long min(long... vals) {
        return Arrays.stream(vals)
                .min()
                .getAsLong();
    }

    long add(int mode, int a) {
        switch (mode) {
            case 0:
            case 4:
                return a;
            case 1:
            case 3:
                if (a == 0) {
                    return 2;
                }
                return a % 2 == 0 ? 0 : 1;
            case 2:
                return a % 2 == 1 ? 0 : 1;
        }
