/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 */
public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        OutputWriter out = new OutputWriter(outputStream);
        D solver = new D();
        solver.solve(1, in, out);
        out.close();
    }

    static class D {
        public void solve(int testNumber, InputReader in, OutputWriter out) {
            int n = in.readInt();
            long[] a = in.readLongArray(n);

            int L = 0;
            while (L < n && a[L] == 0) {
                L++;
            }
            int R = n - 1;
            while (R >= 0 && a[R] == 0) {
                R--;
            }

            if (L >= R) {
                out.printLine(0);
                return;
            }

            long ans = 0;
            for (int i = L; i <= R; ) {
                if (a[i] == 0) {
                    ans++;
                    i++;
                } else {
                    int r = i;
                    while (r <= R && a[r] != 0) {
                        r++;
                    }
                    int odd = 0;
                    for (int j = i; j < r; j++) {
                        if (a[j] % 2 != 0) {
                            odd++;
                        }
                    }
                    ans += Math.max(0, odd - 2);
                    i = r;
                }
            }
            out.printLine(ans);
        }

    }

    static class OutputWriter {
        private final PrintWriter writer;

        public OutputWriter(OutputStream outputStream) {
            writer = new PrintWriter(new BufferedWriter(new OutputStreamWriter(outputStream)));
        }

        public OutputWriter(Writer writer) {
            this.writer = new PrintWriter(writer);
        }

        public void close() {
            writer.close();
        }

        public void printLine(long i) {
            writer.println(i);
        }

        public void printLine(int i) {
            writer.println(i);
        }

    }

    static class InputReader {
        private InputStream stream;
        private byte[] buf = new byte[1024];
        private int curChar;
        private int numChars;
        private InputReader.SpaceCharFilter filter;

        public InputReader(InputStream stream) {
            this.stream = stream;
        }

        public long[] readLongArray(int size) {
            long[] array = new long[size];
            for (int i = 0; i < size; i++) {
                array[i] = readLong();
            }
            return array;
        }

        public int read() {
            if (numChars == -1) {
                throw new InputMismatchException();
            }
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (numChars <= 0) {
                    return -1;
                }
            }
            return buf[curChar++];
        }

        public int readInt() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }
            int res = 0;
            do {
                if (c < '0' || c > '9') {
                    throw new InputMismatchException();
                }
                res *= 10;
                res += c - '0';
                c = read();
            } while (!isSpaceChar(c));
            return res * sgn;
        }

        public long readLong() {
            int c = read();
            while (isSpaceChar(c)) {
                c = read();
            }
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }
            long res = 0;
            do {
                if (c < '0' || c > '9') {
                    throw new InputMismatchException();
                }
                res *= 10;
                res += c - '0';
                c = read();
            } while (!isSpaceChar(c));
            return res * sgn;
        }

        public boolean isSpaceChar(int c) {
            if (filter != null) {
                return filter.isSpaceChar(c);
            }
            return isWhitespace(c);
        }

        public static boolean isWhitespace(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

        public interface SpaceCharFilter {
            public boolean isSpaceChar(int ch);

        }

    }
}

import java.util.Scanner;

public class Main {
	int L;
	long[] Ai = null;

	long[] totalLeftAi1 = null;
	long[] totalLeftAi2 = null;
	long[] totalRightAi2 = null;

	private void prepare() {
		Scanner in = new Scanner(System.in);
		L = in.nextInt();
		Ai = new long[L+1];
		for (int i=1; i<=L; i++) {
			Ai[i] = in.nextInt();
		}
		in.close();

		long totalLeftAi = 0;
		totalLeftAi1 = new long[L+1];
		totalLeftAi2 = new long[L+1];
		totalLeftAi1[0] = 0;
		totalLeftAi2[0] = 0;
		for (int i=1; i<=L; i++) {
			totalLeftAi += Ai[i];
			if (Ai[i] < 1) {
				totalLeftAi1[i] = totalLeftAi1[i-1] + (1 - Ai[i]);
			} else {
				totalLeftAi1[i] = totalLeftAi1[i-1] + (Ai[i] + 1) % 2;
			}
			if (Ai[i] < 2) {
				totalLeftAi2[i] = totalLeftAi2[i-1] + (2 - Ai[i]);
			} else {
				totalLeftAi2[i] = totalLeftAi2[i-1] + (Ai[i] % 2);
			}
			if (totalLeftAi2[i] > totalLeftAi) {
				totalLeftAi2[i] = totalLeftAi;
			}
		}

		long totalRightAi = 0;
		totalRightAi2 = new long[L+2];
		totalRightAi2[L+1] = 0;

		for (int i=L; i>=1; i--) {
			totalRightAi += Ai[i];
			if (Ai[i] < 2) {
				totalRightAi2[i] = totalRightAi2[i+1] + (2 - Ai[i]);
			} else {
				totalRightAi2[i] = totalRightAi2[i+1] + (Ai[i] % 2);
			}
			if (totalRightAi2[i] > totalRightAi) {
				totalRightAi2[i] = totalRightAi;
			}
		}

	}

	public long getCount(int left, int right) {
		return totalLeftAi2[left-1]
				+ totalLeftAi1[right]
				- totalLeftAi1[left]
				+ totalRightAi2[right+1];
	}

	public long solve() {
		prepare();
		long min = Long.MAX_VALUE;

		for (int i=1; i<=L; i++) {
			for (int j=i; j<=L; j++) {
				long count = getCount(i, j);
				if (min > count) {
					min = count;

					//System.out.println(left + "," + right + " : " + count);
				}
			}
		}
		return min;
	}

	public static void main(String[] args) {
		Main main = new Main();
		System.out.println(main.solve());
	}
}

