    void solve() {
        int n = ni();
        long a[] = new long[n];
        for (int i = 0; i < n; ++i) {
            a[i] = nl();
        }
        long dp[][] = new long[n + 1][5];
        for (int i = 0; i <= n; ++i) Arrays.fill(dp[i], Long.MAX_VALUE / 2);
        dp[0][0] = 0;
        for (int i = 0; i < n; ++i) {
            dp[i + 1][0] = min(dp[i][0]) + a[i];
            dp[i + 1][1] = min(dp[i][0], dp[i][1]) + (a[i] == 0 ? 2 : a[i] % 2);
            dp[i + 1][2] = min(dp[i][0], dp[i][1], dp[i][2]) + (a[i] == 0 ? 1 : 1 - a[i] % 2);
            dp[i + 1][3] = min(dp[i][2], dp[i][3]) + (a[i] == 0 ? 2 : a[i] % 2);
            dp[i + 1][4] = min(dp[i][1], dp[i][2], dp[i][3], dp[i][4]) + a[i];
        }
        out.println(min(dp[n]));
    }

