		for(int i=0; i<l; i++) a[i] = sc.nextInt();

		int[][] dp = new int[l+1][2];

		dp[0][0] = dp[0][1] = 0;
		for(int i=0; i<l; i++) {
			int c = Math.abs(a[i] -1) % 2;
			dp[i+1][0] = Math.min(dp[i][0] + c, dp[i][1]);
			dp[i+1][1] = dp[i][1] + a[i];
		}

        out.println(Math.min(dp[l][0], dp[l][1]));
    }
}

