			preEven[i] = preEven[i - 1];
			preSum[i] = preSum[i - 1];

			preOdd[i] += 1 - (a[i] % 2);

			if(a[i] == 0)
				preEven[i] += 2L;
			else
				preEven[i] += a[i] % 2;

			preSum[i] += a[i];

			preOdd[i] = min(preOdd[i], preSum[i]);
			preEven[i] = min(preEven[i], preSum[i]);
		}

		for(int i = n; i >= 1; i--) {

			sufOdd[i] = sufOdd[i + 1];
			sufEven[i] = sufEven[i + 1];
			sufSum[i] = sufSum[i + 1];

			sufOdd[i] += 1 - (a[i] % 2);

			if(a[i] == 0)
				sufEven[i] += 2L;
			else
				sufEven[i] += a[i] % 2;

			sufSum[i] += a[i];

			sufOdd[i] = min(sufOdd[i], sufSum[i]);
			sufEven[i] = min(sufEven[i], sufSum[i]);
