	static class TaskX {

		long[] a;
		public void solve(int testNumber, MyInput in, PrintWriter out) {

			int n = in.nextInt();
			a = in.nextLongArray(n);

			long[][] dp = new long[n+1][5];
			fill(dp, INF);
			for (int i = 0; i < 5; i++) {
				dp[0][i] = 0;
			}

			for (int i = 0; i < n; i++) {
				for (int j = 0; j < 5; j++) {
					for (int k = j; k < 5; k++) {
						dp[i+1][k] = Math.min(dp[i+1][k], dp[i][j] + cost(i, k));
					}
				}
			}

			long ans = INF;
			for (int i = 0; i < 5; i++) {
				ans = Math.min(ans, dp[n][i]);
			}
			out.println(ans);
		}

		long cost(int i, int k) {

			long ret = 0;
			if (k == 0 || k == 4) {
				ret = a[i];
			} else if (k == 1 || k == 3) {
				if (a[i] > 0) {
					if (a[i] % 2 == 0) {
						ret = 0;
					} else {
						ret = 1;
					}
				} else {
					ret = 2;
				}
			} else if (k == 2) {
				if (a[i] % 2 == 1) {
					ret = 0;
				} else {
					ret = 1;
				}
			}
			return ret;
		}
	}

	static void fill(long[][] a, long v) {
		for (int i = 0; i < a.length; i++) {
			for (int j = 0; j < a[0].length; j++) {
				a[i][j] = v;
			}
		}
