import java.util.StringTokenizer;
import java.io.IOException;
import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.io.InputStream;

/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 */
public class Main {
	public static void main(String[] args) {
		InputStream inputStream = System.in;
		OutputStream outputStream = System.out;
		FastScanner in = new FastScanner(inputStream);
		PrintWriter out = new PrintWriter(outputStream);
		D_Ears solver = new D_Ears();
		solver.solve(1, in, out);
		out.close();
	}

	static class D_Ears {
		public void solve(int testNumber, FastScanner in, PrintWriter out) {
			int n = in.nextInt();
			int[] a = new int[n];
			long[] s = new long[n + 1];
			long[] sEven = new long[n + 1];
			for (int i = 0; i < n; i++) {
				a[i] = in.nextInt();
				s[i + 1] = s[i] + a[i];
				sEven[i + 1] = sEven[i] + (a[i] % 2 == 0 ? 1 : 0);
			}

			long[] pref = new long[n];
			for (int i = 1; i < n; i++) {
				pref[i] = s[i];
				pref[i] = Math.min(pref[i], f(a[i - 1]) + pref[i - 1]);
			}

			long[] suff = new long[n];
			for (int i = n - 2; i >= 0; i--) {
				suff[i] = s[n] - s[i + 1];
				suff[i] = Math.min(suff[i], f(a[i + 1]) + suff[i + 1]);
			}

			long ans = Long.MAX_VALUE;
			long best = Long.MAX_VALUE;
			for (int i = 0; i < n; i++) {
				best = Math.min(best, -sEven[i] + pref[i]);
				ans = Math.min(ans, sEven[i + 1] + suff[i] + best);
				ans = Math.min(ans, suff[i] + pref[i] + f(a[i]));
			}
			ans = Math.min(ans, suff[0] + f(a[0]));
			ans = Math.min(ans, pref[n - 1] + f(a[n - 1]));

			out.println(ans);
		}

		private long f(int x) {
			x -= 2;
			if (x < 0) {
				return Math.abs(x);
			}
			return x % 2;
		}

	}

	static class FastScanner {
		private BufferedReader in;
		private StringTokenizer st;

		public FastScanner(InputStream stream) {
			in = new BufferedReader(new InputStreamReader(stream));
		}

		public String next() {
			while (st == null || !st.hasMoreTokens()) {
				try {
					String rl = in.readLine();
					if (rl == null) {
						return null;
					}
					st = new StringTokenizer(rl);
				} catch (IOException e) {
					throw new RuntimeException(e);
				}
			}
			return st.nextToken();
		}

		public int nextInt() {
			return Integer.parseInt(next());
		}

	}
}

import java.util.*;

public class Main {
    public static void main(String args[]) {
        Scanner sc = new Scanner(System.in);
        int l = sc.nextInt();
        int a[] = new int[l];
        int ce = 0;
        for (int i = 0;i < l;++i){
            a[i] = sc.nextInt();
            if((a[i] & 1) == 0)++ce;
        }
        long min = ce;
        for (int i = 0;i < l;++i){
            if(a[i] == 0)continue;
            for (int j = l;j > i;--j){
                if(a[j - 1] == 0)continue;
                long c = cost(a,i,j,ce);
                if(c == -1)break;
                else{
                    if(min > c)min = c;
                }
            }
        }
        System.out.println(min);

    }

    public static long cost(int[] arr,int start,int end,int ce){
        long c1 = 0;
        long c2 = 0;
        for (int i = 0;i < start;++i){
            c1 += arr[i];
        }
        for (int i = end;i < arr.length;++i){
            c1 += arr[i];
        }
        if(c1 >= ce)return -1;
        boolean b = false;
        for(int i = start;i < end;++i){
            if(!b && i < end - 1 && (arr[i] & 1) == 0 && (arr[i + 1] & 1) == 0)b = true;
            if(i == start || i == end - 1)continue;
            else{
                if(arr[i] == 0){
                    ++c2;
                }
                else if(arr[i] % 2 == 0){
                    ++c2;
                }
            }
        }
        return c1 + c2 + (b ? -1 : 0);
    }
}

