    void solve() {
        int n = ni();
        long a[] = new long[n], sum = 0;
        for (int i = 0; i < n; ++i) {
            a[i] = nl();
            sum += a[i];
        }
        long b[] = new long[n + 2];
        long e[] = new long[n + 2];
        for (int i = 0; i < n; ++i) {
            b[i + 1] = a[i] - (a[i] % 2 == 0 ? 1 : 0);
            e[n - i] = a[i] - (a[i] % 2 == 0 ? 1 : 0);
        }
        for (int i = 0; i <= n; ++i) {
            if (b[i] < 0) b[i] = 0;
            b[i + 1] += b[i];
            if (e[i] < 0) e[i] = 0;
            e[i + 1] += e[i];
        }
        long c[] = new long[n + 1];
        long d[] = new long[n + 1];
        for (int i = 0; i < n; ++i) {
            if (a[i] == 0) {
                c[i + 1] = -2;
                d[n - i] = -2;
            } else {
                c[i + 1] = a[i] - (a[i] % 2 == 1 ? 1 : 0);
                d[n - i] = a[i] - (a[i] % 2 == 1 ? 1 : 0);
            }
        }
        for (int i = 0; i < n; ++i) {
            if (c[i] < 0) c[i] = 0;
            c[i + 1] += c[i];
            if (d[i] < 0) d[i] = 0;
            d[i + 1] += d[i];
        }
        int r = 0, l = 0;
        long rv = 0, lv = 0;
        for (int i = 0; i <= n; ++i) {
            if (rv < c[i] - b[i]) {
                rv = c[i] - b[i];
                r = i;
            }
            if (lv < d[i] - e[i]) {
                lv = d[i] - e[i];
                l = i;
            }
        }
        long result = 0;
        for (int i = 0; i < n; ++i) {
            if (r + l <= n) {
                result = Math.max(result,
                        c[r] + d[l] + b[n - l] - b[r]
                );
            }
            result = Math.max(result, c[i] + d[n - i]);
        }
        out.println(sum - result);
    }

