		int back, fore;
		public void solve(int testNumber, MyInput in, PrintWriter out) {

			int l = in.nextInt();
			long[] a = in.nextLongArray(l);
			int n = a.length;
			long[] arev = new long[n];
			for (int i = 0; i < n; i++) {
				arev[n-1-i] = a[i];
			}
			back = 0;
			fore = 0;
			for (int i = a.length-1; i >= 0; i--) {
				if (a[i] == 0) {
					back++;
				} else {
					break;
				}
			}

			for (int i = 0; i < a.length; i++) {
				if (a[i] == 0) {
					fore++;
				} else {
					break;
				}
			}

			long ng = -1, ok = LINF;
			while (ok - ng > 1) {
				long k = (ok + ng) / 2;

				if (check(k, a.clone()) || check2(k, arev.clone())) {
					ok = k;
				} else {
					ng = k;
				}
			}

			out.println(ok);

		}

		// k 回の操作で条件を満たすことが可能かどうか
		boolean check(long k, long[] a) {
			int n = a.length;

			// 追加で操作した回数
			long cnt = 0;

			// 消した石の数の合計
			long total = 0;

			// 消すべき石の合計数
			long sum = Arrays.stream(a).sum();

			boolean add = false;
			boolean add2 = false;
			for (int i = 0; i < n-1; i++) {
				if (a[i] == 0 || a[i+1] == 0) continue;
				if (a[i] % 2 == 0 && a[i+1] % 2 == 0) {
					add2 = true;
				}
			}
			for (int i = n-1-back; i >= 0; i--) {
				if (a[i] % 2 == 0) add = true;
				if (a[i] % 2 == 0) {
					cnt++;
					total += a[i];
				} else {
					total += a[i];
				}

				long rev = sum - total;
				if (k - cnt + Math.max((add ? 1 : 0), (add2 ? 2 : 0)) >= rev) {
					return true;
				}
			}
			return false;
		}


		// k 回の操作で条件を満たすことが可能かどうか
		boolean check2(long k, long[] a) {
			int n = a.length;

			// 追加で操作した回数
			long cnt = 0;

