			for (int i = n-1-fore; i >= 0; i--) {
				if (a[i] % 2 == 0) add = true;
				if (a[i] == 0) {
					cnt++;
				} else if (a[i] % 2 == 0) {
					cnt++;
					total += a[i];
				} else {
					total += a[i];
				}

				long rev = sum - total;
				if (k - cnt + Math.max((add ? 1 : 0), (add2 ? 2 : 0)) >= rev) {
					return true;
				}
			}
			return false;
		}
