    // 0:2way 1:1way
    long[][] dp = new long[l + 1][5];
    for (long[] v : dp)
      Arrays.fill(v, Long.MAX_VALUE / 2);
    Arrays.fill(dp[0], 0);

    for (int i = 1; i <= l; i++) {
      int v = a[i - 1];

      long z = v == 0 ? 2 : 0;
