public class Main {
    public static void main(String args[]) {
        try (Scanner in = new Scanner(System.in)) {
            int L = in.nextInt();
            int[] A = new int[L];
            for (int i = 0; i < L; i++) {
                A[i] = in.nextInt();
//                A[i] = A[i] % 2 == 0 ? (A[i] == 0 ? 0 : 2) : 1;
            }

            long[][] dp = new long[L + 1][5];
            for (int i = 0; i <= L; i++) {
                if (i == 0) {
                    dp[i][0] = A[i];
                    dp[i][1] = (A[i] == 0 ? 0 : (A[i] % 2 == 0 ? 0 : 1));
                    dp[i][2] = (A[i] == 0 ? 0 : (A[i] % 2 == 0 ? 1 : 0));
                    dp[i][3] = (A[i] == 0 ? 0 : (A[i] % 2 == 0 ? 0 : 1));
                    dp[i][4] = A[i];
//                    Utils.debug("dp[" + i + "]", dp[i]);
                    continue;
                }
                for (int j = 0; j < 5; j++) {
                    if (j == 0) {
                        dp[i][j] = (i < L ? A[i] : 0) + dp[i - 1][j];
                    } else if (j == 1) {
                        dp[i][j] = (i < L ? (A[i] == 0 ? 2 : (A[i] % 2 == 0 ? 0 : 1)) : 0) + Math.min(dp[i - 1][j], dp[i - 1][0]);
                    } else if (j == 2) {
                        dp[i][j] = (i < L ? (A[i] == 0 ? 1 : (A[i] % 2 == 0 ? 1 : 0)) : 0) + Math.min(dp[i - 1][j], Math.min(dp[i - 1][1], dp[i - 1][0]));
                    } else if (j == 3) {
                        dp[i][j] = (i < L ? (A[i] == 0 ? 2 : (A[i] % 2 == 0 ? 0 : 1)) : 0) + Math.min(Math.min(dp[i - 1][3], dp[i - 1][2]), Math.min(dp[i - 1][1], dp[i - 1][0]));
                    } else if (j == 4) {
                        dp[i][j] = (i < L ? A[i] : 0) + Math.min(dp[i - 1][4], Math.min(Math.min(dp[i - 1][3], dp[i - 1][2]), Math.min(dp[i - 1][1], dp[i - 1][0])));
                    }
                }
//                Utils.debug("dp[" + i + "]", dp[i]);
            }

            System.out.println(dp[L][4]);
        }
    }
}

import java.io.*;
import java.util.*;

public class Main {
    private static InputStream is;
    private static PrintWriter out;
    private static String INPUT = "";

    void solve() {
        int n = ni();
        long a[] = new long[n], sum = 0;
        for (int i = 0; i < n; ++i) {
            a[i] = nl();
            sum += a[i];
        }
        long b[] = new long[n + 1];
        long e[] = new long[n + 1];
        for (int i = 0; i < n; ++i) {
            b[i + 1] = a[i] - (a[i] % 2 == 0 ? 1 : 0);
            e[n - i] = a[i] - (a[i] % 2 == 0 ? 1 : 0);
        }
        for (int i = 0; i < n; ++i) {
            if (b[i] < 0) b[i] = 0;
            b[i + 1] += b[i];
            if (e[i] < 0) e[i] = 0;
            e[i + 1] += e[i];
        }
        long c[] = new long[n + 1];
        long d[] = new long[n + 1];
        for (int i = 0; i < n; ++i) {
            if (a[i] == 0) {
                c[i + 1] = -2;
                d[n - i] = -2;
            } else {
                c[i + 1] = a[i] - (a[i] % 2 == 1 ? 1 : 0);
                d[n - i] = a[i] - (a[i] % 2 == 1 ? 1 : 0);
            }
        }
        for (int i = 0; i < n; ++i) {
            if (c[i] < 0) c[i] = 0;
            c[i + 1] += c[i];
            if (d[i] < 0) d[i] = 0;
            d[i + 1] += d[i];
        }
        int r = 0, l = 0;
        long rv = 0, lv = 0;
        for (int i = 0; i <= n; ++i) {
            if (rv < c[i] - b[i]) {
                rv = c[i] - b[i];
                r = i;
            }
            if (lv < d[i] - e[i]) {
                lv = d[i] - e[i];
                l = i;
            }
        }
        long result = 0;
        for (int i = 0; i < n; ++i) {
            if (r <= n - l) {
                result = Math.max(result, c[r] + d[l] + b[n - l] - b[r]);
            }
            result = Math.max(result, c[i] + d[n - i]);
            result = Math.max(result, b[i] + e[n - i]);
        }
        out.println(sum - result);
    }

    public static void main(String[] args) throws Exception {
        is = INPUT.isEmpty() ? System.in : new ByteArrayInputStream(INPUT.getBytes());
        out = new PrintWriter(System.out);
        new Main().solve();
        out.flush();
    }

    private static boolean eof() {
        if (lenbuf == -1) return true;
        int lptr = ptrbuf;
        while (lptr < lenbuf)
            if (!isSpaceChar(inbuf[lptr++])) return false;

        try {
            is.mark(1000);
            while (true) {
                int b = is.read();
                if (b == -1) {
                    is.reset();
                    return true;
                } else if (!isSpaceChar(b)) {
                    is.reset();
                    return false;
                }
            }
        } catch (IOException e) {
            return true;
        }
    }

    private static byte[] inbuf = new byte[1024];
    static int lenbuf = 0, ptrbuf = 0;

    private static int readByte() {
        if (lenbuf == -1) throw new InputMismatchException();
        if (ptrbuf >= lenbuf) {
            ptrbuf = 0;
            try {
                lenbuf = is.read(inbuf);
            } catch (IOException e) {
                throw new InputMismatchException();
            }
            if (lenbuf <= 0) return -1;
        }
        return inbuf[ptrbuf++];
    }

    private static boolean isSpaceChar(int c) {
        return !(c >= 33 && c <= 126);
    }

    private static int skip() {
        int b;
        while ((b = readByte()) != -1 && isSpaceChar(b))
            ;
        return b;
    }

