/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 */
public class Main {
	public static void main(String[] args) {
		InputStream inputStream = System.in;
		OutputStream outputStream = System.out;
		FastScanner in = new FastScanner(inputStream);
		PrintWriter out = new PrintWriter(outputStream);
		D_Ears solver = new D_Ears();
		solver.solve(1, in, out);
		out.close();
	}

	static class D_Ears {
		public void solve(int testNumber, FastScanner in, PrintWriter out) {
			int n = in.nextInt();
			int[] a = new int[n];
			long[] s = new long[n + 1];
			long[] sEven = new long[n + 1];
			for (int i = 0; i < n; i++) {
				a[i] = in.nextInt();
				s[i + 1] = s[i] + a[i];
				sEven[i + 1] = sEven[i] + (a[i] % 2 == 0 ? 1 : 0);
			}

			long[] pref = new long[n];
			for (int i = 1; i < n; i++) {
				pref[i] = Math.min(s[i], f(a[i - 1]) + pref[i - 1]);
			}

			long[] suff = new long[n];
			for (int i = n - 2; i >= 0; i--) {
				suff[i] = Math.min(s[n] - s[i + 1], f(a[i + 1]) + suff[i + 1]);
			}

			long ans = Long.MAX_VALUE;
			long best = Long.MAX_VALUE;
			for (int i = 0; i < n; i++) {
				best = Math.min(best, -sEven[i] + pref[i]);
				ans = Math.min(ans, sEven[i + 1] + suff[i] + best);
				ans = Math.min(ans, suff[i] + pref[i] + f(a[i]));
			}

			out.println(ans);
		}

		private long f(int x) {
			x -= 2;
			if (x < 0) {
				return Math.abs(x);
			}
			return x % 2;
		}

	}

	static class FastScanner {
		private BufferedReader in;
		private StringTokenizer st;

		public FastScanner(InputStream stream) {
			in = new BufferedReader(new InputStreamReader(stream));
		}

		public String next() {
			while (st == null || !st.hasMoreTokens()) {
				try {
					String rl = in.readLine();
					if (rl == null) {
						return null;
					}
					st = new StringTokenizer(rl);
				} catch (IOException e) {
					throw new RuntimeException(e);
				}
			}
			return st.nextToken();
		}

		public int nextInt() {
			return Integer.parseInt(next());
		}

	}
}

import java.util.*;
public class Main{
	public static void main(String[] args){
		int ans = 0;
		Scanner sc = new Scanner(System.in);
		int l = sc.nextInt();
		int[] stones = new int[l];
		int[] stones2 = new int[l];
		for(int i=0; i<l; i++){
			stones[i] = sc.nextInt();
			stones2[i] = stones[i] % 2;
		}

		int s = 0;
		int e = l-1;
		for(int i=1; i<l-1; i++){
			if(stones[i] == 0){
				int zeronum = 0;
				int j = i;
				while(stones[j] == 0){
					zeronum++;
					j++;
					if(j == l){
						break;
					}
				}
				int before = getsnum(stones, 0, i);
				int after = getsnum(stones, j, l-1);
				int[] stonesc = stones2;
				for(int k=i; k<j; k++){
					stonesc[k]++;
				}
				int cscore = getscore(stonesc, 0,l-1);
				if(cscore >= before + getscore(stones2, j, l-1)){
					ans = before;
					s = j;
				}
				else if(cscore >= after + getscore(stones2, 0, i)){
					ans = after;
					e = j;
					if(e == l){
						e--;
					}
				}
				else{
					ans += zeronum;
					for(int k=i; k<j; k++){
						stones[k]++;
						stones2[k]++;
					}
				}
				i = j-1;
			}
		}

		ans += getscore(stones2, s, e);

		System.out.println(ans);
	}

	public static int getscore(int[] stones, int s, int e){
		int allodd = 0;
		int maxodd = 0;
		int odd = 0;
		for(int i=s; i<=e; i++){
			if(stones[i] == 1){
				allodd++;
				odd++;
			}
			else{
				if(maxodd < odd){
					maxodd = odd;
				}
				odd = 0;
			}
		}
		if(maxodd < odd){
			maxodd = odd;
		}
		return allodd - maxodd;
	}

	public static int getsnum(int[] stones, int s, int e){
		int num = 0;
		for(int i=s; i<=e; i++){
			num += stones[i];
		}
		return num;
	}
}

