			preEven[i] = preEven[i - 1];
			preSum[i] = preSum[i - 1];

			preOdd[i] += 1 - a[i] % 2;
			preEven[i] += (a[i] == 0) ? 2L : a[i] % 2;
			preSum[i] += a[i];

			preOdd[i] = min(preOdd[i], preSum[i]);
			preEven[i] = min(preEven[i], preSum[i]);
