		for(int i = n; i >= 1; i--) {

			sufOdd[i] = sufOdd[i + 1];
			sufEven[i] = sufEven[i + 1];
			sufSum[i] = sufSum[i + 1];

			sufOdd[i] += 1 - a[i] % 2;
			sufEven[i] += (a[i] == 0) ? 2 : a[i] % 2;
			sufSum[i] += a[i];

			sufOdd[i] = min(sufOdd[i], sufSum[i]);
