namespace MinPro2019D
{
    public class Program
    {
        static readonly Stream stream = Console.OpenStandardInput(1024);
        static readonly byte[] buffer = new byte[1024];
        static int index;
        static int length;
        static int L;
        static readonly long[] dp = new long[5];
        static long A;
        static long x;

        static void Main()
        {
            length = stream.Read(buffer, 0, 1024);

            while (48 <= buffer[index] && buffer[index] <= 57)
            {
                L = L * 10 + buffer[index] - 48;
                ++index;
                if (index < length) continue;
                index = 0;
                length = stream.Read(buffer, 0, 1024);
            }

            for (int i = 0; i < L; i++)
            {
                A = 0;

                while (buffer[index] < 48 || 57 < buffer[index])
                {
                    ++index;
                    if (index < length) continue;
                    index = 0;
                    length = stream.Read(buffer, 0, 1024);
                }

                while (48 <= buffer[index] && buffer[index] <= 57)
                {
                    A = A * 10 + buffer[index] - 48;
                    ++index;
                    if (index < length) continue;
                    index = 0;
                    length = stream.Read(buffer, 0, 1024);
                }

                x = A == 0 ? 2 : A & 1;

                dp[0] += A;
                dp[1] += x;
                dp[2] += (x & 1) ^ 1;
                dp[3] += x;
                dp[4] += A;
                dp[1] = Math.Min(dp[1], dp[0]);
                dp[2] = Math.Min(dp[2], dp[1]);
                dp[3] = Math.Min(dp[3], dp[2]);
                dp[4] = Math.Min(dp[4], dp[3]);
            }

            Console.WriteLine(dp[4].ToString());
        }
