class Program
{
    static void Main(string[] args)
    {
        String line;
        line = Console.ReadLine();
        int L = int.Parse(line);
        int[] mimi = new int[L];
        for(int i = 0; i < L; i++)
        {
            line = Console.ReadLine();
            mimi[i] = int.Parse(line);
        }
        int min = 1000000000;
        for(int i = 0; i <= L; i++)
        {
            int mimi_1 = 0;
            int mimi_2 = 0;
            bool flag_kisu_saisyo = true; //奇数を求めている側（つまり偶数で＋する側）の最初の1回は消せる
            //奇数＋偶数の数え方
            //まずはどこまで調べるか？決める
            int hidari = 0;
            int hidari_sum = 0;
            for(int j = 0; j < i; j++)
            {
                hidari = j;
                hidari_sum += mimi[j];
                if (hidari_sum > i - j)
                {
                    hidari_sum -= mimi[j];
                    mimi_1 += hidari_sum;
                    mimi_2 += hidari_sum;
                    break;
                }
            }
            for(int j = hidari; j < i; j++)
            {
                if (mimi[j] == 0)
                {
                    mimi_1 += 1;
                    mimi_2 += 2;
                }
                else if (mimi[j] % 2 == 0)
                {
                    if (flag_kisu_saisyo) flag_kisu_saisyo = false;
                    else mimi_1 += 1;
                }
                else
                {
                    flag_kisu_saisyo = false;
                    mimi_2 += 1;
                }
            }
            flag_kisu_saisyo = true;
            int migi = L - 1;
            int migi_sum = 0;
            for (int j = L - 1; j >= i; j--)
            {
                migi = j;
                migi_sum += mimi[j];
                if (migi_sum > j - i)
                {
                    migi_sum -= mimi[j];
                    mimi_1 += migi_sum;
                    mimi_2 += migi_sum;
                    break;
                }
            }
            for (int j = migi; j >= i; j--)
            {
                if (mimi[j] == 0)
                {
                    mimi_2 += 1;
                    mimi_1 += 2;
                }
                else if(mimi[j] % 2 == 0)
                {
                    if (flag_kisu_saisyo) flag_kisu_saisyo = false;
                    else  mimi_2 += 1;
                }
                else
                {
                    flag_kisu_saisyo = false;
                    mimi_1 += 1;
                }
            }
            if (min > mimi_1) min = mimi_1;
            if (min > mimi_2) min = mimi_2;
        }

        Console.WriteLine(min);
    }
}

