                    if (s == 0 || s == 4) dp[i + 1, s] = Min(dp[i + 1, s], dp[i, s] + A[i]);
                    else if (s == 2) { dp[i + 1, s] = Min(dp[i + 1, s], dp[i, s] + (A[i] + 1) % 2); }
