using System.Numerics;

public class Program
{
    public static void Main(string[] args)
    {
        //string[] line = Console.ReadLine().Split(' ');

        long N = long.Parse(Console.ReadLine());
        long[] v = new long[N];
        for (long i = 0; i < v.Length; i++)
        {
            v[i] = long.Parse(Console.ReadLine());
        }

        long[,] dp = new long[N + 1, 5];
        for (long x = 0; x < dp.GetLength(0); x++)
        {
            for (long y = 0; y < dp.GetLength(1); y++)
            {
                dp[x, y] = long.MaxValue;
            }
        }

        for (long i = 0; i < 5; i++)
        {
            dp[0, i] = 0;
        }

        for (long i = 0; i < N; i++)
        {
            long cost1 = v[i];
            dp[i + 1, 0] = Math.Min(dp[i + 1, 0], dp[i, 0] + cost1);

            long cost2 = (v[i] == 0) ? 2 : v[i] % 2;
            long min2 = (new long[] { dp[i, 0], dp[i, 1] }).Min();
            dp[i + 1, 1] = Math.Min(dp[i + 1, 1], min2 + cost2);

            long cost3 = (v[i] == 0) ? 1 : ((v[i] % 2 == 0) ? 1 : 0);
            long min3 = (new long[] { dp[i, 0], dp[i, 1], dp[i, 2] }).Min();
            dp[i + 1, 2] = Math.Min(dp[i + 1, 2], min3 + cost3);

            long cost4 = (v[i] == 0) ? 2 : v[i] % 2;
            long min4 = (new long[] { dp[i, 0], dp[i, 1], dp[i, 2], dp[i, 3] }).Min();
            dp[i + 1, 3] = Math.Min(dp[i + 1, 3], min4 + cost4);

            long cost5 = v[i];
            long min5 = (new long[] { dp[i, 0], dp[i, 1], dp[i, 2], dp[i, 3], dp[i, 4] }).Min();
            dp[i + 1, 4] = Math.Min(dp[i + 1, 4], min5 + cost5);
        }

        long ans = long.MaxValue;

        for (long i = 0; i < 5; i++)
        {
            ans = Math.Min(ans, dp[N, i]);
        }


        Console.WriteLine(ans);
        Console.ReadLine();
    }
}

