    //by Camypaperさん 
    public class SimpleScanner
    {
        const int DefaultCapacity = 1024;

        readonly Stream stream;
        readonly int capacity;
        readonly byte[] buffer;

        int index = 0;
        int length = 0;
        bool isEof = false;

        public SimpleScanner(Stream stream, int capacity = DefaultCapacity)
        {
            this.stream = stream;
            this.capacity = capacity;
            this.buffer = new byte[capacity];
        }

        void Reload()
        {
            if (isEof) throw new EndOfStreamException();
            index = 0;
            length = stream.Read(buffer, 0, capacity);
            isEof = length <= 0;
        }

        int Peek()
        {
            if (index < length) return buffer[index];
            Reload();
            return Peek();
        }

        int Read()
        {
            var ret = Peek();
            index++;
            return ret;
        }

        bool IsInputable(int b)
        {
            return 33 <= b && b <= 126;
        }

        public T Next<T>(Func<string, T> parser)
        {
            var sb = new StringBuilder();
            while (!IsInputable(Peek())) Read();
            while (IsInputable(Peek())) sb.Append((char)Read());
            return parser(sb.ToString());
        }
    }
}

using System;
