using System.Linq;

class Program
{
    static void Main(string[] args)
    {
        var L = ReadInt();
        var A = new long[L];
        var even = new bool[L];
        for (var i = 0; i < L; i++)
        {
            A[i] = ReadLong();
            even[i] = A[i] % 2L == 0;
        }

        if (even.All(_ => !_)) { Console.WriteLine(0); return; }

        int startIdx = 0;
        int endIdx = L - 1;

        for (var i = 0; i < L; i++)
        {
            if (!even[i]) continue;

            var isBackwardLoss = JudgeIfLoss(A.Take(i), even.Take(i));
            if (isBackwardLoss) { startIdx = i; }

            var isForwardLoss = JudgeIfLoss(A.Skip(i + 1), even.Skip(i + 1));
            if (isForwardLoss) { endIdx = i; break; }
        }

        var countOfEvenInAnsSection = even.Take(endIdx + 1).Skip(startIdx).Count(_ => _);

        var answer = A.Take(startIdx).Sum()
            + Math.Max(0, countOfEvenInAnsSection - 2)
            + A.Skip(endIdx + 1).Sum()
            ;


        Console.WriteLine($"s:{startIdx}, e:{endIdx}");
        Console.WriteLine(answer);
    }

    private static bool JudgeIfLoss(IEnumerable<long> list, IEnumerable<bool> even)
    {
        var gain = list.Sum();
        var loss = even.Count(_ => _);

        return gain <= loss + 1; // 引き返す分
    }

