        int right_ind = l;
        for (int i = l - 1; i >= 0; i--)
        {
            if (max < sum[i])
            {
                max = sum[i];
                right_ind = i;
            }
        }
        for (int i = l - 1; i >= right_ind; i--)
        {
            ans += a[i];
            a[i] = 0;
        }
        //残ったaを0,1に置き換える
        for (int i = 0; i < l; i++)
            if (a[i] > 0)
                a[i] = a[i] % 2;
        //答えの計算
        int one_l = 0; //連続した1の最大長さ
        int temp = 0;
        for (int i = 0; i < l; i++)
        {
            if (a[i] == 0)
            {
                one_l = Math.Max(one_l, temp);
                temp = 0;
            }
            else
            {
                temp++;
            }
        }
        one_l = Math.Max(one_l, temp);
        ans += a.Sum() - one_l;
        Console.WriteLine(ans);
    }
}

