    //ref: https://qiita.com/Camypaper/items/de6d576fe5513743a50e#%E5%85%A5%E5%8A%9B%E3%81%AE%E9%AB%98%E9%80%9F%E5%8C%96
    //by Camypaperさん 
    public class SimpleScanner
    {
        const int DefaultCapacity = 1024;

        readonly Stream stream;
        readonly int capacity;
        readonly byte[] buffer;
        readonly char[] chars;

        int index = 0;
        int length = 0;
        bool isEof = false;

        public SimpleScanner(Stream stream, int capacity = DefaultCapacity)
        {
            this.stream = stream;
            this.capacity = capacity;
            this.buffer = new byte[capacity];
            this.chars = new char[capacity];
        }

        void Reload()
        {
            index = 0;
            length = stream.Read(buffer, 0, capacity);
            isEof = length <= 0;
        }

        void CheckBuffer()
        {
            if (index < length) return;
            if (isEof) throw new EndOfStreamException();
            Reload();
            CheckBuffer();
        }

        byte Peek()
        {
            CheckBuffer();
            return buffer[index];
        }

        byte Read()
        {
            CheckBuffer();
            return buffer[index++];
        }

        bool CanInput(int b)
        {
            return 33 <= b && b <= 126;
        }

        public unsafe string Next()
        {
            var ptr = 0;
            while (!CanInput(Peek())) Read();
            while (CanInput(Peek())) chars[ptr++] = (char)Read();
            chars[ptr] = '\0';

            fixed (char* chPtr = chars)
            {
                return new string(chPtr);
            }
        }
    }
}

