            int l = ReadInt();
            int[] array = new int[l];
            for(int i = 0; i < l; i++)
            {
                array[i] = ReadInt();
            }
            //必要な操作数
            long[] inLeftOutLeft = new long[l];//i以降すべて
            long[] inLeftOutRight = new long[l];
            long[] inRightOutLeft = new long[l];//i以前すべて
            long[] inRightOutRight = new long[l];

            long[] all = new long[l];
            all[0] = array[0];
            for (long i = 1; i < l; i++) all[i] = all[i - 1] + array[i];

            for (int i = l-1; i >=0; i--)
            {
                if (array[i] == 0)
                {
                    inLeftOutLeft[i] = 2;
                    inLeftOutRight[i] = 1;
                }
                else
                {
                    inLeftOutLeft[i] = array[i] % 2 == 0 ? 0 : 1;
                    inLeftOutRight[i] = array[i] % 2 == 0 ? 1 : 0;
                }
                if (i + 1 < l)
                {
                    inLeftOutLeft[i] += inLeftOutLeft[i + 1];
                    inLeftOutRight[i] += inLeftOutRight[i + 1];
                }
            }
            for(int i = 0; i < l; i++)
            {
                if (array[i] == 0)
                {
                    inRightOutLeft[i] = 1;
                    inRightOutRight[i] = 2;
                }
                else
                {
                    inRightOutLeft[i] = array[i] % 2 == 0 ? 1 : 0;
                    inRightOutRight[i] = array[i] % 2 == 0 ? 0 : 1;
                }
                if (i - 1 >= 0)
                {
                    inRightOutLeft[i] += inRightOutLeft[i - 1];
                    inRightOutRight[i] +=inRightOutRight[i - 1];
                }
            }

            for(int i = 0; i < l; i++)
            {
                long allPtr = all[l - 1];
                if (i > 0) allPtr -= all[i-1];
                inLeftOutLeft[i] = Math.Min(inLeftOutLeft[i], allPtr);
                inLeftOutRight[i] = Math.Min(inRightOutRight[i], all[i]);
            }

            long res = int.MaxValue;
            for (int i = 0; i < l + 1; i++)
            {
                long val = 0;
                if (i == 0)
                {
                    val = Math.Min(inLeftOutLeft[i], inLeftOutRight[i]);
                }
                else if (i == l)
                {
                    val = Math.Min(inRightOutLeft[i-1], inRightOutRight[i-1]);
                }
                else
                {
                    val = Math.Min(inLeftOutLeft[i] + Math.Min(inRightOutRight[i - 1], inRightOutLeft[i - 1]),
                        inRightOutRight[i - 1] + Math.Min(inLeftOutLeft[i], inLeftOutRight[i]));
                }
                //Console.WriteLine(val);
                res = Math.Min(res, val);
            }
            Console.WriteLine(res);
        }

