	// DP
	public class Solver : SolverBase
	{
		public void Run() {
			var L = ReadInt();

			// 1-indexedにする
			var Nums = new int[L+1];
			for (int i = 1; i <= L; i++) {
				Nums[i] = ReadInt();
			}

			// 開始点(S)〜終了点(E)、左端(L)〜右端(R) とした場合の石の個数
			//     L       S     E    R
			// 0 0 偶 偶 偶 奇 奇 奇 偶 偶 0 0 0
			// ~~~ ~~~~~~~ ~~~~~~~ ~~~~ ~~~~~
			// t0  t1      t2      t3   t4
			// それぞれの範囲を t0, t1, t2, t3, t4 とする。

			// DP[i][t] = i番目(1-)が範囲tの場合、そこまでの最小操作回数
			var DP = new long[L+1, 5];

			for (int i = 1; i <= L; i++) {
				// t:0
				DP[i, 0] = DP[i - 1, 0] + Nums[i];

				// t:1
				var lastMin = Math.Min(DP[i - 1, 0], DP[i - 1, 1]);
				if (Nums[i] == 0) {
					DP[i, 1] = lastMin + 2;
				} else if (Nums[i] % 2 == 1) {
					DP[i, 1] = lastMin + 1;
				} else if (Nums[i] % 2 == 0) {
					DP[i, 1] = lastMin;
				}

				// t:2
				lastMin = Math.Min(lastMin, DP[i - 1, 2]);
				if (Nums[i] == 0) {
					DP[i, 2] = lastMin + 1;
				} else if (Nums[i] % 2 == 1) {
					DP[i, 2] = lastMin;
				} else if (Nums[i] % 2 == 0) {
					DP[i, 2] = lastMin + 1;
				}

				// t:3
				lastMin = Math.Min(lastMin, DP[i - 1, 3]);
				if (Nums[i] == 0) {
					DP[i, 3] = lastMin + 2;
				} else if (Nums[i] % 2 == 1) {
					DP[i, 3] = lastMin + 1;
				} else if (Nums[i] % 2 == 0) {
					DP[i, 3] = lastMin;
				}

				// t:4
				lastMin = Math.Min(lastMin, DP[i - 1, 4]);
				DP[i, 4] = lastMin + Nums[i];
			}

			WriteLine(Min(DP[L, 0], DP[L, 1], DP[L, 2], DP[L, 3], DP[L, 4]));
		}

