    public class SimpleScanner
    {
        const int DefaultCapacity = 1024;

        readonly Stream stream;
        readonly int capacity;
        readonly byte[] buffer;
        readonly List<char> chars;

        byte last = 0;
        int index = 0;
        int length = 0;

        public SimpleScanner(Stream stream, int capacity = DefaultCapacity)
        {
            this.stream = stream;
            this.capacity = capacity;
            this.buffer = new byte[capacity];
            this.chars = new List<char>();

            this.length = stream.Read(buffer, 0, capacity);
        }

        void Reload()
        {
            last = buffer[index - 1];
            index = 0;
            length = stream.Read(buffer, 0, capacity);
        }

        bool CheckBuffer()
        {
            if (length <= 0) return false;
            if (index < length) return true;
            Reload();
            return CheckBuffer();
        }

        byte Prev()
        {
            return index == 0 ? last : buffer[index - 1];
        }

        byte Peek()
        {
            return CheckBuffer() ? buffer[index] : (byte)0;
        }

        byte Read()
        {
            return CheckBuffer() ? buffer[index++] : (byte)0;
        }

        bool CanPeekInput()
        {
            byte b = Peek();
            return 33 <= b && b <= 126;
        }

        bool IsPeekNumber()
        {
            byte b = Peek();
            return 48 <= b && b <= 57;
        }

        public string Next()
        {
            chars.Clear();

            while (!CanPeekInput())
            {
                Read();
            }

            while (CanPeekInput())
            {
                chars.Add((char)Read());
            }

            return new string(chars.ToArray());
        }

        public int NextInt()
        {
            return (int)NextLong();
        }

        public long NextLong()
        {
            long ret = 0;

            while (!IsPeekNumber())
            {
                Read();
            }

            byte sign = Prev();

            while (IsPeekNumber())
            {
                ret = ret * 10 + Read() - 48;
            }

            return sign == 45 ? -ret : ret;
        }

        public double NextDouble()
        {
            long integerPart = NextLong();

            if (Peek() == 46)
            {
                Read();
            }

            if (!IsPeekNumber())
            {
                return integerPart;
            }

            double decimalPart = 0.0, place = 1.0;

            while (IsPeekNumber())
            {
                decimalPart += (Read() - 48) * (place /= 10.0);
            }

            return integerPart + (integerPart < 0 ? -decimalPart : decimalPart);
        }
    }
}

