        public static void Main(string[] args)
        {
            var ct = int.Parse(Console.ReadLine());
            var intList = new List<int>();
            for(int i = 0; i < ct; i++)
            {
                intList.Add(int.Parse(Console.ReadLine()));
            }

            var result = int.MaxValue;
            for(int index=0;index < ct; index++)
            {
                var noOddBefore = intList.Take(index).Count(x => x % 2 == 0);
                var noEvenAfter = intList.Skip(index).Count(x => x % 2 == 1);

                var noEvenBefore = intList.Take(index + 1).Count(x => x % 2 == 1);
                var noOddAfter = intList.Skip(index + 1).Count(x => x % 2 == 0);

                var ret = Math.Min(noOddBefore + noEvenAfter, noEvenBefore + noOddAfter);
                result = Math.Min(result, ret);
            }

            result += intList.Count(x => x == 0);
            Console.WriteLine(result);
        }
    }
