        {
            if (isEof) throw new EndOfStreamException();

            chars.Clear();
            while (!CanInput()) Read();
            while (CanInput()) chars.Add((char)Read());
            return new string(chars.ToArray());
        }

        public int NextInt()
        {
            if (isEof) throw new EndOfStreamException();

            return (int)NextLong();
        }

        public long NextLong()
        {
            if (isEof) throw new EndOfStreamException();

            var ret = 0L;
            var isNegative = false;

            while (!IsNumber()) isNegative = Read() == 45;
            while (IsNumber()) ret = ret * 10 + Read() - 48;
            return isNegative ? -ret : ret;
        }

        public double NextDouble()
        {
            if (isEof) throw new EndOfStreamException();

            var integerPart = NextLong();
            if (Peek() == 46) Read();

            double decimalPart = 0.0, place = 1.0;
            while (IsNumber()) decimalPart += (Read() - 48) * (place /= 10.0);
            return integerPart + (integerPart < 0 ? -decimalPart : decimalPart);
        }
