                for (var j = 0; j < 2; j++) dp[i + 1][1] = Min(dp[i + 1][1], dp[i][j] + (A[i] == 0 ? 2 : (A[i] % 2)));
                for (var j = 0; j < 3; j++) dp[i + 1][2] = Min(dp[i + 1][2], dp[i][j] + (A[i] + 1) % 2);
                for (var j = 0; j < 4; j++) dp[i + 1][3] = Min(dp[i + 1][3], dp[i][j] + (A[i] == 0 ? 2 : (A[i] % 2)));
                for (var j = 0; j < 5; j++) dp[i + 1][4] = Min(dp[i + 1][4], dp[i][j] + A[i]);
            }

            OutL(dp[N].Min());
        }

