    class D
    {
        public static void Solve()
        {
            var l = int.Parse(Console.ReadLine());
            ulong[] a = new ulong[l];
            ulong[,] dp = new ulong[l, 5];

            for(int i = 0; i < l; i++)
            {
                a[i] = ulong.Parse(Console.ReadLine());
            }


            for (int j = 0; j < 5; j++)
            {
                dp[0, j] = DPUpdate(0, j, a[0]);
            }

            for (int i = 1; i < l; i++)
            {
                for(int j = 0; j < 5; j++)
                {
                    dp[i, j] = int.MaxValue;
                }
                for(int j = 0; j < 5; j++)
                {
                    for(int c = j; c < 5; c++)
                    {
                        var u = DPUpdate(dp[i-1,j], c, a[i]);
                        if (u < dp[i, c])
                            dp[i, c] = u;
                    }
                }
            }

            for(int i = 0; i < l; i++)
            {
                for(int j = 0; j < 5; j++)
                {
                    Console.Write(dp[i, j]);
                }
                Console.Write("\n");
            }
            var min = ulong.MaxValue;
            for(int i = 0; i < 5; i++)
            {
                min = min > dp[l - 1, i] ? dp[l - 1, i] : min;
            }
            Console.WriteLine(min);
        }

        /// <summary>
        /// dpの更新
        /// </summary>
        /// <param name="now">現在の最小値</param>
        /// <param name="t">更新先の状態</param>
        /// <param name="ai">着目してるコスト</param>
        /// <returns></returns>
        private static ulong DPUpdate(ulong now,int t,ulong ai)
        {
            if (t == 0 || t == 4)
            {
                return now + ai;
            }
            else if (t % 2 == 1)
            {
                return now + (ai == 0 ? 2 : ai % 2);
            }
            else
            {
                return now + (ai == 0 ? 1 : (ai + 1) % 2);
            }
        }
    }
