class Program
{
    static void Main()
    {
        int l = int.Parse(Console.ReadLine());
        int[] a = new int[l];
        for (int i = 0; i < l; i++)
            a[i] = int.Parse(Console.ReadLine());
        //左からどこまで0にしたほうがよいか
        long[] sum = new long[l];
        sum[0] = -a[0];
        for (int i = 1; i < l; i++)
            sum[i] = sum[i - 1] - a[i] + (a[i] == 0 ? 2 : a[i] % 2);
        long max = 0;
        int left_ind = -1;
        for (int i = 0; i < l; i++)
        {
            if (max < sum[i])
            {
                max = sum[i];
                left_ind = i;
            }
        }
        long ans = 0;
        for (int i = 0; i <= left_ind; i++)
        {
            ans += a[i];
            a[i] = 0;
        }
        //右からどこまで0にしたほうがよいか
        sum = new long[l];
        sum[l - 1] = -a[l - 1];
        for (int i = l - 2; i >= 0; i--)
            sum[i] = sum[i + 1] - a[i] + (a[i] == 0 ? 2 : a[i] % 2);
        max = 0;
        int right_ind = l;
        for (int i = l - 1; i >= 0; i--)
        {
            if (max < sum[i])
            {
                max = sum[i];
                right_ind = i;
            }
        }
        for (int i = l - 1; i >= right_ind; i--)
        {
            ans += a[i];
            a[i] = 0;
        }
        //残ったaを0,1に置き換える
        for (int i = 0; i < l; i++)
            if (a[i] > 0)
                a[i] = a[i] % 2 == 0 ? 2 : 1;
        int i_l = 0;
        while (a[i_l] == 0)
            i_l++;
        int i_r = l - 1;
        while (a[i_r] == 0)
            i_r--;
        for (int i = i_l; i <= i_r; i++)
        {
            if (a[i] == 0)
                ans += 2;
        }
        for (int i = 0; i < l; i++)
            a[i] %= 2;
        //答えの計算
        int one_l = 0; //連続した1の最大長さ
        int temp = 0;
        for (int i = 0; i < l; i++)
        {
            if (a[i] == 0)
            {
                one_l = Math.Max(one_l, temp);
                temp = 0;
            }
            else
            {
                temp++;
            }
        }
        one_l = Math.Max(one_l, temp);
        ans += a.Sum() - one_l;
        Console.WriteLine(ans);
    }
}

