        var L = ni();
        var a = ni(L);

        var memo = new long?[L + 1, 5];
        Func<int, int, long> dfs = null;
        dfs = (int pos, int state) => {
            if (pos == L) {
                return 0;
            } else {
                if (!memo[pos, state].HasValue) {
                    long val = long.MaxValue;

                    for (int nextState = state; nextState < 5; nextState++) {
                        if (nextState == 0 || nextState == 4) {
                            val = Math.Min(val, dfs(pos + 1, nextState) + a[pos]);
                        } else if (nextState == 1 || nextState == 3) {
                            var cost = 0L;
                            if (a[pos] % 2 != 0) {
                                cost = 1;
                            } else if (a[pos] == 0) {
                                cost = 2;
                            }
                            val = Math.Min(val, dfs(pos + 1, nextState) + cost);
                        } else if (nextState == 2) { // start is fixed
                            var cost = 0L;
                            if (a[pos] % 2 == 0) {
                                cost = 1;
                            }
                            val = Math.Min(val, dfs(pos + 1, nextState) + cost);
                        }
                    }

                    memo[pos, state] = val;
                }
                return memo[pos, state].Value;
            }
        };

        cout.WriteLine(dfs(0, 0));
    }
