            for (long i = 1; i < l; i++) all[i] = all[i - 1] + array[i];

            for (int i = l-1; i >=0; i--)
            {
                if (array[i] == 0)
                {
                    inLeftOutLeft[i] = 2;
                    inLeftOutRight[i] = 1;
