    static void Main(string[] args)
    {
        var L = ReadInt();
        var A = new long[L];
        var even = new bool[L];
        for (var i = 0; i < L; i++)
        {
            A[i] = ReadLong();
            even[i] = A[i] % 2L == 0;
        }

        if (even.All(_ => !_)) { Console.WriteLine(0); return; }

        int startIdx = 0;
        int endIdx = L - 1;

        long backwardGain = 0L;
        long backwardLoss = 0L;

        long forwardGain = A.Sum();
        long forwardLoss = even.Count(_ => _);

        for (var i = 0; i < L; i++)
        {
            if (!even[i]) continue;

            backwardGain += A[i];
            backwardLoss += even[i] ? 1 : 0;
            if (backwardGain <= backwardLoss) { startIdx = i; }

            forwardGain -= A[i];
            forwardLoss -= even[i] ? 1 : 0;
            if (forwardGain <= forwardLoss) { endIdx = i; break; }
        }

        var countOfEvenInAnsSection = even.Take(endIdx + 1).Skip(startIdx).Count(_ => _);

        var answer = backwardLoss - backwardGain
            + forwardLoss - forwardGain
            ;

        Console.WriteLine(answer);
    }


    public static string Read() { return Console.ReadLine(); }
    public static int ReadInt() { return int.Parse(Read()); }
    public static long ReadLong() { return long.Parse(Read()); }
    public static double ReadDouble() { return double.Parse(Read()); }

    public static string[] Reads() { return Console.ReadLine().Split(' '); }
    public static int[] ReadInts() { return Reads().Select(_ => int.Parse(_)).ToArray(); }
    public static long[] ReadLongs() { return Reads().Select(_ => long.Parse(_)).ToArray(); }
