namespace MinPro2019D
{
    public class Program
    {
        void Solve(SimpleScanner ss, StreamWriter sw)
        {
            //---------------------------------
            var L = ss.NextLong();
            var dp = new long[5];

            for (var i = 0; i < L; i++)
            {
                var A = ss.NextLong();
                var x = A == 0 ? 2 : A & 1;

                dp[0] += A;
                dp[1] += x;
                dp[2] += (x & 1) ^ 1;
                dp[3] += x;
                dp[4] += A;

                for (var t = 1; t < 5; t++)
                {
                    dp[t] = Math.Min(dp[t], dp[t - 1]);
                }
            }

            sw.WriteLine(dp[4]);
            //---------------------------------
        }

        static void Main()
        {
            var ss = new SimpleScanner(Console.OpenStandardInput());
            var sw = new StreamWriter(Console.OpenStandardOutput()) {AutoFlush = false};
            new Program().Solve(ss, sw);
            sw.Flush();
        }
    }

    public class SimpleScanner
    {
        const int DefaultCapacity = 256;

        readonly Stream stream;
        readonly int capacity;
        readonly byte[] buffer;
        readonly List<char> chars;

        int index;
        int length;

        public SimpleScanner(Stream stream, int capacity = DefaultCapacity)
        {
            this.stream = stream;
            this.capacity = capacity;
            this.buffer = new byte[capacity];
            this.chars = new List<char>();

            Read();
        }

        byte Peek()
        {
            return buffer[index];
        }

        byte Read()
        {
            byte ret = Peek();
            if (++index < length) return ret;

            index = 0;
            length = stream.Read(buffer, 0, capacity);
            return ret;
        }

        bool CanInput()
        {
            return 33 <= Peek() && Peek() <= 126;
        }

        bool IsNumber()
        {
            return 48 <= Peek() && Peek() <= 57;
        }

        public string Next()
        {
            chars.Clear();

            while (!CanInput())
            {
                Read();
            }

            while (CanInput())
            {
                chars.Add((char)Read());
            }

            return new string(chars.ToArray());
        }

        public int NextInt()
        {
            return (int)NextLong();
        }

        public long NextLong()
        {
            long ret = 0;
            bool isNegative = false;

            while (!IsNumber())
            {
                isNegative = Read() == 45;
            }

            while (IsNumber())
            {
                ret = ret * 10 + Read() - 48;
            }

            return isNegative ? -ret : ret;
        }

        public double NextDouble()
        {
            long integerPart = NextLong();

            if (Peek() == 46) Read();

            double decimalPart = 0.0, place = 1.0;

            while (IsNumber())
            {
                decimalPart += (Read() - 48) * (place /= 10.0);
            }

            return integerPart + (integerPart < 0 ? -decimalPart : decimalPart);
        }
    }
}

using System;
using System.Linq;
using static System.Math;

class D
{
	static void Main()
	{
		var n = int.Parse(Console.ReadLine());
		var a = new int[n].Select(_ => long.Parse(Console.ReadLine())).ToArray();

		var dp = new int[n + 1].Select(_ => Enumerable.Repeat(1L << 60, 5).ToArray()).ToArray();
		dp[0][0] = 0;

		for (int i = 0, j = 1; i < n; i++, j++)
		{
			var even = a[i] == 0 ? 2 : a[i] % 2;
			var odd = (a[i] + 1) % 2;

			// 0L, 2L, 1, 2R, 0R
			dp[j][0] = Min(dp[j][0], dp[i][0] + a[i]);
			dp[j][1] = Min(dp[j][1], Min(dp[i][0], dp[i][1]) + even);
			dp[j][2] = Min(dp[j][2], Min(dp[i][0], Min(dp[i][1], dp[i][2])) + odd);
			dp[j][3] = Min(dp[j][3], Min(dp[i][0], Min(dp[i][2], dp[i][3])) + even);
			dp[j][4] = Min(dp[j][4], Min(dp[i][2], Min(dp[i][3], dp[i][4])) + a[i]);
		}
		Console.WriteLine(dp[n].Min());
	}
}

