namespace AtTest.Yahoo2019
{
    class D
    {
        static void Main(string[] args)
        {
            Method(args);
            Console.ReadLine();
        }

        static void Method(string[] args)
        {
            int l = ReadInt();
            int[] array = new int[l];
            for(int i = 0; i < l; i++)
            {
                array[i] = ReadInt();
            }
            //必要な操作数
            int[] inLeftOutLeft = new int[l];//i以降すべて
            int[] inLeftOutRight = new int[l];
            int[] inRightOutLeft = new int[l];//i以前すべて
            int[] inRightOutRight = new int[l];

            long[] all = new long[l];
            all[0] = array[0];
            for (int i = 1; i < l; i++) all[i] = all[i - 1] + array[i];

            for (int i = l-1; i >=0; i--)
            {
                if (array[i] == 0)
                {
                    inLeftOutLeft[i] = 2;
                    inLeftOutRight[i] = 1;
                }
                else
                {
                    inLeftOutLeft[i] = array[i] % 2 == 0 ? 0 : 1;
                    inLeftOutRight[i] = array[i] % 2 == 0 ? 1 : 0;
                }
                if (i + 1 < l)
                {
                    inLeftOutLeft[i] += inLeftOutLeft[i + 1];
                    inLeftOutRight[i] += inLeftOutRight[i + 1];
                }
            }
            for(int i = 0; i < l; i++)
            {
                if (array[i] == 0)
                {
                    inRightOutLeft[i] = 1;
                    inRightOutRight[i] = 2;
                }
                else
                {
                    inRightOutLeft[i] = array[i] % 2 == 0 ? 1 : 0;
                    inRightOutRight[i] = array[i] % 2 == 0 ? 0 : 1;
                }
                if (i - 1 >= 0)
                {
                    inRightOutLeft[i] += inRightOutLeft[i - 1];
                    inRightOutRight[i] +=inRightOutRight[i - 1];
                }
            }

            for(int i = 0; i < l; i++)
            {
                long allPtr = all[l - 1];
                if (i > 0) allPtr -= all[i-1];
                if (allPtr < int.MaxValue)
                {
                    inLeftOutLeft[i] = Math.Min(inLeftOutLeft[i], (int)allPtr);
                }
                if (all[i] < int.MaxValue)
                {
                    inLeftOutRight[i] = Math.Min(inRightOutRight[i], (int)all[i]);
                }
            }

            int res = int.MaxValue;
            for (int i = 0; i < l + 1; i++)
            {
                int val = 0;
                if (i == 0)
                {
                    val = Math.Min(inLeftOutLeft[i], inLeftOutRight[i]);
                }
                else if (i == l)
                {
                    val = Math.Min(inRightOutLeft[i-1], inRightOutRight[i-1]);
                }
                else
                {
                    val = Math.Min(inLeftOutLeft[i] + Math.Min(inRightOutRight[i - 1], inRightOutLeft[i - 1]),
                        inRightOutRight[i - 1] + Math.Min(inLeftOutLeft[i], inLeftOutRight[i]));
                }
                //Console.WriteLine(val);
                res = Math.Min(res, val);
            }
            Console.WriteLine(res);
        }

        private static string Read() { return Console.ReadLine(); }
        private static int ReadInt() { return int.Parse(Read()); }
        private static long ReadLong() { return long.Parse(Read()); }
        private static double ReadDouble() { return double.Parse(Read()); }
        private static int[] ReadInts() { return Array.ConvertAll(Read().Split(), int.Parse); }
        private static long[] ReadLongs() { return Array.ConvertAll(Read().Split(), long.Parse); }
        private static double[] ReadDoubles() { return Array.ConvertAll(Read().Split(), double.Parse); }
    }
}

using System;
using System.Linq;
using System.Collections.Generic;

class Cmondai
{
    static void Main()
    {
        var L = Int64.Parse(Console.ReadLine());
        var A = new List<long>();
        for (int i=0;i<L;++i)
        {
            A.Add(Int64.Parse(Console.ReadLine()));
        }
        var dp = new long[L,5];
        for (int i=0;i<L; ++i)
        {
            var num = A[i] % 2;
            var even = A[i] == 0 ? 2 : num == 0 ? 0 : 1;
            var odd = A[i] == 0 ? 1 : num == 0 ? 1 : 0;
            var value = GetValue(dp,i,0);
            dp[i, 0] = A[i] + value;
            value = GetValue(dp, i, 1,value);
            dp[i, 1] = even+value;
            value = GetValue(dp, i, 2,value);
            dp[i, 2] = odd+value;
            value = GetValue(dp, i, 3,value);
            dp[i, 3] = even + value;
            value = GetValue(dp, i, 4, value);
            dp[i,4]= A[i] + value;
        }
        var ans = Math.Min(dp[L - 1, 0],
                  Math.Min(dp[L - 1, 1],
                  Math.Min(dp[L - 1, 2],
                  Math.Min(dp[L-1,3],dp[L - 1, 4]))));
        Console.WriteLine(ans);
    }
    static long GetValue(long[,] dp,long num,int section,long value=long.MaxValue)
    {
        if (num == 0) return 0;
        else
        {
            switch (section)
            {
                case 0:return dp[num - 1, section];
                default:return Math.Min(value, dp[num - 1, section]);
            }
        }
    }
}

