    public class SimpleScanner
    {
        const int DefaultCapacity = 1024;

        readonly Stream stream;
        readonly int capacity;
        readonly byte[] buffer;

        int index;
        int length;

        public SimpleScanner(Stream stream, int capacity = DefaultCapacity)
        {
            this.stream = stream;
            this.capacity = capacity;
            this.buffer = new byte[capacity];

            length = stream.Read(buffer, 0, capacity);
        }

        [MethodImpl(MethodImplOptions.AggressiveInlining)]
        public long NextLong()
        {
            var ret = 0L;

            while (buffer[index] < 48 || 57 < buffer[index])
            {
                ++index;

                if (index < length) continue;
                index = 0;
                length = stream.Read(buffer, 0, capacity);
            }

            while (48 <= buffer[index] && buffer[index] <= 57)
            {
                ret = ret * 10 + buffer[index] - 48;
                ++index;

                if (index < length) continue;
                index = 0;
                length = stream.Read(buffer, 0, capacity);
            }

            return ret;
        }
    }
