using System;
using System.Collections.Generic;
using System.Linq;

public class Solution
{
    public static void Main()
    {
        var l = int.Parse(Console.ReadLine());
        var a = new long[l];
        for (int i = 0; i < l; i++)
        {
            a[i] = long.Parse(Console.ReadLine());
        }
        // 5 zone : zero, even, odd, even, zero
        var dp = new long[5, l];
        for (int i = 0; i < l; i++)
        {
            for (int z = 0; z < 5; z++)
            {
                long d;
                switch (z)
                {
                    case 0: // zero
                    case 4:
                        d = a[i];
                        break;
                    case 1: //even
                    case 3:
                        d = a[i] == 0 ? 2 : a[i] % 2;
                        break;
                    case 2: //odd
                    default:
                        d = (a[i] + 1) % 2;
                        break;
                }
                if (i == 0)
                {
                    dp[z, i] = d;
                }
                else
                {
                    dp[z, i] = Enumerable.Range(0, z + 1).Min(x => dp[x, i - 1]) + d;
                }
            }
            Console.Error.WriteLine($"{dp[0, i]} {dp[1, i]} {dp[2, i]} {dp[3, i]} {dp[4, i]} ");
        }

        var min = Enumerable.Range(0, 5).Min(x => dp[x, l - 1]);
        Console.WriteLine(min);
    }
}

