    public class SimpleScanner
    {
        const int DefaultCapacity = 1024;

        readonly Stream stream;
        readonly int capacity;
        readonly byte[] buffer;
        readonly List<char> chars;

        int index = 0;
        int length = 0;
        bool isEof = false;

        public SimpleScanner(Stream stream, int capacity = DefaultCapacity)
        {
            this.stream = stream;
            this.capacity = capacity;
            this.buffer = new byte[capacity];
            this.chars = new List<char>();
        }

        void Reload()
        {
            index = 0;
            length = stream.Read(buffer, 0, capacity);
            isEof = length <= 0;
        }

        void CheckBuffer()
        {
            if (index < length) return;
            if (isEof) throw new EndOfStreamException();
            Reload();
            CheckBuffer();
        }

        byte Peek()
        {
            CheckBuffer();
            return buffer[index];
        }

        byte Read()
        {
            CheckBuffer();
            return buffer[index++];
        }

        bool CanInput(byte b)
        {
            return 33 <= b && b <= 126;
        }

        public string Next()
        {
            chars.Clear();
            while (!CanInput(Peek())) Read();
            while (CanInput(Peek())) chars.Add((char)Read());
            return new string(chars.ToArray());
        }

        bool IsNumber(byte b)
        {
            return 48 <= b && b <= 57;
        }

        public long NextLong()
        {
            var ret = 0L;
            while (!CanInput(Peek())) Read();
            while (IsNumber(Peek())) ret = ret * 10 + Read() - 48;
            if (CanInput(Peek())) throw new FormatException();
            return ret;
        }
    }
}

using System;

public class Program
{
    private int L;
    private int[] A;

    public void Solve()
    {
        var sc = new Scanner();
        L = sc.NextInt();
        A = new int[L];
        for (int i = 0; i < L; i++)
        {
            A[i] = sc.NextInt();
        }


        var dp = new long[L + 1, 5];

        for (int i = 0; i < L; i++)
        {
            long min = long.MaxValue;

            for (int j = 0; j <= 4; j++)
            {
                min = Math.Min(min, dp[i, j]);
                long plus = -1;
                switch (j)
                {
                    case 0:
                    case 4:
                        plus = A[i];
                        break;
                    case 1:
                    case 3:
                        plus = A[i] == 0 ? 2 : A[i] % 2;
                        break;
                    case 2:
                        plus = (A[i] + 1) % 2;
                        break;
                }

                dp[i + 1, j] = min + plus;
            }
        }

        long ans = long.MaxValue;
        for (int i = 0; i <= 4; i++)
        {
            ans = Math.Min(ans, dp[L, i]);
        }

        Console.WriteLine(ans);
    }


    public static void Main(string[] args)
    {
        new Program().Solve();
    }
}

