        for (int i = 0; i < n; i++)
        {
            b[i] = a[i];
            if (a[i] % 2 == 0) b[i]++;
        }
        b[0] = a[0];
        long e = 0; long emax = 0;
        int p = 0;

        for (int i = 0; i < n; i++)
        {
            e += Math.Abs(a[i] - b[i]) - a[i];
            b[i] = 0;
            if (i + 1 < n)
            {
                b[i + 1]--;
                if (a[i + 1] % 2 == 0) e++;
                else e--;
            }            
            if (e > emax) p = i + 1;
        }

        long ans = 0;
        long remain = 0;
        int q = p;
        for (int i = p + 1; i < n; i++) remain += a[i];
        long rmin = remain;
        int f = 0;
        for(int i=0; i<n; i++)
        {
            if (i < p) ans += a[i];
            if (i == p)
            {
                ans += (a[i] % 2);
                if (p == 0) ans = 0;
            }
            if (i > p)
            {             
                remain -= a[i];
                if (a[i] % 2 == 1)
                {
                    f--;
                }
                if (a[i] % 2 == 0)
                {
                    remain++; f++;
                }
                if (a[i] == 0) f--;
                if (remain < rmin) rmin = remain;
                if (remain - f < rmin) rmin = remain - f;
                if (f < 0) f = 0;
