func solve(scanner *bufio.Scanner, writer *bufio.Writer) {
	n := getNextInt(scanner)
	aa := make([]int, n)
	for i := 0; i < n; i++ {
		aa[i] = getNextInt(scanner)
		if aa[i] == 0 {
			continue
		}
		aa[i] = 2 - aa[i]%2
	}

	dp := make([][5]int, n+1)
	for i := 0; i <= n; i++ {
		for ii := 0; ii < 5; ii++ {
			dp[i][ii] = math.MaxInt32
		}
	}
	dp[0][0] = 0
	for i := 0; i < n; i++ {
		for ii := 0; ii < 5; ii++ {
			if dp[i][ii] == math.MaxInt32 {
				continue
			}
			switch ii {
			case 0:
				dp[i+1][0] = minint(dp[i+1][0], dp[i][ii]+aa[i])
				dp[i+1][1] = minint(dp[i+1][1], dp[i][ii]+absint(2-aa[i]))
				dp[i+1][2] = minint(dp[i+1][2], dp[i][ii]+absint(1-aa[i]))
			case 1:
				dp[i+1][1] = minint(dp[i+1][1], dp[i][ii]+absint(2-aa[i]))
				dp[i+1][2] = minint(dp[i+1][2], dp[i][ii]+absint(1-aa[i]))
				dp[i+1][4] = minint(dp[i+1][4], dp[i][ii]+aa[i])
			case 2:
				dp[i+1][2] = minint(dp[i+1][2], dp[i][ii]+absint(1-aa[i]))
				dp[i+1][3] = minint(dp[i+1][3], dp[i][ii]+absint(2-aa[i]))
				dp[i+1][4] = minint(dp[i+1][4], dp[i][ii]+aa[i])
			case 3:
				dp[i+1][3] = minint(dp[i+1][3], dp[i][ii]+absint(2-aa[i]))
				dp[i+1][4] = minint(dp[i+1][4], dp[i][ii]+aa[i])
			case 4:
				dp[i+1][4] = minint(dp[i+1][4], dp[i][ii]+aa[i])
			}
		}
	}
	ans := math.MaxInt32
	for ii := 0; ii < 5; ii++ {
		ans = minint(ans, dp[n][ii])
	}

	fmt.Fprintln(writer, ans)
}

func minint(a, b int) int {
	if a < b {
		return a
	}
	return b
}

func absint(a int) int {
	if a < 0 {
		return -a
	}
	return a
}

