	n := getNextInt(scanner)
	aa := make([]int, n)
	for i := 0; i < n; i++ {
		aa[i] = getNextInt(scanner)
		if aa[i] == 0 {
			continue
		}
		aa[i] = 2 - aa[i]%2
	}

	// dp[i番目まで見た][1を使用した][2を使用した][最後に使用した数] = 最小値
	dp := make([][2][2][3]int, n+1)
	for i := 0; i <= n; i++ {
		for ii := 0; ii < 2; ii++ {
			for iii := 0; iii < 2; iii++ {
				for iiii := 0; iiii < 3; iiii++ {
					dp[i][ii][iii][iiii] = math.MaxInt32
				}
			}
		}
	}
	dp[0][0][0][0] = 0
	for i := 0; i < n; i++ {
		for ii := 0; ii < 2; ii++ {
			for iii := 0; iii < 2; iii++ {
				for iiii := 0; iiii < 3; iiii++ {
					if dp[i][ii][iii][iiii] == math.MaxInt32 {
						continue
					}
					if iiii == 0 {
						dp[i+1][ii][iii][0] = minint(dp[i+1][ii][iii][0], dp[i][ii][iii][iiii]+aa[i])
						if ii == 1 || iii == 1 {
							continue
						}
						dp[i+1][1][iii][1] = minint(dp[i+1][1][iii][1], dp[i][ii][iii][iiii]+absint(1-aa[i]))
						dp[i+1][ii][1][2] = minint(dp[i+1][ii][1][2], dp[i][ii][iii][iiii]+absint(2-aa[i]))
						continue
					}
					if iiii == 1 {
						dp[i+1][ii][iii][0] = minint(dp[i+1][ii][iii][0], dp[i][ii][iii][iiii]+aa[i])
						dp[i+1][1][iii][1] = minint(dp[i+1][1][iii][1], dp[i][ii][iii][iiii]+absint(1-aa[i]))
						dp[i+1][ii][1][2] = minint(dp[i+1][ii][1][2], dp[i][ii][iii][iiii]+absint(2-aa[i]))
						continue
					}
					dp[i+1][ii][iii][0] = minint(dp[i+1][ii][iii][0], dp[i][ii][iii][iiii]+aa[i])
					if ii == 0 {
						dp[i+1][1][iii][1] = minint(dp[i+1][1][iii][1], dp[i][ii][iii][iiii]+absint(1-aa[i]))
					}
					dp[i+1][ii][1][2] = minint(dp[i+1][ii][1][2], dp[i][ii][iii][iiii]+absint(2-aa[i]))
				}
			}
		}
	}
	ans := math.MaxInt32
	for ii := 0; ii < 2; ii++ {
		for iii := 0; iii < 2; iii++ {
			for iiii := 0; iiii < 3; iiii++ {
				ans = minint(ans, dp[n][ii][iii][iiii])
			}
		}
	}

	fmt.Fprintln(writer, ans)
}

func minint(a, b int) int {
	if a < b {
		return a
	}
	return b
}

func absint(a int) int {
	if a < 0 {
		return -a
	}
	return a
}

