        if (MEMO[t][i]) return MEMO[t][i];
        return MEMO[t][i] = min(
            t > 0 ? long.max : AS[i] + solve(i+1, 0),
            t > 1 ? long.max : (AS[i] == 0 ? 2 : AS[i] % 2) + solve(i+1, 1),
            t > 2 ? long.max : (AS[i] == 0 ? 1 : (AS[i]+1) % 2) + solve(i+1, 2),
            t > 3 ? long.max : (AS[i] == 0 ? 2 : AS[i] % 2) + solve(i+1, 3),
            AS[i] + solve(i+1, 4)
        );
    }

    writeln(solve(0, 0));
}

ulong[] A;

ulong cost(ulong i, ulong j) {
	switch(j) {
		case 0, 4: // never visit there
			return A[i];
		case 1, 3: // even(x > 0)
			return A[i] == 0 ? 2 : A[i] % 2;
		case 2: // odd
			return (A[i] + 1) % 2;
		default: return 0;
	}
}

