点j以右から始めて、点jに帰ってくる場合の最良を y2[i]

x2[i] = min(x[i], x2[i - 1] + q[i]);
y2[i] = min(y[j], y2[j + 1] + q[j]),

求めるものは min(x2[i] + y2[i])

*/


void main(){
	long l = read.to!long;

	long[] as;
	foreach(i; 0 .. l) as ~= read.to!long;
	debug writeln("as:", as);

	foreach(i; 0 .. l) if(as[i] > 0){
		if(as[i] % 2 == 1) as[i] = 1;
		else as[i] = 2;
	}
	debug writeln("as:", as);

	long[] ps, qs;
	foreach(i; 0 .. l){
		if(as[i] == 0) ps~= 2, qs ~= 1;
		else if(as[i] == 1) ps ~= 0, qs ~= -1;
		else ps ~= -2, qs ~= -1;
	}
	debug writeln("ps:", ps);
	debug writeln("qs:", qs);

	long[] xs = new long[](l + 1);
	xs[0] = 0;
	foreach(i; 1 .. l) xs[i] = min(xs[i - 1] + ps[i - 1], 0);
	debug writeln("xs:", xs);

	long[] ys = new long[](l + 1);
	ys[l] = 0;
	foreach_reverse(i; 1 .. l) ys[i] = min(ys[i + 1] + ps[i], 0);
	debug writeln("ys:", ys);

	long[] x2s = new long[](l + 1);
	x2s[0] = xs[0];
	foreach(i; 1 .. l) x2s[i] = min(x2s[i - 1] + qs[i - 1], xs[i]);
	debug writeln("x2s:", x2s);

	long[] y2s = new long[](l + 1);
	y2s[l] = ys[l];
	foreach_reverse(i; 1 .. l) y2s[i] = min(y2s[i + 1] + qs[i], ys[i]);
	debug writeln("y2s:", y2s);

	long sum;
	foreach(a; as) sum += a;
	debug writeln("sum:", sum);

	long ans = sum + 10;
	foreach(i; 1 .. l) ans = min(ans, sum + x2s[i] + y2s[i]);

	ans.writeln;

}

import std.stdio, std.algorithm, std.conv, std.array, std.string, std.math, std.typecons, std.numeric;

long[10^^5*2] AS;
long[10^^5*2][5] MEMO;

void main()
{
    auto L = readln.chomp.to!int;
    foreach (i; 0..L) {
        AS[i] = readln.chomp.to!long;
    }

    foreach (ref m; MEMO) m[] = -1;

    long solve(int i, int t) {
        if (i == L) return 0;
        if (MEMO[t][i] != -1) return MEMO[t][i];
        return MEMO[t][i] = min(
            t > 0 ? long.max : AS[i] + solve(i+1, 0),
            t > 1 ? long.max : (AS[i] == 0 ? 2 : AS[i] % 2) + solve(i+1, 1),
            t > 2 ? long.max : (AS[i] == 0 ? 1 : (AS[i]+1) % 2) + solve(i+1, 2),
            t > 3 ? long.max : (AS[i] == 0 ? 2 : AS[i] % 2) + solve(i+1, 3),
            AS[i] + solve(i+1, 4)
        );
    }

    writeln(solve(0, 0));
}

