enum inf3 = 1_001_001_001;
enum inf6 = 1_001_001_001_001_001_001L;
enum mod = 1_000_000_007L;


void main() {
    int n;
    scan(n);
    auto a = iota(n).map!(i => readln.chomp.to!int).array;
    auto s = new long[](n + 1);
    foreach (i ; 1 .. n + 1) {
        s[i] = s[i - 1] + a[i - 1];
    }
    auto p = new long[][](2, n + 1);
    foreach (i ; 1 .. n + 1) {
        p[0][i] = s[i];
        if (a[i - 1] == 0) {
            p[0][i] = min(p[0][i], 2 + p[0][i - 1]);
        }
        else {
            p[0][i] = min(p[0][i], (a[i - 1] % 2 == 1) + p[0][i - 1]);
        }
        p[1][i] = min(s[i], (a[i - 1] % 2 == 0) + p[1][i - 1]);
    }

    debug {
        writefln("p[0]: %s", p[0]);
        writefln("p[1]: %s", p[1]);
    }
    auto sf = new long[][](2, n + 1);

    foreach_reverse (i ; 0 .. n) {
        sf[0][i] = s[n] - s[i];
        if (a[i] == 0) {
            sf[0][i] = min(sf[0][i], 2 + sf[0][i + 1]);
        }
        else {
            sf[0][i] = min(sf[0][i], (a[i] % 2 == 1) + sf[0][i + 1]);
        }
        sf[1][i] = min(s[n] - s[i], (a[i] % 2 == 0) + sf[1][i + 1]);
    }

    debug {
        writefln("sf[0]: %s", sf[0]);
        writefln("sf[1]: %s", sf[1]);
    }

    long ans = p[0][n];

    for (int l, r; l < n; l++) {
        if (a[l] % 2 == 0) {
            r = l + 1;
            continue;
        }
        while (r < n && ((l == r) || (a[r] % 2 == 1))) {
            r++;
            debug {
                writefln("l = %d, r = %d, %d", l, r, p[0][l] + sf[0][r]);
            }
            ans = min(ans, p[0][l] + sf[0][r]);
        }
    }

    writeln(ans);
}







