proc buildCumTab(a: seq[int]): seq[int] =
  let n = a.len()
  var c = newSeq[int](n + 1)
  for i in 1..n:
    c[i] = c[i - 1] + a[i - 1]
  return c

# [s, t)
proc lookupCumTab(c: seq[int]; s, t: int): int = c[t] - c[s]

proc main() =
  let n = readInt1()
  let a = readSeq(n).map(parseInt)
  let c = a.buildCumTab()

  var dpR = newSeq2[int](n + 1, 2)
  dpR[n][0] = 0
  dpR[n][1] = 0
  for i in countdown(n - 1, 0):
    #dpR[i][0]
    block:
      var opt = c.lookupCumTab(i, n)
      if a[i] mod 2 == 1:
        opt = min(opt, dpR[i + 1][0])
        opt = min(opt, dpR[i + 1][1])
      elif a[i] == 0:
        opt = min(opt, dpR[i + 1][1] + 1)
        opt = min(opt, dpR[i + 1][0] + 1)
      elif a[i] mod 2 == 0:
        opt = min(opt, dpR[i + 1][1])
        opt = min(opt, dpR[i + 1][0] + 1)
      else:
        assert false
      dpR[i][0] = opt

    #dpR[i][1]
    block:
      var opt = c.lookupCumTab(i, n)
      if a[i] == 0:
        opt = min(opt, dpR[i + 1][1] + 2)
      elif a[i] mod 2 == 0:
        opt = min(opt, dpR[i + 1][1] + 0)
      elif a[i] mod 2 == 1:
        opt = min(opt, dpR[i + 1][1] + 1)
      dpR[i][1] = opt

  var dpL = newSeq2[int](n + 1, 2)
  dpL[0][0] = 0
  dpL[0][1] = 0
  for i in 1..n:
    #dpL[i][0]
    block:
      var opt = c.lookupCumTab(0, i)
      if a[i - 1] mod 2 == 1:
        opt = min(opt, dpL[i - 1][0])
        opt = min(opt, dpL[i - 1][1])
      elif a[i - 1] == 0:
        opt = min(opt, dpL[i - 1][1] + 1)
        opt = min(opt, dpL[i - 1][0] + 1)
      elif a[i - 1] mod 2 == 0:
        opt = min(opt, dpL[i - 1][1])
        opt = min(opt, dpL[i - 1][0] + 1)
      else:
        assert false
      dpL[i][0] = opt

    #dpL[i][1]
    block:
      var opt = c.lookupCumTab(0, i)
      if a[i - 1] == 0:
        opt = min(opt, dpL[i - 1][1] + 2)
      elif a[i - 1] mod 2 == 0:
        opt = min(opt, dpL[i - 1][1] + 0)
      elif a[i - 1] mod 2 == 1:
        opt = min(opt, dpL[i - 1][1] + 1)
      dpL[i][1] = opt

  var ans = INF
  for i in 0..n:
    var sol = 0

    sol = dpL[i][1] + dpR[i][0]
    ans = min(ans, sol)

    sol = dpL[i][0] + dpR[i][1]
    ans = min(ans, sol)

  echo ans

main()

