import math


def round(n):
    if n == 0:
        return 0
    if n % 2 == 0:
        return 2
    return 1


def aggregate(arr):
    aggregated = [[-1, 0, 0]]
    for i in arr:
        rounded = round(i)
        if aggregated[-1][0] != rounded:
            aggregated.append([rounded, 1, i])
        else:
            aggregated[-1][1] += 1
            aggregated[-1][2] += i
    return aggregated[1:]


def calc_pass_cost(n):
    if n % 2 == 0:
        return 1
    return 0


def trim_edges_if_zero(aggregated):
    result = aggregated
    if aggregated[0][0] == 0:
        result = result[1:]
    if aggregated[-1][0] == 0:
        result = result[:-1]
    return result


def trim_edge_by_cost(aggregated):
    pass_costs = 0
    ignored_stones = 0
    for i, v in enumerate(aggregated):
        if i > 0:
            pass_costs += calc_pass_cost(v[0]) * v[1]
        ignored_stones += v[2]
        if pass_costs >= ignored_stones:
            return i + 1, ignored_stones
    return 0, 0


def trim_edges(aggregated):
    return aggregated[1:-1]


def calc_cost(aggregated):
    cost = 0
    for v in aggregated:
        cost += calc_pass_cost(v[0]) * v[1]
    return cost


if __name__ == "__main__":
    L = int(input())
    A = [0] * L
    for i in range(L):
        A[i] = int(input())

    agg = trim_edges_if_zero(aggregate(A))
    left_trim_point, left_ignored_stone = trim_edge_by_cost(agg)
    right_trim_point, right_ignored_stone = trim_edge_by_cost(agg[::-1])
    agg_trimmed = trim_edges(agg[left_trim_point:len(agg)-right_trim_point])

    cost = calc_cost(agg_trimmed)
    print(cost + left_ignored_stone + right_ignored_stone)

