        if (dp[i][6] != LLONG_MAX) {
            amin(dp[i+1][6], dp[i][6] + g);
            amin(dp[i+1][7], dp[i][6] + a[i]);
        }
        if (dp[i][7] != LLONG_MAX) {
            amin(dp[i+1][7], dp[i][7] + a[i]);
        }
    }

    return *min_element(ALL(dp[L]));
}

