def trim0(l):
    assert isinstance(l, list)
    while l and l[0] == 0:
        l.pop(0)
    while l and l[-1] == 0:
        l.pop(-1)


def even_len(l):
    return len(list(itertools.takewhile(lambda x: x % 2 == 0, l)))


def count0(l):
    return len(list(filter(lambda x: x == 0, l)))


def count1(l):
    return len(list(filter(lambda x: x == 1, l)))


def count_evens(l):
    return len(list(filter(lambda x: x % 2 == 0, l)))


def get_end_point(l):
    assert isinstance(l, list)
    costs = [0] * len(l)
    count = 0
    for i in range(1, len(l)):
        if l[i - 1] == 0:
            count -= 2
        elif l[i - 1] == 1:
            pass
        else:
            count += l[i - 1] - (l[i - 1] % 2)
        costs[i] = count
    return max(filter(lambda x: x[1] == min(costs), enumerate(costs)), key=lambda x: x[0])[0]


def get_start_point(l):
    assert isinstance(l, list)
    costs = [0] * (len(l) + 1)
    count = 0
    for i in range(1, len(l) + 1):
        if l[len(l) - i] <= 1:
            count -= 1
        elif l[len(l) - i] % 2 == 1:
            count -= 1
        else:
            count += 1
        costs[len(l) - i] = count
    return min(filter(lambda x: x[1] == min(costs), enumerate(costs)), key=lambda x: x[0])[0]


def main():
    l = get_int()
    a = [get_int() for _ in range(l)]

    left_end = get_end_point(a)
    left_start = left_end + get_start_point(a[left_end:])
    right_end = l - get_end_point(a[::-1])
    right_start = right_end - get_start_point(a[:right_end][::-1])

    cost_outer = sum(a[:left_end]) + sum(a[right_end:])
    cost_l = 0
    cost_l += count0(a[left_end:left_start]) * 2
    cost_l += (left_start - left_end) - count_evens(a[left_end:left_start])
    cost_r = 0
    cost_r += count0(a[right_start:right_end]) * 2
    cost_r += (right_end - right_start) - count_evens(a[right_start:right_end])
    cost_middle = count_evens(a[left_start:right_start])
    print(cost_outer + cost_l + cost_r + cost_middle)


