def error_print(*args):
    print(*args, file=sys.stderr)


def mt(f):
    import time

    def wrap(*args, **kwargs):
        s = time.time()
        ret = f(*args, **kwargs)
        e = time.time()

        error_print(e - s, 'sec')
        return ret

    return wrap


@mt
def slv(L, A):
    c = 0
    for a in A:
        if a == 0:
            c += 1
        else:
            break
    A = A[c:]

    c = 0
    for i in range(len(A)-1, 0, -1):
        a = A[i]
        if a == 0:
            c += 1
        else:
            break
    if c != 0:
        A = A[:-c]

    B = []
    S = []
    f = True
    for a in A:
        if a == 0 and f:
            S[-1] += 1
        elif a == 0 and not f:
            f = True
            S.append(1)
        elif a != 0 and f:
            f = False
            B.append([a])
        else:
            B[-1].append(a)


    S.append(0)


    C = []
    D = []
    E = []
    for b in B:
        c = 0
        d = 0
        e = []
        for b_ in b:
            c += (b_ + 1) % 2
            d += b_
            e.append(b_ % 2)

        o = sum(e)
        even = len(e) - o
        for i in range(len(e)):
            if e[i] != 1:
                break
            o -= 1
        for i in range(len(e)-1, -1, -1):
            if e[i] != 1:
                break
            o -= 1
        # print(o, even)
        E.append(min(o, max(0, even-1)))
        C.append(c)
        D.append(d)

    # print(A)
    # print(B)
    # print(S)
    # print(C)
    # print(D)
    # print(E)


    ans =  0
    CS = sum(C)
    # SS = sum(S)
    for i in range(len(C)):
        error_print('+')
        if D[i] - CS > S[i]:
            if S[i] == 0:
                ans += E[i]

            else:
                ans += C[i]
                ans += S[i]

        else:
            error_print('-')
            ans += D[i]
        CS -= C[i]
    return ans


def main():
    L = read_int()
    A = [read_int() for _ in range(L)]
    print(slv(L, A))


