def error_print(*args):
    print(*args, file=sys.stderr)


def mt(f):
    import time

    def wrap(*args, **kwargs):
        s = time.time()
        ret = f(*args, **kwargs)
        e = time.time()

        error_print(e - s, 'sec')
        return ret

    return wrap


@mt
def slv(L, A):

    dp = [[0] * (L+1) for _ in range(5)]
    for i, a in enumerate(A):
        dp[0][i+1] = dp[0][i] + a
    for i, a in enumerate(A):
        dp[1][i+1] = min(dp[1][i], dp[0][i]) + (a%2 if a != 0 else 1)
        dp[2][i+1] = min(dp[2][i], dp[1][i]) + ((a+1)%2 if a != 0 else 1)
        dp[3][i+1] = min(dp[3][i], dp[2][i]) + (a%2 if a != 0 else 1)
        dp[4][i+1] = min(dp[4][i], dp[3][i]) + a

    return min([dp[i][L] for i in range(5)])

