def hoge(A, x, flag = False):
    path = []
    tmp = []
    for a in A:
        if a != x:
            tmp.append(a)
        else:
            if tmp:
                path.append(tmp)
            tmp = []
    if tmp:
        path.append(tmp)
    if flag:
        return path[1:-1]
    return path

