const LZERO: usize = 0;
const LEVEN: usize = 1;
const ODD: usize = 2;
const REVEN: usize = 3;
const RZERO: usize = 4;
const REGION_LEN: usize = 5;

fn solve(aa: &[u64], last_region_max: usize, memo: &mut [[Option<u64>; REGION_LEN]]) -> u64 {
    if let Some(ans) = memo[aa.len()][last_region_max] {
        return ans;
    }

    let ans = match aa.split_last() {
        None => 0,
        Some((&last, rest)) => {
            (0..last_region_max+1).map(|last_region| {
                solve(rest, last_region, memo) + match last_region {
                    LZERO | RZERO => last,
                    ODD => (last+1) % 2,
                    LEVEN | REVEN => if last == 0 { 2 } else { last % 2 },
                    _ => panic!()
                }
            }).min().unwrap()
        }
    };

    memo[aa.len()][last_region_max] = Some(ans);
    ans
}

fn main() {
    read!();
    let aa: Vec<u64> = read_vec();
    println!("{}", solve(&aa, RZERO, &mut vec![[None; REGION_LEN]; aa.len() + 1]));
}

use std::cmp::min;
const INF: u64 = 1 << 60;

fn main() {
    let (r, w) = (std::io::stdin(), std::io::stdout());
    let mut sc = IO::new(r.lock(), w.lock());

    let l: usize = sc.read();
    let a: Vec<u64> = sc.vec(l);

    let mut dp = [INF; 5];
    dp[0] = 0;
    for i in 0..l {
        let a = a[i];
        let mut next = [INF; 5];
        for state in 0..5 {
            for next_state in state..5 {
                let cost = match next_state {
                    0 => a,
                    1 => {
                        if a == 0 {
                            2
                        } else {
                            a % 2
                        }
                    }
                    2 => (a + 1) % 2,
                    3 => {
                        if a == 0 {
                            2
                        } else {
                            a % 2
                        }
                    }
                    4 => a,
                    _ => unreachable!(),
                };
                next[next_state] = min(next[next_state], dp[state] + cost);
            }
        }
        dp = next;
    }
    println!("{}", dp.iter().min().unwrap());
}

pub struct IO<R, W: std::io::Write>(R, std::io::BufWriter<W>);

impl<R: std::io::Read, W: std::io::Write> IO<R, W> {
    pub fn new(r: R, w: W) -> Self {
        IO(r, std::io::BufWriter::new(w))
    }
    pub fn write<S: ToString>(&mut self, s: S) {
        use std::io::Write;
        self.1.write(s.to_string().as_bytes()).unwrap();
    }
