use std::cmp;

const INF: u64 = 1e17 as u64;

fn main() {
    let s = std::io::stdin();
    let mut sc = Scanner { stdin: s.lock() };
    let n: usize = sc.read();
    let a: Vec<u64> = sc.vec(n);
    let b = a.iter().rev().map(|&a| a).collect();

    let dp = forward_dp(a);
    let inv = forward_dp(b);

    let mut ans = cmp::min(*dp[n].iter().min().unwrap(), *inv[n].iter().min().unwrap());
    for i in 1..n {
        let prefix = *dp[i].iter().min().unwrap();
        let suffix = *inv[n - i].iter().min().unwrap();
        ans = cmp::min(ans, prefix + suffix);
    }
    println!("{}", ans);
}

// 0 .. 0 e .. e o .. o e .. e 0 .. 0
fn forward_dp(a: Vec<u64>) -> Vec<Vec<u64>> {
    let n = a.len();
    let mut dp = vec![vec![INF; 3]; n + 1];
    dp[0][0] = 0;
    dp[0][1] = 0;
    dp[0][2] = 0;
    for i in 0..n {
        let even_cost = if a[i] == 0 { 2 } else { a[i] % 2 };
        dp[i + 1][0] = cmp::min(dp[i + 1][0], dp[i][0] + a[i]);

        dp[i + 1][1] = cmp::min(dp[i + 1][1], dp[i][0] + even_cost);
        dp[i + 1][1] = cmp::min(dp[i + 1][1], dp[i][1] + even_cost);

        dp[i + 1][2] = cmp::min(dp[i + 1][2], dp[i][0] + (a[i] + 1) % 2);
        dp[i + 1][2] = cmp::min(dp[i + 1][2], dp[i][1] + (a[i] + 1) % 2);
        dp[i + 1][2] = cmp::min(dp[i + 1][2], dp[i][2] + (a[i] + 1) % 2);
    }
    dp
}

