use std::cmp::*;
use std::fmt::Write;
fn solve<R: BufRead>(parser: &mut Parser<R>) -> String {
    let mut buf = String::new();
    input! {
        parser = parser,
        n: usize,
        xs: [i64; n],
    }
    let mut ys = vec![];
    ys.push(0);
    for &x in &xs {
        ys.push(x);
    }
    ys.push(0);
    let mut res_t = 0;
    let mut odd_count = 0;
    let mut count = 0;
    for i in 1..n + 2 {
        odd_count += (ys[i - 1] + ys[i]) % 2;
        count += ys[i];
        if ys[i] == 0 {
            res_t = max(res_t, count - max(0, (odd_count / 2) - 1));
            odd_count = 0;
            count = 0;
        }
    }
    let res = xs.iter().sum::<i64>() - res_t;
    writeln!(buf, "{}", res);
    buf
}

