fn f(xs: &Vec<i64>) -> (i64, i64) {
    let mut sum = xs.iter().sum::<i64>();
    let mut odd_count = 0;
    if xs[0] % 2 == 1 {
        odd_count += 1;
    }
    for i in 1..xs.len() {
        if (xs[i - 1] + xs[i]) % 2 == 1 {
            odd_count += 1;
        }
    }
    if xs[xs.len() - 1] % 2 == 1 {
        odd_count += 1;
    }
    (sum, max(0, odd_count / 2 - 1))
}

use std::cmp::*;
use std::fmt::Write;
fn solve<R: BufRead>(parser: &mut Parser<R>) -> String {
    let mut buf = String::new();
    input! {
        parser = parser,
        n: usize,
        xs: [i64; n],
    }
    let sum = xs.iter().sum::<i64>();
    let mut zss = vec![];
    let mut zs = vec![];
    let mut prev = -1;
    let mut left = 0;
    let mut right = 0;
    for i in 0..n {
        if xs[i] != 0 {
            left = i;
            break;
        }
    }
    for i in (0..n).rev() {
        if xs[i] != 0 {
            right = i;
            break;
        }
    }
    for i in left..right + 1 {
        let x = xs[i];
        // eprintln!("i={}", i);
        if x == 0 {
            if prev != 0 {
                zss.push(zs.clone());
                zs.clear();
                zs = vec![1];
            } else {
                zs[0] += 1;
            }
        } else {
            if prev == 0 {
                zss.push(zs.clone());
                zs.clear();
            }
            zs.push(x);
        }
        prev = x;
    }
    zss.push(zs);
    // eprintln!("{:?}", zss);
    let mut valid_zeros = vec![true; zss.len()];
    {
        let mut left_zero_count = 0;
        let mut left_sum = 0;
        for i in 0..zss.len() {
            if i % 2 == 0 {
                left_sum += zss[i].iter().sum::<i64>();
            } else {
                left_zero_count += zss[i][0];
                if left_zero_count >= left_sum {
                    left_sum = 0;
                    left_zero_count = 0;
                    valid_zeros[i] = false;
                }
            }
        }
    }
    {
        let mut right_zero_count = 0;
        let mut right_sum = 0;
        for i in (0..zss.len()).rev() {
            if i % 2 == 0 {
                right_sum += zss[i].iter().sum::<i64>();
            } else {
                right_zero_count += zss[i][0];
                if right_zero_count >= right_sum {
                    right_sum = 0;
                    right_zero_count = 0;
                    valid_zeros[i] = false;
                }
            }
        }
    }
    // eprintln!("{:?}", valid_zeros);
    let mut yss = vec![];
    let mut ys = vec![];
    let mut pena = 0;
    for i in 0..zss.len() {
        if i % 2 == 0 {
            for &z in &zss[i] {
                ys.push(z);
            }
        } else {
            if valid_zeros[i] {
                for _ in 0..zss[i][0] {
                    ys.push(1);
                }
                pena += zss[i][0];
            } else {
                yss.push((ys.clone(), pena));
                ys.clear();
                pena = 0;
            }
        }
    }
    if !ys.is_empty() {
        yss.push((ys, pena));
    }
    // eprintln!("{:?}", yss);
    let mut res = 1 << 60;
    for (ys, pena) in &yss {
        let (s, cut) = f(ys);
        // eprintln!("s={}, cut={}, pena={}", s, cut, pena);
        res = min(res, sum - s + cut + pena);
    }
    writeln!(buf, "{}", res);
    buf
}

use std::cmp;

const INF: i64 = 1 << 50;

fn main() {
    let (r, w) = (std::io::stdin(), std::io::stdout());
    let mut sc = IO::new(r.lock(), w.lock());
    let n: usize = sc.read();
    let a: Vec<i64> = sc.vec(n);
    let mut dp = [INF; 5];
    dp[0] = 0;
    for i in 0..n {
        let a = a[i];
        let mut next = [INF; 5];
        for i in 0..5 {
            for j in i..5 {
                let cost = match j {
                    0 => a,
                    1 if a == 0 => 2,
                    1 => a % 2,
                    2 => (a + 1) % 2,
                    3 if a == 0 => 2,
                    3 => a % 2,
                    4 => a,
                    _ => unreachable!(),
                };
                next[j] = cmp::min(next[j], dp[i] + cost);
            }
        }
        dp = next;
    }

    let ans = dp.iter().min().unwrap();
    println!("{}", ans);
}

pub struct IO<R, W: std::io::Write>(R, std::io::BufWriter<W>);

impl<R: std::io::Read, W: std::io::Write> IO<R, W> {
    pub fn new(r: R, w: W) -> IO<R, W> {
        IO(r, std::io::BufWriter::new(w))
    }
    pub fn write<S: std::ops::Deref<Target = str>>(&mut self, s: S) {
        use std::io::Write;
        self.1.write(s.as_bytes()).unwrap();
    }
    pub fn read<T: std::str::FromStr>(&mut self) -> T {
        use std::io::Read;
        let buf = self
            .0
            .by_ref()
            .bytes()
            .map(|b| b.unwrap())
            .skip_while(|&b| b == b' ' || b == b'\n' || b == b'\r' || b == b'\t')
            .take_while(|&b| b != b' ' && b != b'\n' && b != b'\r' && b != b'\t')
            .collect::<Vec<_>>();
        unsafe { std::str::from_utf8_unchecked(&buf) }
            .parse()
            .ok()
            .expect("Parse error.")
    }
    pub fn vec<T: std::str::FromStr>(&mut self, n: usize) -> Vec<T> {
        (0..n).map(|_| self.read()).collect()
    }
    pub fn chars(&mut self) -> Vec<char> {
        self.read::<String>().chars().collect()
    }
}

