const INF: i64 = 1e18 as i64;

fn main() {
    input! {
        n: usize,
        a: [i64; n]
    };

    let cost = |mode: usize, val: i64| {
        if mode == 0 || mode == 4 {
            val
        } else if mode == 1 || mode == 3 {
            ifv!(val == 0, 2, val % 2)
        } else {
            (val % 2) ^ 1
        }
    };

    let mut dp = dvec!(INF; n+1, 5);
    dp[0][0] = 0;
    for i in 0..n {
        for j in 0..5 {
            let base = dp[i][j];
            if base == INF {
                continue;
            }
            if j != 4 {
                dp[i][j+1] = min(dp[i][j+1], base);
            }
            dp[i+1][j] = min(dp[i+1][j], base+cost(j, a[i]));
        }
    }

    println!("{}", min(dp[n][2], min(dp[n][3], dp[n][4])));
}

