fn main() {
    let n: usize = read_line().trim().parse().unwrap();
    let mut A = Vec::with_capacity(n);
    let mut memo = vec![0u64; n+2];
    let mut count = vec![0u64; n+2];
    let mut zero = vec![0u64; n+2];
    let mut cs = Vec::new();
    let mut zs = Vec::new();
    for i in 0..n {
        let a: u64 = read_line().trim().parse().unwrap();
        A.push(a);
        memo[i+1] = memo[i] + a;
        count[i+1] = count[i];
        zero[i+1] = zero[i];
        if a%2 == 1 {
            count[i+1]+=1;
            cs.push(i);
        }
        if a == 0 {
            zero[i+1]+=1;
            zs.push(i);
        }
    }

    let mut dp = vec![vec![0u64; 5]; n+1];

    for i in 0..n {
        let mut tmp = dp[i][0];
        dp[i+1][0] = tmp + A[i];
        tmp = cmp::min(tmp, dp[i][1]);
        if A[i] > 0 {
            dp[i+1][1] = tmp + A[i] % 2;
        } else {
            dp[i+1][1] = tmp + 2;
        }
        tmp = cmp::min(tmp, dp[i][2]);
        dp[i+1][2] = tmp + (A[i]+1) % 2;
        tmp = cmp::min(tmp, dp[i][3]);
        if A[i] > 0 {
            dp[i+1][3] = tmp + A[i] % 2;
        } else {
            dp[i+1][3] = tmp + 2;
        }
        tmp = cmp::min(tmp, dp[i][4]);
        dp[i+1][4] = tmp + A[i];
    }
    let mut ans = dp[n][0];
    for i in 1..5 {
        ans = cmp::min(dp[n][i], ans);
    }

    println!("{}",  ans);
