                dp[i][j] = dp[i][j - 1];
            }

            if i > 0 {
                let next = if stones[j] > a[i - 1] {
                    dp[i - 1][j] + stones[j] - a[i - 1]
                } else if stones[j] > 0 {
                    dp[i - 1][j] + (a[i - 1] - stones[j]) % 2
                } else {
                    dp[i - 1][j] + a[i - 1]
                };
                if next < dp[i][j] {
                    dp[i][j] = next;
                }
            }
        }
    }
