fn solve() {
    let l = get!(usize);
    let a = get!(u64; l);

    let mut dp = vec![vec![0; l]; 5];

    dp[0][0] = a[0];
    dp[1][0] = if a[0] == 0 {2} else {a[0]%2};
    dp[2][0] = (a[0]+1) % 2;
    dp[3][0] = if a[0] == 0 {2} else {a[0]%2};
    dp[4][0] = a[0];

    for i in 0..5 {
        for j in 1..l {
            dp[i][j] += match i {
                0 => dp[0][j-1] + a[j],
                1 => min(dp[0][j-1], dp[1][j-1]) + if a[j] == 0 {2} else {a[j]%2},
                2 => min(dp[0][j-1], min(dp[1][j-1], dp[2][j-1])) + (a[j]+1)%2,
                3 => min(dp[0][j-1], min(dp[1][j-1], min(dp[2][j-1], dp[3][j-1]))) + if a[j] == 0 {2} else {a[j]%2},
                4 => min(dp[0][j-1], min(dp[1][j-1], min(dp[2][j-1], min(dp[3][j-1], dp[4][j-1])))) + a[j],
                _ => 0,
            };
        }
    }

    let mut mind = std::u64::MAX;
    for i in 0..5 {
        mind = min(dp[i][l-1], mind);
    }
    println!("{}", mind);
}

