fn f(xs: &Vec<i64>) -> (i64, i64) {
    let mut sum = xs.iter().sum::<i64>();
    let mut odd_count = 0;
    if xs[0] % 2 == 1 {
        odd_count += 1;
    }
    for i in 1..xs.len() {
        if (xs[i - 1] + xs[i]) % 2 == 1 {
            odd_count += 1;
        }
    }
    if xs[xs.len() - 1] % 2 == 1 {
        odd_count += 1;
    }
    (sum, max(0, odd_count / 2 - 1))
}

use std::cmp::*;
use std::fmt::Write;
fn solve<R: BufRead>(parser: &mut Parser<R>) -> String {
    let mut buf = String::new();
    input! {
        parser = parser,
        n: usize,
        xs: [i64; n],
    }
    let sum = xs.iter().sum::<i64>();
    let mut zss = vec![];
    let mut zs = vec![];
    let mut prev = -1;
    let mut left = 0;
    let mut right = 0;
    for i in 0..n {
        if xs[i] != 0 {
            left = i;
            break;
        }
    }
    for i in (0..n).rev() {
        if xs[i] != 0 {
            right = i;
            break;
        }
    }
    for i in left..right + 1 {
        let x = xs[i];
        // eprintln!("i={}", i);
        if x == 0 {
            if prev != 0 {
                zss.push(zs.clone());
                zs.clear();
                zs = vec![1];
            } else {
                zs[0] += 1;
            }
        } else {
            if prev == 0 {
                zss.push(zs.clone());
                zs.clear();
            }
            zs.push(x);
        }
        prev = x;
    }
    zss.push(zs);
    // eprintln!("{:?}", zss);
    let mut valid_zeros = vec![true; zss.len()];
    {
        let mut left_zero_count = 0;
        let mut left_sum = 0;
        for i in 0..zss.len() {
            if i % 2 == 0 {
                left_sum += zss[i].iter().sum::<i64>();
            } else {
                left_zero_count += zss[i][0];
                if left_zero_count >= left_sum {
                    left_sum = 0;
                    left_zero_count = 0;
                    valid_zeros[i] = false;
                }
            }
        }
    }
    {
        let mut right_zero_count = 0;
        let mut right_sum = 0;
        for i in (0..zss.len()).rev() {
            if i % 2 == 0 {
                right_sum += zss[i].iter().sum::<i64>();
            } else {
                right_zero_count += zss[i][0];
                if right_zero_count >= right_sum {
                    right_sum = 0;
                    right_zero_count = 0;
                    valid_zeros[i] = false;
                }
            }
        }
    }
    // eprintln!("{:?}", valid_zeros);
    let mut yss = vec![];
    let mut ys = vec![];
    let mut pena = 0;
    for i in 0..zss.len() {
        if i % 2 == 0 {
            for &z in &zss[i] {
                ys.push(z);
            }
        } else {
            if valid_zeros[i] {
                for _ in 0..zss[i][0] {
                    ys.push(1);
                }
                pena += zss[i][0];
            } else {
                yss.push((ys.clone(), pena));
                ys.clear();
                pena = 0;
            }
        }
    }
    if !ys.is_empty() {
        yss.push((ys, pena));
    }
    // eprintln!("{:?}", yss);
    let mut res = 1 << 60;
    for y in &yss {
        let ref ys = y.0;
        let ref pena = y.1;
        let (s, cut) = f(ys);
        // eprintln!("s={}, cut={}, pena={}", s, cut, pena);
        res = min(res, sum - s + cut + pena);
    }
    writeln!(buf, "{}", res);
    buf
}

