fn f(aa: &[i64]) -> i64 {
    let l = aa.len();
    let mut dp = vec![0i64; l + 1];
    let mut b = vec![0; l + 1];
    let mut ans = vec![0; l + 1];

    for i in 1..l + 1 {
        let prev = dp[i - 1];
        let a = aa[i - 1];

        let a_prev = if i <= 1 { 0 } else { aa[i - 2] };

        if a == 0 {
            dp[i] = max(dp[i], prev - 1);
        } else {
            dp[i] = a;
            dp[i] = max(dp[i], prev + a - (a_prev + 1) % 2);
            ans[i] = dp[i] + max(0, b[i - 1] - a % 2);
            dp[i] = max(dp[i], a + a_prev);
            ans[i] = max(ans[i], a + a_prev);
        }

        if a % 2 == 0 && a > 1 {
            b[i] = b[i - 1] + 1;
        } else {
            b[i] = b[i - 1] - 1;
            b[i] = max(0, b[i]);
        }
    }

    // debug!(&dp, &b);
    let ans = aa.iter().sum::<i64>() - ans.into_iter().max().unwrap_or(0);
    ans
}

