fn f(aa: &[i64]) -> i64 {
    let l = aa.len();
    let mut dp = vec![0i64; l + 1];
    let mut b = vec![0; l + 1];

    for i in 1..l + 1 {
        let prev = dp[i - 1];
        let a = aa[i - 1];

        let a_prev = if i <= 1 { 0 } else { aa[i - 2] };

        if a == 0 {
            dp[i] = max(dp[i], prev - 1);
        } else {
            dp[i] = a;
            dp[i] = max(dp[i], prev + a - (a_prev + 1) % 2);
            dp[i] = max(dp[i], a + a_prev);
        }

        if a % 2 == 0 && a > 1 {
            b[i] = b[i - 1] + 1;
        } else {
            b[i] = b[i - 1] - 1;
            b[i] = max(0, b[i]);
        }
    }

    // debug!(&dp, &b);
    let ans = aa.iter().sum::<i64>()
        - (1..l + 1)
            .map(|i| dp[i] + max(0, b[i - 1] - aa[i - 1] % 2))
            .max()
            .unwrap_or(0);
    ans
}

fn solve() {
    let l = get!(usize);
    let mut aa = get!(i64; l);
    let a1 = f(&aa);
    aa.reverse();
    let a2 = f(&aa);

    println!("{}", min(a1, a2));
}

