    let mut odd = vec![0_i64; n+1];
    let mut even = vec![0_i64; n+1];
    let mut zero = vec![0_i64; n+1];
    let mut i = 0;
    for _ in 0..n {
    	let x = get!();
        if xs.len() == 0 && x == 0 {
        	continue;
        }
        xs.push(x);
        odd[i+1] = odd[i];
        even[i+1] = even[i];
        zero[i+1] = zero[i];
        if x % 2 == 0 {
        	even[i+1] += 1;
            if x == 0 {
            	zero[i+1] += 1;
            }
        } else {
        	odd[i+1] += 1;
        }
        i += 1;
    }
    while let Some(x) = xs.pop() {
    	if x > 0 {
        	xs.push(x);
            break;
        }
    }
